inline bool shadow_live_wanted();   // defined with the live-shadow state

inline bool kh_cbc_on() {
    return shadow_live_wanted() ||
           g_stats_armed.load(std::memory_order_relaxed) ||
           g_dbg_mode.load(std::memory_order_relaxed) == 152;
}

inline const KhCbCensusEntry* kh_cbc_find(void* khcb_buf) {
    for (int khcb_i = 0; khcb_i < KH_CBC_N; ++khcb_i) {
        if (g_cbc[khcb_i].buf == khcb_buf) return &g_cbc[khcb_i];
    }
    return nullptr;
}

// This probe tests a 16-float window for the row-vector view layout (basis
// rows near-unit and near-orthogonal, last column 0,0,0,1, finite
// translation) and its transpose, and extracts the camera. VIEW-SIGNATURE
// PROBE (instrument-first; the projection playbook, round 2).
inline bool kh_cbc_view_probe(const float* khcv_w, float* khcv_cam) {
    auto khcv_n3 = [](float a, float b, float c) {
        return sqrtf(a * a + b * b + c * c);
    };

    for (int khcv_t = 0; khcv_t < 2; ++khcv_t) {
        float khcv_v[4][4];

        for (int khcv_r = 0; khcv_r < 4; ++khcv_r) {
            for (int khcv_c = 0; khcv_c < 4; ++khcv_c) {
                khcv_v[khcv_r][khcv_c] = khcv_t == 0
                    ? khcv_w[khcv_r * 4 + khcv_c]
                    : khcv_w[khcv_c * 4 + khcv_r];
            }
        }

        if (fabsf(khcv_v[0][3]) > 1e-4f || fabsf(khcv_v[1][3]) > 1e-4f ||
            fabsf(khcv_v[2][3]) > 1e-4f || fabsf(khcv_v[3][3] - 1.0f) > 1e-4f) {
            continue;
        }

        const float khcv_r0 = khcv_n3(khcv_v[0][0], khcv_v[0][1], khcv_v[0][2]);
        const float khcv_r1 = khcv_n3(khcv_v[1][0], khcv_v[1][1], khcv_v[1][2]);
        const float khcv_r2 = khcv_n3(khcv_v[2][0], khcv_v[2][1], khcv_v[2][2]);

        if (fabsf(khcv_r0 - 1.0f) > 0.05f || fabsf(khcv_r1 - 1.0f) > 0.05f ||
            fabsf(khcv_r2 - 1.0f) > 0.05f) {
            continue;
        }

        const float khcv_d01 = khcv_v[0][0] * khcv_v[1][0] +
                               khcv_v[0][1] * khcv_v[1][1] +
                               khcv_v[0][2] * khcv_v[1][2];
        const float khcv_d02 = khcv_v[0][0] * khcv_v[2][0] +
                               khcv_v[0][1] * khcv_v[2][1] +
                               khcv_v[0][2] * khcv_v[2][2];
        const float khcv_d12 = khcv_v[1][0] * khcv_v[2][0] +
                               khcv_v[1][1] * khcv_v[2][1] +
                               khcv_v[1][2] * khcv_v[2][2];

        if (fabsf(khcv_d01) > 0.1f || fabsf(khcv_d02) > 0.1f ||
            fabsf(khcv_d12) > 0.1f) {
            continue;
        }

        const float khcv_tm = khcv_n3(khcv_v[3][0], khcv_v[3][1], khcv_v[3][2]);
        if (!(khcv_tm == khcv_tm) || khcv_tm > 1.0e7f) continue;

        extract_camera_pos(khcv_v, khcv_cam);
        if (khcv_cam[0] == khcv_cam[0] && khcv_cam[1] == khcv_cam[1] &&
            khcv_cam[2] == khcv_cam[2]) {
            return true;
        }
    }

    return false;
}

inline void kh_cbc_note(void* khcb_res, float khcb_m22, float khcb_m32,
                        const float* khcb_cam) {
    int khcb_slot = -1;
    uint64_t khcb_oldest = ~0ull;
    int khcb_oldest_i = 0;

    for (int khcb_i = 0; khcb_i < KH_CBC_N; ++khcb_i) {
        if (g_cbc[khcb_i].buf == khcb_res) { khcb_slot = khcb_i; break; }
        if (!g_cbc[khcb_i].buf) { if (khcb_slot < 0) khcb_slot = khcb_i; continue; }
        if (g_cbc[khcb_i].ms < khcb_oldest) {
            khcb_oldest = g_cbc[khcb_i].ms;
            khcb_oldest_i = khcb_i;
        }
    }

    if (khcb_slot < 0) {
        khcb_slot = khcb_oldest_i;
        g_cbc[khcb_slot] = KhCbCensusEntry{};
        g_cbc_evicts++;
    }

    g_cbc[khcb_slot].buf = khcb_res;
    g_cbc[khcb_slot].m22 = khcb_m22;
    g_cbc[khcb_slot].m32 = khcb_m32;
    g_cbc[khcb_slot].ms = steady_now_ms();
    g_cbc[khcb_slot].hits++;
    g_cbc_records++;

    if (khcb_cam) {
        g_cbc[khcb_slot].cam[0] = khcb_cam[0];
        g_cbc[khcb_slot].cam[1] = khcb_cam[1];
        g_cbc[khcb_slot].cam[2] = khcb_cam[2];
        g_cbc[khcb_slot].cam_ok = true;
        g_cbc_cam_recs++;
    } else {
        g_cbc[khcb_slot].cam_ok = false;   // a stale camera never outlives its upload
    }
}
