// Dominant-pair near from the published census (-1 = no reference yet).
inline float kh_enc_near_ref() {
    float khn_best = -1.0f;
    uint32_t khn_hits = 0;

    for (int khn_i = 0; khn_i < KH_PROJ_CENSUS_N; ++khn_i) {
        const KhProjPair& khn_p = g_proj_census_pub[khn_i];
        if (khn_p.hits > khn_hits && khn_p.nearp > 0.0f) {
            khn_hits = khn_p.hits;
            khn_best = khn_p.nearp;
        }
    }

    return khn_best;
}

// kh_enc_near_ok returns true on a cold reference or a non-positive near,
// which is right where it GUARDS an override (a cold gate must not block the
// first encode) and wrong where used it to QUALIFY a substitute - there it
// means a degenerate pair is accepted as authority. THE PROBE MUST NOT SPEND
// THE REJECT COUNTER.

// near from a forward-encode pair (ndc = m22 + m32/d): near = -m32/m22.
inline float kh_enc_pair_near(float khn_m22, float khn_m32) {
    if (g_dbg_mode.load(std::memory_order_relaxed) == 66) return -khn_m32;   // raw form
    return fabsf(khn_m22) > 1e-9f ? (-khn_m32 / khn_m22) : -1.0f;
}

// True = same CLASS as the session's dominant pair, or no reference yet
// (cold: a cold gate must not block the first encode). The class verdict, NO
// side effects beyond publishing the reference the dump reads.
inline bool kh_enc_near_in_class(float khn_near) {
    if (g_dbg_mode.load(std::memory_order_relaxed) == 65) return true;
    const float khn_ref = kh_enc_near_ref();
    g_enc_near_ref_m = khn_ref;
    if (khn_ref <= 0.0f || khn_near <= 0.0f) return true;
    const float khn_hi = khn_near > khn_ref ? khn_near : khn_ref;
    const float khn_lo = khn_near > khn_ref ? khn_ref : khn_near;

    return khn_hi <= khn_lo * KH_ENC_NEAR_CLASS;
}

// REFUSAL form (every rung): the verdict plus the census. Verdict is
// byte-identical to 's kh_enc_near_ok.
inline bool kh_enc_near_ok(float khn_near) {
    if (kh_enc_near_in_class(khn_near)) return true;
    g_enc_near_class_rejects++;
    g_enc_near_rej_m = khn_near;
    return false;
}

// ENDORSEMENT form (substitutions only): the same class test, failing CLOSED.
// A cold reference or a non-finite/non-positive near endorses nothing.
inline bool kh_enc_near_endorsed(float khn_near) {
    if (g_dbg_mode.load(std::memory_order_relaxed) == 66) return kh_enc_near_ok(khn_near);   // form
    if (g_dbg_mode.load(std::memory_order_relaxed) == 65) return true;   // 65 still reverts the whole feature
    if (!(khn_near > 0.0f) || !(khn_near < 1.0e6f)) { g_enc_endorse_rejects++; return false; }
    const float khn_ref = kh_enc_near_ref();
    g_enc_near_ref_m = khn_ref;
    if (!(khn_ref > 0.0f)) { g_enc_endorse_rejects++; return false; }   // cold: endorse nothing
    const float khn_hi = khn_near > khn_ref ? khn_near : khn_ref;
    const float khn_lo = khn_near > khn_ref ? khn_ref : khn_near;

    if (khn_hi > khn_lo * KH_ENC_NEAR_CLASS) { g_enc_endorse_rejects++; return false; }

    return true;
}

// Far plane from a forward-encode pair (ndc = m22 + m32/d): far is where ndc
// reaches 1. Degenerate (infinite-far class) and non-physical pairs return
// 1e9 - always above the ceiling, i.e. refused.
inline float kh_enc_far(float m22, float m32) {
    const float khd = 1.0f - m22;
    if (fabsf(khd) < 1e-7f) return 1e9f;
    const float khf = m32 / khd;
    return khf > 0.0f ? khf : 1e9f;
}

