static float    g_band_uv_drift_px = -1.0f;   // last (-1 = no dual coverage this frame)
static float    g_band_uv_drift_px_max = 0.0f;
static double   g_band_uv_drift_sum = 0.0;
static uint64_t g_band_uv_drift_n = 0;
static uint64_t g_band_uv_drift_over2 = 0;   // frames past 2 texels
static int      g_band_uv_drift_slot = -1;   // serving sealed slot at the last read
static uint32_t g_band_uv_drift_why = 0;   // starve census: bit0 preconditions
                                               // bit1 no serving sealed slot, bit2 no
                                               // live cover
static float    g_band_stage_wait_ms = -1.0f;   // capture -> commit latency
static float    g_band_stage_wait_max_ms = 0.0f;
// Candidate (b) SEAL-SIDE SPLIT reads on bandSealInjDxM / bandSealInjRotDeg
// (the committed vcol camera against THIS cycle's injection basis) - read it
// against the standing ~1.8 m / ~1.07 deg basis offset this tree already
// carries (compCamRtM / injRotDeltaDeg); only an EXCESS convicts.
static uint64_t g_band_esc_lands = 0;   // reseals that landed after an escape
static float    g_band_esc_land_ms = -1.0f;   // last escape -> land (ms)
static float    g_band_esc_land_ms_max = 0.0f;
static double   g_band_esc_land_ms_sum = 0.0;
static uint32_t g_band_esc_land_fr = 0;   // last, in cycles
static uint32_t g_band_esc_land_fr_max = 0;
static float    g_band_esc_land_cdx = -1.0f;   // baked cam vs g_ls.cam at land (m)
static float    g_band_esc_land_cdx_max = 0.0f;
static float    g_band_seal_inj_dx = -1.0f;   // committed vcol cam vs cycle_pv cam (m)
static float    g_band_seal_inj_dx_max = 0.0f;
static float    g_band_seal_inj_rot = -1.0f;   // ... forward-axis angle (deg)
static float    g_band_seal_inj_rot_max = 0.0f;
static float    g_band_reseal_step = -1.0f;   // old vcol cam -> new vcol cam (m)
static float    g_band_reseal_step_max[3] = { 0.0f, 0.0f, 0.0f };   // by tier
static uint64_t g_band_reseal_n[3] = { 0, 0, 0 };
static double   g_band_reseal_sum[3] = { 0.0, 0.0, 0.0 };
// khsl_vc = the vcol being committed (12 floats, column layout), khsl_old =
// the vcol it replaces. Shared landing bookkeeping (render thread only).
inline void kh_seal_land_note(int khsl_slot, float khsl_now, float khsl_esc_t,
                              uint64_t khsl_esc_cycle, const float* khsl_old,
                              const float* khsl_vc);

// Gated on a plain bool, so the steady-state cost is one load.
inline void kh_band_stage_commit(ID3D11DeviceContext* ctx) {
    if (!g_ls.stage_any) return;
    if (!ctx || !g_ls.atlas_tex) return;
    if (!g_ls.frame_view_valid || g_ls.frame_view_time < 0.0f) return;
    // The pairing view is THIS cycle's publish; a staged capture from this
    // cycle is still waiting for the next one.
    if (g_boundary_t >= 0.0f && g_ls.frame_view_time < g_boundary_t) return;

    const float khsc_now = effect_time_seconds();
    const bool khsc_qok = g_ls.last_publish_rot_err <= 1e-3f;
    bool khsc_any = false;

    for (int khsc_i = 0; khsc_i < 8; ++khsc_i) {
        auto& b = g_ls.band[khsc_i];
        if (!b.stage_valid) continue;

        const int khsc_p = b.stage_pool;
        const bool khsc_dead = !b.valid || !b.tex || !b.srv ||
                               khsc_p < 0 || khsc_p >= KH_BAND_STAGE_POOL ||
                               !g_band_pool[khsc_p].tex || !g_band_pool[khsc_p].srv;

        if (khsc_dead) {   // wiped underneath us: release and reseal clean
            if (khsc_p >= 0 && khsc_p < KH_BAND_STAGE_POOL) g_band_pool[khsc_p].busy = false;
            b.stage_valid = false;
            b.stage_pool = -1;
            b.last_time = 0.0f;
            g_band_stage_drop_dead++;
            continue;
        }

        if (g_boundary_t >= 0.0f && b.stage_since >= g_boundary_t) {
            khsc_any = true;   // staged this cycle: its view has not arrived
            continue;
        }

        const bool khsc_aged = khsc_now - b.stage_since > 0.05f;

        if (!khsc_qok && !khsc_aged) {   // publish not exact-class: keep waiting
            khsc_any = true;
            g_band_stage_hold_quality++;
            continue;
        }

        if (khsc_aged) {   // no pairing view came: the old seal stands
            g_band_pool[khsc_p].busy = false;
            b.stage_valid = false;
            b.stage_pool = -1;
            b.last_time = 0.0f;   // let the next sweep re-stage
            g_band_stage_drop_age++;
            continue;
        }

        // KH_BAND_STAGE_FLIP (mode 346, ARM - opt-in, mode 0 byte-identical):
        // weld the latched per-band pair instead of the commit-time global
        // frame_view.
        const bool khfl_on = g_dbg_mode.load(std::memory_order_relaxed) == 346;
        float khwn_code = 4.0f;   // stage-baseline unless overridden
        if (khfl_on && !b.stage_pair_ok) {
            const bool khfl_alive = g_ls.alt_view_valid &&
                g_ls.frame_view_time - g_ls.alt_view_time < 0.25f;
            const bool khfl_pool = khsc_now - g_band_pool_miss_t > 0.1f;
            if (khfl_alive && khfl_pool &&
                khsc_now - b.stage_since <= 0.045f) {
                khsc_any = true;
                g_band_stage_flip_hold++;
                continue;
            }
            if (khfl_alive && !khfl_pool) {
                g_band_stage_flip_poolbail++;   // refused under pressure
            }
            if (khfl_alive) { g_band_stage_flip_late++; khwn_code = 3.0f; }
            else { g_band_stage_flip_single++; khwn_code = 2.0f; }
        }
        memcpy(b.sm, b.stage_sm, sizeof(b.sm));
        memcpy(b.border, b.stage_border, sizeof(b.border));

        float khsl_old[12];   // the vcol being replaced
        memcpy(khsl_old, b.vcol, sizeof(khsl_old));
        if (!kh_band_view_native(g_ls.frame_view, true)) {
            khsc_any = true;
            continue;
        }
        // A mixed stage can never become coherent with ANY future publish
        // (its capture camera is fixed), so it DROPS via the aged-drop
        // mechanics and the next sweep re-stages clean; the old complete seal
        // keeps serving.
        if (b.stage_view_ok) {
            const float khpx_s = kh_band_source_gap(b.stage_view, g_ls.frame_view);
            if (khpx_s >= 0.0f) {
                if (khpx_s > 0.5f) g_band_stage_xsrc++;
                else g_band_stage_samesrc++;
            }
        }
        if (b.stage_view_ok &&
            !kh_band_pair_coherent(b.stage_view, g_ls.frame_view)) {
            g_band_pool[khsc_p].busy = false;
            b.stage_valid = false;
            b.stage_pool = -1;
            b.last_time = 0.0f;
            continue;
        }
        const bool khsc_same = g_dbg_mode.load(std::memory_order_relaxed) == 335 &&
                               b.stage_view_ok;
        if (khfl_on && b.stage_pair_ok) {   // the per-band flip weld
            memcpy(b.vcol, b.stage_pair, sizeof(b.vcol));
            g_band_stage_flip++;
            khwn_code = 1.0f;
        } else if (khsc_same) {
            memcpy(b.vcol, b.stage_view, sizeof(b.vcol));
            g_band_pair_same_seals++;
            khwn_code = 5.0f;
        } else {
            // Mode 351 = baseline weld unconditionally. ROTATIONAL SAME-FRAME
            // COHERENCE.
            if (b.stage_first_ok &&
                g_dbg_mode.load(std::memory_order_relaxed) != 351) {
                memcpy(b.vcol, b.stage_first, sizeof(b.vcol));
                g_band_rot_welds++;   // stage-first welds
                khwn_code = 8.0f;   // 8 = stage-first weld
            } else {
                for (int c = 0; c < 3; ++c) {
                    for (int r = 0; r < 4; ++r) {
                        b.vcol[c * 4 + r] = g_ls.frame_view[r * 4 + c];
                    }
                }
            }
        }
        kh_seal_land_note(khsc_i, khsc_now, b.esc_t, b.esc_cycle, khsl_old, b.vcol);
        kh_weld_note(b.vcol, khwn_code);   // weld identity census
        b.esc_t = -1.0f;

        // SWAP, do not copy: the back buffer was filled AT THE RESOLVE that
        // paired this sm, so its content is the content that sm describes.
        // The retiring front texture becomes the pool's next back buffer.
        {
            ID3D11Texture2D* khsc_t = b.tex;
            ID3D11ShaderResourceView* khsc_s = b.srv;
            b.tex = g_band_pool[khsc_p].tex;
            b.srv = g_band_pool[khsc_p].srv;
            g_band_pool[khsc_p].tex = khsc_t;
            g_band_pool[khsc_p].srv = khsc_s;
            g_band_pool[khsc_p].busy = false;
            b.stage_pool = -1;
        }

        const float khsc_w = (khsc_now - b.stage_since) * 1000.0f;
        g_band_stage_wait_ms = khsc_w;
        if (khsc_w > g_band_stage_wait_max_ms) g_band_stage_wait_max_ms = khsc_w;
        b.pending_view = false;
        b.vcol_bridge = false;
        b.stage_valid = false;
        b.stage_view_ok = false;
        b.stage_pair_ok = false;
        b.stage_first_ok = false;
        b.last_time = khsc_now;
        b.copies++;
        g_band_stage_commits++;
        g_ls.band_captures++;
        g_ls.seal_completions++;
        if (g_ls.first_capture_time < 0.0f) g_ls.first_capture_time = khsc_now;
        if (g_first_bandcap_t < 0.0f) g_first_bandcap_t = khsc_now;
    }

    g_ls.stage_any = khsc_any;
}
static uint64_t g_band_seal_unlocked = 0;   // seals taken with !view_src_valid
static uint64_t g_band_cold_holds = 0;   // consumptions held by the health gate
static uint64_t g_recv_cold_wipes = 0;   // cold-era seals dropped at the rise
static constexpr uint64_t KH_RECV_HEALTH_DWELL_MS = 500ull;
static bool     g_recv_health_ok = false;   // one-way latch (session state)
static uint64_t g_recv_health_since_ms = 0;   // dwell start (0 = not running)
static float    g_recv_health_t = -1.0f;   // cold-timeline stamp of the rise
static float    g_sun_map_mature_pub = -1.0f;   // last localityMeta.z filled
static uint64_t g_sun_mat_dem_new = 0;   // de-matures, by reason
static uint64_t g_sun_mat_dem_cchg = 0;
static uint64_t g_sun_mat_dem_big = 0;
static uint64_t g_sun_mat_dem_drift = 0;
static uint64_t g_sun_mat_caster_rolls = 0;   // caster changes held mature

// It is a ONE-WAY latch: mid-session lock churn must not blink the world
// shadow out, and the forced-drop path already wipes the tables itself.
// Absent beats FOREIGN - the same doctrine the warm-up gate, the band prov
// guard and the sun-axis refusal are all written on.
inline bool kh_recv_health() {
    if (g_recv_health_ok) return true;
    if (g_dbg_mode.load(std::memory_order_relaxed) == 47) return true;   // revert
    const bool khrh_ok = g_ls.view_src_valid &&
                         g_ls.pub_fresh_ms != 0 &&
                         steady_now_ms() - g_ls.pub_fresh_ms <= 1000 &&
                         g_sun_dir_derived_valid &&
                         g_sun_derived_samples >= 120;

    if (!khrh_ok) { g_recv_health_since_ms = 0; return false; }

    const uint64_t khrh_now = steady_now_ms();

    if (g_recv_health_since_ms == 0) { g_recv_health_since_ms = khrh_now; return false; }
    if (khrh_now - g_recv_health_since_ms < KH_RECV_HEALTH_DWELL_MS) return false;

    g_recv_health_ok = true;
    g_recv_health_t = effect_time_seconds();

    for (int khrh_b = 0; khrh_b < 8; ++khrh_b) {
        if (!g_ls.band[khrh_b].valid) continue;
        g_ls.band[khrh_b].valid = false;
        g_ls.band[khrh_b].pending_view = false;
        g_ls.band[khrh_b].vcol_bridge = false;
        g_recv_cold_wipes++;
    }

    return true;
}
