inline void kh_note_lock_churn(int khc_site) {
    const uint64_t khc_now = steady_now_ms();

    if (khc_site == 1) g_lock_churn_stamp_relock++;
    else if (khc_site == 2) g_lock_churn_stamp_drop++;
    else if (khc_site == 3) g_lock_churn_stamp_prewarm++;
    else g_lock_churn_stamp_ring++;

    if (g_lock_churn_prev_ms != 0 && khc_now - g_lock_churn_prev_ms < 1500) {
        g_lock_churn_stamps_close++;
    }

    g_lock_churn_prev_ms = khc_now;
}
