inline bool kh_dl_dense(uint16_t khdn_sightings, uint16_t khdn_gap) {
    if (g_dbg_mode.load(std::memory_order_relaxed) == 59) {   // pre-form
        return khdn_sightings >= KH_DL_DENSE_SIGHTS_WIDE &&
               khdn_gap <= KH_DL_DENSE_GAP_MS;
    }

    return khdn_sightings >= KH_DL_DENSE_SIGHTS;
}
// gap_max_ms was a LIFETIME maximum that never decayed, so one unlucky
// sampling gap early in an entry's life priced its tail at GAP_MULT x that
// gap for the rest of its existence - and permanently disqualified it from
