static uint32_t g_dl_exp_tail_max = 0;

// Always >= the most recent gap, so the TTL can never fall below GAP_MULT
// re-sight intervals. Cadence mark update: max(this gap, the decayed previous
// mark). The 60 s bound is the old guard against a stamp from a previous era
// (a compacted-out ghost's slot) pricing an eternal tail.
inline uint16_t kh_dl_gap_mark(uint16_t khg_prev, uint64_t khg_gap) {
    if (khg_gap >= 60000) return khg_prev;   // out-of-era stamp: no evidence
    const uint16_t khg_now = static_cast<uint16_t>(khg_gap);

    if (g_dbg_mode.load(std::memory_order_relaxed) == 53) {   // : lifetime high-water
        return khg_now > khg_prev ? khg_now : khg_prev;
    }

    const uint16_t khg_dec = static_cast<uint16_t>(
        (static_cast<uint32_t>(khg_prev) * KH_DL_GAP_DECAY_NUM) / KH_DL_GAP_DECAY_DEN);
    if (khg_dec < khg_prev) g_dl_gap_decays++;
    return khg_now > khg_dec ? khg_now : khg_dec;
}
static constexpr float    KH_DL_MATCH_M = 1.0f;   // pool update match radius (same light re-sighted)

// The mode variable remains the internal gate every path checks (and what a
// future kill-switch would flip); modes 1/2 were the retired camera-origin
// hypotheses. dumpDynamicLights stays as the standing diagnostic surface.
static std::atomic<int>      g_dl_mode{3};
static std::atomic<uint32_t> g_dl_intensity_bits{0x3F800000u};   // float bits, default 1.0
static std::atomic<bool>     g_dl_recon{false};   // armed by the first dumpDynamicLights
static std::atomic<bool>     g_dl_census_on{false};   // per-draw variability sampling

struct DlWindowMeta {
    void*    buf = nullptr;   // weak identity (dedupe key with first)
    uint32_t first = 0;   // firstConstant (16-byte units)
    uint32_t num = 0;   // bound window size (constants)
    uint32_t bytes11 = 0;   // lights bytes actually copied
    uint16_t vs_bytes[KH_DL_VS_SLOTS] = {};   // VS constants copied per slot (0 = absent)
};

struct DlWinReport {   // last harvest's per-window verdicts (dump)
    uint64_t buf = 0;
    uint32_t first = 0;
    uint32_t point_n = 0, spot_n = 0;
    uint8_t  origin_ok = 0;
    float    ox = 0.0f, oz = 0.0f;
    float    scale = 0.0f;   // this window's cb10[2].x (fold forensics)
    float    gdiff[3] = {};   // this window's cb10[3].xyz
    uint8_t  derived_ok = 0;   // engine-derived origin found and validated
    float    d_ox = 0.0f, d_oz = 0.0f;
    float    d_res = -1.0f;   // post-snap residual of the derived origin
    int32_t  d_slot = -1;   // VS slot of the model-view (or pure view)
    int32_t  d_wslot = -1;   // VS slot of the world matrix (-1 = pure route)
    uint8_t  pool_vote = 0;   // origin recovered by voting against the pool
    uint16_t v_best = 0;   // winning origin's vote count
    uint16_t v_runner = 0;   // runner-up's vote count (margin forensics)
    uint16_t v_cands = 0;   // distinct candidate origins seen
    float    v_res = -1.0f;   // winning vote's residual
};

struct DlCandRec {   // derivation-candidate recon (the landscape ring)
    uint64_t t_ms = 0;
    uint32_t buf_lo = 0;   // window buffer identity (low 32)
    uint8_t  kind = 0;   // 0 pure, 1 pair, 2 cam-triple, 3 obj-triple
    int8_t   slot = -1;
    uint16_t off = 0;
    float    ox = 0.0f, oz = 0.0f;
    float    res = -1.0f;   // post-snap residual (loose candidates included)
    float    ydelta = 0.0f;
};

struct DlM3Ring {   // mode-3 harvest ring (flicker forensics)
    uint64_t t_ms = 0;
    uint16_t pool_n = 0;
    uint16_t anchored = 0;   // windows with resolved origins this harvest
    uint16_t added = 0, updated = 0, expired = 0;
    uint16_t spot_flips = 0;   // classification changed on update
    float    gdiff[3] = {};   // last anchored window's RAW cb10[3]
    float    scale = 0.0f;   // last anchored window's RAW cb10[2].x
};

struct DlPoolLight {
    float    rec[24] = {};   // the 6-float4 record VERBATIM (producer side)
                                  // +0 rewritten to absolute world
    uint8_t  spot = 0;   // index >= its list's pointN
    uint8_t  aux = 0;   // content authored by an AUX-pass window only
    uint8_t  derived = 0;   // authored/confirmed by an exact derivation
                                  // (ONLY these anchor pool votes - the vote
                                  // must never trust its own output)
    uint64_t stamp = 0;   // last re-sight (persistence TTL)
    uint64_t first_ms = 0;   // census: first sight (lifetime)
    uint16_t gap_max_ms = 0;   // worst observed re-sight gap (cadence evidence)
    uint16_t sightings = 0;   // saturating sighting count
};

struct DlRingEntry {
    uint32_t serial = 0;   // harvest ordinal
    uint64_t t_ms = 0;
    uint32_t point_n = 0, spot_n = 0;
    float    dist_scale = 0.0f;
    uint32_t hash32 = 0;   // list-content hash (change cadence)
    float    cam[3] = {};   // capture camera (engine axes)
    uint64_t b10 = 0, b11 = 0;   // slot buffer weak identities (integer form)
    uint32_t f10 = 0, f11 = 0;   // firstConstant offsets (16-byte units)
    uint32_t n10 = 0, n11 = 0;   // bound window sizes (constants)
    float    l0[8] = {};   // first light: pos.xyz, diffuse.rgb, fadeStart, coneCos
    uint8_t  counts_as_float = 0;   // counts arrived float-written (census)
};

struct DynLightsState {
    // published mirror (render thread writes at harvest; both draw paths read
    // under the park invariant)
    bool     valid = false;
    uint32_t point_n = 0, spot_n = 0;
    float    ctl[16] = {};   // cb10
    float    lights[KH_DL_MAX_LIGHTS * 24] = {};   // cb11 (active prefix)
    float    view_cols[12] = {};   // 3 float4 view columns
    bool     view_valid = false;
    float    cam[3] = {};   // capture camera (engine axes)
    uint64_t stamp_ms = 0;
    uint32_t serial = 0;   // harvest count
    uint64_t hash = 0;
    // staging machinery (render thread only)
    ID3D11Buffer* staging[2] = {};
    uint8_t  inflight[2] = {};
    uint32_t issue_serial = 0;
    uint32_t slot_bytes11[2] = {};   // lights bytes actually copied
    float    pending_view[2][12] = {};
    float    pending_cam[2][3] = {};
    uint8_t  pending_view_ok[2] = {};
    // per-draw window arena (render thread only): every distinct slot-11
    // window sampled during the frame is copied here with its control block;
    // harvest at the next injection recovers each list's origin and merges
    // the union into the mode-3 pool
    ID3D11Buffer* arena[2] = {};
    uint8_t  arena_inflight[2] = {};
    int      arena_write = 0;
    DlWindowMeta win_meta[2][KH_DL_WIN_MAX] = {};
    uint32_t win_count[2] = {};
    float    arena_view[2][12] = {};   // frame view COLUMNS latched at the side's first capture
    float    arena_cam[2][3] = {};   // bridge TRUE-world camera, same latch
    uint8_t  arena_view_ok[2] = {};
    // merged absolute-world pool (render thread writes at harvest; both draw
    // paths read under the park invariant)
    std::vector<DlPoolLight> pool;   // UNCAPPED; grows at harvest, TTL-swept
    uint32_t pool_n = 0;
    // anchor table (derived-provenance light positions; the vote's ground
    // truth, decoupled from shading persistence)
    float    anchor_pos[KH_DL_ANCHOR_N][3] = {};
    uint64_t anchor_stamp[KH_DL_ANCHOR_N] = {};
    uint32_t anchor_n = 0;
    uint64_t anchor_admits = 0;   // ULP-class derivations admitted to the table
    uint64_t anchor_res_rejects = 0;   // derived origins good enough to shade, not to testify
    // derivation-candidate recon ring (every validate-pass from the full
    // scans, LOOSE ones included: the constant landscape)
    DlCandRec cand_ring[256] = {};
    uint32_t cand_head = 0;
    uint64_t pool_stamp = 0;
    float    pool_scale = 1.0f;   // cb10[2].x consensus (last valid window)
    float    pool_gdiff[3] = { 1.0f, 1.0f, 1.0f };
    float    main_gdiff[3] = { 1.0f, 1.0f, 1.0f };
    float    main_scale = 1.0f;
    uint8_t  main_ref_valid = 0;
    float    ref_pend_g[3] = {};
    float    ref_pend_s = 0.0f;
    uint64_t ref_pend_ms = 0;
    uint64_t ref_holds = 0;   // out-of-band candidates held out
    uint64_t ref_jump_adopts = 0;   // confirmed exposure jumps adopted
    DlWinReport win_report[KH_DL_WIN_MAX] = {};
    uint32_t win_report_n = 0;
    DlM3Ring m3_ring[KH_DL_RING] = {};
    uint32_t m3_ring_head = 0;
    // fill census (mode 3): how many lights each fill packed - a flap between
    // 0 and k here convicts selection/staleness, a steady k acquits it
    // (park-ordered single-writer like the pool itself)
    uint64_t fill_calls = 0;
    uint32_t fill_last_n = 0;
    uint32_t fill_min_n = 0xFFFFFFFFu;
    uint32_t fill_max_n = 0;
    uint64_t pool_spot_flips = 0;   // point<->spot reclassification on update
    uint64_t win_aux = 0;   // windows classified AUX (divergent pass globals)
    uint64_t aux_adds = 0;   // lights first seen only through an aux window
    uint64_t aux_refreshes = 0;   // aux sightings that refreshed a stamp only
    // engine-derived origin census
    uint64_t vs_copies = 0;   // VS slot windows copied into the arena
    uint64_t vs_scans = 0;   // windows scanned for a view candidate
    uint64_t vs_hint_hits = 0;   // memoized (slot, offset, form) hit first try
    uint64_t vs_ortho_pass = 0;   // candidates passing the structural test
    uint64_t vs_rot_rejects = 0;   // rotation != the frame view (model-view / aux pass)
    uint64_t vs_y_rejects = 0;   // |Y delta| beyond tolerance
    uint64_t vs_grid_rejects = 0;   // origin off the 100 m grid
    uint64_t vs_noref = 0;   // no frame view latched for the side
    uint64_t vs_valid = 0;   // validated derived origins
    uint64_t vs_pair_tries = 0;   // MV x W pairings attempted
    uint64_t vs_pair_valid = 0;   // pairings that passed the Y + grid proof
    uint64_t vs_pair_y_rejects = 0;   // pair route Y failures
    uint64_t vs_pair_grid_rejects = 0;   // pair route grid failures
    float    vs_last_ydelta = 0.0f;   // most recent Y-reject delta (either route)
    uint64_t vs_triple_valid = 0;   // bare-triple candidates passing the proof
    uint64_t vs_zero_origins = 0;   // the true-world degeneracy won (nothing non-zero)
    uint64_t vs_nonzero_origins = 0;   // a light-frame origin won
    uint64_t origin_range_rejects = 0;   // decoded records implausibly far from the camera
    uint64_t origin_pool_votes = 0;   // windows resolved by pool voting (propagation)
    uint64_t origin_vote_ambiguous = 0;   // votes refused for lattice ambiguity (no clear majority)
    uint64_t vs_range_prunes = 0;   // candidates pruned by the range arbiter at selection
    uint8_t  vs_hint_kind = 0;   // winning route: 0 pure, 1 pair, 2 cam-triple, 3 obj-triple
    int32_t  vs_hint_slot = -1;   // memoized MODEL-VIEW find (session-scoped)
    uint32_t vs_hint_off = 0;   // float offset within the slot block
    uint8_t  vs_hint_form = 0;   // 0 = file convention, 1 = transposed storage
    int32_t  vs_hint_wslot = -1;   // memoized WORLD-matrix find (-1 = pure view)
    uint32_t vs_hint_woff = 0;
    uint8_t  vs_hint_wform = 0;
    // window / origin / pool counters
    uint64_t win_captured = 0;   // window copies issued into the arena
    uint64_t win_table_full = 0;   // ninth+ distinct window in one frame
    uint64_t lists_anchored = 0;   // windows whose origin resolved (derivation)
    uint64_t lists_unanchored = 0;   // windows with no resolvable origin (dropped)
    uint64_t pool_added = 0;   // new lights entering the pool
    uint64_t pool_updated = 0;   // re-sighted lights refreshed in place
    uint64_t pool_expired = 0;   // TTL expiries (light off / gone / moved away)
    void*    slot10_buf = nullptr; void* slot11_buf = nullptr;
    uint32_t slot10_first = 0, slot11_first = 0;
    uint32_t slot10_num = 0, slot11_num = 0;
    uint32_t bw10 = 0, bw11 = 0;   // buffer byte widths
    // counters (render thread writes; dump/stats read)
    uint64_t acquires = 0;   // acquisition entries (armed injections)
    uint64_t copies = 0;   // copy pairs issued
    uint64_t still_drawing = 0;   // harvest retries (GPU not done)
    uint64_t no_ctx1 = 0;   // ID3D11DeviceContext1 unavailable
    uint64_t slot_nulls = 0;   // slot 10 or 11 unbound at the injection
    uint64_t issue_skips = 0;   // both staging slots in flight
    uint64_t bounds_rejects = 0;   // window outside the buffer
    uint64_t window_clamps = 0;   // bound window smaller than 32 lights
    uint64_t val_rejects = 0;   // CPU validation refused a harvest
    uint64_t counts_float = 0;   // counts arrived float-written
    uint64_t clamped_counts = 0;   // pointN+spotN exceeded capacity
    uint64_t zero_lists = 0;   // valid harvests with zero lights
    uint64_t hash_changes = 0;   // list content changed between harvests
    uint64_t stale_skips = 0;   // fill stood down on an expired mirror
    uint64_t view_miss_skips = 0;   // mode-2 fill without view columns
    uint64_t pool_offset_binds = 0;   // slot bound with firstConstant != 0
    uint64_t shared_pool_binds = 0;   // slots 10 and 11 share one buffer
    float    last_rej[4] = {};   // forensic: the values that failed + reason id
    DlRingEntry ring[KH_DL_RING];
    uint32_t ring_head = 0;
};
static DynLightsState g_dl;

// Per-draw variability census (render thread; armed by the dump): sampled
// slot-11 window identities per frame - the distinct (buffer, offset) count
// answers the per-draw culling question (one global visible list vs lists
// culled per draw), folded at the frame boundary (main clear).
static uint32_t g_dl_cd_ctr = 0;
static void*    g_dl_cd_bufs[8] = {};
static uint32_t g_dl_cd_first[8] = {};
static uint32_t g_dl_cd_n = 0;
static uint32_t g_dl_cd_null = 0, g_dl_cd_samples = 0;
static uint32_t g_dl_cd_distinct_last = 0, g_dl_cd_distinct_max = 0;
static uint32_t g_dl_cd_null_last = 0, g_dl_cd_samples_last = 0;

inline bool dl_finite(float v) { return v == v && v < 1.0e30f && v > -1.0e30f; }

inline void dynlights_sample_draw(ID3D11DeviceContext* ctx) {
    ID3D11DeviceContext1* khd_c1 = kh_ctx1(ctx);   // cached Q(no release)
    if (!khd_c1) return;
    ID3D11Buffer* khd_b11 = nullptr;
    UINT khd_f11 = 0, khd_n11 = 0;
    khd_c1->PSGetConstantBuffers1(11, 1, &khd_b11, &khd_f11, &khd_n11);
    g_dl_cd_samples++;

    if (!khd_b11) {
        g_dl_cd_null++;
        return;
    }

    {   // census: distinct (buffer, offset) pairs this frame
        bool khd_seen = false;

        for (uint32_t i = 0; i < g_dl_cd_n; ++i) {
            if (g_dl_cd_bufs[i] == static_cast<void*>(khd_b11) && g_dl_cd_first[i] == khd_f11) {
                khd_seen = true;
                break;
            }
        }

        if (!khd_seen && g_dl_cd_n < 8) {
            g_dl_cd_bufs[g_dl_cd_n] = static_cast<void*>(khd_b11);
            g_dl_cd_first[g_dl_cd_n] = khd_f11;
            g_dl_cd_n++;
        }
    }

    // arena capture: only when this window is new to the WRITE side
    const int khd_w = g_dl.arena_write;
    bool khd_have = false;

    for (uint32_t i = 0; i < g_dl.win_count[khd_w]; ++i) {
        if (g_dl.win_meta[khd_w][i].buf == static_cast<void*>(khd_b11) &&
            g_dl.win_meta[khd_w][i].first == khd_f11) {
            khd_have = true;
            break;
        }
    }

    if (khd_have) {
        khd_b11->Release();
        return;
    }

    if (g_dl.win_count[khd_w] >= KH_DL_WIN_MAX) {
        g_dl.win_table_full++;
        khd_b11->Release();
        return;
    }

    if (!g_dl.arena[khd_w]) {
        ID3D11Device* khd_dev = nullptr;
        ctx->GetDevice(&khd_dev);

        if (khd_dev) {
            D3D11_BUFFER_DESC khd_sd = {};
            khd_sd.ByteWidth = KH_DL_ARENA_BYTES;
            khd_sd.Usage = D3D11_USAGE_STAGING;
            khd_sd.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
            khd_dev->CreateBuffer(&khd_sd, nullptr, &g_dl.arena[khd_w]);
            khd_dev->Release();
        }
    }

    ID3D11Buffer* khd_b10 = nullptr;
    UINT khd_f10 = 0, khd_n10 = 0;
    khd_c1->PSGetConstantBuffers1(10, 1, &khd_b10, &khd_f10, &khd_n10);
    ID3D11Buffer* khd_vsb[KH_DL_VS_SLOTS] = {};
    UINT khd_vsf[KH_DL_VS_SLOTS] = {}, khd_vsn[KH_DL_VS_SLOTS] = {};
    khd_c1->VSGetConstantBuffers1(0, KH_DL_VS_SLOTS, khd_vsb, khd_vsf, khd_vsn);

    if (g_dl.arena[khd_w] && khd_b10) {
        D3D11_BUFFER_DESC khd_d10 = {}, khd_d11 = {};
        khd_b10->GetDesc(&khd_d10);
        khd_b11->GetDesc(&khd_d11);
        const uint32_t khd_off10 = khd_f10 * 16u;
        const uint32_t khd_off11 = khd_f11 * 16u;
        uint32_t khd_want11 = KH_DL_ARR_BYTES;
        if (khd_n11 > 0 && khd_n11 * 16u < khd_want11) khd_want11 = khd_n11 * 16u;

        if (khd_off10 + KH_DL_CTL_BYTES <= khd_d10.ByteWidth && khd_off11 < khd_d11.ByteWidth) {
            if (khd_off11 + khd_want11 > khd_d11.ByteWidth) khd_want11 = khd_d11.ByteWidth - khd_off11;
            khd_want11 -= khd_want11 % KH_DL_LIGHT_BYTES;   // whole records only

            if (g_dl.win_count[khd_w] == 0) {
                // first capture of this side: latch the FRAME's bridge view
                // (rotation reference + TRUE-world camera for the origin
                // subtraction; all main-pass draws share it)
                if (g_ro.cycle_pv_valid) {
                    for (int khd_k = 0; khd_k < 3; ++khd_k) {
                        g_dl.arena_view[khd_w][khd_k * 4 + 0] = g_ro.cycle_pv.view[0][khd_k];
                        g_dl.arena_view[khd_w][khd_k * 4 + 1] = g_ro.cycle_pv.view[1][khd_k];
                        g_dl.arena_view[khd_w][khd_k * 4 + 2] = g_ro.cycle_pv.view[2][khd_k];
                        g_dl.arena_view[khd_w][khd_k * 4 + 3] = 0.0f;
                    }

                    extract_camera_pos(g_ro.cycle_pv.view, g_dl.arena_cam[khd_w]);
                    g_dl.arena_view_ok[khd_w] = 1;
                } else {
                    g_dl.arena_view_ok[khd_w] = 0;
                }
            }

            const uint32_t khd_slot = g_dl.win_count[khd_w];
            const uint32_t khd_dst = khd_slot * KH_DL_WIN_BYTES;
            D3D11_BOX khd_box10 = { khd_off10, 0, 0, khd_off10 + KH_DL_CTL_BYTES, 1, 1 };
            ctx->CopySubresourceRegion(g_dl.arena[khd_w], 0, khd_dst, 0, 0, khd_b10, 0, &khd_box10);

            if (khd_want11 > 0) {
                D3D11_BOX khd_box11 = { khd_off11, 0, 0, khd_off11 + khd_want11, 1, 1 };
                ctx->CopySubresourceRegion(g_dl.arena[khd_w], 0, khd_dst + KH_DL_CTL_BYTES, 0, 0,
                                           khd_b11, 0, &khd_box11);
            }

            DlWindowMeta& khd_meta = g_dl.win_meta[khd_w][khd_slot];
            khd_meta.buf = static_cast<void*>(khd_b11);
            khd_meta.first = khd_f11;
            khd_meta.num = khd_n11;
            khd_meta.bytes11 = khd_want11;
            uint32_t khd_vs_dst = khd_dst + KH_DL_STAGE_BYTES;

            for (uint32_t khd_vs = 0; khd_vs < KH_DL_VS_SLOTS; ++khd_vs) {
                khd_meta.vs_bytes[khd_vs] = 0;

                if (khd_vsb[khd_vs]) {
                    D3D11_BUFFER_DESC khd_vd = {};
                    khd_vsb[khd_vs]->GetDesc(&khd_vd);
                    const uint32_t khd_voff = khd_vsf[khd_vs] * 16u;

                    if (khd_voff < khd_vd.ByteWidth) {
                        uint32_t khd_vwant = KH_DL_VS_BYTES;
                        if (khd_vsn[khd_vs] > 0 && khd_vsn[khd_vs] * 16u < khd_vwant) khd_vwant = khd_vsn[khd_vs] * 16u;
                        if (khd_voff + khd_vwant > khd_vd.ByteWidth) khd_vwant = khd_vd.ByteWidth - khd_voff;
                        khd_vwant &= ~15u;

                        if (khd_vwant >= 64u) {   // at least one 4x4
                            D3D11_BOX khd_vbox = { khd_voff, 0, 0, khd_voff + khd_vwant, 1, 1 };
                            ctx->CopySubresourceRegion(g_dl.arena[khd_w], 0, khd_vs_dst, 0, 0,
                                                       khd_vsb[khd_vs], 0, &khd_vbox);
                            khd_meta.vs_bytes[khd_vs] = static_cast<uint16_t>(khd_vwant);
                            g_dl.vs_copies++;
                        }
                    }
                }

                khd_vs_dst += KH_DL_VS_BYTES;
            }

            g_dl.win_count[khd_w] = khd_slot + 1;
            g_dl.win_captured++;
        } else {
            g_dl.bounds_rejects++;
        }
    }

    if (khd_b10) khd_b10->Release();
    for (uint32_t khd_vs = 0; khd_vs < KH_DL_VS_SLOTS; ++khd_vs) {
        if (khd_vsb[khd_vs]) khd_vsb[khd_vs]->Release();
    }
    khd_b11->Release();
}

inline void dynlights_census_fold() {
    g_dl_cd_distinct_last = g_dl_cd_n;
    if (g_dl_cd_n > g_dl_cd_distinct_max) g_dl_cd_distinct_max = g_dl_cd_n;
    g_dl_cd_null_last = g_dl_cd_null;
    g_dl_cd_samples_last = g_dl_cd_samples;
    g_dl_cd_n = 0;
    g_dl_cd_null = 0;
    g_dl_cd_samples = 0;
}

// Structural affine test shared by the derivation, in FOUR packings (the 4x3
// forms joined after a field census found ZERO world-matrix candidates: the
// engine packs transforms the way this file's own shadow matrices are packed
// - '3 rows of [a, b, c, t]' - which a 4x4-with- (0,0,0,1)-lane test can
// never see; the same census identified the rotation-matching 4x4s as
// translation-STRIPPED view rotations, their Y-reject delta equal to the
// camera's full height): 0 = 4x4, the file's row-vector convention ((0,0,0,1)
// column checked) 1 = 4x4 transposed / HLSL column-major default (lane
// checked) 2 = 4x3 in 3 registers, column-major rows [a, b, c, t] - the
// shadow_mats convention: V[i][k] = reg_k[i], V[3][k] = reg_k[3] 3 = 4 row
// registers with LIVE xyz and dead w lanes (row-major 3x4) Forms 2/3 have no
// lane to check; the orthonormal rotation here and the Y + grid proof
// downstream carry the discrimination.
inline uint32_t dl_form_floats(uint8_t khd_form) { return khd_form == 2 ? 12u : 16u; }

inline bool dl_cand_structure(const float* khd_mf, uint8_t khd_form, float (&khd_v)[4][4]) {
    if (khd_form <= 1) {
        for (int i = 0; i < 4; ++i) {
            for (int k = 0; k < 4; ++k) {
                khd_v[i][k] = khd_form == 0 ? khd_mf[i * 4 + k] : khd_mf[k * 4 + i];
            }
        }

        if (fabsf(khd_v[0][3]) > 0.001f || fabsf(khd_v[1][3]) > 0.001f ||
            fabsf(khd_v[2][3]) > 0.001f || fabsf(khd_v[3][3] - 1.0f) > 0.001f) {
            return false;
        }
    } else if (khd_form == 2) {
        for (int k = 0; k < 3; ++k) {
            khd_v[0][k] = khd_mf[k * 4 + 0];
            khd_v[1][k] = khd_mf[k * 4 + 1];
            khd_v[2][k] = khd_mf[k * 4 + 2];
            khd_v[3][k] = khd_mf[k * 4 + 3];
            khd_v[k][3] = 0.0f;
        }

        khd_v[3][3] = 1.0f;
    } else {
        for (int i = 0; i < 4; ++i) {
            khd_v[i][0] = khd_mf[i * 4 + 0];
            khd_v[i][1] = khd_mf[i * 4 + 1];
            khd_v[i][2] = khd_mf[i * 4 + 2];
            khd_v[i][3] = 0.0f;
        }

        khd_v[3][3] = 1.0f;
    }

    for (int r = 0; r < 3; ++r) {
        const float khd_n2 = khd_v[r][0] * khd_v[r][0] + khd_v[r][1] * khd_v[r][1] +
                             khd_v[r][2] * khd_v[r][2];
        if (khd_n2 < 0.96f || khd_n2 > 1.04f) return false;
    }

    for (int a = 0; a < 3; ++a) {
        for (int b = a + 1; b < 3; ++b) {
            const float khd_d = khd_v[a][0] * khd_v[b][0] + khd_v[a][1] * khd_v[b][1] +
                                khd_v[a][2] * khd_v[b][2];
            if (fabsf(khd_d) > 0.02f) return false;
        }
    }

    return true;
}

inline bool dl_rot_matches(const float (&khd_v)[4][4], const float* khd_cols) {
    for (int j = 0; j < 3; ++j) {
        for (int k = 0; k < 3; ++k) {
            if (fabsf(khd_v[j][k] - khd_cols[k * 4 + j]) > KH_DL_DERIVE_ROT_TOL) return false;
        }
    }

    return true;
}

inline bool dl_rot_identity(const float (&khd_v)[4][4]) {
    for (int j = 0; j < 3; ++j) {
        for (int k = 0; k < 3; ++k) {
            const float khd_want = j == k ? 1.0f : 0.0f;
            if (fabsf(khd_v[j][k] - khd_want) > KH_DL_DERIVE_ROT_TOL) return false;
        }
    }

    return true;
}

// The frame-structure proof shared by every route: Y delta ~ 0 (heights are
// absolute in the list frame) and X/Z on the 100 m grid, with per-route
// tolerances (matrix pairs inherit lamp-class slack; bare triples must be
// near-exact - a random constant must not fake a camera). Rejects log the Y
// delta.
inline bool dl_origin_validate(float khd_ex, float khd_ey, float khd_ez, bool khd_pair,
                               float khd_ytol, float khd_gtol,
                               float& khd_ox, float& khd_oz, float& khd_res) {
    if (fabsf(khd_ey) > khd_ytol) {
        if (khd_pair) g_dl.vs_pair_y_rejects++; else g_dl.vs_y_rejects++;
        g_dl.vs_last_ydelta = khd_ey;
        return false;
    }

    const float khd_sx = floorf(khd_ex / KH_DL_ORIGIN_Q + 0.5f) * KH_DL_ORIGIN_Q;
    const float khd_sz = floorf(khd_ez / KH_DL_ORIGIN_Q + 0.5f) * KH_DL_ORIGIN_Q;
    const float khd_rx = fabsf(khd_ex - khd_sx);
    const float khd_rz = fabsf(khd_ez - khd_sz);

    if (khd_rx > khd_gtol || khd_rz > khd_gtol) {
        if (khd_pair) g_dl.vs_pair_grid_rejects++; else g_dl.vs_grid_rejects++;
        return false;
    }

    khd_ox = khd_sx;
    khd_oz = khd_sz;
    khd_res = khd_rx > khd_rz ? khd_rx : khd_rz;
    return true;
}

inline void dl_cand_record(const DlWindowMeta& khd_m, uint8_t khd_kind, int32_t khd_slot,
                           uint32_t khd_off, float khd_ox, float khd_oz, float khd_res,
                           float khd_yd) {
    DlCandRec& khd_c = g_dl.cand_ring[g_dl.cand_head++ % 256u];
    khd_c.t_ms = steady_now_ms();
    khd_c.buf_lo = static_cast<uint32_t>(reinterpret_cast<uintptr_t>(khd_m.buf));
    khd_c.kind = khd_kind;
    khd_c.slot = static_cast<int8_t>(khd_slot);
    khd_c.off = static_cast<uint16_t>(khd_off);
    khd_c.ox = khd_ox;
    khd_c.oz = khd_oz;
    khd_c.res = khd_res;
    khd_c.ydelta = khd_yd;
}

inline bool dynlights_derive_origin(const uint8_t* khd_win, const DlWindowMeta& khd_m, int khd_side,
                                    const float* khd_recs, uint32_t khd_rec_n,
                                    float& khd_ox, float& khd_oz, float& khd_res,
                                    int32_t& khd_slot_out, int32_t& khd_wslot_out) {
    if (!g_dl.arena_view_ok[khd_side]) {
        g_dl.vs_noref++;
        return false;
    }

    g_dl.vs_scans++;
    const float* khd_bcols = g_dl.arena_view[khd_side];
    const float* khd_bcam = g_dl.arena_cam[khd_side];
    const uint8_t* khd_vs_base = khd_win + KH_DL_STAGE_BYTES;

    auto khd_block = [&](int32_t khd_s) {
        return reinterpret_cast<const float*>(khd_vs_base + khd_s * KH_DL_VS_BYTES);
    };

    // Applied at candidate SELECTION and in the hint - impostors die at
    // candidacy and can never lock in.
    const float* khd_rec0 = nullptr;

    for (uint32_t i = 0; i < khd_rec_n; ++i) {
        const float* khd_rr = khd_recs + i * 24;

        if (dl_finite(khd_rr[0]) && dl_finite(khd_rr[1]) && dl_finite(khd_rr[2])) {
            khd_rec0 = khd_rr;
            break;
        }
    }

    auto khd_range_ok = [&](float khd_cox, float khd_coz) {
        if (!khd_rec0) return true;
        const float khd_rx = khd_cox + khd_rec0[0] - khd_bcam[0];
        const float khd_rz = khd_coz + khd_rec0[2] - khd_bcam[2];

        if (khd_rx * khd_rx + khd_rz * khd_rz > 3000.0f * 3000.0f) {
            g_dl.vs_range_prunes++;
            return false;
        }

        return true;
    };

    // best-candidate accumulators: RESIDUAL is the rank (the origin-flap
    // lesson: the matrix-over-triple preference let 0.29 m impostors outrank
    // 0.002 m truth); the authorship ceiling gates every offer; zero-origin
    // tracked separately (the degeneracy bin).
    float khd_b_ox = 0.0f, khd_b_oz = 0.0f, khd_b_res = 1.0e9f;
    int32_t khd_b_slot = -1, khd_b_wslot = -1;
    uint32_t khd_b_off = 0, khd_b_woff = 0;
    uint8_t khd_b_form = 0, khd_b_wform = 0, khd_b_kind = 0;
    bool khd_have_nz = false, khd_have_z = false;
    float khd_z_res = 1.0e9f;

    auto khd_offer = [&](float ox, float oz, float res, uint8_t kind,
                         int32_t slot, uint32_t off, uint8_t form,
                         int32_t wslot, uint32_t woff, uint8_t wform) {
        if (res > KH_DL_ORIGIN_RES_MAX) return;   // impostor class: never authors
        if (!khd_range_ok(ox, oz)) return;   // structural impostors die here

        if (ox == 0.0f && oz == 0.0f) {
            khd_have_z = true;
            if (res < khd_z_res) khd_z_res = res;
            return;
        }

        if (!khd_have_nz || res < khd_b_res) {
            khd_have_nz = true;
            khd_b_ox = ox; khd_b_oz = oz; khd_b_res = res;
            khd_b_kind = kind;
            khd_b_slot = slot; khd_b_off = off; khd_b_form = form;
            khd_b_wslot = wslot; khd_b_woff = woff; khd_b_wform = wform;
        }
    };

    float khd_tox, khd_toz, khd_tres;

    // memoized fast path (non-zero winners only ever memoize)
    if (g_dl.vs_hint_slot >= 0 && g_dl.vs_hint_slot < static_cast<int32_t>(KH_DL_VS_SLOTS)) {
        const uint32_t khd_mfl = khd_m.vs_bytes[g_dl.vs_hint_slot] / 4u;
        bool khd_hit = false;

        if (g_dl.vs_hint_kind == 2) {
            if (g_dl.vs_hint_off + 4 <= khd_mfl) {
                const float* khd_t = khd_block(g_dl.vs_hint_slot) + g_dl.vs_hint_off;

                if (dl_finite(khd_t[0]) && dl_finite(khd_t[1]) && dl_finite(khd_t[2]) &&
                    dl_origin_validate(khd_bcam[0] - khd_t[0], khd_bcam[1] - khd_t[1],
                                       khd_bcam[2] - khd_t[2], true, 0.5f, 0.25f,
                                       khd_tox, khd_toz, khd_tres) &&
                    khd_tres <= KH_DL_ORIGIN_RES_MAX &&
                    khd_range_ok(khd_tox, khd_toz) &&
                    !(khd_tox == 0.0f && khd_toz == 0.0f)) {
                    khd_hit = true;
                }
            }
        } else if (g_dl.vs_hint_kind == 3 && g_dl.vs_hint_wslot >= 0 &&
                   g_dl.vs_hint_wslot < static_cast<int32_t>(KH_DL_VS_SLOTS)) {
            const uint32_t khd_wfl = khd_m.vs_bytes[g_dl.vs_hint_wslot] / 4u;

            if (g_dl.vs_hint_off + 4 <= khd_mfl &&
                g_dl.vs_hint_woff + dl_form_floats(g_dl.vs_hint_wform) <= khd_wfl) {
                const float* khd_t = khd_block(g_dl.vs_hint_slot) + g_dl.vs_hint_off;
                float khd_vw[4][4];

                if (dl_finite(khd_t[0]) && dl_finite(khd_t[1]) && dl_finite(khd_t[2]) &&
                    dl_cand_structure(khd_block(g_dl.vs_hint_wslot) + g_dl.vs_hint_woff,
                                      g_dl.vs_hint_wform, khd_vw) &&
                    dl_rot_identity(khd_vw) &&
                    dl_origin_validate(khd_vw[3][0] - khd_t[0], khd_vw[3][1] - khd_t[1],
                                       khd_vw[3][2] - khd_t[2], true, 0.5f, 0.25f,
                                       khd_tox, khd_toz, khd_tres) &&
                    khd_tres <= KH_DL_ORIGIN_RES_MAX &&
                    khd_range_ok(khd_tox, khd_toz) &&
                    !(khd_tox == 0.0f && khd_toz == 0.0f)) {
                    khd_hit = true;
                }
            }
        } else if (g_dl.vs_hint_kind == 1 && g_dl.vs_hint_wslot >= 0 &&
                   g_dl.vs_hint_wslot < static_cast<int32_t>(KH_DL_VS_SLOTS)) {
            const uint32_t khd_wfl = khd_m.vs_bytes[g_dl.vs_hint_wslot] / 4u;

            if (g_dl.vs_hint_off + dl_form_floats(g_dl.vs_hint_form) <= khd_mfl &&
                g_dl.vs_hint_woff + dl_form_floats(g_dl.vs_hint_wform) <= khd_wfl) {
                float khd_vm[4][4], khd_vw[4][4];

                if (dl_cand_structure(khd_block(g_dl.vs_hint_slot) + g_dl.vs_hint_off,
                                      g_dl.vs_hint_form, khd_vm) &&
                    dl_rot_matches(khd_vm, khd_bcols) &&
                    dl_cand_structure(khd_block(g_dl.vs_hint_wslot) + g_dl.vs_hint_woff,
                                      g_dl.vs_hint_wform, khd_vw) &&
                    dl_rot_identity(khd_vw)) {
                    float khd_cam[3];
                    extract_camera_pos(khd_vm, khd_cam);

                    if (dl_finite(khd_cam[0]) && dl_finite(khd_cam[1]) && dl_finite(khd_cam[2]) &&
                        dl_origin_validate(khd_bcam[0] - khd_cam[0] - khd_vw[3][0],
                                           khd_bcam[1] - khd_cam[1] - khd_vw[3][1],
                                           khd_bcam[2] - khd_cam[2] - khd_vw[3][2],
                                           true, KH_DL_DERIVE_Y_TOL, KH_DL_DERIVE_GRID_TOL,
                                           khd_tox, khd_toz, khd_tres) &&
                        khd_tres <= KH_DL_ORIGIN_RES_MAX &&
                        khd_range_ok(khd_tox, khd_toz) &&
                        !(khd_tox == 0.0f && khd_toz == 0.0f)) {
                        khd_hit = true;
                    }
                }
            }
        }

        if (khd_hit) {
            khd_ox = khd_tox;
            khd_oz = khd_toz;
            khd_res = khd_tres;
            khd_slot_out = g_dl.vs_hint_slot;
            khd_wslot_out = g_dl.vs_hint_wslot;
            g_dl.vs_hint_hits++;
            g_dl.vs_valid++;
            return true;
        }
    }

    // full scan: matrices first
    struct DlMvCand { float cam[3]; int32_t slot; uint32_t off; uint8_t form; };
    struct DlWCand { float t[3]; int32_t slot; uint32_t off; uint8_t form; };
    DlMvCand khd_mv[8];
    DlWCand khd_wm[8];
    uint32_t khd_mv_n = 0, khd_wm_n = 0;

    for (uint32_t khd_s = 0; khd_s < KH_DL_VS_SLOTS; ++khd_s) {
        const uint32_t khd_fl = khd_m.vs_bytes[khd_s] / 4u;
        if (khd_fl < 12) continue;
        const float* khd_base = khd_block(static_cast<int32_t>(khd_s));

        for (uint32_t khd_off = 0; khd_off + 12 <= khd_fl; khd_off += 4) {
            for (uint8_t khd_form = 0; khd_form < 4; ++khd_form) {
                if (khd_off + dl_form_floats(khd_form) > khd_fl) continue;
                float khd_v[4][4];
                if (!dl_cand_structure(khd_base + khd_off, khd_form, khd_v)) continue;
                g_dl.vs_ortho_pass++;

                if (dl_rot_matches(khd_v, khd_bcols)) {
                    float khd_cam[3];
                    extract_camera_pos(khd_v, khd_cam);

                    if (!dl_finite(khd_cam[0]) || !dl_finite(khd_cam[1]) || !dl_finite(khd_cam[2])) {
                        continue;
                    }

                    if (dl_origin_validate(khd_bcam[0] - khd_cam[0], khd_bcam[1] - khd_cam[1],
                                           khd_bcam[2] - khd_cam[2], false,
                                           KH_DL_DERIVE_Y_TOL, KH_DL_DERIVE_GRID_TOL,
                                           khd_tox, khd_toz, khd_tres)) {
                        dl_cand_record(khd_m, 0, static_cast<int32_t>(khd_s), khd_off,
                                       khd_tox, khd_toz, khd_tres, 0.0f);
                        khd_offer(khd_tox, khd_toz, khd_tres, static_cast<uint8_t>(0),
                                  static_cast<int32_t>(khd_s), khd_off, khd_form, -1, 0, 0);
                    }

                    if (khd_mv_n < 8) {
                        khd_mv[khd_mv_n].cam[0] = khd_cam[0];
                        khd_mv[khd_mv_n].cam[1] = khd_cam[1];
                        khd_mv[khd_mv_n].cam[2] = khd_cam[2];
                        khd_mv[khd_mv_n].slot = static_cast<int32_t>(khd_s);
                        khd_mv[khd_mv_n].off = khd_off;
                        khd_mv[khd_mv_n].form = khd_form;
                        khd_mv_n++;
                    }
                } else if (dl_rot_identity(khd_v)) {
                    if (dl_finite(khd_v[3][0]) && dl_finite(khd_v[3][1]) && dl_finite(khd_v[3][2]) &&
                        fabsf(khd_v[3][0]) < 1.0e7f && fabsf(khd_v[3][1]) < 1.0e7f &&
                        fabsf(khd_v[3][2]) < 1.0e7f && khd_wm_n < 8) {
                        khd_wm[khd_wm_n].t[0] = khd_v[3][0];
                        khd_wm[khd_wm_n].t[1] = khd_v[3][1];
                        khd_wm[khd_wm_n].t[2] = khd_v[3][2];
                        khd_wm[khd_wm_n].slot = static_cast<int32_t>(khd_s);
                        khd_wm[khd_wm_n].off = khd_off;
                        khd_wm[khd_wm_n].form = khd_form;
                        khd_wm_n++;
                    }
                } else {
                    g_dl.vs_rot_rejects++;
                }
            }
        }
    }

    // kind 1: MV x W pairs (W' light-frame yields the origin; W true yields
    // the tracked (0,0) degeneracy)
    for (uint32_t a = 0; a < khd_mv_n; ++a) {
        for (uint32_t b = 0; b < khd_wm_n; ++b) {
            g_dl.vs_pair_tries++;

            if (dl_origin_validate(khd_bcam[0] - khd_mv[a].cam[0] - khd_wm[b].t[0],
                                   khd_bcam[1] - khd_mv[a].cam[1] - khd_wm[b].t[1],
                                   khd_bcam[2] - khd_mv[a].cam[2] - khd_wm[b].t[2],
                                   true, KH_DL_DERIVE_Y_TOL, KH_DL_DERIVE_GRID_TOL,
                                   khd_tox, khd_toz, khd_tres)) {
                g_dl.vs_pair_valid++;
                dl_cand_record(khd_m, 1, khd_mv[a].slot, khd_mv[a].off,
                               khd_tox, khd_toz, khd_tres, 0.0f);
                khd_offer(khd_tox, khd_toz, khd_tres, 1,
                          khd_mv[a].slot, khd_mv[a].off, khd_mv[a].form,
                          khd_wm[b].slot, khd_wm[b].off, khd_wm[b].form);
            }
        }
    }

    // kinds 2/3: bare float triples (tight tolerances - a round constant must
    // not fake a camera or an object position)
    for (uint32_t khd_s = 0; khd_s < KH_DL_VS_SLOTS; ++khd_s) {
        const uint32_t khd_fl = khd_m.vs_bytes[khd_s] / 4u;
        if (khd_fl < 4) continue;
        const float* khd_base = khd_block(static_cast<int32_t>(khd_s));

        for (uint32_t khd_off = 0; khd_off + 4 <= khd_fl; khd_off += 4) {
            const float* khd_t = khd_base + khd_off;

            if (!dl_finite(khd_t[0]) || !dl_finite(khd_t[1]) || !dl_finite(khd_t[2])) continue;
            if (fabsf(khd_t[0]) > 1.0e7f || fabsf(khd_t[1]) > 1.0e7f || fabsf(khd_t[2]) > 1.0e7f) continue;

            // kind 2: T = camera in the light frame
            if (dl_origin_validate(khd_bcam[0] - khd_t[0], khd_bcam[1] - khd_t[1],
                                   khd_bcam[2] - khd_t[2], true, 0.5f, 0.25f,
                                   khd_tox, khd_toz, khd_tres)) {
                g_dl.vs_triple_valid++;
                dl_cand_record(khd_m, 2, static_cast<int32_t>(khd_s), khd_off,
                               khd_tox, khd_toz, khd_tres, 0.0f);
                khd_offer(khd_tox, khd_toz, khd_tres, 2,
                          static_cast<int32_t>(khd_s), khd_off, 0, -1, 0, 0);
            }

            // kind 3: T = object position in the light frame, against each
            // true-world W translation
            for (uint32_t b = 0; b < khd_wm_n; ++b) {
                if (dl_origin_validate(khd_wm[b].t[0] - khd_t[0], khd_wm[b].t[1] - khd_t[1],
                                       khd_wm[b].t[2] - khd_t[2], true, 0.5f, 0.25f,
                                       khd_tox, khd_toz, khd_tres)) {
                    g_dl.vs_triple_valid++;
                    dl_cand_record(khd_m, 3, static_cast<int32_t>(khd_s), khd_off,
                                   khd_tox, khd_toz, khd_tres, 0.0f);
                    khd_offer(khd_tox, khd_toz, khd_tres, 3,
                              static_cast<int32_t>(khd_s), khd_off, 0,
                              khd_wm[b].slot, khd_wm[b].off, khd_wm[b].form);
                }
            }
        }
    }

    if (khd_have_nz) {
        khd_ox = khd_b_ox;
        khd_oz = khd_b_oz;
        khd_res = khd_b_res;
        khd_slot_out = khd_b_slot;
        khd_wslot_out = khd_b_wslot;
        g_dl.vs_hint_kind = khd_b_kind;
        g_dl.vs_hint_slot = khd_b_slot;
        g_dl.vs_hint_off = khd_b_off;
        g_dl.vs_hint_form = khd_b_form;
        g_dl.vs_hint_wslot = khd_b_wslot;
        g_dl.vs_hint_woff = khd_b_woff;
        g_dl.vs_hint_wform = khd_b_wform;
        g_dl.vs_nonzero_origins++;
        g_dl.vs_valid++;
        return true;
    }

    if (khd_have_z && khd_range_ok(0.0f, 0.0f)) {
        // the true-world degeneracy: accepted only alone, never memoized, and
        // only when it places this list near the camera like any other
        // candidate (the range arbiter applies to everyone)
        khd_ox = 0.0f;
        khd_oz = 0.0f;
        khd_res = khd_z_res;
        khd_slot_out = -1;
        khd_wslot_out = -1;
        g_dl.vs_zero_origins++;
        g_dl.vs_valid++;
        return true;
    }

    return false;
}

// Anchor-table upsert: exact-derivation lights become long-lived surveying
// knowledge. Match-in-place refresh; oldest evicted when full.
inline void dynlights_anchor_upsert(float khd_x, float khd_y, float khd_z, uint64_t khd_now) {
    int khd_oldest = 0;

    for (uint32_t a = 0; a < g_dl.anchor_n; ++a) {
        if (fabsf(g_dl.anchor_pos[a][0] - khd_x) < KH_DL_MATCH_M &&
            fabsf(g_dl.anchor_pos[a][1] - khd_y) < KH_DL_MATCH_M &&
            fabsf(g_dl.anchor_pos[a][2] - khd_z) < KH_DL_MATCH_M) {
            g_dl.anchor_pos[a][0] = khd_x;
            g_dl.anchor_pos[a][1] = khd_y;
            g_dl.anchor_pos[a][2] = khd_z;
            g_dl.anchor_stamp[a] = khd_now;
            return;
        }

        if (g_dl.anchor_stamp[a] < g_dl.anchor_stamp[khd_oldest]) khd_oldest = static_cast<int>(a);
    }

    uint32_t khd_slot;

    if (g_dl.anchor_n < KH_DL_ANCHOR_N) {
        khd_slot = g_dl.anchor_n++;
    } else {
        khd_slot = static_cast<uint32_t>(khd_oldest);
    }

    g_dl.anchor_pos[khd_slot][0] = khd_x;
    g_dl.anchor_pos[khd_slot][1] = khd_y;
    g_dl.anchor_pos[khd_slot][2] = khd_z;
    g_dl.anchor_stamp[khd_slot] = khd_now;
}

inline bool dynlights_pool_vote(const float* khd_l, uint32_t khd_total,
                                float& khd_ox, float& khd_oz, DlWinReport& khd_rep) {
    if (g_dl.anchor_n == 0 || khd_total == 0) return false;
    float khd_cox[8], khd_coz[8], khd_cres[8];
    uint32_t khd_cv[8], khd_cn = 0;

    for (uint32_t i = 0; i < khd_total; ++i) {
        const float* khd_r = khd_l + i * 24;
        if (!dl_finite(khd_r[0]) || !dl_finite(khd_r[1]) || !dl_finite(khd_r[2])) continue;

        for (uint32_t d = 0; d < g_dl.anchor_n; ++d) {
            // THE LATTICE LESSON stands: anchors are derivation-written only
            // - exogenous truth, never the vote's own output - now in a
            // dedicated LONG-LIVED table (surveying knowledge), decoupled
            // from the shading pool's cadence expiry.
            if (fabsf(g_dl.anchor_pos[d][1] - khd_r[1]) > 0.25f) continue;   // same light: identical Y
            const float khd_ex = g_dl.anchor_pos[d][0] - khd_r[0];
            const float khd_ez = g_dl.anchor_pos[d][2] - khd_r[2];
            const float khd_sx = floorf(khd_ex / KH_DL_ORIGIN_Q + 0.5f) * KH_DL_ORIGIN_Q;
            const float khd_sz = floorf(khd_ez / KH_DL_ORIGIN_Q + 0.5f) * KH_DL_ORIGIN_Q;
            const float khd_rx = fabsf(khd_ex - khd_sx);
            const float khd_rz = fabsf(khd_ez - khd_sz);
            if (khd_rx > KH_DL_ORIGIN_RES_MAX || khd_rz > KH_DL_ORIGIN_RES_MAX) continue;
            const float khd_res = khd_rx > khd_rz ? khd_rx : khd_rz;
            bool khd_found = false;

            for (uint32_t c = 0; c < khd_cn; ++c) {
                if (khd_cox[c] == khd_sx && khd_coz[c] == khd_sz) {
                    khd_cv[c]++;
                    if (khd_res < khd_cres[c]) khd_cres[c] = khd_res;
                    khd_found = true;
                    break;
                }
            }

            if (!khd_found && khd_cn < 8) {
                khd_cox[khd_cn] = khd_sx;
                khd_coz[khd_cn] = khd_sz;
                khd_cres[khd_cn] = khd_res;
                khd_cv[khd_cn] = 1;
                khd_cn++;
            }
        }
    }

    int khd_best = -1;

    for (uint32_t c = 0; c < khd_cn; ++c) {
        if (khd_best < 0 ||
            khd_cv[c] > khd_cv[khd_best] ||
            (khd_cv[c] == khd_cv[khd_best] && khd_cres[c] < khd_cres[khd_best])) {
            khd_best = static_cast<int>(c);
        }
    }

    if (khd_best < 0) return false;
    uint32_t khd_runner = 0;

    for (uint32_t c = 0; c < khd_cn; ++c) {
        if (static_cast<int>(c) != khd_best && khd_cv[c] > khd_runner) khd_runner = khd_cv[c];
    }

    khd_rep.v_best = static_cast<uint16_t>(khd_cv[khd_best]);
    khd_rep.v_runner = static_cast<uint16_t>(khd_runner);
    khd_rep.v_cands = static_cast<uint16_t>(khd_cn);
    khd_rep.v_res = khd_cres[khd_best];

    // unambiguous majority, or a lone near-ULP candidate (plant-class)
    const bool khd_clear = khd_cv[khd_best] >= 2 && khd_cv[khd_best] >= khd_runner + 2;
    const bool khd_lone = khd_cn == 1 && khd_cres[khd_best] <= 0.005f;

    if (!khd_clear && !khd_lone) {
        g_dl.origin_vote_ambiguous++;
        return false;
    }

    khd_ox = khd_cox[khd_best];
    khd_oz = khd_coz[khd_best];
    return true;
}

// Unresolved windows are dropped and counted - never guessed. Origin recovery
// + PERSISTENT union merge for one harvested arena side.
inline void dynlights_merge_windows(const uint8_t* khd_base, int khd_side) {
    g_dl.win_report_n = 0;
    const uint64_t khd_now = steady_now_ms();
    const uint64_t khd_anchored0 = g_dl.lists_anchored;
    float khd_best_lum = -1.0f;
    float khd_best_g[3] = { 1.0f, 1.0f, 1.0f };
    float khd_best_s = 1.0f;
    const uint64_t khd_added0 = g_dl.pool_added;
    const uint64_t khd_updated0 = g_dl.pool_updated;
    const uint64_t khd_expired0 = g_dl.pool_expired;
    const uint64_t khd_flips0 = g_dl.pool_spot_flips;

    {   // anchor-table sweep: long TTL, movers-only concern
        uint32_t khd_ak = 0;

        for (uint32_t a = 0; a < g_dl.anchor_n; ++a) {
            if (khd_now - g_dl.anchor_stamp[a] > KH_DL_ANCHOR_TTL_MS) continue;

            if (khd_ak != a) {
                g_dl.anchor_pos[khd_ak][0] = g_dl.anchor_pos[a][0];
                g_dl.anchor_pos[khd_ak][1] = g_dl.anchor_pos[a][1];
                g_dl.anchor_pos[khd_ak][2] = g_dl.anchor_pos[a][2];
                g_dl.anchor_stamp[khd_ak] = g_dl.anchor_stamp[a];
            }

            khd_ak++;
        }

        g_dl.anchor_n = khd_ak;
    }

    {   // TTL sweep first: compact out entries not re-sighted in time
        uint32_t khd_keep = 0;

        for (uint32_t i = 0; i < g_dl.pool_n; ++i) {
            const DlPoolLight& khd_e = g_dl.pool[i];
            uint64_t khd_ttl;

            if (khd_e.gap_max_ms == 0) {
                khd_ttl = KH_DL_TTL_FLOOR_MS;   // single sighting: no cadence evidence yet
            } else {
                khd_ttl = kh_dl_gap_mult() * static_cast<uint64_t>(khd_e.gap_max_ms);
                const uint64_t khd_floor = kh_dl_dense(khd_e.sightings, khd_e.gap_max_ms)
                                         ? KH_DL_TTL_DENSE_FLOOR_MS : KH_DL_TTL_FLOOR_MS;
                if (khd_ttl < khd_floor) khd_ttl = khd_floor;
                if (khd_ttl > KH_DL_TTL_CAP_MS) khd_ttl = KH_DL_TTL_CAP_MS;
            }

            if (khd_now - khd_e.stamp > khd_ttl) {
                g_dl.pool_expired++;

                if (g_diag_armed.load(std::memory_order_relaxed)) {   // census
                    DlExpiry& khd_x = g_dl_exp[g_dl_exp_head];
                    khd_x = DlExpiry{};
                    khd_x.life_ms = khd_e.first_ms != 0 && khd_e.stamp >= khd_e.first_ms
                                  ? static_cast<uint32_t>(khd_e.stamp - khd_e.first_ms) : 0u;
                    khd_x.tail_ms = static_cast<uint32_t>(khd_now - khd_e.stamp);
                    khd_x.ttl_ms = static_cast<uint32_t>(khd_ttl);
                    khd_x.gap_max_ms = khd_e.gap_max_ms;
                    khd_x.sightings = khd_e.sightings;
                    khd_x.dense = (khd_e.gap_max_ms != 0 &&
                                   kh_dl_dense(khd_e.sightings, khd_e.gap_max_ms)) ? 1 : 0;
                    khd_x.floored = (khd_e.gap_max_ms == 0 ||
                                     kh_dl_gap_mult() * static_cast<uint64_t>(khd_e.gap_max_ms)
                                         < khd_ttl) ? 1 : 0;
                    g_dl_exp_head = (g_dl_exp_head + 1) % KH_DL_EXP_RING;
                    g_dl_exp_n++;
                    if (khd_x.floored) g_dl_exp_floor_hits++;
                    if (khd_x.dense) g_dl_exp_dense_hits++;
                    g_dl_exp_tail_sum += khd_x.tail_ms;
                    g_dl_exp_life_sum += khd_x.life_ms;
                    if (khd_x.tail_ms < g_dl_exp_tail_min) g_dl_exp_tail_min = khd_x.tail_ms;
                    if (khd_x.tail_ms > g_dl_exp_tail_max) g_dl_exp_tail_max = khd_x.tail_ms;
                }

                continue;
            }

            if (khd_keep != i) g_dl.pool[khd_keep] = g_dl.pool[i];
            khd_keep++;
        }

        g_dl.pool_n = khd_keep;
    }

    const uint32_t khd_wn = g_dl.win_count[khd_side];

    for (uint32_t w = 0; w < khd_wn && w < KH_DL_WIN_MAX; ++w) {
        const DlWindowMeta& khd_m = g_dl.win_meta[khd_side][w];
        const uint8_t* khd_p = khd_base + w * KH_DL_WIN_BYTES;
        float khd_ctl[16];
        memcpy(khd_ctl, khd_p, sizeof(khd_ctl));
        int32_t khd_pc_i = 0, khd_sc_i = 0;
        memcpy(&khd_pc_i, khd_p + 0, 4);
        memcpy(&khd_sc_i, khd_p + 16, 4);

        if (khd_pc_i < 0 || khd_pc_i > 1024 || khd_sc_i < 0 || khd_sc_i > 1024 ||
            !dl_finite(khd_ctl[8]) || khd_ctl[8] <= 1.0e-6f || khd_ctl[8] >= 1.0e6f) {
            g_dl.val_rejects++;
            continue;
        }

        uint32_t khd_pc = static_cast<uint32_t>(khd_pc_i);
        uint32_t khd_sc = static_cast<uint32_t>(khd_sc_i);
        uint32_t khd_total = khd_pc + khd_sc;

        if (khd_total > KH_DL_MAX_LIGHTS) {
            g_dl.clamped_counts++;
            if (khd_pc > KH_DL_MAX_LIGHTS) khd_pc = KH_DL_MAX_LIGHTS;
            khd_sc = KH_DL_MAX_LIGHTS - khd_pc;
            khd_total = KH_DL_MAX_LIGHTS;
        }

        const uint32_t khd_avail = khd_m.bytes11 / KH_DL_LIGHT_BYTES;

        if (khd_total > khd_avail) {
            if (khd_pc > khd_avail) khd_pc = khd_avail;
            khd_sc = khd_avail - khd_pc;
            khd_total = khd_avail;
        }

        DlWinReport& khd_rep = g_dl.win_report[g_dl.win_report_n < KH_DL_WIN_MAX
                                             ? g_dl.win_report_n++ : KH_DL_WIN_MAX - 1];
        khd_rep = DlWinReport{};
        khd_rep.buf = reinterpret_cast<uint64_t>(khd_m.buf);
        khd_rep.first = khd_m.first;
        khd_rep.point_n = khd_pc;
        khd_rep.spot_n = khd_sc;
        khd_rep.scale = khd_ctl[8];
        khd_rep.gdiff[0] = khd_ctl[12];
        khd_rep.gdiff[1] = khd_ctl[13];
        khd_rep.gdiff[2] = khd_ctl[14];
        {   // main-pass reference candidates: brightest ctl this harvest
            const float khd_lum = khd_ctl[12] + khd_ctl[13] + khd_ctl[14];

            if (dl_finite(khd_lum) && khd_lum > khd_best_lum) {
                khd_best_lum = khd_lum;
                khd_best_g[0] = khd_ctl[12];
                khd_best_g[1] = khd_ctl[13];
                khd_best_g[2] = khd_ctl[14];
                khd_best_s = khd_ctl[8];
            }
        }

        if (khd_total == 0) continue;
        const float* khd_l = reinterpret_cast<const float*>(khd_p + KH_DL_CTL_BYTES);

        float khd_dox = 0.0f, khd_doz = 0.0f, khd_dres = -1.0f;
        int32_t khd_dslot = -1, khd_dwslot = -1;
        const bool khd_derived_ok = dynlights_derive_origin(khd_p, khd_m, khd_side,
                                                            khd_l, khd_total,
                                                            khd_dox, khd_doz, khd_dres,
                                                            khd_dslot, khd_dwslot);
        khd_rep.derived_ok = khd_derived_ok ? 1 : 0;
        khd_rep.d_ox = khd_dox;
        khd_rep.d_oz = khd_doz;
        khd_rep.d_res = khd_dres;
        khd_rep.d_slot = khd_dslot;
        khd_rep.d_wslot = khd_dwslot;

        float khd_o_x = khd_dox;
        float khd_o_z = khd_doz;

        if (!khd_derived_ok) {
            // propagation: vote this window's records against the pool
            if (dynlights_pool_vote(khd_l, khd_total, khd_o_x, khd_o_z, khd_rep)) {
                g_dl.origin_pool_votes++;
                khd_rep.pool_vote = 1;
            } else {
                g_dl.lists_unanchored++;   // origin unresolved: authors nothing
                continue;
            }
        }

        // RANGE BACKSTOP (the (0,0) poisoning lesson): visible-light lists
        // are camera-culled by construction, so a decoded record landing
        // kilometers from the capture camera convicts the ORIGIN, whatever
        // route produced it. Applied to both routes; anchors cannot normally
        // trip it, and a tripped window authors nothing.
        if (khd_total > 0 && g_dl.arena_view_ok[khd_side]) {
            const float khd_r0x = khd_o_x + khd_l[0] - g_dl.arena_cam[khd_side][0];
            const float khd_r0z = khd_o_z + khd_l[2] - g_dl.arena_cam[khd_side][2];

            if (khd_r0x * khd_r0x + khd_r0z * khd_r0z > 3000.0f * 3000.0f) {
                g_dl.origin_range_rejects++;
                continue;
            }
        }

        g_dl.lists_anchored++;   // origin resolved (name kept; source is the derivation)
        khd_rep.origin_ok = 1;
        khd_rep.ox = khd_o_x;
        khd_rep.oz = khd_o_z;
        g_dl.pool_scale = khd_ctl[8];   // census of the last anchored window's
        g_dl.pool_gdiff[0] = khd_ctl[12];   // RAW globals (the dump/ring read these)
        g_dl.pool_gdiff[1] = khd_ctl[13];
        g_dl.pool_gdiff[2] = khd_ctl[14];

        // The trigger-window mirror is main-pass BY CONSTRUCTION (the
        // injection triggers inside the main pass); a window whose globals
        // diverge from that reference is AUX: alive for persistence, never an
        // author of content.
        bool khd_main = true;

        if (g_dl.main_ref_valid) {   // vs the max-luminance reference (one)
                                     // harvest of lag; brightness moves slowly)
            for (int khd_k = 0; khd_k < 3 && khd_main; ++khd_k) {
                const float khd_mref = g_dl.main_gdiff[khd_k];
                const float khd_tol = 0.5f * (fabsf(khd_mref) > 0.02f ? fabsf(khd_mref) : 0.02f);
                if (fabsf(khd_ctl[12 + khd_k] - khd_mref) > khd_tol) khd_main = false;
            }

            if (khd_main && fabsf(khd_ctl[8] - g_dl.main_scale) > 0.25f * fabsf(g_dl.main_scale)) {
                khd_main = false;
            }
        }

        if (!khd_main) g_dl.win_aux++;

        for (uint32_t i = 0; i < khd_total; ++i) {
            const float* khd_r = khd_l + i * 24;
            const float khd_wx = khd_rep.ox + khd_r[0];
            const float khd_wy = khd_r[1];
            const float khd_wz = khd_rep.oz + khd_r[2];
            if (!dl_finite(khd_wx) || !dl_finite(khd_wy) || !dl_finite(khd_wz)) continue;
            int khd_hit = -1;

            for (uint32_t d = 0; d < g_dl.pool_n; ++d) {
                if (fabsf(g_dl.pool[d].rec[0] - khd_wx) < KH_DL_MATCH_M &&
                    fabsf(g_dl.pool[d].rec[1] - khd_wy) < KH_DL_MATCH_M &&
                    fabsf(g_dl.pool[d].rec[2] - khd_wz) < KH_DL_MATCH_M) {
                    khd_hit = static_cast<int>(d);
                    break;
                }
            }

            if (khd_hit < 0) {
                if (g_dl.pool_n >= static_cast<uint32_t>(g_dl.pool.size())) {
                    g_dl.pool.push_back(DlPoolLight{});   // UNCAPPED growth
                }

                khd_hit = static_cast<int>(g_dl.pool_n++);
                g_dl.pool[khd_hit] = DlPoolLight{};   // the slot may hold a
                                                      // compacted-out ghost's stamps
                g_dl.pool_added++;
                if (!khd_main) g_dl.aux_adds++;   // provisional: main upgrades it
            } else if (!khd_main) {
                // AUX SIGHTING: keeps the entry alive (stamp + cadence),
                // never authors content - pass-darkened values must not
                // overwrite main-pass records (the fold era's flap).
                DlPoolLight& khd_ax = g_dl.pool[khd_hit];
                const uint64_t khd_gap = khd_now - khd_ax.stamp;
                khd_ax.gap_max_ms = kh_dl_gap_mark(khd_ax.gap_max_ms, khd_gap);
                if (khd_ax.sightings < 0xFFFF) khd_ax.sightings++;
                khd_ax.stamp = khd_now;
                g_dl.aux_refreshes++;
                continue;
            } else {
                g_dl.pool_updated++;
            }

            // Re-sight (main-pass, or first sight via aux) writes the WHOLE
            // record VERBATIM - live color/attenuation (animated fires keep
            // flickering), freshest position, and NO folded globals: the fold
            // era proved that baking any pass's cb10 into shared records
            // makes the pass alternation flap per-light.
            DlPoolLight& khd_pl = g_dl.pool[khd_hit];
            const uint8_t khd_spot_new = i >= khd_pc ? 1 : 0;

            if (khd_pl.stamp != 0) {
                if (khd_pl.spot != khd_spot_new) g_dl.pool_spot_flips++;
                const uint64_t khd_gap = khd_now - khd_pl.stamp;
                khd_pl.gap_max_ms = kh_dl_gap_mark(khd_pl.gap_max_ms, khd_gap);
                if (khd_pl.sightings < 0xFFFF) khd_pl.sightings++;
            } else {
                khd_pl.gap_max_ms = 0;
                khd_pl.sightings = 1;
                khd_pl.first_ms = khd_now;   // census: lifetime origin
            }
            memcpy(khd_pl.rec, khd_r, sizeof(khd_pl.rec));
            khd_pl.rec[0] = khd_wx;   // +0 rewritten to absolute world
            khd_pl.rec[1] = khd_wy;
            khd_pl.rec[2] = khd_wz;
            khd_pl.spot = khd_spot_new;
            khd_pl.aux = khd_main ? 0 : 1;   // a main sighting upgrades aux content
            if (khd_derived_ok) {
                khd_pl.derived = 1;   // upgrade-only provenance (diagnostics)

                if (khd_dres >= 0.0f && khd_dres <= KH_DL_ANCHOR_RES) {
                    dynlights_anchor_upsert(khd_wx, khd_wy, khd_wz, khd_now);
                    g_dl.anchor_admits++;
                } else {
                    g_dl.anchor_res_rejects++;
                }
            }

            khd_pl.stamp = khd_now;
        }
    }

    if (khd_best_lum > 0.0f) {   // empty harvests keep the last reference
        // In-band vs the standing reference adopts (tracks adaptation);
        // out-of-band holds and must agree with itself across the confirm
        // window to adopt.
        const float khd_cand_l = khd_best_g[0] + khd_best_g[1] + khd_best_g[2];
        const float khd_ref_l  = g_dl.main_gdiff[0] + g_dl.main_gdiff[1] + g_dl.main_gdiff[2];
        const bool khd_l_ok = !g_dl.main_ref_valid ||
            (khd_cand_l <= khd_ref_l * KH_DL_REF_BAND &&
             khd_ref_l  <= khd_cand_l * KH_DL_REF_BAND);
        const bool khd_s_ok = !g_dl.main_ref_valid ||
            (khd_best_s > 1.0e-6f && g_dl.main_scale > 1.0e-6f &&
             khd_best_s <= g_dl.main_scale * KH_DL_REF_BAND &&
             g_dl.main_scale <= khd_best_s * KH_DL_REF_BAND);
        bool khd_adopt = khd_l_ok && khd_s_ok;

        if (!khd_adopt) {
            const float khd_pl = g_dl.ref_pend_g[0] + g_dl.ref_pend_g[1] + g_dl.ref_pend_g[2];
            const bool khd_agree = g_dl.ref_pend_ms != 0 &&
                khd_pl > 0.0f && g_dl.ref_pend_s > 1.0e-6f && khd_best_s > 1.0e-6f &&
                khd_cand_l <= khd_pl * KH_DL_REF_BAND && khd_pl <= khd_cand_l * KH_DL_REF_BAND &&
                khd_best_s <= g_dl.ref_pend_s * KH_DL_REF_BAND &&
                g_dl.ref_pend_s <= khd_best_s * KH_DL_REF_BAND;

            if (khd_agree && khd_now - g_dl.ref_pend_ms >= KH_DL_REF_CONFIRM_MS) {
                khd_adopt = true;   // a persistent new exposure level
                g_dl.ref_jump_adopts++;
            } else {
                if (!khd_agree) {
                    g_dl.ref_pend_g[0] = khd_best_g[0];
                    g_dl.ref_pend_g[1] = khd_best_g[1];
                    g_dl.ref_pend_g[2] = khd_best_g[2];
                    g_dl.ref_pend_s = khd_best_s;
                    g_dl.ref_pend_ms = khd_now;
                }

                g_dl.ref_holds++;
            }
        }

        if (khd_adopt) {
            g_dl.main_gdiff[0] = khd_best_g[0];
            g_dl.main_gdiff[1] = khd_best_g[1];
            g_dl.main_gdiff[2] = khd_best_g[2];
            g_dl.main_scale = khd_best_s;
            g_dl.main_ref_valid = 1;
            g_dl.ref_pend_ms = 0;
        }
    }

    g_dl.pool_stamp = khd_now;

    {   // mode-3 harvest ring (flicker forensics): per-harvest deltas +
        // the last anchored window's RAW globals. The gdiff alternation this
        // ring caught (main ~0.5 grey vs a PiP/reflection pass's near-zero
        // blue at half cadence) named the pass structure the MAIN/AUX
        // classification now encodes.
        DlM3Ring& khd_mr = g_dl.m3_ring[g_dl.m3_ring_head++ % KH_DL_RING];
        khd_mr.t_ms = khd_now;
        khd_mr.pool_n = static_cast<uint16_t>(g_dl.pool_n);
        khd_mr.anchored = static_cast<uint16_t>(khd_anchored0 <= g_dl.lists_anchored
                        ? g_dl.lists_anchored - khd_anchored0 : 0);
        khd_mr.added = static_cast<uint16_t>(khd_added0 <= g_dl.pool_added
                     ? g_dl.pool_added - khd_added0 : 0);
        khd_mr.updated = static_cast<uint16_t>(khd_updated0 <= g_dl.pool_updated
                       ? g_dl.pool_updated - khd_updated0 : 0);
        khd_mr.expired = static_cast<uint16_t>(khd_expired0 <= g_dl.pool_expired
                       ? g_dl.pool_expired - khd_expired0 : 0);
        khd_mr.spot_flips = static_cast<uint16_t>(khd_flips0 <= g_dl.pool_spot_flips
                          ? g_dl.pool_spot_flips - khd_flips0 : 0);
        khd_mr.gdiff[0] = g_dl.pool_gdiff[0];
        khd_mr.gdiff[1] = g_dl.pool_gdiff[1];
        khd_mr.gdiff[2] = g_dl.pool_gdiff[2];
        khd_mr.scale = g_dl.win_report_n > 0
                     ? g_dl.win_report[g_dl.win_report_n - 1].scale : 0.0f;
    }
}

// Arena lifecycle at the injection: harvest the PREVIOUS frame's captures
// (DO_NOT_WAIT; a stall retries next injection WITHOUT flipping, so
// un-harvested copies are never overwritten), then flip sides so this frame's
// sampler writes the freshly drained buffer.
inline void dynlights_harvest_arena(ID3D11DeviceContext* ctx) {
    const int khd_r = g_dl.arena_write ^ 1;

    if (g_dl.arena_inflight[khd_r] && g_dl.arena[khd_r]) {
        D3D11_MAPPED_SUBRESOURCE khd_m = {};
        const HRESULT khd_hr = ctx->Map(g_dl.arena[khd_r], 0, D3D11_MAP_READ,
                                        D3D11_MAP_FLAG_DO_NOT_WAIT, &khd_m);

        if (FAILED(khd_hr)) {
            g_dl.still_drawing++;
            return;   // retry next injection; no flip
        }

        dynlights_merge_windows(static_cast<const uint8_t*>(khd_m.pData), khd_r);
        ctx->Unmap(g_dl.arena[khd_r], 0);
        g_dl.arena_inflight[khd_r] = 0;
    }

    // flip: the side the sampler filled this frame goes in flight; the
    // drained side becomes the new write target
    g_dl.arena_inflight[g_dl.arena_write] = g_dl.win_count[g_dl.arena_write] > 0 ? 1 : 0;
    g_dl.arena_write = khd_r;
    g_dl.win_count[khd_r] = 0;
    memset(g_dl.win_meta[khd_r], 0, sizeof(g_dl.win_meta[khd_r]));
}

// Counts read as INT BIT PATTERNS first (the disassembly's ige compare), with
// an integral-float fallback recorded by the census - the dump names which
// convention the engine actually used, so a wrong guess can never hide. Parse
// + validate + publish one completed staging readback.
inline void dynlights_publish(const uint8_t* khd_p, int khd_s) {
    float khd_ctl[16];
    memcpy(khd_ctl, khd_p, sizeof(khd_ctl));
    int32_t khd_pc_i = 0, khd_sc_i = 0;
    memcpy(&khd_pc_i, khd_p + 0, 4);   // cb10[0].x
    memcpy(&khd_sc_i, khd_p + 16, 4);   // cb10[1].x
    uint32_t khd_pc = 0, khd_sc = 0;
    uint8_t khd_as_float = 0;

    if (khd_pc_i >= 0 && khd_pc_i <= 1024 && khd_sc_i >= 0 && khd_sc_i <= 1024) {
        khd_pc = static_cast<uint32_t>(khd_pc_i);
        khd_sc = static_cast<uint32_t>(khd_sc_i);
    } else {
        const float khd_pf = khd_ctl[0], khd_sf = khd_ctl[4];

        if (dl_finite(khd_pf) && dl_finite(khd_sf) &&
            khd_pf >= 0.0f && khd_pf <= 1024.0f && khd_sf >= 0.0f && khd_sf <= 1024.0f &&
            khd_pf == floorf(khd_pf) && khd_sf == floorf(khd_sf)) {
            khd_pc = static_cast<uint32_t>(khd_pf);
            khd_sc = static_cast<uint32_t>(khd_sf);
            khd_as_float = 1;
            g_dl.counts_float++;
        } else {
            g_dl.val_rejects++;
            g_dl.last_rej[0] = khd_ctl[0];
            g_dl.last_rej[1] = khd_ctl[4];
            g_dl.last_rej[2] = khd_ctl[8];
            g_dl.last_rej[3] = 1.0f;   // reason: counts
            return;
        }
    }

    // Scale / global-diffuse sanity: a poisoned scale garbles every light's
    // attenuation - refuse the harvest rather than shade with it.
    if (!dl_finite(khd_ctl[8]) || khd_ctl[8] <= 1.0e-6f || khd_ctl[8] >= 1.0e6f ||
        !dl_finite(khd_ctl[12]) || !dl_finite(khd_ctl[13]) || !dl_finite(khd_ctl[14])) {
        g_dl.val_rejects++;
        g_dl.last_rej[0] = khd_ctl[0];
        g_dl.last_rej[1] = khd_ctl[4];
        g_dl.last_rej[2] = khd_ctl[8];
        g_dl.last_rej[3] = 2.0f;   // reason: scale/diffuse
        return;
    }

    uint32_t khd_total = khd_pc + khd_sc;

    if (khd_total > KH_DL_MAX_LIGHTS) {
        g_dl.clamped_counts++;
        if (khd_pc > KH_DL_MAX_LIGHTS) khd_pc = KH_DL_MAX_LIGHTS;
        khd_sc = KH_DL_MAX_LIGHTS - khd_pc;
        khd_total = KH_DL_MAX_LIGHTS;
    }

    const uint32_t khd_avail = g_dl.slot_bytes11[khd_s] / KH_DL_LIGHT_BYTES;

    if (khd_total > khd_avail) {   // the copied window undercuts the count
        if (khd_pc > khd_avail) khd_pc = khd_avail;
        khd_sc = khd_avail - khd_pc;
        khd_total = khd_avail;
    }

    const float* khd_l = reinterpret_cast<const float*>(khd_p + KH_DL_CTL_BYTES);

    if (khd_total > 0 &&
        (!dl_finite(khd_l[0]) || !dl_finite(khd_l[1]) || !dl_finite(khd_l[2]))) {
        g_dl.val_rejects++;
        g_dl.last_rej[0] = khd_l[0];
        g_dl.last_rej[1] = khd_l[1];
        g_dl.last_rej[2] = khd_l[2];
        g_dl.last_rej[3] = 3.0f;   // reason: position
        return;
    }

    if (khd_total == 0) g_dl.zero_lists++;

    // publish (render thread; readers are park-ordered)
    g_dl.point_n = khd_pc;
    g_dl.spot_n = khd_sc;
    memcpy(g_dl.ctl, khd_ctl, sizeof(g_dl.ctl));
    if (khd_total > 0) memcpy(g_dl.lights, khd_l, static_cast<size_t>(khd_total) * KH_DL_LIGHT_BYTES);
    memcpy(g_dl.view_cols, g_dl.pending_view[khd_s], sizeof(g_dl.view_cols));
    g_dl.view_valid = g_dl.pending_view_ok[khd_s] != 0;
    memcpy(g_dl.cam, g_dl.pending_cam[khd_s], sizeof(g_dl.cam));
    g_dl.stamp_ms = steady_now_ms();
    g_dl.serial++;
    g_dl.valid = true;

    uint64_t khd_h = CryptoGenerator::FNV1A64_OFFSET;   // FNV-1a over counts (word mixes) + active records (bytes)
    khd_h = (khd_h ^ khd_pc) * CryptoGenerator::FNV1A64_PRIME;
    khd_h = (khd_h ^ khd_sc) * CryptoGenerator::FNV1A64_PRIME;
    const uint8_t* khd_hb = khd_p + KH_DL_CTL_BYTES;
    const size_t khd_hn = static_cast<size_t>(khd_total) * KH_DL_LIGHT_BYTES;
    khd_h = CryptoGenerator::fnv1a64_update(khd_h, khd_hb, khd_hn);
    if (khd_h != g_dl.hash) { g_dl.hash_changes++; g_dl.hash = khd_h; }

    DlRingEntry& khd_r = g_dl.ring[g_dl.ring_head++ % KH_DL_RING];
    khd_r.serial = g_dl.serial;
    khd_r.t_ms = g_dl.stamp_ms;
    khd_r.point_n = khd_pc;
    khd_r.spot_n = khd_sc;
    khd_r.dist_scale = khd_ctl[8];
    khd_r.hash32 = static_cast<uint32_t>(khd_h);
    memcpy(khd_r.cam, g_dl.cam, sizeof(khd_r.cam));
    khd_r.b10 = reinterpret_cast<uint64_t>(g_dl.slot10_buf);
    khd_r.b11 = reinterpret_cast<uint64_t>(g_dl.slot11_buf);
    khd_r.f10 = g_dl.slot10_first;
    khd_r.f11 = g_dl.slot11_first;
    khd_r.n10 = g_dl.slot10_num;
    khd_r.n11 = g_dl.slot11_num;
    khd_r.counts_as_float = khd_as_float;

    if (khd_total > 0) {
        khd_r.l0[0] = khd_l[0];  khd_r.l0[1] = khd_l[1];  khd_r.l0[2] = khd_l[2];   // +0 position
        khd_r.l0[3] = khd_l[8];  khd_r.l0[4] = khd_l[9];  khd_r.l0[5] = khd_l[10];   // +2 diffuse
        khd_r.l0[6] = khd_l[20];   // +5 fade start
        khd_r.l0[7] = khd_l[7];   // +1 cone cos
    } else {
        memset(khd_r.l0, 0, sizeof(khd_r.l0));
    }
}

// Runs inside an ACCEPTED injection on the render thread (never on
// anomalous/rescue cycles - the caller gates). Harvest first, so a completed
// copy publishes before this frame's cbd fills read the mirror; then census
// the live slot bindings and issue this frame's copy into a free staging
// slot.
inline void dynlights_acquire(ID3D11DeviceContext* ctx, const float view[4][4]) {
    if ((g_dl_mode.load(std::memory_order_relaxed) <= 0 ||
         !g_ls.wanted.load(std::memory_order_relaxed)) &&
        !g_dl_recon.load(std::memory_order_relaxed)) return;   // fully dormant
                                   // (mode requires a lit consumer)
    g_dl.acquires++;

    // (0) arena lifecycle: harvest the previous frame's per-draw window
    // captures (origin recovery + pool merge for mode 3), then flip.
    dynlights_harvest_arena(ctx);

    // (1) harvest completed copies (DO_NOT_WAIT: a stalled copy retries at
    // the next injection; the hash census flags any ordering surprise)
    for (int khd_s = 0; khd_s < 2; ++khd_s) {
        if (!g_dl.inflight[khd_s] || !g_dl.staging[khd_s]) continue;
        D3D11_MAPPED_SUBRESOURCE khd_m = {};
        const HRESULT khd_hr = ctx->Map(g_dl.staging[khd_s], 0, D3D11_MAP_READ,
                                        D3D11_MAP_FLAG_DO_NOT_WAIT, &khd_m);
        if (FAILED(khd_hr)) { g_dl.still_drawing++; continue; }
        dynlights_publish(static_cast<const uint8_t*>(khd_m.pData), khd_s);
        ctx->Unmap(g_dl.staging[khd_s], 0);
        g_dl.inflight[khd_s] = 0;
    }

    // (2) live slot census + this frame's copy
    ID3D11DeviceContext1* khd_c1 = kh_ctx1(ctx);   // cached Q(no release)
    if (!khd_c1) { g_dl.no_ctx1++; return; }
    ID3D11Buffer* khd_b10 = nullptr;
    UINT khd_f10 = 0, khd_n10 = 0;
    ID3D11Buffer* khd_b11 = nullptr;
    UINT khd_f11 = 0, khd_n11 = 0;
    khd_c1->PSGetConstantBuffers1(10, 1, &khd_b10, &khd_f10, &khd_n10);
    khd_c1->PSGetConstantBuffers1(11, 1, &khd_b11, &khd_f11, &khd_n11);

    g_dl.slot10_buf = static_cast<void*>(khd_b10);
    g_dl.slot11_buf = static_cast<void*>(khd_b11);
    g_dl.slot10_first = khd_f10;
    g_dl.slot11_first = khd_f11;
    g_dl.slot10_num = khd_n10;
    g_dl.slot11_num = khd_n11;

    if (!khd_b10 || !khd_b11) {
        // unbound light slots are the normal DAY state (lists exist but hold
        // zero lights, or the slots go stale between lit passes) - counted,
        // mirror simply expires
        g_dl.slot_nulls++;
        if (khd_b10) khd_b10->Release();
        if (khd_b11) khd_b11->Release();
        return;
    }

    if (khd_f10 != 0 || khd_f11 != 0) g_dl.pool_offset_binds++;
    if (khd_b10 == khd_b11) g_dl.shared_pool_binds++;

    int khd_w = -1;
    for (int khd_s = 0; khd_s < 2; ++khd_s) {
        if (!g_dl.inflight[khd_s]) { khd_w = khd_s; break; }
    }

    if (khd_w < 0) {
        g_dl.issue_skips++;
        khd_b10->Release();
        khd_b11->Release();
        return;
    }

    if (!g_dl.staging[khd_w]) {
        ID3D11Device* khd_dev = nullptr;
        ctx->GetDevice(&khd_dev);

        if (khd_dev) {
            D3D11_BUFFER_DESC khd_sd = {};
            khd_sd.ByteWidth = KH_DL_STAGE_BYTES;
            khd_sd.Usage = D3D11_USAGE_STAGING;
            khd_sd.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
            khd_dev->CreateBuffer(&khd_sd, nullptr, &g_dl.staging[khd_w]);
            khd_dev->Release();
        }

        if (!g_dl.staging[khd_w]) {
            khd_b10->Release();
            khd_b11->Release();
            return;
        }
    }

    D3D11_BUFFER_DESC khd_d10 = {}, khd_d11 = {};
    khd_b10->GetDesc(&khd_d10);
    khd_b11->GetDesc(&khd_d11);
    g_dl.bw10 = khd_d10.ByteWidth;
    g_dl.bw11 = khd_d11.ByteWidth;
    const uint32_t khd_off10 = khd_f10 * 16u;   // firstConstant is in 16-byte constants
    const uint32_t khd_off11 = khd_f11 * 16u;
    uint32_t khd_want11 = KH_DL_ARR_BYTES;

    if (khd_n11 > 0 && khd_n11 * 16u < khd_want11) {
        khd_want11 = khd_n11 * 16u;   // the engine bound a smaller window
        g_dl.window_clamps++;
    }

    if (khd_off10 + KH_DL_CTL_BYTES > khd_d10.ByteWidth || khd_off11 >= khd_d11.ByteWidth) {
        g_dl.bounds_rejects++;
        khd_b10->Release();
        khd_b11->Release();
        return;
    }

    if (khd_off11 + khd_want11 > khd_d11.ByteWidth) khd_want11 = khd_d11.ByteWidth - khd_off11;
    khd_want11 -= khd_want11 % KH_DL_LIGHT_BYTES;   // whole records only

    D3D11_BOX khd_box10 = { khd_off10, 0, 0, khd_off10 + KH_DL_CTL_BYTES, 1, 1 };
    ctx->CopySubresourceRegion(g_dl.staging[khd_w], 0, 0, 0, 0, khd_b10, 0, &khd_box10);

    if (khd_want11 > 0) {
        D3D11_BOX khd_box11 = { khd_off11, 0, 0, khd_off11 + khd_want11, 1, 1 };
        ctx->CopySubresourceRegion(g_dl.staging[khd_w], 0, KH_DL_CTL_BYTES, 0, 0, khd_b11, 0, &khd_box11);
    }

    g_dl.slot_bytes11[khd_w] = khd_want11;
    g_dl.inflight[khd_w] = 1;
    g_dl.issue_serial++;
    g_dl.copies++;

    // View columns + camera captured WITH the list: the space decode and the
    // plant comparison must use the FRAME'S OWN view, not a later one.
    if (view) {
        for (int khd_k = 0; khd_k < 3; ++khd_k) {
            g_dl.pending_view[khd_w][khd_k * 4 + 0] = view[0][khd_k];
            g_dl.pending_view[khd_w][khd_k * 4 + 1] = view[1][khd_k];
            g_dl.pending_view[khd_w][khd_k * 4 + 2] = view[2][khd_k];
            g_dl.pending_view[khd_w][khd_k * 4 + 3] = 0.0f;
        }

        extract_camera_pos(view, g_dl.pending_cam[khd_w]);
        g_dl.pending_view_ok[khd_w] = 1;
    } else {
        g_dl.pending_view_ok[khd_w] = 0;
    }

    khd_b10->Release();
    khd_b11->Release();
}

// Zeroed lanes (mode 0 / stale / empty / rejected) stand the shader down -
// cbd is zero-initialized by both callers, so standing down is the default,
// never an action. Fills the dynamic-lights lanes of a draw constant block.
inline void fill_dynlights_cb(ConstantData& cbd, const RenderObject& o) {
    const int khd_mode = g_dl_mode.load(std::memory_order_relaxed);
    if (khd_mode <= 0) return;
    const uint32_t khd_bits = g_dl_intensity_bits.load(std::memory_order_relaxed);
    float khd_int = 1.0f;
    memcpy(&khd_int, &khd_bits, sizeof(khd_int));

    if (khd_mode == 3) {
        if (g_dl.pool_n == 0) return;
        if (steady_now_ms() - g_dl.pool_stamp > KH_DL_POOL_STALE_MS) { g_dl.stale_skips++; return; }
        // mesh center + half diagonal, engine axes (SQF [x,y,zASL] -> engine
        // [x, zASL, y])
        const float khd_c[3] = { o.pos[0], o.pos[2], o.pos[1] };
        const float khd_half = 0.5f * sqrtf(o.size[0] * o.size[0] +
                                            o.size[1] * o.size[1] +
                                            o.size[2] * o.size[2]);
        const float khd_scale = (g_dl.main_ref_valid && g_dl.main_scale > 1.0e-6f)
                              ? g_dl.main_scale : 1.0f;
        uint32_t khd_sel[KH_DL_MAX_LIGHTS];
        float khd_dst[KH_DL_MAX_LIGHTS];
        uint32_t khd_n = 0;

        for (uint32_t i = 0; i < g_dl.pool_n; ++i) {
            const DlPoolLight& khd_pl = g_dl.pool[i];
            const float khd_dx = khd_pl.rec[0] - khd_c[0];
            const float khd_dy = khd_pl.rec[1] - khd_c[1];
            const float khd_dz = khd_pl.rec[2] - khd_c[2];
            const float khd_d = sqrtf(khd_dx * khd_dx + khd_dy * khd_dy + khd_dz * khd_dz);
            // hard-fade reach: fade zeroes at dist*scale >= start + 1/invW
            const float khd_inv = khd_pl.rec[21];
            const float khd_reach = (khd_pl.rec[20] + (khd_inv > 1.0e-6f ? 1.0f / khd_inv : 0.0f))
                                  / khd_scale;
            if (khd_d > khd_reach + khd_half) continue;   // contributes exactly zero
            uint32_t khd_j = khd_n < KH_DL_MAX_LIGHTS ? khd_n : KH_DL_MAX_LIGHTS;

            while (khd_j > 0 && khd_dst[khd_j - 1] > khd_d) {
                if (khd_j < KH_DL_MAX_LIGHTS) {
                    khd_dst[khd_j] = khd_dst[khd_j - 1];
                    khd_sel[khd_j] = khd_sel[khd_j - 1];
                }

                --khd_j;
            }

            if (khd_j < KH_DL_MAX_LIGHTS) {
                khd_dst[khd_j] = khd_d;
                khd_sel[khd_j] = i;
                if (khd_n < KH_DL_MAX_LIGHTS) khd_n++;
            }
        }

        if (khd_n == 0) return;
        // points first, then spots - two packing passes
        uint32_t khd_out = 0, khd_pn = 0;

        for (int khd_pass = 0; khd_pass < 2; ++khd_pass) {
            for (uint32_t k = 0; k < khd_n; ++k) {
                const DlPoolLight& khd_pl = g_dl.pool[khd_sel[k]];
                if ((khd_pl.spot != 0) != (khd_pass == 1)) continue;
                memcpy(cbd.dl_lights[khd_out * 6], khd_pl.rec, KH_DL_LIGHT_BYTES);
                khd_out++;
                if (khd_pass == 0) khd_pn++;
            }
        }

        cbd.dl_ctl[0] = 3.0f;
        cbd.dl_ctl[1] = static_cast<float>(khd_pn);
        cbd.dl_ctl[2] = static_cast<float>(khd_out - khd_pn);
        cbd.dl_ctl[3] = khd_scale;

        if (g_dl.main_ref_valid &&
            (g_dl.main_gdiff[0] > 0.0f || g_dl.main_gdiff[1] > 0.0f || g_dl.main_gdiff[2] > 0.0f)) {
            cbd.dl_global[0] = g_dl.main_gdiff[0];   // the MAIN pass's cb10[3]
            cbd.dl_global[1] = g_dl.main_gdiff[1];
            cbd.dl_global[2] = g_dl.main_gdiff[2];
        } else {
            cbd.dl_global[0] = 1.0f;   // cold / degenerate reference
            cbd.dl_global[1] = 1.0f;
            cbd.dl_global[2] = 1.0f;
        }

        cbd.dl_global[3] = khd_int;
        g_dl.fill_calls++;
        g_dl.fill_last_n = khd_out;
        if (khd_out < g_dl.fill_min_n) g_dl.fill_min_n = khd_out;
        if (khd_out > g_dl.fill_max_n) g_dl.fill_max_n = khd_out;
        return;
    }

    // modes 1/2: the legacy trigger-window mirror
    if (!g_dl.valid) return;
    if (steady_now_ms() - g_dl.stamp_ms > KH_DL_STALE_MS) { g_dl.stale_skips++; return; }
    const uint32_t khd_n = g_dl.point_n + g_dl.spot_n;
    if (khd_n == 0) return;
    if (khd_mode == 2 && !g_dl.view_valid) { g_dl.view_miss_skips++; return; }
    cbd.dl_ctl[0] = static_cast<float>(khd_mode);
    cbd.dl_ctl[1] = static_cast<float>(g_dl.point_n);
    cbd.dl_ctl[2] = static_cast<float>(g_dl.spot_n);
    cbd.dl_ctl[3] = g_dl.ctl[8];   // global distance scale (cb10[2].x)
    cbd.dl_global[0] = g_dl.ctl[12];   // global diffuse multiplier (cb10[3].xyz)
    cbd.dl_global[1] = g_dl.ctl[13];
    cbd.dl_global[2] = g_dl.ctl[14];
    cbd.dl_global[3] = khd_int;
    memcpy(cbd.dl_view, g_dl.view_cols, sizeof(cbd.dl_view));
    memcpy(cbd.dl_lights, g_dl.lights, static_cast<size_t>(khd_n) * KH_DL_LIGHT_BYTES);
}

// Session reset for the mirror (device objects are release_shadow_device_
// state's job; this clears the PODs, the censuses and the ring).
inline void dynlights_reset_session() {
    g_dl.valid = false;
    g_dl.point_n = g_dl.spot_n = 0;
    memset(g_dl.ctl, 0, sizeof(g_dl.ctl));
    g_dl.view_valid = false;
    g_dl.cam[0] = g_dl.cam[1] = g_dl.cam[2] = 0.0f;
    g_dl.stamp_ms = 0;
    g_dl.serial = 0;
    g_dl.hash = 0;
    g_dl.inflight[0] = g_dl.inflight[1] = 0;
    g_dl.issue_serial = 0;
    g_dl.slot_bytes11[0] = g_dl.slot_bytes11[1] = 0;
    g_dl.pending_view_ok[0] = g_dl.pending_view_ok[1] = 0;
    g_dl.slot10_buf = nullptr;
    g_dl.slot11_buf = nullptr;
    g_dl.slot10_first = g_dl.slot11_first = 0;
    g_dl.slot10_num = g_dl.slot11_num = 0;
    g_dl.bw10 = g_dl.bw11 = 0;
    g_dl.acquires = 0; g_dl.copies = 0; g_dl.still_drawing = 0;
    g_dl.no_ctx1 = 0; g_dl.slot_nulls = 0; g_dl.issue_skips = 0;
    g_dl.bounds_rejects = 0; g_dl.window_clamps = 0; g_dl.val_rejects = 0;
    g_dl.counts_float = 0; g_dl.clamped_counts = 0; g_dl.zero_lists = 0;
    g_dl.hash_changes = 0; g_dl.stale_skips = 0; g_dl.view_miss_skips = 0;
    g_dl.pool_offset_binds = 0; g_dl.shared_pool_binds = 0;
    g_dl.lists_anchored = 0; g_dl.lists_unanchored = 0;
    memset(g_dl.last_rej, 0, sizeof(g_dl.last_rej));
    memset(g_dl.ring, 0, sizeof(g_dl.ring));
    g_dl.ring_head = 0;
    g_dl_cd_ctr = 0; g_dl_cd_n = 0; g_dl_cd_null = 0; g_dl_cd_samples = 0;
    g_dl_cd_distinct_last = 0; g_dl_cd_distinct_max = 0;
    g_dl_cd_null_last = 0; g_dl_cd_samples_last = 0;
    memset(g_dl_cd_bufs, 0, sizeof(g_dl_cd_bufs));
    memset(g_dl_cd_first, 0, sizeof(g_dl_cd_first));
    // arena / pool / origin machinery (device objects stay with
    // release_shadow_device_state)
    g_dl.arena_inflight[0] = g_dl.arena_inflight[1] = 0;
    g_dl.arena_write = 0;
    memset(g_dl.win_meta, 0, sizeof(g_dl.win_meta));
    g_dl.win_count[0] = g_dl.win_count[1] = 0;
    g_dl.pool.clear();
    g_dl.pool.shrink_to_fit();
    g_dl.pool_n = 0;
    g_dl.pool_stamp = 0;
    g_dl.pool_scale = 1.0f;
    g_dl.pool_gdiff[0] = g_dl.pool_gdiff[1] = g_dl.pool_gdiff[2] = 1.0f;
    g_dl.main_gdiff[0] = g_dl.main_gdiff[1] = g_dl.main_gdiff[2] = 1.0f;
    g_dl.main_scale = 1.0f;
    g_dl.main_ref_valid = 0;
    g_dl.ref_pend_g[0] = g_dl.ref_pend_g[1] = g_dl.ref_pend_g[2] = 0.0f;
    g_dl.ref_pend_s = 0.0f; g_dl.ref_pend_ms = 0;
    g_dl.ref_holds = 0; g_dl.ref_jump_adopts = 0;
    memset(g_dl.win_report, 0, sizeof(g_dl.win_report));
    g_dl.win_report_n = 0;
    g_dl.origin_range_rejects = 0;
    g_dl.origin_pool_votes = 0;
    g_dl.origin_vote_ambiguous = 0;
    g_dl.vs_range_prunes = 0;
    memset(g_dl.anchor_pos, 0, sizeof(g_dl.anchor_pos));
    memset(g_dl.anchor_stamp, 0, sizeof(g_dl.anchor_stamp));
    g_dl.anchor_n = 0;
    g_dl.anchor_admits = 0;
    g_dl.anchor_res_rejects = 0;
    memset(g_dl.cand_ring, 0, sizeof(g_dl.cand_ring));
    g_dl.cand_head = 0;
    memset(g_dl.m3_ring, 0, sizeof(g_dl.m3_ring));
    g_dl.m3_ring_head = 0;
    g_dl.fill_calls = 0;
    g_dl.fill_last_n = 0;
    g_dl.fill_min_n = 0xFFFFFFFFu;
    g_dl.fill_max_n = 0;
    g_dl.pool_spot_flips = 0;
    g_dl.win_aux = 0;
    g_dl.aux_adds = 0;
    g_dl.aux_refreshes = 0;
    memset(g_dl.arena_view, 0, sizeof(g_dl.arena_view));
    memset(g_dl.arena_cam, 0, sizeof(g_dl.arena_cam));
    g_dl.arena_view_ok[0] = g_dl.arena_view_ok[1] = 0;
    g_dl.vs_copies = 0; g_dl.vs_scans = 0; g_dl.vs_hint_hits = 0;
    g_dl.vs_ortho_pass = 0; g_dl.vs_rot_rejects = 0; g_dl.vs_y_rejects = 0;
    g_dl.vs_grid_rejects = 0; g_dl.vs_noref = 0; g_dl.vs_valid = 0;
    g_dl.vs_pair_tries = 0;
    g_dl.vs_pair_valid = 0;
    g_dl.vs_pair_y_rejects = 0;
    g_dl.vs_pair_grid_rejects = 0;
    g_dl.vs_last_ydelta = 0.0f;
    g_dl.vs_triple_valid = 0;
    g_dl.vs_zero_origins = 0;
    g_dl.vs_nonzero_origins = 0;
    g_dl.vs_hint_kind = 0;
    g_dl.vs_hint_slot = -1;
    g_dl.vs_hint_off = 0;
    g_dl.vs_hint_form = 0;
    g_dl.vs_hint_wslot = -1;
    g_dl.vs_hint_woff = 0;
    g_dl.vs_hint_wform = 0;
    g_dl.win_captured = 0; g_dl.win_table_full = 0;
    g_dl.pool_added = 0; g_dl.pool_updated = 0; g_dl.pool_expired = 0;

}

// the CPU band-hit replication is gone with recvHitBand - see the note at the
// FfrRecord lanes. Debug visual 14 replaces it.
inline void fill_lighting_frame_cb(ConstantData& cbd) {
    // Direction: the published derived latch, the single source now (the
    // getLighting-era ~9-deg-divergence note is retired with it; see
    // kh_shadow_sun's sunset lesson - the divergence was the engine clamping
    // its shadow light, and the derivation measures that).
    cbd.lighting1[0] = g_sun_dir_engine[0];
    cbd.lighting1[1] = g_sun_dir_engine[1];
    cbd.lighting1[2] = g_sun_dir_engine[2];
    cbd.lighting1[3] = g_lit_gate_pub ? 1.0f : 0.0f;
    // Colors: the PUBLISHED block snapshot (getLighting retired).
    const bool khzs_sunz = g_pub_block_valid &&
                           g_pub_block_sun[0] == 0.0f &&
                           g_pub_block_sun[1] == 0.0f &&
                           g_pub_block_sun[2] == 0.0f;
    const float khzs_now = effect_time_seconds();
    const bool khzs_jump = g_sun_last_jump_ms != 0 &&
                           steady_now_ms() - g_sun_last_jump_ms < 15000;
    const bool khzs_contra = g_blk_bright_seen_t >= 0.0f &&
                             khzs_now - g_blk_bright_seen_t < KH_BLK_BRIGHT_RECENT_S &&
                             !khzs_jump &&
                             g_dbg_mode.load(std::memory_order_relaxed) != 430;
    const bool khzs_dark = g_light_probe.std_sun_l >= 0.0f &&
                           g_light_probe.std_sun_l <= 0.5f &&
                           !khzs_contra &&
                           g_dbg_mode.load(std::memory_order_relaxed) != 385;
    const bool khzs_zero = khzs_sunz && !khzs_dark &&
                           g_dbg_mode.load(std::memory_order_relaxed) != 99;
    if (khzs_zero) g_blk_zero_sun_refusals++;
    if (khzs_sunz && khzs_dark) g_blk_zero_sun_admits++;
    if (khzs_sunz && khzs_contra &&
        g_light_probe.std_sun_l >= 0.0f && g_light_probe.std_sun_l <= 0.5f) {
        g_blk_zero_sun_wit_refusals++;   // engagement lane
    }
    if (g_pub_block_valid && !khzs_zero) {
        cbd.lighting2[0] = g_pub_block_sun[0];
        cbd.lighting2[1] = g_pub_block_sun[1];
        cbd.lighting2[2] = g_pub_block_sun[2];
        cbd.light_amb[0] = g_pub_block_amb[0];
        cbd.light_amb[1] = g_pub_block_amb[1];
        cbd.light_amb[2] = g_pub_block_amb[2];
        cbd.light_amb[3] = 1.0f;
    } else {
        cbd.lighting2[0] = 1.0f;
        cbd.lighting2[1] = 1.0f;
        cbd.lighting2[2] = 1.0f;
        cbd.light_amb[0] = 1.0f;
        cbd.light_amb[1] = 1.0f;
        cbd.light_amb[2] = 1.0f;
        cbd.light_amb[3] = 0.0f;
    }
    cbd.lighting2[3] = g_shadow_map_strength;

    // Pure read of the bytes this fill just wrote - no gate, no threshold, no
    // arbitration.
    {
        const float khbs_s = fmaxf(cbd.lighting2[0], fmaxf(cbd.lighting2[1], cbd.lighting2[2]))
                           + fmaxf(cbd.light_amb[0], fmaxf(cbd.light_amb[1], cbd.light_amb[2]));
        if (khbs_s == khbs_s) {   // NaN-safe
            g_blk_shade_now = khbs_s;
            g_blk_shade_n++;
            if (khbs_s > g_blk_shade_max) g_blk_shade_max = khbs_s;
            if (g_blk_shade_max > 0.0f && khbs_s < 0.10f * g_blk_shade_max) g_blk_shade_dark++;
            if (g_blk_shade_max > 0.0f &&
                khbs_s < 0.50f * g_blk_shade_max &&
                khbs_s >= 0.10f * g_blk_shade_max) {
                g_blk_dim_frames++;
                g_blk_dim_last_s = effect_time_seconds();
                if (g_blk_dim_first_s < 0.0f) g_blk_dim_first_s = g_blk_dim_last_s;
            }
            if (khbs_s < g_blk_shade_min) {
                g_blk_shade_min = khbs_s;
                for (int khbs_i = 0; khbs_i < 3; ++khbs_i) {
                    g_blk_shade_amb[khbs_i] = cbd.light_amb[khbs_i];
                    g_blk_shade_sun[khbs_i] = cbd.lighting2[khbs_i];
                }
                g_blk_shade_valid    = g_pub_block_valid ? 1.0f : 0.0f;
                g_blk_shade_litgate  = cbd.lighting1[3];
                g_blk_shade_strength = g_shadow_map_strength;
                g_blk_shade_std_amb  = g_light_probe.std_amb_l;
                g_blk_shade_std_sun  = g_light_probe.std_sun_l;
                g_blk_shade_anch_sun = g_light_probe.anch_sun_l;
                g_blk_shade_map_age  = (g_sun_map_valid && g_sun_map_time >= 0.0f)
                    ? (effect_time_seconds() - g_sun_map_time) : -1.0f;
                g_blk_shade_t        = effect_time_seconds();
                g_blk_shade_probe_age = (g_light_probe.valid &&
                                         g_light_probe.last_confirm >= 0.0f)
                    ? (g_blk_shade_t - g_light_probe.last_confirm) : -1.0f;
            }
        }
    }

    // Reads the standing sun sum - the same lane blkShadeStdSun latches -
    // never the block being filled, so a publish-path fault cannot poison the
    // reference it is measured against. Pure gauge, updated once per fill
    // beside the latch it extends.
    {
        const float khkl_std = g_light_probe.std_sun_l;
        const float khkl_now = effect_time_seconds();
        if (khkl_std > 1.0e-6f) {
            // A regime adoption snapped the anchor since the last fill: a
            // genuine level change (skipTime / weather roll). The keel snaps
            // with it - read from the counter, not wired into the locator.
            if (g_blk_anchor_snaps != g_blk_keel_snap_mark) {
                g_blk_keel_snap_mark = g_blk_anchor_snaps;
                g_blk_keel_sl = khkl_std;
                g_blk_keel_snaps++;
            }
            if (g_blk_keel_sl <= 0.0f) {
                g_blk_keel_sl = khkl_std;   // first capture
            } else if (g_blk_keel_t >= 0.0f && khkl_now > g_blk_keel_t) {
                const float khkl_dt = khkl_now - g_blk_keel_t;
                const float khkl_r  = KH_BLK_KEEL_RATE *
                                      (khkl_dt < 1.0f ? khkl_dt : 1.0f);
                float khkl_f = khkl_std / g_blk_keel_sl;
                if (khkl_f > 1.0f + khkl_r) khkl_f = 1.0f + khkl_r;
                if (khkl_f < 1.0f - khkl_r) khkl_f = 1.0f - khkl_r;
                g_blk_keel_sl *= khkl_f;
            }
            g_blk_keel_t = khkl_now;

            if (g_blk_keel_sl > 1.0e-6f) {
                const float khkl_q = khkl_std / g_blk_keel_sl;
                g_blk_walk_ratio = khkl_q;
                if (khkl_q > g_blk_walk_ratio_max) g_blk_walk_ratio_max = khkl_q;
                if (g_blk_walk_ratio_min < 0.0f || khkl_q < g_blk_walk_ratio_min) {
                    g_blk_walk_ratio_min = khkl_q;
                    g_blk_walk_min_t    = khkl_now;
                    g_blk_walk_min_keel = g_blk_keel_sl;
                    g_blk_walk_min_std  = khkl_std;
                }
                if (khkl_q < KH_BLK_DIM_BAR) {
                    g_blk_walk_dim_frames++;
                    if (g_blk_walk_dim_first < 0.0f) g_blk_walk_dim_first = khkl_now;
                    g_blk_walk_dim_last = khkl_now;
                    if (g_blk_walk_dim_open < 0.0f) g_blk_walk_dim_open = khkl_now;
                    const float khkl_sp = khkl_now - g_blk_walk_dim_open;
                    if (khkl_sp > g_blk_walk_dim_span_max) g_blk_walk_dim_span_max = khkl_sp;
                } else {
                    g_blk_walk_dim_open = -1.0f;   // window closes; span already banked
                }
            }
        }
    }

    const bool khl_map_fresh = g_sun_map_valid && g_sun_map_time >= 0.0f &&
        effect_time_seconds() - g_sun_map_time < KH_SUN_MAP_SELF_MAX_AGE_S;

    // KH_SUN_ANCHOR: ONE origin for every sun matrix in this template, set
    // UNCONDITIONALLY before any of them fills.
    cbd.sun_origin[0] = g_sun_anchor_now[0];
    cbd.sun_origin[1] = g_sun_anchor_now[1];
    cbd.sun_origin[2] = g_sun_anchor_now[2];

    {
        const int khlf_dm = g_dbg_mode.load(std::memory_order_relaxed);
        if (khlf_dm != 247 && g_vmir_mask_time >= 0.0f && g_vmir_w > 0 &&
            effect_time_seconds() - g_vmir_mask_time < 0.5f) {
            cbd.mir_meta[0] = 1.0f;
            cbd.mir_meta[1] = static_cast<float>(g_vmir_w);
            cbd.mir_meta[2] = static_cast<float>(g_vmir_h);
        }
        if (khlf_dm != 255 &&
            (g_sun_anchor_now[0] != 0.0f || g_sun_anchor_now[1] != 0.0f ||
             g_sun_anchor_now[2] != 0.0f)) {
            cbd.mir_meta[3] = fminf(fmaxf(
                g_sun_range.load(std::memory_order_relaxed), 8.0f), 1000.0f);
        }
    }

    if (khl_map_fresh) {
        // KH_SUN_ANCHOR: the union matrix may be older than this flush's
        // anchor (hash-skip frames) - rebase it algebraically so every matrix
        // in THIS block shares cbd.sun_origin (set above, unconditionally).
        // Ledger at g_sun_anchor_now; zero anchors make this a straight copy.
        kh_sun_rebase_vp(&cbd.sun_vp[0][0], g_sun_map_vp,
                         g_sun_map_anchor, g_sun_anchor_now);
        cbd.sun_meta[0] = g_sun_map_cam_anchor ? 2.0f : 1.0f;
        cbd.sun_meta[1] = static_cast<float>(g_sun_map_size);   // rendered size (KH_SUN_LADDER)
        cbd.sun_meta[2] = g_sun_map_bias;
        cbd.sun_meta[3] = g_shadow_map_strength;

        // the hero tier rides the union's freshness window - it is rendered
        // by the same pass, so one clock serves both.
        kh_fill_sun_tier_cb(cbd.sun_vp2, cbd.sun_meta2, g_sun2_map_valid,
                            g_sun2_map_vp, g_sun2_map_bias, g_sun2_half_diag, g_sun2_map_size);

        // the MID and OUTER bands ride the same clock - rendered by the same
        // pass, one freshness window for the whole ladder (KH_SUN_CASCADE). A
        // downed/failed band leaves its meta zeroed and the shader chain
        // falls through.
        kh_fill_sun_tier_cb(cbd.sun_vp3, cbd.sun_meta3, g_sun3_map_valid,
                            g_sun3_map_vp, g_sun3_map_bias, g_sun3_half_diag, g_sun3_map_size);

        kh_fill_sun_tier_cb(cbd.sun_vp4, cbd.sun_meta4, g_sun4_map_valid,
                            g_sun4_map_vp, g_sun4_map_bias, g_sun4_half_diag, g_sun4_map_size);
        kh_fill_sun_tier_cb(cbd.sun_vp5, cbd.sun_meta5, g_sun5_map_valid,
                            g_sun5_map_vp, g_sun5_map_bias, g_sun5_half_diag, g_sun5_map_size);   // FAR band, same clock
        // KH_SELF_PREFILTER arms (mode 357 = classic taps everywhere; a band
        // whose convert did not complete stays classic on its own - the flag
        // pairs render AND convert).
        {
            const int khpf_dm = g_dbg_mode.load(std::memory_order_relaxed);
            const bool khpf_off = khpf_dm == 357 || khpf_dm == 366;   // era arm
            cbd.sun_pf[0] = (!khpf_off && g_sun2_map_valid && g_sun_pf_valid[0]) ? 1.0f : 0.0f;
            cbd.sun_pf[1] = (!khpf_off && g_sun3_map_valid && g_sun_pf_valid[1]) ? 1.0f : 0.0f;
            cbd.sun_pf[2] = (!khpf_off && g_sun4_map_valid && g_sun_pf_valid[2]) ? 1.0f : 0.0f;
        }
    }

    // Received-term outage forensics: the world-shadows-on-mesh term vanishes
    // whenever this early-out fires on a LIT object.
    if (!g_atlas_frame_cur && !g_atlas_frame_prev) {
        g_recv_stream_skips++;
        return;
    }

    if (ffr_armed()) {   // vanish anatomy, written before any gate
        FfrRecord& khva_r = ffr_head();
        khva_r.kh_live_tab = static_cast<uint8_t>(g_ls.count > 255u ? 255u : g_ls.count);
        const uint64_t khva_now = steady_now_ms();
        khva_r.kh_sun_st = (g_sun_valid_ms == 0 ||
                            khva_now - g_sun_valid_ms < KH_SUN_COLD_HOLD_MS) ? 0
                         : (g_sun_unstable_ms != 0 &&
                            khva_now - g_sun_unstable_ms < KH_SUN_SETTLE_MS) ? 1 : 2;
    }
    if (g_ls.count == 0 || g_ls.newest < 0) {
        g_recv_term_skips++;
        return;
    }

    uint32_t order[KH_LIVE_MAX_CASCADES];
    uint32_t n = 0;
    float owpt[KH_LIVE_MAX_CASCADES];

    for (uint32_t i = 0; i < g_ls.count && n < KH_LIVE_MAX_CASCADES; ++i) {
        const LiveShadowEntry& le = g_ls.entries[i];
        const float ilen = sqrtf(le.m[0] * le.m[0] + le.m[4] * le.m[4] + le.m[8] * le.m[8]);
        const float texels = le.tile[2] > le.tile[0]
                           ? (le.tile[2] - le.tile[0]) * static_cast<float>(g_ls.atlas_size)
                           : 1.0f;
        const float wpt = ilen > 1e-9f ? (2.0f / ilen) / (texels > 1.0f ? texels : 1.0f) : 1e9f;

        uint32_t j = n;
        while (j > 0 && owpt[j - 1] > wpt) {
            owpt[j] = owpt[j - 1];
            order[j] = order[j - 1];
            --j;
        }

        owpt[j] = wpt;
        order[j] = i;
        ++n;
    }

    if (n == 0) return;

    // SUN-SETTLE GATE (round 3): the live-table receive was the last UNGATED
    // shadow term - a cold mispaired cascade matrix reads as the "zoomed-out
    // wrong mapping" (wrong scale by construction). The zeroed count
    // short-circuits the shader; the table re-enters the frame the hold
    // expires.
    if (!kh_sun_settled()) return;

    // shadow_meta[0] (the count) is written LAST, after the table lands.
    uint32_t out_i = 0;

    cbd.shadow_meta[1] = g_shadow_map_sign;
    cbd.shadow_meta[2] = g_shadow_map_bias;
    cbd.shadow_meta[3] = static_cast<float>(g_ls.atlas_size);
    // shadowMeta2 is PER-OBJECT (the far-vis flag) and fills in
    // fill_lighting_obj_cb. Its yzw stays zero: each entry's camera origin is
    // folded into its translation below, so the shader's (wpos - meta2.yzw)
    // consumes ABSOLUTE world positions and per-entry staleness cannot
    // misregister.

    for (uint32_t i = 0; i < n && out_i < KH_LIVE_MAX_CASCADES; ++i, ++out_i) {
        const LiveShadowEntry& e = g_ls.entries[order[i]];
        memcpy(cbd.shadow_tiles[out_i], e.tile, sizeof(e.tile));

        for (int r = 0; r < 3; ++r) {
            float* dst = cbd.shadow_mats[out_i * 3 + r];
            const float* row = e.m + r * 4;
            dst[0] = row[0];
            dst[1] = row[1];
            dst[2] = row[2];
            // t' = t - M.row. cam_entry: uvz = M*(p - cam) + t = M*p + t'
            dst[3] = row[3] - (row[0] * e.cam[0] + row[1] * e.cam[1] + row[2] * e.cam[2]);
        }
    }

    cbd.shadow_meta[0] = static_cast<float>(out_i);
    if (ffr_armed()) ffr_head().kh_live_served = static_cast<uint8_t>(out_i);

}

// So an UNLIT farVis object NEVER received its far clamp (permanently
// hard-clipped at max view distance - the feature silently dead for unlit
// spawns), and lit ones LOST it on every atlas-outage or settle-hold frame (a
// far blink). CB-SPLIT (object half): the per-object lighting lanes the frame
// fill above surrendered.
inline void fill_lighting_obj_cb(ConstantData& cbd, const RenderObject& o) {
    cbd.lighting0[0] = o.lit ? 1.0f : 0.0f;
    // 169 = explicit armed alias.
    {
        const int khl_dm = g_dbg_mode.load(std::memory_order_relaxed);
        // 5 = mode 183, the SELF-SHADOW kill.
        cbd.lighting0[1] = khl_dm == 166 ? 2.0f
                         : khl_dm == 167 ? 3.0f
                         : khl_dm == 168 ? 4.0f
                         : khl_dm == 183 ? 5.0f
                         : khl_dm == 211 ? 6.0f   // far fade OFF
                         : khl_dm == 215 ? 7.0f   // footprint-scaled PCF
                         // codes 8 / 10 / 11 / 12 (modes 216 / 224 / 225 /
                         // 226) are GONE, not renumbered. 216/225/226 are
                         // DELISTED in the SQF whitelist too. 224 STAYS
                         // whitelisted because its CPU half is still live
                         // (khsf_rev: the compare- bias floor and the
                         // lateral/depth extent split), but it no longer
                         // carries a shader code.
                         : khl_dm == 220 ? 9.0f   // coverage fallback ON (opt-in)
                         : khl_dm == 227 ? 13.0f   // back-face map, bias dropped
                         : khl_dm == 229 ? 14.0f   // RPDB gradient back ON
                         : khl_dm == 230 ? 15.0f   // geometric N.L gate revert
                         : khl_dm == 231 ? 16.0f   // geometric N.L veto restored
                         : khl_dm == 232 ? 17.0f   // slope ceiling 8 restored
                         : khl_dm == 234 ? 18.0f   // shader slope + no raster bias
                         : khl_dm == 233 ? 19.0f   // vertex-normal bias slope
                         : khl_dm == 238 ? 20.0f   // flat self ring (density-adaptive revert)
                         : khl_dm == 245 ? 22.0f   // cascade filtering revert (KH_SUN_CAST_SOFT)
                                                  // + KH_SUN_BAND_FLAT_RING; fire CB carries
                                                  // it too)
                         : khl_dm == 246 ? 23.0f   // self range fade revert (KH_SUN_SELF_FADE)
                                                  // mesh CB only - the fade lives in the
                                                  // self term) code 21 is SPENT but
                                                  // deliberately NOT mapped here - it is the
                                                  // cast tier chain's revert (mode 243) and
                                                  // is written only by the FIRE's cast CB
                                                  // fill, whose consumer
                                                  // (SunShadowOcclusion) is the only reader
                                                  // of the 20.5-21.5 window.
                         : khl_dm == 296 ? 41.0f   // SELF band lit-return
                         : khl_dm == 248 ? 24.0f   // mirror consumption OFF
                         : khl_dm == 253 ? 25.0f   // gradient slack OFF
                                                  // (KH_SUN_GRAD_SLACK; the fwidth depth
                                                  // slack on every self tier).
                         : khl_dm == 257 ? 26.0f   // tier blend OFF (KH_TIER_BLEND)
                                                  // hard cascade steps restored - BOTH fills
                                                  // carry it, both chains read it).
                         : khl_dm == 259 ? 27.0f   // normal-offset sampling OFF
                                                  // (self chain only).
                         : khl_dm == 260 ? 28.0f   // footprint tap spread OFF
                                                  // (fixed +-1 ring; self chain).
                         : khl_dm == 262 ? 29.0f   // contact shortcut OFF - since
                                                  // an alias of the default.
                         : khl_dm == 263 ? 30.0f   // contact shortcut ON (opt-in)
                                                  // experimental arm; band tiers).
                         : khl_dm == 267 ? 32.0f   // gradient-OFF isolator
                         : khl_dm == 268 ? 33.0f   // FULL revert of the noise
                         : khl_dm == 272 ? 34.0f   // INERT - code 34
                                                  // has no guard site left. The damper is ON
                                                  // by default again and code 39 (mode 288)
                                                  // is its only kill, bundled with slope 0.8
                                                  // + floor x1.25. There is no damper-alone
                                                  // isolator; 272 is a silent alias of the
                                                  // default. (audit: the old note here still
                                                  // promised the 35 arm.)
                         : khl_dm == 280 ? 35.0f   // INERT - code 35
                                                  // 288/code 39 is the live arm. (audit.)
                         : khl_dm == 282 ? 36.0f   // alias of default
                                                  // (3x3 is the default again).
                         : khl_dm == 284 ? 37.0f   // tier-proportional floor
                                                  // OFF (shipped this arm UNREACHABLE - no
                                                  // mode set 37; owned and fixed).
                         : khl_dm == 285 ? 38.0f   // diamond ring opt-in
                         : khl_dm == 288 ? 39.0f   // crop-measured
                                                  // bias opt-in (slope 0.8, floor x1.25, no
                                                  // damper). Next free code: 40.
                         : khl_dm == 264 ? 31.0f   // self-PCF OFF (KH_SELF_PCF)
                                                  // hard single-texel taps restored on all
                                                  // four self tiers - the pre-compare). Mesh
                                                  // fill only: the self chain has no fire-CB
                                                  // reader, so the fire fill maps 264 to its
                                                  // default deliberately.
                         : khl_dm == 352 ? 43.0f   // stencil range fade OFF
                         : khl_dm == 353 ? 44.0f   // soft compare OFF (hard)
                                                  // corner step restored on all four self
                                                  // tiers)
                         : khl_dm == 354 ? 45.0f   // smooth spread OFF (the)
                                                  // int ring spread returns)
                         : khl_dm == 356 ? 46.0f   // self chain samples the
                                                  // world-absolute interpolant again
                                                  // (PS-side anchor sub; the pre-arithmetic)
                         : khl_dm == 358 ? 47.0f   // PF-EXCLUSIVE (armed band)
                                                  // verdicts come from the pyramid alone;
                                                  // authorship separation vs 357)
                         : khl_dm == 362 ? 48.0f   // UNBOUNDED grad slack
                         // 446 (code 76, witness off) is an ALIAS of the default since 26711 and maps to the default deliberately (the 264 precedent): the shader has had no reader for 76 since then.
                         // 450 (code 77, whole-union witness) and 452 (code 78, tier-scoped witness) were RETIRED at 26719 with the witness body (KhUnionClear deleted; KH_SUN_PANCAKE removed its only case): modes retired in the whitelist, codes 76 / 77 / 78 burned (never reassign).
                         // 453 (code 79, pf deep gate) and 455 (code 81, geometric horizon) were minted at 26711/26713, read null against the strap and were WIPED at 26714: modes retired in the whitelist, codes 79 and 81 burned (never reassign).
                         : khl_dm == 454 ? 80.0f   // KH_RPDB_WORLD_CLAMP OFF: the receiver-plane gradient clamp back to 8 TEXELS per tier (the 26711 form; 32 mm at mid). Mesh fill only (no RPDB in the cast chain).
                         : khl_dm == 456 ? 82.0f   // KH_SLOPE_WORLD ON - an ALIAS of the default since 26714 (stays whitelisted).
                         : khl_dm == 457 ? 83.0f   // KH_SLOPE_WORLD OFF: the slope-scaled self bias texel-priced per tier again (the 26713 form; 1.4 mm * tan at mid). Mesh fill only. Next free code: 84.
                         : khl_dm == 445 ? 75.0f   // KH_TIER_FADE_DIR hold, 0.28 ramp - OPT-IN again since 26718 (default 26715-26717)
                         : khl_dm == 458 ? 84.0f   // hold OFF - an ALIAS of the default since 26718
                         : khl_dm == 459 ? 85.0f   // KH_HOLD_STEEP: hold, 0.10 ramp - OPT-IN again since 26718 (default 26716-26717)
                         : khl_dm == 460 ? 86.0f   // hold 0.28 - an ALIAS of 445 since 26718
                         : khl_dm == 461 ? 87.0f   // fade end 0.98 - an ALIAS of the default since 26718
                         : khl_dm == 462 ? 88.0f   // KH_FADE_TO_GUARD: the tier fade ends at the 0.998 guard - OPT-IN (default at 26717 only).
                         : khl_dm == 463 ? 89.0f   // KH_FAR_SELF_GATE ON: the far self tier runs only when outer did not contain / carried / certified the fragment (the 26718 default; retired at 26719 under KH_SUN_PANCAKE). Mesh fill only (no far gate in the cast chain). Next free code: 90.
                         : khl_dm == 444 ? 74.0f   // KH_PF_RAMP_FLOOR OFF (precision floor as sigma)
                         : khl_dm == 442 ? 72.0f   // KH_TIER_FADE_DIR OFF (symmetric fade)
                         : khl_dm == 443 ? 73.0f   // KH_TIER_PARTNER_PAINT (partner alone in the band)
                         // 401 (code 71, the far-self gate WITHOUT the kh4_cert clause) was RETIRED at 26719 with the gate: mode retired in the whitelist, code 71 burned (never reassign). 463 / 89 is the gate's restore arm.
                         : khl_dm == 400 ? 70.0f   // now an ALIAS of the
                         : khl_dm == 398 ? 69.0f   // far guard CLAMPED to
                         : khl_dm == 397 ? 68.0f   // RETIRED - dead code
                                                  // 6x range (the far tier over-claims again
                                                  // and a beyond- range caster's shadow can
                                                  // vanish)
                         : khl_dm == 396 ? 67.0f   // KH_CERT_CLEAR off
                                                  // (a clear texel stops certifying; the
                                                  // halo class returns and visual 32 paints
                                                  // those pixels RED again)
                         : khl_dm == 394 ? 66.0f   // KH_CERT_CONTENT off
                         : khl_dm == 392 ? 65.0f   // far self tier ungated - an ALIAS of the default since 26719 (stays whitelisted; the shader no longer reads 65)
                         : khl_dm == 388 ? 62.0f   // 0.60 fade
                                                  // start returns (fine tier yields earlier;
                                                  // wider two-grid mix)
                         : khl_dm == 386 ? 60.0f   // jurisdiction edge
                                                  // fade OFF (the hard certification cliff
                                                  // returns at window edges)
                         : khl_dm == 387 ? 61.0f   // fixed 12/48/192 m
                                                  // jurisdiction guards (pre-literals;
                                                  // under-claim at s > 1)
                         : khl_dm == 371 ? 55.0f   // thin 10% blend band
                                                  // + always-on jurisdiction return (quality
                                                  // seams snap again)
                         : khl_dm == 370 ? 54.0f   // range-fade
                                                  // curve returns (fade from 85%; self
                                                  // shadows thin ~30 m early)
                         : khl_dm == 369 ? 53.0f   // facet bias normal
                                                  // re-armed (crevice fireflies, edge dither
                                                  // and motion film-grain RETURN)
                         : khl_dm == 368 ? 52.0f   // straddle guard OFF
                                                  // (unguarded spread + pf engagement
                                                  // return; crevice fireflies and edge
                                                  // dither should RETURN)
                         : khl_dm == 367 ? 51.0f   // KH_UNION_LIT_GUARD
                                                  // revert - the union override
                                                  // (unconditional lit fallthrough) returns
                         : khl_dm == 365 ? 50.0f   // KH_SELF_CLASSIC
                         : khl_dm == 366 ? 50.0f   // THE ERA ARM - classic
                                                  // kernel + union-only maps + pf off (CPU
                                                  // halves at khsh_render_cams / the sun_pf
                                                  // arm fill)
                         : khl_dm == 363 ? 49.0f   // rotated decision ring
                         : khl_dm == 381 ? 59.0f   // ABSOLUTE-interpolant
                         : 1.0f;
        // mir_meta is a FRAME field and this is the per-object fill: the pass
        // uploads the frame slice ONCE from the khr_cbf/khf_cbf template
        // BEFORE the mesh loop, and every per-object cbd is a copy of that
        // template whose frame section is never uploaded - a frame field
        // written here is silently discarded.
    }
    cbd.lighting0[2] = o.light_ambient;
    cbd.lighting0[3] = o.light_diffuse;
    cbd.shadow_meta2[0] = (o.far_vis ||
        g_dbg_mode.load(std::memory_order_relaxed) == 303) ? 1.0f : 0.0f;   // far-visibility clamp (see far_vis)
    // 0 when never read - the shader treats 0 as no cut. KH_OBJ_VIS_CUT (mode
    // 437 zeroes; 303 already stands the whole far contract down): a
    // farVis-off object is sliced at the engine's object view distance.
    cbd.shadow_meta2[1] = (o.far_vis ||
        g_dbg_mode.load(std::memory_order_relaxed) == 437 ||
        g_dbg_mode.load(std::memory_order_relaxed) == 303) ? 0.0f
        : g_obj_vis.load(std::memory_order_relaxed);
    // Dynamic lights (points/spots/environment lamps): the validated engine
    // mirror, culled PER OBJECT (mode 3's nearest-set selection is a per-mesh
    // verdict). Unlit objects skip - the historic gate, preserved on the
    // object side of the split. Dormant at mode 0.
    if (o.lit) fill_dynlights_cb(cbd, o);
}

// (The historic one-call fill_lighting_cb wrapper is RETIRED unused: every
// fill site calls the halves - fill_lighting_frame_cb + fill_lighting_obj_cb
// - directly.)

// Shadow phase tracking (render thread only, like ReorderState).
static constexpr float    KH_SHADOW_AXIS_COS_TOL   = 0.995f;   // ~5.7 degrees off the sun vector
static constexpr float    KH_SHADOW_ORTHO_TOL      = 0.02f;   // orthonormality slack for the 3x3 test

// Forward: defined with the live-capture group below.
inline void shadow_live_consider_atlas(ID3D11Texture2D* tex, const D3D11_TEXTURE2D_DESC& td);

struct ShadowReconState {
    bool     phase_active = false;   // depth-only, non-main DSV currently bound
    void*    target_identity = nullptr;
};
static ShadowReconState g_sr;   // render thread only

// Absolute cosine between a (possibly scaled) axis and the published sun.
inline float shadow_axis_abs_cos(float ax, float ay, float az) {
    const float len2 = ax * ax + ay * ay + az * az;
    if (len2 < 1e-12f) return 0.0f;
    const float d = ax * g_sun_dir_engine[0] + ay * g_sun_dir_engine[1] + az * g_sun_dir_engine[2];
    return fabsf(d) / sqrtf(len2);
}

// Live capture pieces

// Cleared at every frame boundary (shadow_live_frame_reset) and on atlas
// adoption, so a destroyed view whose address gets reused by an unrelated SRV
// can never inherit a stale classification beyond the frame it died in - the
// same reuse hazard that bans long-lived pointer memoization everywhere else
// in this machinery.
static void* g_atlas_srv_cache[8] = {};
static uint32_t g_atlas_srv_count = 0;

// The export settles what characters are NOT: there are no stencil shadow
// volumes in the capture, VS-VertexShader_141 is an ordinary skinned
// shadow-map pass (three BLENDWEIGHT/BLENDINDICES sets, a CB10[192] bone
// palette, normal-offset depth bias, SV_Position only), and the single
// geometry shader is a cascade slice router (SV_RenderTargetArrayIndex from
// cb2[1].w), not a volume generator.
struct KhShadowTexObs {
    uint32_t width = 0;
    uint32_t height = 0;
    uint32_t array_size = 0;
    uint32_t format = 0;   // DXGI_FORMAT as uint
    uint32_t samples = 0;
    uint32_t mips = 0;
    uint32_t bind = 0;   // D3D11_BIND_FLAG bits
    uint32_t clause = 0;   // see the codes above
    uint32_t identities = 0;   // identity CHANGES at this shape: 1 = one stable
                                // texture, climbing = recreated across the
                                // session OR several coexisting and
                                // alternating. It counts changes, not a
                                // distinct set - two targets ping-ponging
                                // inflate it, which is itself the signal that
                                // there are two.
    uint64_t sightings = 0;
    void*    last_id = nullptr;
    float    last_seen = 0.0f;
};

static constexpr int KH_SHADOW_TEX_CENSUS_N = 12;
static KhShadowTexObs g_shadow_tex_census[KH_SHADOW_TEX_CENSUS_N];
static uint32_t g_shadow_tex_census_n = 0;
static uint32_t g_shadow_tex_census_evicts = 0;   // distinct shapes beyond the table
static uint64_t g_shadow_tex_considers = 0;   // the instrument's own liveness
// The lead in three numbers, so it survives a full table.
static uint64_t g_shadow_tex_array_rejects = 0;
static uint32_t g_shadow_tex_array_max_w = 0;
static uint32_t g_shadow_tex_array_max_slices = 0;
// Candidate outcomes: a candidate that passes every clause still may not be
// adopted. Without these a full table cannot distinguish 'no candidate' from
// 'candidate refused by the grow-or-recover hold'.
static uint64_t g_shadow_tex_same = 0;   // already the held atlas
static uint64_t g_shadow_tex_kept = 0;   // lost to a larger live atlas
static uint64_t g_shadow_tex_adopts = 0;   // became the atlas

inline void kh_shadow_tex_census(ID3D11Texture2D* khsc_tex,
                                 const D3D11_TEXTURE2D_DESC& khsc_td,
                                 uint32_t khsc_clause) {
    g_shadow_tex_considers++;

    if (khsc_clause == 4) {
        g_shadow_tex_array_rejects++;
        if (khsc_td.Width > g_shadow_tex_array_max_w) g_shadow_tex_array_max_w = khsc_td.Width;
        if (khsc_td.ArraySize > g_shadow_tex_array_max_slices)
            g_shadow_tex_array_max_slices = khsc_td.ArraySize;
    }

    void* khsc_id = static_cast<void*>(khsc_tex);
    const float khsc_now = effect_time_seconds();

    for (uint32_t khsc_i = 0; khsc_i < g_shadow_tex_census_n; ++khsc_i) {
        KhShadowTexObs& e = g_shadow_tex_census[khsc_i];

        if (e.width == khsc_td.Width && e.height == khsc_td.Height &&
            e.array_size == khsc_td.ArraySize &&
            e.format == static_cast<uint32_t>(khsc_td.Format) &&
            e.samples == khsc_td.SampleDesc.Count && e.clause == khsc_clause) {
            e.sightings++;
            if (khsc_id != e.last_id) { e.last_id = khsc_id; e.identities++; }
            e.last_seen = khsc_now;
            return;
        }
    }

    if (g_shadow_tex_census_n >= static_cast<uint32_t>(KH_SHADOW_TEX_CENSUS_N)) {
        g_shadow_tex_census_evicts++;
        return;
    }

    KhShadowTexObs& e = g_shadow_tex_census[g_shadow_tex_census_n++];
    e = KhShadowTexObs{};
    e.width = khsc_td.Width;
    e.height = khsc_td.Height;
    e.array_size = khsc_td.ArraySize;
    e.format = static_cast<uint32_t>(khsc_td.Format);
    e.samples = khsc_td.SampleDesc.Count;
    e.mips = khsc_td.MipLevels;
    e.bind = khsc_td.BindFlags;
    e.clause = khsc_clause;
    e.identities = 1;
    e.sightings = 1;
    e.last_id = khsc_id;
    e.last_seen = khsc_now;
}

// So the engine tiles its eight cascades into ONE 2D atlas (8 binds a frame
// against shadowLiveCascades 8) and the ArraySize clause never fires. That
// clause is not the fault and must not be relaxed. It could be written behind
// a render target, or filled by a copy, or bound only in a phase the DSV
// probe never samples.
struct KhSrvArrObs {
    uint32_t width = 0;
    uint32_t height = 0;
    uint32_t array_size = 0;
    uint32_t format = 0;   // the VIEW's format, which is what the shader reads
    uint32_t res_format = 0;   // the RESOURCE's format (typeless for depth)
    uint32_t view_dim = 0;   // D3D11_SRV_DIMENSION as uint
    uint32_t slots = 0;   // bitmask of PS slots it was bound to (0-31)
    uint32_t identities = 0;   // identity CHANGES at this shape (1 = one stable view)
    uint64_t sightings = 0;
    void*    last_id = nullptr;
    float    last_seen = 0.0f;
};

static constexpr int KH_SRV_ARR_CENSUS_N = 8;
static constexpr uint32_t KH_SRV_ARR_BUDGET = 64;   // inspections per frame
static KhSrvArrObs g_srv_arr_census[KH_SRV_ARR_CENSUS_N];
static uint32_t g_srv_arr_census_n = 0;
static uint32_t g_srv_arr_evicts = 0;
static uint64_t g_srv_arr_scans = 0;   // SRVs actually inspected (liveness)
static uint64_t g_srv_arr_hits = 0;   // array-dimension SRVs seen
static uint64_t g_srv_arr_depth_hits = 0;   // ... of those, depth-shaped and >= 1024
static uint32_t g_srv_arr_depth_max_w = 0;
static uint32_t g_srv_arr_depth_max_slices = 0;
static uint32_t g_srv_arr_budget_used = 0;   // per frame
static uint64_t g_srv_arr_budget_stops = 0;   // frames that hit the cap
static void* g_srv_arr_memo[16] = {};
static uint32_t g_srv_arr_memo_n = 0;

// Cleared at the frame boundary (hooked_clear_depthstencil), with the
// projection census publish.
inline void kh_srv_arr_frame_reset() {
    g_srv_arr_budget_used = 0;
    g_srv_arr_memo_n = 0;
}

// Depth SRVs never carry the typeless resource format; they carry its
// colour-read equivalent, which is exactly the mapping shadow_live_ensure_srv
// performs in the other direction. A format the engine could be READING depth
// through. R16_UNORM is included because a 16-bit cascade is legal and this
// list is a recogniser, not a contract.
inline bool kh_srv_fmt_is_depthish(uint32_t khsa_f) {
    switch (static_cast<DXGI_FORMAT>(khsa_f)) {
        case DXGI_FORMAT_R32_FLOAT:
        case DXGI_FORMAT_R24_UNORM_X8_TYPELESS:
        case DXGI_FORMAT_X24_TYPELESS_G8_UINT:
        case DXGI_FORMAT_R16_UNORM:
        case DXGI_FORMAT_R16_FLOAT:
        case DXGI_FORMAT_R32_TYPELESS:
        case DXGI_FORMAT_R24G8_TYPELESS:
        case DXGI_FORMAT_R16_TYPELESS:
            return true;
        default:
            return false;
    }
}

inline void kh_srv_arr_census(ID3D11ShaderResourceView* khsa_srv, UINT khsa_slot) {
    if (!khsa_srv) return;

    if (g_srv_arr_budget_used >= KH_SRV_ARR_BUDGET) {
        g_srv_arr_budget_stops++;
        return;
    }

    void* khsa_vid = static_cast<void*>(khsa_srv);

    for (uint32_t khsa_m = 0; khsa_m < g_srv_arr_memo_n; ++khsa_m) {
        if (g_srv_arr_memo[khsa_m] == khsa_vid) return;   // already classified this frame
    }

    if (g_srv_arr_memo_n < 16) g_srv_arr_memo[g_srv_arr_memo_n++] = khsa_vid;
    g_srv_arr_budget_used++;
    g_srv_arr_scans++;

    D3D11_SHADER_RESOURCE_VIEW_DESC khsa_vd = {};
    khsa_srv->GetDesc(&khsa_vd);

    if (khsa_vd.ViewDimension != D3D11_SRV_DIMENSION_TEXTURE2DARRAY &&
        khsa_vd.ViewDimension != D3D11_SRV_DIMENSION_TEXTURE2DMSARRAY) {
        return;   // not an array view: not the question
    }

    g_srv_arr_hits++;

    ID3D11Resource* khsa_res = nullptr;
    khsa_srv->GetResource(&khsa_res);
    if (!khsa_res) return;

    ID3D11Texture2D* khsa_tex = nullptr;
    khsa_res->QueryInterface(__uuidof(ID3D11Texture2D), reinterpret_cast<void**>(&khsa_tex));
    khsa_res->Release();
    if (!khsa_tex) return;

    D3D11_TEXTURE2D_DESC khsa_td = {};
    khsa_tex->GetDesc(&khsa_td);
    khsa_tex->Release();   // identity only; the desc is already copied out

    const uint32_t khsa_vfmt = static_cast<uint32_t>(khsa_vd.Format);

    if (kh_srv_fmt_is_depthish(khsa_vfmt) && khsa_td.Width >= 1024) {
        g_srv_arr_depth_hits++;
        if (khsa_td.Width > g_srv_arr_depth_max_w) g_srv_arr_depth_max_w = khsa_td.Width;
        if (khsa_td.ArraySize > g_srv_arr_depth_max_slices)
            g_srv_arr_depth_max_slices = khsa_td.ArraySize;
    }

    const float khsa_now = effect_time_seconds();
    const uint32_t khsa_bit = khsa_slot < 32u ? (1u << khsa_slot) : 0u;

    for (uint32_t khsa_i = 0; khsa_i < g_srv_arr_census_n; ++khsa_i) {
        KhSrvArrObs& e = g_srv_arr_census[khsa_i];

        if (e.width == khsa_td.Width && e.height == khsa_td.Height &&
            e.array_size == khsa_td.ArraySize && e.format == khsa_vfmt &&
            e.view_dim == static_cast<uint32_t>(khsa_vd.ViewDimension)) {
            e.sightings++;
            e.slots |= khsa_bit;
            if (khsa_vid != e.last_id) { e.last_id = khsa_vid; e.identities++; }
            e.last_seen = khsa_now;
            return;
        }
    }

    if (g_srv_arr_census_n >= static_cast<uint32_t>(KH_SRV_ARR_CENSUS_N)) {
        g_srv_arr_evicts++;
        return;
    }

    KhSrvArrObs& e = g_srv_arr_census[g_srv_arr_census_n++];
    e = KhSrvArrObs{};
    e.width = khsa_td.Width;
    e.height = khsa_td.Height;
    e.array_size = khsa_td.ArraySize;
    e.format = khsa_vfmt;
    e.res_format = static_cast<uint32_t>(khsa_td.Format);
    e.view_dim = static_cast<uint32_t>(khsa_vd.ViewDimension);
    e.slots = khsa_bit;
    e.identities = 1;
    e.sightings = 1;
    e.last_id = khsa_vid;
    e.last_seen = khsa_now;
}

inline void shadow_live_consider_atlas(ID3D11Texture2D* tex, const D3D11_TEXTURE2D_DESC& td) {
    // It is written as a code so the census can name the refusing clause;
    // nothing about what is adopted moves. Ledger at KhShadowTexObs.
    uint32_t khsc_clause = 0;

    if ((td.BindFlags & D3D11_BIND_SHADER_RESOURCE) == 0) {
        khsc_clause = 1;
    } else if (td.Width != td.Height || td.Width < 1024) {
        khsc_clause = 2;
    } else if (td.SampleDesc.Count > 1) {
        khsc_clause = 3;
    } else if (td.ArraySize != 1) {
        khsc_clause = 4;
    } else if (td.Format != DXGI_FORMAT_R32_TYPELESS && td.Format != DXGI_FORMAT_R24G8_TYPELESS &&
               td.Format != DXGI_FORMAT_R16_TYPELESS && td.Format != DXGI_FORMAT_R32G8X24_TYPELESS) {
        khsc_clause = 5;
    }

    kh_shadow_tex_census(tex, td, khsc_clause);

    if (khsc_clause != 0) return;

    void* id = static_cast<void*>(tex);
    if (id == g_ls.atlas_identity) { g_shadow_tex_same++; return; }
    // 'Keep the largest' alone made the hold a one-way latch: a mid-session
    // shadow-quality change RECREATES the engine atlas, and a
    // same-size-or-smaller successor could never displace the held one - a
    // dead texture kept alive while every resolve stopped matching it (cast
    // and receive quietly starve). GROW-OR-RECOVER adoption.
    const float now_at = effect_time_seconds();
    const bool held_dead = g_ls.atlas_tex && (now_at - g_ls.atlas_last_seen > 3.0f);
    if (g_ls.atlas_tex && td.Width <= g_ls.atlas_size && !held_dead) {
        g_shadow_tex_kept++;   // census: candidate lost to a larger live atlas
        return;   // keep the largest LIVE atlas
    }

    g_shadow_tex_adopts++;   // census: this candidate becomes the atlas

    if (g_ls.atlas_srv) { g_ls.atlas_srv->Release(); g_ls.atlas_srv = nullptr; }
    if (g_ls.atlas_tex) { g_ls.atlas_tex->Release(); }
    tex->AddRef();
    g_ls.atlas_tex = tex;

    g_ls.atlas_identity = id;
    g_ls.atlas_size = td.Width;
    g_ls.atlas_fmt = static_cast<uint32_t>(td.Format);
    g_atlas_srv_count = 0;   // the cache attested a different identity (cold-latch fix)
    g_ls.atlas_last_seen = now_at;   // adoption grace: displaceable only after 3 s unseen
    g_ls.srv_failed = false;
    g_ls.cache_valid = false;   // new atlas: relearn the upload locator
    g_atlas_srv_count = 0;   // cached SRVs belong to the OLD atlas

    // Drop the textures; band_capture's batch-create rebuilds all eight at
    // the adopted desc on the first reseal.
    for (int b = 0; b < 8; ++b) {
        auto& bb = g_ls.band[b];
        if (bb.srv) { bb.srv->Release(); bb.srv = nullptr; }
        if (bb.tex) { bb.tex->Release(); bb.tex = nullptr; }
        bb.valid = false;
        bb.pending_view = false;
        memset(bb.sm, 0, sizeof(bb.sm));
        memset(bb.border, 0, sizeof(bb.border));
        bb.last_time = 0.0f;
    }

    kh_band_pool_release();   // back buffers are clones of the OLD desc
}

static bool     g_tw_harvest = false;
static uint64_t g_hv_windows = 0;
static uint64_t g_hv_rej_scale = 0, g_hv_rej_ratio = 0, g_hv_rej_iso = 0;
static uint64_t g_hv_rej_trans = 0, g_hv_rej_ortho = 0;
static uint32_t g_hv_best_stage = 0;
static float    g_hv_best_n0 = -1.0f;
inline bool shadow_live_test_window(const float* w) {
    const float* r0 = w + 0;
    const float* r1 = w + 4;
    const float* r2 = w + 8;
    const float n0 = r0[0] * r0[0] + r0[1] * r0[1] + r0[2] * r0[2];
    const float n1 = r1[0] * r1[0] + r1[1] * r1[1] + r1[2] * r1[2];
    const float n2 = r2[0] * r2[0] + r2[1] * r2[1] + r2[2] * r2[2];
    if (n0 < 1e-12f || n1 < 1e-12f || n2 < 1e-12f) return false;

    // Scale window: every genuine sampling transform observed sits at 1/160..
    // 1/24 per meter (plus a 1/600 long-range one); [1/1000, 1/8] keeps that
    // family with margin and rejects the 1/2.2-scale look-alikes that slipped
    // under a bare <0.5 ceiling.
    if (n0 > 0.015625f || n1 > 0.015625f) { g_stats.live_rej_scale++;
        if (g_tw_harvest) { g_hv_rej_scale++; if (g_hv_best_stage < 1) { g_hv_best_stage = 0; } }
        return false; }   // uv scale <= 1/8
    if (n0 < 1e-7f || n1 < 1e-7f) { g_stats.live_rej_scale++;
        if (g_tw_harvest) { g_hv_rej_scale++; if (g_hv_best_stage < 1) { g_hv_best_stage = 1; g_hv_best_n0 = n0; } }
        return false; }   // floor 1/3162: LOW sun stretches extents // uv scale >= 1/1000
    // Depth scale within a factor ~20 of the uv scale (observed ~0.5-2x).
    if (n2 < 0.0025f * n0 || n2 > 400.0f * n0) { g_stats.live_rej_ratio++;
        if (g_tw_harvest) { g_hv_rej_ratio++; if (g_hv_best_stage < 2) { g_hv_best_stage = 2; g_hv_best_n0 = n0; } }
        return false; }
    // u/v isotropy (norms-squared within ~10% = norms within ~5%).
    if (fabsf(n1 - n0) > 0.1f * n0) { g_stats.live_rej_iso++;
        if (g_tw_harvest) { g_hv_rej_iso++; if (g_hv_best_stage < 3) { g_hv_best_stage = 3; g_hv_best_n0 = n0; } }
        return false; }
    if (w[3] < -8.0f || w[3] > 9.0f) { g_stats.live_rej_trans++;
        if (g_tw_harvest) { g_hv_rej_trans++; if (g_hv_best_stage < 4) { g_hv_best_stage = 4; g_hv_best_n0 = n0; } }
        return false; }
    if (w[7] < -8.0f || w[7] > 9.0f) { g_stats.live_rej_trans++; return false; }
    if (w[11] < -8.0f || w[11] > 9.0f) { g_stats.live_rej_trans++; return false; }
    const float d01 = r0[0] * r1[0] + r0[1] * r1[1] + r0[2] * r1[2];
    const float d02 = r0[0] * r2[0] + r0[1] * r2[1] + r0[2] * r2[2];
    const float d12 = r1[0] * r2[0] + r1[1] * r2[1] + r1[2] * r2[2];

    if (fabsf(d01) > KH_SHADOW_ORTHO_TOL * sqrtf(n0 * n1) ||
        fabsf(d02) > KH_SHADOW_ORTHO_TOL * sqrtf(n0 * n2) ||
        fabsf(d12) > KH_SHADOW_ORTHO_TOL * sqrtf(n1 * n2)) {
        g_stats.live_rej_ortho++;
        if (g_tw_harvest) { g_hv_rej_ortho++; if (g_hv_best_stage < 5) { g_hv_best_stage = 5; g_hv_best_n0 = n0; } }
        return false;
    }

    if (fabsf(r0[0] * r0[0] - n0) < KH_SHADOW_ORTHO_TOL * n0 &&
        fabsf(r1[1] * r1[1] - n1) < KH_SHADOW_ORTHO_TOL * n1 &&
        fabsf(r2[2] * r2[2] - n2) < KH_SHADOW_ORTHO_TOL * n2) {
        return false;   // scaled-identity false positives
    }

    for (int a = 0; a < 6; ++a) {
        float x, y, z;
        if (a < 3)  { const float* r = w + a * 4; x = r[0]; y = r[1]; z = r[2]; }
        else        { const int c = a - 3; x = r0[c]; y = r1[c]; z = r2[c]; }
        if (shadow_axis_abs_cos(x, y, z) >= KH_SHADOW_AXIS_COS_TOL) {
            g_stats.live_accepts++;

            return true;
        }
    }

    return false;
}

inline bool shadow_view_shaped(const float* w) {
    if (fabsf(w[15] - 1.0f) > 1e-3f) return false;
    const float n0 = w[0] * w[0] + w[1] * w[1] + w[2] * w[2];
    const float n1 = w[4] * w[4] + w[5] * w[5] + w[6] * w[6];
    if (n0 < 0.9f || n0 > 1.1f || n1 < 0.9f || n1 > 1.1f) return false;
    const float d01 = w[0] * w[4] + w[1] * w[5] + w[2] * w[6];
    return fabsf(d01) < 0.1f;
}

inline void shadow_view_scan(ID3D11Resource* res, const void* data, uint32_t bytes, uint32_t base_off = 0) {
    // base_off (floats): nonzero when the data is a WINDOW into the buffer
    // (the binding-readback path) - offsets stored and matched below are
    // canonical buffer offsets, so both supply paths feed one lock.
    if (!reorder_on_render_thread() || bytes < 64 || !res) return;

    // Under mode 406, where the compile blocks and the very first flush is a
    // gate-passed one, the SAME scene locks on bind scan number two at a
    // rotation error of 1.79e-07, with pubAccepts 274075 and every band
    // valid.
    if (g_acq_hold.load(std::memory_order_relaxed)) { g_acq_hold_scans++; return; }

    // LOCKED FAST PATH: with a source locked, the publish branch requires res
    // == view_src_res and the admission branch requires the lock to be ABSENT
    // - for every foreign resource the whole offset loop is already a
    // guaranteed no-op (~1,600 uploads x 49 compares per frame of pure
    // waste). One pointer compare is the identical no-op, cheaper.
    if (g_ls.view_src_valid && res != g_ls.view_src_res) return;
    const float* f = static_cast<const float*>(data);
    const uint32_t nf = bytes / 4;

    const bool khv_census = g_stats_armed.load(std::memory_order_relaxed);

    for (uint32_t off = 0; off + 16 <= nf && off <= 192; off += 4) {
        const float* w = f + off;

        // Pure observation: no branch below reads it, and it runs only while
        // armed, locked, and BEFORE this cycle's first accept - the only
        // window the question is about.
        if (khv_census && g_pub_first_d < 0.0f && g_ls.view_src_valid &&
            off + base_off != g_ls.view_src_off && g_ro.cycle_pv_valid &&
            shadow_view_shaped(w)) {
            float khv_a[16];

            if (g_ls.view_src_orient == 1) {
                memcpy(khv_a, w, sizeof(khv_a));
            } else {
                for (int r = 0; r < 4; ++r) {
                    for (int c = 0; c < 4; ++c) khv_a[r * 4 + c] = w[c * 4 + r];
                }
            }

            // Same three tests the publish applies, in the same order.
            const float khv_t = fabsf(khv_a[12]) + fabsf(khv_a[13]) + fabsf(khv_a[14]);

            if (khv_t <= 0.05f) {
                const float* khv_b = &g_ro.cycle_pv.view[0][0];
                float khv_er = 0.0f;

                for (int r = 0; r < 3; ++r) {
                    for (int c = 0; c < 3; ++c) {
                        khv_er += fabsf(khv_a[r * 4 + c] - khv_b[r * 4 + c]);
                    }
                }

                if (khv_er <= 0.35f) {   // the publish's own family bar
                    g_pub_alt_hits++;

                    if (g_pub_alt_first_d < 0.0f) {
                        g_pub_alt_first_d = static_cast<float>(g_topo.draws);
                        g_pub_alt_off = off + base_off;
                        g_pub_alt_er = khv_er;
                    }
                }
            }
        }

        // The probe re-validates the remembered source on the unfakeable
        // exact-class fingerprint (translation exactly zero AND rotation
        // within 1e-3 of the bridge) - a genuinely wrong first lock never
        // passes it.
        if (!g_ls.view_src_valid && res == g_ls.view_src_res &&
            off + base_off == g_ls.view_src_off &&
            g_ls.view_src_relative && g_ro.cycle_pv_valid) {
            float pf[16];

            if (g_ls.view_src_orient == 1) {
                memcpy(pf, w, sizeof(pf));
            } else {
                for (int r = 0; r < 4; ++r) {
                    for (int c = 0; c < 4; ++c) {
                        pf[r * 4 + c] = w[c * 4 + r];
                    }
                }
            }

            const float khr_tmag = fabsf(pf[12]) + fabsf(pf[13]) + fabsf(pf[14]);

            // tmag is scored first because the probe body is skipped entirely
            // above 0.05 - if the source stops reading camera-relative at
            // all, that is a different failure from reading camera-relative
            // but rotating wrong, and only the unconditional stamp separates
            // them.
            if (g_view_drop_path != 0) {
                g_view_relock_probes++;

                if (g_view_relock_tmag_min < 0.0f || khr_tmag < g_view_relock_tmag_min) {
                    g_view_relock_tmag_min = khr_tmag;
                }
            }

            if (khr_tmag <= 0.05f) {
                const float* bv = &g_ro.cycle_pv.view[0][0];
                float khr_er = 0.0f;

                for (int r = 0; r < 3; ++r) {
                    for (int c = 0; c < 3; ++c) {
                        khr_er += fabsf(pf[r * 4 + c] - bv[r * 4 + c]);
                    }
                }

                if (g_view_drop_path != 0 &&
                    (g_view_relock_er_min < 0.0f || khr_er < g_view_relock_er_min)) {
                    g_view_relock_er_min = khr_er;
                }

                bool khr_take = khr_er <= 1e-3f;

                if (!khr_take && g_dbg_mode.load(std::memory_order_relaxed) != 38 &&
                    g_view_drop_path == 1 && g_view_drop_bar > 0.0f &&
                    khr_er <= g_view_drop_bar) {
                    if (g_view_relock_wide_cycle != 0 &&
                        g_view_relock_wide_cycle + 1 == g_topo_cycles) {
                        khr_take = true;
                        g_view_relock_wide_takes++;
                    } else if (g_view_relock_wide_cycle != g_topo_cycles) {
                        g_view_relock_wide_arms++;
                    }

                    g_view_relock_wide_cycle = g_topo_cycles;
                    g_view_relock_wide_er = khr_er;
                }

                if (khr_take) {
                    // Relock: restore the source; entries latched while the
                    // pairing was dead were paired against garbage -
                    // boundary-wipe semantics (delay-class: the table
                    // rebuilds from live latches within a second).
                    g_ls.view_src_valid = true;
                    kh_view_lock_acquired(1);   // relock probe
                    g_ls.view_src_miss = 0;
                    g_ls.pub_rej_streak = 0;
                    g_ls.pub_ok_since_lock = false;   // re-confirm
                    g_ls.view_relocks++;
                    kh_live_wipe_note(1);
                    g_ls.count = 0;
                    g_ls.newest = -1;
                    g_lock_wipes++;
                    g_lock_churn_ms_v = steady_now_ms();   // lock-settle: hold the cast through the rebuild
                    kh_note_lock_churn(1);
                    g_ls.pub_exact_ms = steady_now_ms();
                    g_ls.pub_any_ms = g_ls.pub_exact_ms;   // relock counts as a publication
                    g_ls.pub_fresh_ms = g_ls.pub_exact_ms;   // exact by construction
                }
            }
        }

        if (g_ls.view_src_valid && res == g_ls.view_src_res && off + base_off == g_ls.view_src_off) {
            g_pub_slot_hits_f++;   // census: an upload AT the locked slot
            float fv[16];

            if (g_ls.view_src_orient == 1) {
                memcpy(fv, w, sizeof(fv));
            } else {
                for (int r = 0; r < 4; ++r) {
                    for (int c = 0; c < 4; ++c) {
                        fv[r * 4 + c] = w[c * 4 + r];
                    }
                }
            }

            if (g_ls.view_src_relative) {
                const float tmag = fabsf(fv[12]) + fabsf(fv[13]) + fabsf(fv[14]);

                if (tmag > 0.05f) {   // an object, not the view
                    if (g_pub_first_d < 0.0f) {   // census
                        g_pub_rej_tmag_f++;
                        g_pub_rej_tmag++;

                        if (g_pub_rej_first_d < 0.0f) {
                            g_pub_rej_first_d = static_cast<float>(g_topo.draws);
                        }
                    }

                    continue;
                }

                if (g_ro.cycle_pv_valid) {
                    const float* bv = &g_ro.cycle_pv.view[0][0];
                    float e_rot = 0.0f;

                    for (int r = 0; r < 3; ++r) {
                        for (int c = 0; c < 3; ++c) {
                            e_rot += fabsf(fv[r * 4 + c] - bv[r * 4 + c]);
                        }
                    }

                    // Family filter only: non-view families differ by >>1.
                    // 0.15 was speed-fragile (the bridge lags a frame; a fast
                    // spin exceeded it, reads stalled, the health check
                    // evicted the lock, and seals fell to the skewed fallback
                    // until relearn - the mid-session received drift that
                    // 'calmed down halfway through').
                    if (e_rot > 0.35f) {
                        if (g_pub_first_d < 0.0f) {   // census
                            g_pub_rej_family_f++;
                            g_pub_rej_family++;

                            if (g_pub_rej_first_d < 0.0f) {
                                g_pub_rej_first_d = static_cast<float>(g_topo.draws);
                            }
                        }

                        continue;
                    }

                    g_ls.last_publish_rot_err = e_rot;   // cold fire quality gate
                    g_ls.pub_any_ms = steady_now_ms();   // stream liveness (lit gate)
                    if (e_rot <= KH_LIT_FRESH_ERR) g_ls.pub_fresh_ms = g_ls.pub_any_ms;
                    // Exact-class stamp (the cast gate's recent-exact input;
                    // see pub_exact_ms). Same 1e-3 bar as the gates - the bar
                    // is unchanged, only WHERE it is evaluated moved.
                    if (e_rot <= 1e-3f) g_ls.pub_exact_ms = steady_now_ms();
                }
            }

            if (g_ls.view_src_relative && g_ro.cycle_pv_valid) {
                const float* bv = &g_ro.cycle_pv.view[0][0];
                float khpv_rd = 0.0f;

                for (int r = 0; r < 3; ++r) {
                    for (int c = 0; c < 3; ++c) khpv_rd += fabsf(fv[r * 4 + c] - bv[r * 4 + c]);
                }

                if (khpv_rd < 1.0e-5f) {
                    fv[12] = bv[12];
                    fv[13] = bv[13];
                    fv[14] = bv[14];
                } else {
                    double cam[3];

                    for (int j = 0; j < 3; ++j) {
                        cam[j] = -(static_cast<double>(bv[12]) * bv[j * 4 + 0] +
                                   static_cast<double>(bv[13]) * bv[j * 4 + 1] +
                                   static_cast<double>(bv[14]) * bv[j * 4 + 2]);
                    }

                    for (int c = 0; c < 3; ++c) {
                        fv[12 + c] = static_cast<float>(
                            -(cam[0] * fv[0 * 4 + c] + cam[1] * fv[1 * 4 + c] + cam[2] * fv[2 * 4 + c]));
                    }
                }

                fv[15] = 1.0f;
            }

            {
                const float pub_now = effect_time_seconds();
                if (g_pub_first < 0.0f) g_pub_first = pub_now;

                if (pub_now - g_pub_first < 3.0f) {
                    RVExtBridge::ProjectionViewTransform bpv = {};

                    if (RVExtBridge::get_projection_view_transform(bpv)) {
                        float bvv[16];
                        memcpy(bvv, &bpv.view, sizeof(bvv));
                        float rd = 0.0f;
                        float md = 0.0f;   // rotation moved since the last accepted publish

                        for (int rr = 0; rr < 3; ++rr) {
                            for (int cc = 0; cc < 3; ++cc) {
                                rd += fabsf(fv[rr * 4 + cc] - bvv[rr * 4 + cc]);
                                if (g_ls.prev_view_valid) md += fabsf(fv[rr * 4 + cc] - g_ls.prev_view[rr * 4 + cc]);
                            }
                        }

                        const float khpk_barv = 0.02f + (md < 0.3f ? md : 0.3f);

                        if (rd > khpk_barv) {
                            g_ls.cold_pub_rejects++;   // forensic: coldPubRejects

                            if (g_pub_first_d < 0.0f) {   // census
                                g_pub_rej_cold_f++;
                                g_pub_rej_cold++;

                                if (g_pub_rej_first_d < 0.0f) {
                                    g_pub_rej_first_d = static_cast<float>(g_topo.draws);
                                }
                            }

                            // Forty consecutive rejects (~0.7 s) drops the
                            // lock and the ring re-acquires from the live
                            // harvest within a few frames.
                            const uint32_t khpk_bar = g_ls.pub_ok_since_lock ? 40u : 8u;

                            if (++g_ls.pub_rej_streak >= khpk_bar && g_ls.view_src_valid) {
                                // The streak says the disagreement is
                                // STANDING; this says it is also BIG ENOUGH
                                // TO BE REAL. The KH_PUB_DROP_HOLD_MS clock
                                // below keeps a persistent small disagreement
                                // from becoming a permanent one - two
                                // continuous seconds of soft rejection still
                                // drops the lock. setRenderDebug 23 reverts.
                                const bool khpk_hard =
                                    rd > khpk_barv * KH_PUB_DROP_HYST;
                                const uint64_t khpk_now = steady_now_ms();

                                if (!khpk_hard &&
                                    g_dbg_mode.load(std::memory_order_relaxed) != 23) {
                                    if (g_view_drop_hyst_since == 0) {
                                        g_view_drop_hyst_since = khpk_now;
                                    }

                                    const uint64_t khpk_held =
                                        khpk_now - g_view_drop_hyst_since;

                                    if (static_cast<float>(khpk_held) > g_view_drop_hyst_max_ms) {
                                        g_view_drop_hyst_max_ms = static_cast<float>(khpk_held);
                                    }

                                    if (khpk_held < KH_PUB_DROP_HOLD_MS) {
                                        g_view_drop_hyst_holds++;
                                        g_view_drop_hyst_rd = rd;
                                        g_view_drop_hyst_bar = khpk_barv;
                                        return;   // full no-op: the lock survives
                                    }

                                    g_view_drop_hyst_forced++;   // the clock ran out
                                }

                                g_view_drop_forced++;
                                g_view_drop_path = 1;
                                // the identity we are dropping, so the next
                                // acquisition can be compared against it.
                                g_view_lock_res_pre = static_cast<const void*>(g_ls.view_src_res);
                                g_view_lock_off_pre = g_ls.view_src_off;
                                g_view_lock_orient_pre = g_ls.view_src_orient;
                                g_view_lock_same_slot = 0;
                                g_view_drop_ms = steady_now_ms();
                                g_view_drop_rd = rd;
                                g_view_drop_md = md;
                                g_view_drop_bar = khpk_barv;
                                g_view_relock_er_min = -1.0f;   // score the NEW dead era only
                                g_view_relock_tmag_min = -1.0f;
                                g_view_relock_probes = 0;
                                g_view_relock_wide_cycle = 0;
                                g_ring_best_valid = false;
                                g_ls.view_src_valid = false;
                                g_ls.vc_n = 0;
                                g_ls.pub_rej_streak = 0;
                                g_view_drop_hyst_since = 0;
                                g_view_relock_forced++;
                                kh_note_lock_churn(2);
                                g_lock_churn_ms_v = steady_now_ms();   // lock-settle: the dropped lock's
                                kh_live_wipe_note(2);
                                g_ls.count = 0;
                                g_ls.newest = -1;

                                for (int khpk_b = 0; khpk_b < 8; ++khpk_b) {
                                    g_ls.band[khpk_b].valid = false;
                                    g_ls.band[khpk_b].pending_view = false;
                                }

                                g_relock_recv_wipes++;
                            }

                            return;   // full no-op: no publish state was touched
                        }

                        g_ls.pub_rej_streak = 0;
                        g_view_drop_hyst_since = 0;   // the run is broken
                        g_ls.pub_ok_since_lock = true;   // confirmed
                    }
                }
            }

            if (g_ls.frame_view_valid) {
                memcpy(g_ls.prev_view, g_ls.frame_view, sizeof(g_ls.prev_view));
                g_ls.prev_view_valid = true;
                // KH_BAND_ALT_PROVISIONAL: when the incoming publish crosses
                // sources, the outgoing frame_view IS the other source's
                // freshest statement - latch it.
                float khav_a[3], khav_b[3];
                if (kh_view_camera_exact(reinterpret_cast<const float(*)[4]>(g_ls.frame_view), khav_a) &&
                    kh_view_camera_exact(reinterpret_cast<const float(*)[4]>(fv), khav_b)) {
                    const float khav_dx = khav_a[0] - khav_b[0];
                    const float khav_dy = khav_a[1] - khav_b[1];
                    const float khav_dz = khav_a[2] - khav_b[2];
                    const float khav_d = sqrtf(khav_dx * khav_dx + khav_dy * khav_dy +
                                               khav_dz * khav_dz);
                    if (khav_d == khav_d && khav_d > 0.5f) {
                        memcpy(g_ls.alt_view, g_ls.frame_view, sizeof(g_ls.alt_view));
                        g_ls.alt_view_valid = true;
                        g_ls.alt_view_time = g_ls.frame_view_time;
                    }
                }
            }

            memcpy(g_ls.frame_view, fv, sizeof(g_ls.frame_view));
            g_ls.frame_view_valid = true;
            g_ls.frame_view_time = effect_time_seconds();
            g_ls.frame_view_hits++;
            g_ls.view_published_this_frame = true;

            if (g_pub_first_d < 0.0f) {   // census: the cycle's FIRST accept
                g_pub_first_d = static_cast<float>(g_topo.draws);
                g_pub_hits_pre_accept = g_pub_slot_hits_f - 1u;   // this hit excluded
                if (g_view_scan_from_bind) g_pub_bind_accepts++;
            }

            g_pub_accepts++;
            // the arm is UNCONDITIONAL on the publish again.
            if (!g_mask_cast_fired) {
                g_mask_cast_arm = true;   // once per frame (engine-mask path)
            }

            // complete any seals waiting for this frame's view
            for (int bi = 0; bi < 8; ++bi) {
                auto& bs = g_ls.band[bi];
                if (!bs.valid || !bs.pending_view) continue;

                if (g_ls.last_publish_rot_err > 1e-3f) {
                    g_ls.band_bail_quality++;
                    continue;
                }

                // RECEIVE-V2 EPOCH GUARD: a pending seal older than this
                // frame would pair a CROSS-FRAME view - the permanent receive
                // offset (the same epoch-mixing disease the cast had).
                // Invalidate instead; the next resolve reseals with a
                // same-frame pair. This also retires the 100 ms bridge
                // fallback (stale pendings die at 50 ms, before it fires).
                if (g_ls.frame_view_time - bs.pending_since > 0.05f) {
                    // default = the ORIGINAL epoch death (invalidate). The
                    // adaptive tail lives inside mode 341 with its stack.
                    if (g_dbg_mode.load(std::memory_order_relaxed) != 341) {
                        bs.valid = false;
                        bs.pending_view = false;
                        // reseal next sweep instead of waiting out the tier
                        // interval (348 restores the wait).
                        if (g_dbg_mode.load(std::memory_order_relaxed) != 348) {
                            bs.last_time = 0.0f;
                            g_band_pend_dead_fast++;
                        }
                        continue;
                    }
                    // ADAPTIVE TAIL (see the late bar; same rule).
                    if (!bs.vcol_bridge) {
                        const bool khtb_alive = g_ls.alt_view_valid &&
                            g_ls.frame_view_time - g_ls.alt_view_time < 0.25f;
                        if (g_dbg_mode.load(std::memory_order_relaxed) == 344 ||
                            !khtb_alive) {
                            bs.pending_view = false;
                            if (!khtb_alive) g_band_pend_single_src++;
                        } else {
                            bs.valid = false;
                            bs.pending_view = false;
                            bs.last_time = 0.0f;   // reseal next sweep
                        }
                        g_band_pend_timeout_kept++;
                    } else {
                        bs.valid = false;
                        bs.pending_view = false;
                    }
                    continue;
                }

                // Measured BEFORE the overwrite, because the overwrite is the
                // event under suspicion. vcol[c*4+r] == V[r*4+c], so the
                // world camera forward axis is (vcol[8], vcol[9], vcol[10])
                // on the old pair and (fv[2], fv[6], fv[10]) on the incoming
                // one.
                if (!kh_band_view_native(fv, true)) {   // foreign publish never completes a seal
                    continue;
                }
                // Absent beats offset: invalidate (the epoch guard's exact
                // shape) and the next resolve reseals coherent.
                // KH_BAND_PAIR_MIXED (mode 337 reverts): the provisional vcol
                // IS the capture's own view; a completing publish >50 m from
                // it would weld sm(A) to view(B).
                if (!bs.vcol_bridge &&
                    !kh_band_pair_coherent(bs.vcol, fv)) {
                    bs.valid = false;
                    bs.pending_view = false;
                    continue;
                }
                {
                    bool khcv_ok = !bs.vcol_bridge;
                    for (int khcv_j = 0; khcv_ok && khcv_j < 3; ++khcv_j) {
                        const float* khcv_v = &bs.vcol[khcv_j * 4];
                        const float khcv_n = sqrtf(khcv_v[0] * khcv_v[0] +
                                                   khcv_v[1] * khcv_v[1] +
                                                   khcv_v[2] * khcv_v[2]);
                        if (!(khcv_n > 0.9f && khcv_n < 1.1f)) khcv_ok = false;
                    }
                    const float khcv_t = sqrtf(bs.vcol[3] * bs.vcol[3] +
                                               bs.vcol[7] * bs.vcol[7] +
                                               bs.vcol[11] * bs.vcol[11]);
                    if (khcv_t == khcv_t) {
                        g_band_complete_old_trn_m = khcv_t;
                        if (khcv_t > g_band_complete_old_trn_max_m) {
                            g_band_complete_old_trn_max_m = khcv_t;
                        }
                    }
                    if (!khcv_ok) g_band_complete_inv++;
                    const bool khcc_cross = g_boundary_t >= 0.0f &&
                                            bs.pending_since < g_boundary_t;
                    float khcc_d = bs.vcol[8] * fv[2] + bs.vcol[9] * fv[6] +
                                   bs.vcol[10] * fv[10];
                    khcc_d = khcc_d > 1.0f ? 1.0f : (khcc_d < -1.0f ? -1.0f : khcc_d);
                    const float khcc_deg = acosf(khcc_d) * 57.29578f;
                    // |t_old - t_new| between two WORLD-space views
                    // (bandCompleteOldTrnM ~ camAbsM, measured) is rotation
                    // times the |C| lever arm - the 853-1556 m class was
                    // never a camera distance. The lane now reports the exact
                    // camera gap; the deg lane carries rotation alone.
                    float khcc_m = -1.0f;
                    {
                        float khcc_a[3] = { 0.0f, 0.0f, 0.0f };
                        for (int khcc_j = 0; khcc_j < 3; ++khcc_j) {
                            const float* khcc_v = &bs.vcol[khcc_j * 4];
                            khcc_a[0] -= khcc_v[3] * khcc_v[0];
                            khcc_a[1] -= khcc_v[3] * khcc_v[1];
                            khcc_a[2] -= khcc_v[3] * khcc_v[2];
                        }
                        float khcc_b[3];
                        if (khcv_ok &&
                            kh_view_camera_exact(reinterpret_cast<const float(*)[4]>(fv), khcc_b)) {
                            const float khcc_dx = khcc_a[0] - khcc_b[0];
                            const float khcc_dy = khcc_a[1] - khcc_b[1];
                            const float khcc_dz = khcc_a[2] - khcc_b[2];
                            const float khcc_q = sqrtf(khcc_dx * khcc_dx +
                                                       khcc_dy * khcc_dy +
                                                       khcc_dz * khcc_dz);
                            if (khcc_q == khcc_q) khcc_m = khcc_q;
                        }
                    }

                    if (khcv_ok && khcc_cross) {
                        g_band_complete_cross++;
                        g_band_complete_skew_deg = khcc_deg;
                        g_band_complete_skew_m = khcc_m;

                        if (khcc_deg > g_band_complete_skew_max) {
                            g_band_complete_skew_max = khcc_deg;
                        }

                        if (khcc_m > g_band_complete_skew_max_m) {
                            g_band_complete_skew_max_m = khcc_m;
                        }
                    } else if (khcv_ok) {
                        g_band_complete_same++;
                    }
                }

                const float khoc_page = g_ls.frame_view_time - bs.pending_since;
                // the whole -completion stack is mode 341; the default is
                // baseline (overwrite unconditionally below).
                const bool khcm_on =
                    g_dbg_mode.load(std::memory_order_relaxed) == 341;
                // widened 0.025 -> 0.045 - the flip's wait for its own
                // cascade's publish (CompAgeMsMax 24.3 measured; epoch at 50
                // still backstops).
                if (khcm_on && khoc_page > 0.045f) {
                    if (!bs.vcol_bridge) {
                        // Mode 344 = old tails. Where the second source is
                        // DEAD (no alt-latch crossing for 0.25 s) there is no
                        // lottery: the provisional IS the source - finalize
                        // (baseline behaviour, which never cut off).
                        const bool khta_alive = g_ls.alt_view_valid &&
                            g_ls.frame_view_time - g_ls.alt_view_time < 0.25f;
                        if (g_dbg_mode.load(std::memory_order_relaxed) == 344 ||
                            !khta_alive) {
                            bs.pending_view = false;
                            if (!khta_alive) g_band_pend_single_src++;
                        } else {
                            bs.valid = false;
                            bs.pending_view = false;
                            bs.last_time = 0.0f;   // reseal next sweep
                        }
                        g_band_pend_late_kept++;   // tail events (both kinds)
                    } else {
                        g_band_pend_late_bridge++;
                    }
                    continue;
                }

                // Bridge provisionals are exempt: they cannot finalize and
                // never serve unfinalized, so refusing would only starve
                // them.
                if (khcm_on && !bs.vcol_bridge) {
                    const float khss_d = kh_band_source_gap(bs.vcol, fv);
                    const int khss_m = g_dbg_mode.load(std::memory_order_relaxed);
                    if (khss_m == 342) {
                        // lock (archaeology): cross-source finalizes.
                        if (khss_d > 0.5f) {
                            g_band_comp_src_ref++;
                            g_band_comp_src_m = khss_d;
                            if (khss_d > g_band_comp_src_max_m) g_band_comp_src_max_m = khss_d;
                            bs.pending_view = false;
                            continue;
                        }
                    } else if (khss_m != 340) {
                        if (khss_d >= 0.0f && khss_d <= 0.5f) {
                            g_band_comp_src_alt++;
                            continue;
                        }
                    }
                }
                // PICK CENSUS (always on): every accepted overwrite,
                // classified by the provisional-vs-completing camera gap.
                if (!bs.vcol_bridge) {
                    const float khpx_d = kh_band_source_gap(bs.vcol, fv);
                    if (khpx_d >= 0.0f) {
                        if (khpx_d > 0.5f) g_band_comp_xsrc++;
                        else g_band_comp_samesrc++;
                    }
                }
                // ORDER CENSUS: the served weld span (accepted only).
                {
                    const float khoc_cms = khoc_page * 1000.0f;
                    if (khoc_cms == khoc_cms) {
                        g_band_comp_age_sum += khoc_cms;
                        g_band_comp_age_n++;
                        if (khoc_cms > g_band_comp_age_max_ms) g_band_comp_age_max_ms = khoc_cms;
                    }
                }
                for (int c = 0; c < 3; ++c) {
                    for (int r = 0; r < 4; ++r) {
                        bs.vcol[c * 4 + r] = fv[r * 4 + c];
                    }
                }

                bs.pending_view = false;
                bs.vcol_bridge = false;
                g_ls.seal_completions++;
                kh_weld_note(bs.vcol, 6.0f);   // weld identity census

            }

            // Latched here, read only by the mode-346 commit; first cross
            // wins; foreign publishes never latch and non-exact publishes
            // never latch (the commit's own quality bar). Stages from the
            // current cycle wait for the next one, the commit's own
            // convention.
            if (g_ls.last_publish_rot_err <= 1e-3f && kh_band_view_native(fv, false)) {
                for (int khsf_i = 0; khsf_i < 8; ++khsf_i) {
                    auto& khsf_b = g_ls.band[khsf_i];
                    if (!khsf_b.stage_valid || khsf_b.stage_first_ok) continue;
                    for (int c = 0; c < 3; ++c) {
                        for (int r = 0; r < 4; ++r) {
                            khsf_b.stage_first[c * 4 + r] = fv[r * 4 + c];
                        }
                    }
                    khsf_b.stage_first_ok = true;
                }
            }
            if (g_ls.last_publish_rot_err <= 1e-3f && kh_band_view_native(fv, false)) {
                for (int khfl_i = 0; khfl_i < 8; ++khfl_i) {
                    auto& khfl_b = g_ls.band[khfl_i];
                    if (!khfl_b.stage_valid || khfl_b.stage_pair_ok ||
                        !khfl_b.stage_view_ok) continue;
                    if (g_boundary_t >= 0.0f &&
                        khfl_b.stage_since >= g_boundary_t) continue;
                    const float khfl_d = kh_band_source_gap(khfl_b.stage_view, fv);
                    if (khfl_d > 0.5f) {
                        for (int c = 0; c < 3; ++c) {
                            for (int r = 0; r < 4; ++r) {
                                khfl_b.stage_pair[c * 4 + r] = fv[r * 4 + c];
                            }
                        }
                        khfl_b.stage_pair_ok = true;
                    }
                }
            }

            return;
        }

        if (!g_ls.view_src_valid && shadow_view_shaped(w)) {
            // a tab-out stalls uploads past the health limit) the true view
            // could never survive in the ring long enough to relearn, and
            // everything downstream froze (camera-following cast, 91%
            // incomplete seals). RELATIVE FINGERPRINT at admission: ~1,600
            // streaming object uploads per frame flood a 16-slot ring in
            // microseconds - after an eviction (e.g.
            const float tmag_r = fabsf(w[12]) + fabsf(w[13]) + fabsf(w[14]);
            const float tmag_c = fabsf(w[3]) + fabsf(w[7]) + fabsf(w[11]);
            g_va_shaped++;   // hunt census

            if (tmag_r >= 10.0f && tmag_c >= 10.0f) {
                const float khv_t = tmag_r < tmag_c ? tmag_r : tmag_c;
                if (khv_t < g_va_tmag_min) g_va_tmag_min = khv_t;
            }

            if (tmag_r < 10.0f || tmag_c < 10.0f) {
                const uint32_t i = g_ls.vc_n & 15;
                g_ls.vc_ring[i].res = res;
                g_ls.vc_ring[i].off = off + base_off;
                memcpy(g_ls.vc_ring[i].m, w, 64);
                g_ls.vc_n++;
                g_ring_admits++;

                // The ring keeps the last sixteen; this keeps the BEST one,
                // so the injection's position stops deciding what the hunt
                // gets to see. Both orientations are scored because the
                // convention is not known until the lock is taken.
                if (g_ro.cycle_pv_valid &&
                    g_dbg_mode.load(std::memory_order_relaxed) != 41) {
                    const float* khb_t = &g_ro.cycle_pv.view[0][0];

                    for (int khb_o = 1; khb_o <= 2; ++khb_o) {
                        float khb_e = 0.0f;

                        for (int r = 0; r < 3; ++r) {
                            for (int c = 0; c < 3; ++c) {
                                const float khb_v = (khb_o == 1) ? w[r * 4 + c]
                                                                 : w[c * 4 + r];
                                khb_e += fabsf(khb_v - khb_t[r * 4 + c]);
                            }
                        }

                        if (!g_ring_best_valid || khb_e < g_ring_best_er) {
                            g_ring_best_valid = true;
                            g_ring_best_er = khb_e;
                            g_ring_best_res = static_cast<const void*>(res);
                            g_ring_best_off = off + base_off;
                            g_ring_best_orient = static_cast<uint32_t>(khb_o);
                            g_ring_best_cycle = g_topo_cycles;
                            memcpy(g_ring_best_m, w, 64);
                        }
                    }
                }
            }
        }
    }
}

inline void shadow_register_upload(ID3D11Resource* res, const void* data, uint32_t bytes) {
    if (!res || !data || bytes < 48) return;   // cap removed: big CBs hold the maps

    for (uint32_t i = 0; i < 16; ++i) {
        if (g_ls.cb_reg[i].buf == res) {
            g_ls.cb_reg[i].floats = bytes / 4 <= 512 ? bytes / 4 : 512;
            g_ls.cb_reg[i].seq = ++g_ls.cb_reg_seq;
            memcpy(g_ls.cb_reg[i].data, data, g_ls.cb_reg[i].floats * sizeof(float));
            return;
        }
    }

    CbRegSlot:
    {
        auto& r = g_ls.cb_reg[g_ls.cb_reg_next];
        g_ls.cb_reg_next = (g_ls.cb_reg_next + 1) & 15;
        r.seq = ++g_ls.cb_reg_seq;
        r.buf = res;
        r.floats = bytes / 4 <= 512 ? bytes / 4 : 512;
        memcpy(r.data, data, r.floats * sizeof(float));
    }
}

inline bool kh_probe_world_cycle() {
    return !g_ro.cycle_vp_valid ||
           (g_ro.cycle_vp_min <= 0.3f && g_ro.cycle_vp_max >= 0.7f);
}

// 15% luminance band - tight enough to SEPARATE the two observed
// standard-flavor regimes (0.822 vs 1.174 amb-lum: 30% apart) that the
// adoption side's 50% band deliberately merges.
inline bool kh_probe_lum_band(float a, float b) {
    const float khp_m = a > b ? a : b;
    const float khp_eps = 0.15f * khp_m > 0.02f ? 0.15f * khp_m : 0.02f;
    return fabsf(a - b) <= khp_eps;
}

inline bool kh_probe_anchor_band(float a, float b) {
    const float khpa_m = a > b ? a : b;
    // 4% excludes it; real drift rides the 5%/s anchor tracking and never
    // nears the band edge. 8% -> 4%.
    const float khpa_eps = 0.04f * khpa_m > 0.02f ? 0.04f * khpa_m : 0.02f;
    return fabsf(a - b) <= khpa_eps;
}

// The interleaved foreign writer can therefore never land (the world writer
// keeps re-arming the standing flavor every frame), while a REAL lighting
// change (skipTime, overcast roll) moves every writer to the new level, the
// standing flavor goes silent, and the new level adopts in 500 ms.
inline void kh_probe_std_refresh(CbColorProbe& khp, const float* f, uint32_t nf, float khp_now) {
    // The arbitration below judges only PERSISTENCE, never content, so when
    // the real block pauses during the transition window the blank wins
    // exclusivity and HIJACKS the standing regime - after which recovery is
    // impossible by design: every real-flavor pending dies at the next blank
    // sighting ('standing flavor still live'), the mirror goes blank, and
    // downstream shows one of two faces of the same root: publish ADOPTS the
    // blank when the sun-jump witness is fresh (black boxes; stats3:
    // std/mirror/staged all zero with lightLocStdAgeS 11 ms in daylight), or
    // collapse-HOLDS the previous day values against it when the witness is
    // stale (the dimmed-noon-at-night boxes).
    if (khp.off >= 40 && khp.off - 40 + 38 < nf) {
        const float* khpz_b = f + (khp.off - 40);
        const float khpz_al = khpz_b[8] + khpz_b[9] + khpz_b[10];
        const float khpz_sl = khpz_b[16] + khpz_b[17] + khpz_b[18];
        const float khpz_fl = khpz_b[36] + khpz_b[37] + khpz_b[38];

        if (khpz_al < 1.0e-6f && khpz_sl < 1.0e-6f && khpz_fl < 1.0e-6f) {
            g_blk_blank_skips++;
            return;
        }
    }

    bool khp_apply = true;
    bool khp_adopted = false;   // this apply came through a regime adoption

    // Refuse it instead; cold (no standing yet) keeps the unconditional first
    // capture.
    if (khp.std_amb_l >= 0.0f && !(khp.off >= 40 && khp.off - 40 + 18 < nf)) {
        g_blk_smallnf_skips++;
        return;
    }

    if (khp.off >= 40 && khp.off - 40 + 18 < nf && khp.std_amb_l >= 0.0f) {
        const float* khp_b = f + (khp.off - 40);
        const float khp_al = khp_b[8] + khp_b[9] + khp_b[10];
        const float khp_sl = khp_b[16] + khp_b[17] + khp_b[18];
        if (khp_sl > 1.0f) g_blk_bright_seen_t = khp_now;

        // ser 6629->6630 sun 17.235->13.751 at amb 1.44) with blkRegimeAdopts
        // 0 over 6938 flushes and 5.3M rejects - the standing never ADOPTS,
        // it WALKS: the locked buffer multiplexes two standard-mode flavors
        // (~2780 confirms/flush) and chained in-band intermediate uploads
        // migrate the standing a whole cluster inside one frame, so the
        // end-of-frame winner follows draw composition, i.e.
        const bool khan_off = g_dbg_mode.load(std::memory_order_relaxed) == 258;
        const float khan_ra = (!khan_off && khp.anch_amb_l >= 0.0f) ? khp.anch_amb_l : khp.std_amb_l;
        const float khan_rs = (!khan_off && khp.anch_sun_l >= 0.0f) ? khp.anch_sun_l : khp.std_sun_l;

        // Real night: witness below horizon, predicate never engages,
        // bit-identical. The sticky guard protects the pending from THIRD
        // flavors only; nothing protected it from the ruling flavor itself.
        if (kh_probe_anchor_band(khp_al, khan_ra) &&   // 8% - see the band's
            kh_probe_anchor_band(khp_sl, khan_rs)) {
            const bool khkc_jump = g_sun_last_jump_ms != 0 &&
                steady_now_ms() - g_sun_last_jump_ms < 15000;
            const bool khp_kill_contra =
                g_dbg_mode.load(std::memory_order_relaxed) != 429 &&
                khp.std_sun_l >= 0.0f && khp.std_sun_l < 0.1f &&
                khp.pend_t >= 0.0f && khp.pend_sun_l > 1.0f &&
                g_blk_bright_seen_t >= 0.0f &&
                khp_now - g_blk_bright_seen_t < KH_BLK_BRIGHT_RECENT_S &&
                !khkc_jump;
            if (khp_kill_contra) {
                g_blk_contra_pend_holds++;   // engagement lane
            } else {
                khp.pend_t = -1.0f;   // standing flavor still live: pending dies
                khp.pend_seen = -1.0f;
            }
        } else {
            if (kh_probe_lum_band(khp_al, khp.std_amb_l) &&
                kh_probe_lum_band(khp_sl, khp.std_sun_l)) {
                g_blk_anchor_rejects++;   // the intra-frame walk step, named
            }
            const bool khp_agree = khp.pend_t >= 0.0f &&
                kh_probe_lum_band(khp_al, khp.pend_amb_l) &&
                kh_probe_lum_band(khp_sl, khp.pend_sun_l);

            if (khp_agree) khp.pend_seen = khp_now;
            const bool khp_starved = khp.last_std_time >= 0.0f &&
                khp_now - khp.last_std_time > 2.0f;
            // The starvation rescue keys on the standing going UNSEEN, but a
            // wrong dark flavor can itself upload every frame - standing
            // "alive", every interleaved third flavor re-seeds the pending,
            // the bright world flavor never survives its 500 ms bar, and a
            // sun-dark standing rules a lit world forever.
            const bool khp_dark_contra = khp.std_sun_l >= 0.0f && khp.std_sun_l < 0.1f &&
                khp.pend_t >= 0.0f && khp.pend_sun_l > 1.0f &&
                kh_sky_static() && fabsf(g_skysun_ref[1]) > 0.10f;
            if (khp_dark_contra) g_blk_dark_contra_sticky++;
            // the contradiction WINDOW, not the per-upload count. The sticky
            // lane counts uploads and a busy frame inflates it; the escape
            // needs elapsed time, so the window's open edge is latched and
            // cleared the moment the contradiction stops.
            if (khp_dark_contra) {
                if (g_blk_dark_contra_first < 0.0f) g_blk_dark_contra_first = khp_now;
            } else {
                g_blk_dark_contra_first = -1.0f;
            }
            const bool khp_dark_escape = khp_dark_contra && khp_sl > 1.0f &&
                g_blk_dark_contra_first >= 0.0f &&
                khp_now - g_blk_dark_contra_first > 2.0f &&
                g_dbg_mode.load(std::memory_order_relaxed) != 93;

            if (!khp_agree) {
                if (khp_dark_escape) {
                    // khp_apply is left ALONE so the apply below runs, which
                    // is how the adoption branch signals success. Only a
                    // bright incoming flavor can get here.
                    khp.regime_adopts++;
                    khp_adopted = true;   // anchor snaps at the apply tail
                    g_blk_dark_force_adopts++;
                    g_blk_dark_force_held_s = khp_now - g_blk_dark_contra_first;
                    g_blk_dark_contra_first = -1.0f;   // window closes with the fix
                } else if ((khp_starved || khp_dark_contra) && khp.pend_t >= 0.0f && khp.pend_seen >= 0.0f &&
                    khp_now - khp.pend_seen < 0.35f) {
                    if (khp_dark_contra) {
                        g_blk_sticky_rejects++;
                        g_blk_sticky_pend_age = khp.pend_t >= 0.0f ? khp_now - khp.pend_t : -1.0f;
                        if (g_blk_sticky_pend_age > g_blk_sticky_pend_age_max) {
                            g_blk_sticky_pend_age_max = g_blk_sticky_pend_age;
                        }
                        g_blk_sticky_in_sl = khp_sl;
                        g_blk_sticky_pend_sl = khp.pend_sun_l;
                        g_blk_sticky_std_sl = khp.std_sun_l;
                    }
                    khp_apply = false;
                    khp.regime_rejects++;
                } else if (khp_dark_contra &&
                           (khp_sl < 1.0f ||
                            (g_dbg_mode.load(std::memory_order_relaxed) != 63 &&
                             khp.pend_sun_l > 1.0f &&
                             khp_sl < khp.pend_sun_l * KH_BLK_DARK_RESEED_FRAC)) &&
                           g_dbg_mode.load(std::memory_order_relaxed) != 18) {
                    // The clock, not the values, is what starves the
                    // adoption: 0.95 sightings a frame slip past the sticky
                    // guard above and each one sets pend_t = now, so the 500
                    // ms exclusivity bar below is never reached.
                    khp_apply = false;
                    khp.regime_rejects++;
                    g_blk_dark_seed_blocks++;
                } else {
                    if (khp_dark_contra) {
                        g_blk_dark_reseeds++;
                        g_blk_dark_reseed_sl = khp_sl;
                        if (khp_sl < g_blk_dark_reseed_sl_min ||
                            g_blk_dark_reseed_sl_min < 0.0f) g_blk_dark_reseed_sl_min = khp_sl;
                        if (khp_sl > g_blk_dark_reseed_sl_max) g_blk_dark_reseed_sl_max = khp_sl;
                        g_blk_dark_reseed_sl_sum += static_cast<double>(khp_sl);
                        g_blk_dark_reseed_pend_sl = khp.pend_sun_l;
                        g_blk_dark_std_sl = khp.std_sun_l;
                        if (khp.pend_sun_l > 1.0e-4f) {
                            const float khp_ratio = khp_sl / khp.pend_sun_l;
                            if (khp_ratio < g_blk_dark_reseed_ratio_min ||
                                g_blk_dark_reseed_ratio_min < 0.0f) g_blk_dark_reseed_ratio_min = khp_ratio;
                            if (khp_ratio > g_blk_dark_reseed_ratio_max) g_blk_dark_reseed_ratio_max = khp_ratio;
                        }
                        if (g_blk_dark_first_s < 0.0f) g_blk_dark_first_s = khp_now;
                        g_blk_dark_last_s = khp_now;
                    }
                    khp.pend_amb_l = khp_al;
                    khp.pend_sun_l = khp_sl;
                    khp.pend_t = khp_now;
                    khp.pend_seen = khp_now;
                    khp_apply = false;
                    khp.regime_rejects++;
                }
            } else if (khp_now - khp.pend_t < 0.5f) {
                khp_apply = false;
                khp.regime_rejects++;
            } else if (khp.std_sun_l > 1.0f && khp_sl < 0.1f * khp.std_sun_l &&
                       !(g_sun_last_jump_ms != 0 &&
                         steady_now_ms() - g_sun_last_jump_ms < 15000)) {
                // Persistence alone cannot split a skipTime night from the
                // cloud-deck blend; the sun-jump witness can.
                khp_apply = false;
                khp.regime_rejects++;
                g_blk_collapse_holds++;
            } else if (khp_starved && khp.std_sun_l > 1.0f &&
                       khp.pend_sun_l >= 0.0f &&
                       khp.pend_sun_l < KH_BLK_STARVED_DIM_FRAC * khp.std_sun_l &&
                       !(g_sun_last_jump_ms != 0 &&
                         steady_now_ms() - g_sun_last_jump_ms < 15000) &&
                       g_dbg_mode.load(std::memory_order_relaxed) != 433 &&
                       kh_blk_sdh_window_holds(khp_now)) {
                // The rescue's premise - the unseen standing is dead -
                // remains true; its corollary - the first resumer is
                // therefore the world's lighting - was never stated and is
                // now measured false (entry ratio 0.222 in one flush against
                // a standing confirmed bright moments before).
                khp_apply = false;
                khp.regime_rejects++;
                g_blk_starved_dim_holds++;
            } else {
                khp.regime_adopts++;   // exclusive for 500 ms: a real level change
                khp_adopted = true;   // anchor snaps at the apply tail
                if (khp_starved) g_blk_starved_adopts++;   // census
                if (khp_dark_contra) g_blk_dark_readopts++;   // census
                {
                    const float khac_r = (khp.std_sun_l > 1.0e-6f && khp.pend_sun_l >= 0.0f)
                        ? khp.pend_sun_l / khp.std_sun_l : -1.0f;
                    g_blk_adopt_ratio_last = khac_r;
                    if (khac_r >= 0.0f) {
                        if (g_blk_adopt_ratio_min < 0.0f || khac_r < g_blk_adopt_ratio_min)
                            g_blk_adopt_ratio_min = khac_r;
                        if (khac_r > g_blk_adopt_ratio_max) g_blk_adopt_ratio_max = khac_r;
                    }
                    const float khac_g = (khp.last_std_time >= 0.0f)
                        ? khp_now - khp.last_std_time : -1.0f;
                    g_blk_adopt_gap_last = khac_g;
                    if (khac_g > g_blk_adopt_gap_max) g_blk_adopt_gap_max = khac_g;
                    g_blk_adopt_t_last = khp_now;
                }
            }
        }
    }

    // KH_FOG_LANE_REFRESH - (mode 321 reverts; catalog ledger). THE FOG TERMS
    // HAVE BEEN RIDING A LUMINANCE VERDICT THEY HAVE NOTHING TO DO WITH.
    if (!khp_apply) {
        const uint32_t khfg_base = khp.off >= 40 ? khp.off - 40 : 0;
        if (g_dbg_mode.load(std::memory_order_relaxed) != 321 &&
            khp.std_amb_l >= 0.0f &&   // a mirror exists to patch
            khfg_base == khp.nb_base &&   // same window as the capture
            khfg_base + 56 <= nf) {
            uint32_t khfg_mode = 0;
            memcpy(&khfg_mode, &f[khfg_base + 44], sizeof(khfg_mode));
            if (khfg_mode == 1u || khfg_mode == 3u) {
                memcpy(khp.nb + 36, f + khfg_base + 36, 20 * sizeof(float));
                g_blk_fog_refreshes++;
            } else {
                g_blk_fog_mode_stands++;
            }
        }
        return;
    }
    g_blk_applies++;   // applied captures (the ffr row deltas ride this)
    locator_capture(khp, f, nf, 56);
    khp.meta = static_cast<int>(khp.off - khp.nb_base);
    khp.last_std_time = khp_now;
    khp.std_amb_l = khp.nb[8] + khp.nb[9] + khp.nb[10];
    khp.std_sun_l = khp.nb[16] + khp.nb[17] + khp.nb[18];
    // Under 258 the anchor shadows the standing so a live un-revert never
    // acts on a stale reference.
    if (khp.anch_sun_l < 0.0f || khp_adopted ||
        g_dbg_mode.load(std::memory_order_relaxed) == 258) {
        khp.anch_amb_l = khp.std_amb_l;
        khp.anch_sun_l = khp.std_sun_l;
        khp.anch_t = khp_now;
        if (khp_adopted) g_blk_anchor_snaps++;
    } else {
        const float khan_dt = (khp.anch_t >= 0.0f && khp_now > khp.anch_t)
                            ? (khp_now - khp.anch_t) : 0.0f;
        khp.anch_t = khp_now;
        const float khan_r = 0.05f * khan_dt;
        const float khan_da = khp.std_amb_l - khp.anch_amb_l;
        const float khan_ca = khan_r * fmaxf(khp.anch_amb_l, 0.02f);
        khp.anch_amb_l += fmaxf(-khan_ca, fminf(khan_ca, khan_da));
        const float khan_ds = khp.std_sun_l - khp.anch_sun_l;
        const float khan_cs = khan_r * fmaxf(khp.anch_sun_l, 0.02f);
        khp.anch_sun_l += fmaxf(-khan_cs, fminf(khan_cs, khan_ds));
    }
}

inline void locator_note_upload(ID3D11Resource* res, const void* data, uint32_t bytes) {
    if (!res || !data || bytes < 64) return;   // the block is 56+ floats
    // never self-learn: our own CBs carry the staged fog and camera too
    if (res == static_cast<ID3D11Resource*>(g_res.composite_cb)) return;
    if (res == static_cast<ID3D11Resource*>(g_res.constant_buffer)) return;
    if (res == static_cast<ID3D11Resource*>(g_res.frame_cb)) return;
    if (res == static_cast<ID3D11Resource*>(g_res.composite_frame_cb)) return;

    const float* f = static_cast<const float*>(data);
    const uint32_t nf_full = bytes / 4;
    if (nf_full > g_loc_max_cb_floats) g_loc_max_cb_floats = nf_full;
    const uint32_t nf = nf_full > 4096 ? 4096 : nf_full;

    // References: decay from the staged fog (nonzero even with fog off - RV's
    // default is 0.014), altitude from the injection-recorded render camera
    // (valid once the first injection has run).
    const float decay = g_fog[1];
    const float cam_alt = g_ls.cam[1];
    const bool ref_ok = g_fog_valid && decay > 1.0e-4f && cam_alt != 0.0f;
    // A degenerate one (setFog decay 0) used to freeze the mirror outright;
    // an ALREADY-LOCKED offset now re-verifies on the altitude + fog-mode
    // pair instead. Discovery and relocation are untouched.
    const bool khz_hold = !ref_ok && g_fog_valid && cam_alt != 0.0f &&
                          !(decay > 1.0e-4f) && g_light_probe.valid &&
                          g_dbg_mode.load(std::memory_order_relaxed) != 299;

    if (g_light_probe.valid && res == g_light_probe.buf && (ref_ok || khz_hold)) {
        bool ok = ref_ok
                ? locator_light_anchor(f, g_light_probe.off, nf, decay, cam_alt)
                : locator_zero_anchor(f, g_light_probe.off, nf, cam_alt);
        if (ok && !ref_ok) g_fog_zero_holds++;   // census

        if (!ok && ref_ok) {
            for (uint32_t i = 0; i + 16 <= nf; ++i) {
                if (locator_light_anchor(f, i, nf, decay, cam_alt)) {
                    g_light_probe.off = i;
                    g_light_probe.relocs++;
                    ok = true;
                    break;
                }
            }
        }

        if (ok) {
            g_light_probe.hits++;
            g_light_probe.last_err = fabsf(f[g_light_probe.off + 12] + cam_alt);
            g_light_probe.last_confirm = effect_time_seconds();
            // Confirms still stamp (the buffer IS the block - no expiry
            // churn), but the MIRROR only refreshes on the standard layout,
            // so every consumer keeps the last-known standard lanes up high.
            const uint32_t mode_i = g_light_probe.off - 25;   // block lane 15

            if (mode_i < nf) {
                g_light_probe.last_mode = f[mode_i];
                // Four value slots name what the lane actually carries.
                const float khml_v = f[mode_i];
                for (int khml_i = 0; khml_i < 4; ++khml_i) {
                    if (g_blk_mode_census_v[khml_i] == khml_v) {
                        g_blk_mode_census_n[khml_i]++; break;
                    }
                    if (g_blk_mode_census_n[khml_i] == 0) {
                        g_blk_mode_census_v[khml_i] = khml_v;
                        g_blk_mode_census_n[khml_i] = 1; break;
                    }
                }
            }

            // What makes this safe to TEST: admitted uploads face the FULL
            // arbitration - anchor band, pending, exclusivity - so garbage
            // luminance is band-rejected exactly like a foreign cluster,
            // while a sane FSAA-off standard block wearing lane-15 == 2
            // passes and lights the meshes.
            if (mode_i < nf && f[mode_i] == 1.0f &&
                g_light_probe.off >= 40 && g_light_probe.off - 40 + 18 < nf) {
                const float* khcr_b = f + (g_light_probe.off - 40);
                float* khcr_e = g_blk_ring[g_blk_ring_next];
                khcr_e[0] = khcr_b[8];  khcr_e[1] = khcr_b[9];  khcr_e[2] = khcr_b[10];
                khcr_e[3] = khcr_b[16]; khcr_e[4] = khcr_b[17]; khcr_e[5] = khcr_b[18];
                khcr_e[6] = khcr_e[0] + khcr_e[1] + khcr_e[2];
                khcr_e[7] = khcr_e[3] + khcr_e[4] + khcr_e[5];
                g_blk_ring_next = (g_blk_ring_next + 1u) & 3u;
                if (g_blk_ring_count < 4) g_blk_ring_count++;
            }

            const bool khml_adm = f[mode_i] == 1.0f ||
                (g_dbg_mode.load(std::memory_order_relaxed) == 277 &&
                 f[mode_i] == 2.0f);

            if (mode_i < nf && khml_adm && kh_probe_world_cycle()) {
                // world-cycle PRE-FILTER + the DECIDING exclusive-persistence
                // arbitration (kh_probe_std_refresh).
                kh_probe_std_refresh(g_light_probe, f, nf, effect_time_seconds());
            }
        } else {
            g_light_probe.misses++;   // shared/ring CBs make misses normal
        }
    }

    const float now = effect_time_seconds();

    // The gate's cost rationale never applied here: the anchor's fast path is
    // three float compares at fixed offsets per nf>=72 upload, and a hit is a
    // 384-byte memcpy (~4 KB/frame at the measured rate).
    if (nf >= 72) {
        if (g_sky_probe.valid && now - g_sky_probe.last_confirm > 60.0f) {
            g_sky_probe.valid = false;   // freshness flag only: the mirror and
                                         // hits persist - consumption is
                                         // mirror-based (hits > 0)
        }

        if (locator_sky_anchor(f, nf)) {
            g_sky_probe.buf = res;   // last host (diagnostic only)
            g_sky_probe.off = 0;
            g_sky_probe.floats = nf_full;
            g_sky_probe.valid = true;
            g_sky_probe.hits++;
            g_sky_probe.last_confirm = now;
            locator_capture(g_sky_probe, f, nf, 96);
        }
    }

    // attempt window (~120 ms each second): expiry, then the unlocked LIGHT
    // scan (hundreds of uploads per attempt, negligible)
    if (now - floorf(now) >= 0.12f) return;

    // TIME-based expiry: a lock survives any miss rate and expires only after
    // 30 s without a confirmation; valid/buf drop but off/meta/nb SURVIVE, so
    // a dump taken mid-relearn still shows the last-known block contents.
    if (g_light_probe.valid && now - g_light_probe.last_confirm > 30.0f) {
        g_light_probe.valid = false;
        g_light_probe.buf = nullptr;
        g_light_probe.misses = 0;
    }

    // The ring-CB lesson it carried moved with it. From here down the window
    // is light-only; locScanUploads counts light-discovery window uploads
    // now.)
    const bool want_light = !g_light_probe.valid && ref_ok;
    if (!want_light) return;
    g_loc_scan_uploads++;

    for (uint32_t i = 0; i + 16 <= nf; ++i) {
        if (locator_light_anchor(f, i, nf, decay, cam_alt)) {
            g_light_probe.buf = res;
            g_light_probe.off = i;
            g_light_probe.floats = nf_full;
            g_light_probe.valid = true;
            g_light_probe.hits = 1;
            g_light_probe.misses = 0;
            g_light_probe.relocs = 0;
            g_light_probe.last_err = fabsf(f[i + 12] + cam_alt);
            g_light_probe.last_confirm = now;
            const uint32_t mode_i2 = g_light_probe.off - 25;   // block lane 15

            if (mode_i2 < nf) g_light_probe.last_mode = f[mode_i2];

            if (mode_i2 < nf && f[mode_i2] == 1.0f && kh_probe_world_cycle()) {
                // world gate + regime arbitration (see kh_probe_std_refresh).
                kh_probe_std_refresh(g_light_probe, f, nf, now);
            }
            break;
        }
    }
}

inline void shadow_live_upload(const void* data, uint32_t bytes) {
    if (!shadow_live_wanted() || !g_ls.phase_on_atlas) return;
    if (bytes < 12 * sizeof(float)) return;
    // cap raised for the whole-pool bind era (SpanMax 65,536 measured; the
    // cascade matrix sits at an arbitrary depth in the bound range).
    if (bytes > 65536) bytes = 65536;
    const float* f = static_cast<const float*>(data);
    const uint32_t nfloats = bytes / 4;

    if (g_ls.cycle_latched) {
        for (uint32_t off = 0; off + 12 <= nfloats && off <= 128; off += 4) {
            if (shadow_live_test_window(f + off)) { g_live_stash_accepts++; break; }   // accept stashes internally (census)
        }

        return;
    }

    // Keep the small sampling block of the cycle regardless of who wins the
    // pending race - it complements the big block per commit.
    if (bytes <= 256) {
        const float* ff = static_cast<const float*>(data);
        const uint32_t nf = static_cast<uint32_t>(bytes / 4);

        for (uint32_t off = 0; off + 12 <= nf && off <= 8; off += 4) {
            if (shadow_live_test_window(ff + off)) {
                break;
            }
        }
    }

    if (g_ls.pending_valid && bytes < g_ls.pending_bytes) return;   // never downgrade (same size: last upload wins)

    if (g_ls.cache_valid && bytes == g_ls.cache_bytes && g_ls.cache_offset + 12 <= nfloats) {
        if (shadow_live_test_window(f + g_ls.cache_offset)) {
            memcpy(g_ls.pending_m, f + g_ls.cache_offset, sizeof(g_ls.pending_m));
            g_ls.pending_valid = true;
            g_live_pend_sets++;   // census
            g_ls.pending_bytes = static_cast<uint32_t>(bytes);
            return;
        }
    }

    for (uint32_t off = 0; off + 12 <= nfloats; off += 4) {
        if (shadow_live_test_window(f + off)) {
            g_ls.cache_valid = true;
            g_ls.cache_bytes = static_cast<uint32_t>(bytes);
            g_ls.cache_offset = off;
            memcpy(g_ls.pending_m, f + off, sizeof(g_ls.pending_m));
            g_ls.pending_valid = true;
            g_live_pend_sets++;   // census
            g_ls.pending_bytes = static_cast<uint32_t>(bytes);
            return;
        }
    }
}

inline void shadow_live_on_draw(ID3D11DeviceContext* ctx) {
    if (!g_ls.pending_valid || g_ls.pending_vp_valid || !g_ls.phase_on_atlas || !ctx || g_ls.atlas_size == 0) return;
    UINT nvp = 1;
    D3D11_VIEWPORT vp = {};
    ctx->RSGetViewports(&nvp, &vp);
    if (nvp == 0 || vp.Width <= 0.0f || vp.Height <= 0.0f) return;
    g_ls.pending_vp[0] = vp.TopLeftX;
    g_ls.pending_vp[1] = vp.TopLeftY;
    g_ls.pending_vp[2] = vp.Width;
    g_ls.pending_vp[3] = vp.Height;
    g_ls.pending_vp_valid = true;
}

// Cycle exit: the fully-upgraded pending latch becomes a table entry.
inline void shadow_live_finalize_cycle() {
    if (!g_ls.pending_valid || !g_ls.pending_vp_valid || g_ls.atlas_size == 0) {
        // Priority order matches the condition; the atlas term is tested
        // first because it is the only one that can latch stale across cycles
        // rather than merely miss one.
        if (g_ls.atlas_size == 0)            g_live_fin_bail_atlas++;
        else if (!g_ls.pending_valid)        g_live_fin_bail_pend++;
        else                                 g_live_fin_bail_vp++;
        g_ls.pending_valid = false;
        g_ls.pending_bytes = 0;
        g_ls.pending_vp_valid = false;
        return;
    }
    g_live_last_commit_t = effect_time_seconds();   // outage ruler

    g_ls.pending_valid = false;
    g_ls.pending_bytes = 0;
    g_ls.pending_vp_valid = false;

    D3D11_VIEWPORT vp = {};
    vp.TopLeftX = g_ls.pending_vp[0];
    vp.TopLeftY = g_ls.pending_vp[1];
    vp.Width = g_ls.pending_vp[2];
    vp.Height = g_ls.pending_vp[3];

    // Refuse the commit and keep the table. The DERIVATION deliberately still
    // samples every window (in band_capture): if the published sun ever
    // locked wrong, derivation keeps measuring truth and the
    // confirmation-held snap + jump arbiter recover it - no deadlock.
    {
        const float* khlx_r2 = g_ls.pending_m + 8;
        const float khlx_now = effect_time_seconds();
        const bool khlx_fv = g_ls.frame_view_valid && g_ls.frame_view_time >= 0.0f &&
                             khlx_now - g_ls.frame_view_time < 0.05f;

        // Without a view there is no rotation into world space and therefore
        // no provenance test at all - this block used to be skipped and the
        // commit went through UNVERIFIED. It now refuses instead: the table
        // keeps its previous entry, exactly like every other bail here, and
        // the next cycle with a view commits normally.
        if (!(khlx_fv || g_ro.cycle_pv_valid)) {
            g_live_rej_no_view++;
            // 37 = pristine skip the test entirely rather than rotating
            // through an invalid latch.
            if (g_dbg_mode.load(std::memory_order_relaxed) != 37) return;
        } else {
            float khlx_w[3];

            for (int c = 0; c < 3; ++c) {
                khlx_w[c] = khlx_fv
                    ? g_ls.frame_view[c * 4 + 0] * khlx_r2[0] +
                      g_ls.frame_view[c * 4 + 1] * khlx_r2[1] +
                      g_ls.frame_view[c * 4 + 2] * khlx_r2[2]
                    : g_ro.cycle_pv.view[c][0] * khlx_r2[0] +
                      g_ro.cycle_pv.view[c][1] * khlx_r2[1] +
                      g_ro.cycle_pv.view[c][2] * khlx_r2[2];
            }

            float khlx_deg = -1.0f;

            if (kh_sun_axis_foreign(khlx_w[0], khlx_w[1], khlx_w[2], &khlx_deg)) {
                g_live_rej_sun_axis++;
                g_live_rej_sun_axis_deg = khlx_deg;
                return;
            }
        }
    }

    // Slot selection: same cascade = same scale (each cascade's extent is
    // distinct); a re-render replaces its entry in place. New scales append;
    // a full table evicts the stalest entry.
    const float* pm = g_ls.pending_m;
    const float pn0 = pm[0] * pm[0] + pm[1] * pm[1] + pm[2] * pm[2];
    if (g_ls.wipe_deferred) {   // KH_LIVE_WIPE_DEFER: the deferred door-4 wipe lands here
        g_ls.count = 0;
        g_ls.newest = -1;
        g_ls.wipe_deferred = false;
        g_live_wipe_prunes++;
    }
    int slot = -1;

    for (uint32_t i = 0; i < g_ls.count; ++i) {
        const float* m = g_ls.entries[i].m;
        const float n0 = m[0] * m[0] + m[1] * m[1] + m[2] * m[2];
        if (fabsf(n0 - pn0) <= 0.2f * n0) { slot = static_cast<int>(i); break; }
    }

    if (slot < 0) {
        if (g_ls.count < KH_LIVE_MAX_CASCADES) {
            slot = static_cast<int>(g_ls.count++);
        } else {
            uint64_t oldest = ~0ull;

            for (uint32_t i = 0; i < g_ls.count; ++i) {
                if (g_ls.entries[i].stamp < oldest) { oldest = g_ls.entries[i].stamp; slot = static_cast<int>(i); }
            }
        }
    }

    const float inv = 1.0f / static_cast<float>(g_ls.atlas_size);
    const float texel = inv;
    LiveShadowEntry& e = g_ls.entries[slot];
    memcpy(e.m, g_ls.pending_m, sizeof(e.m));
    e.tile[0] = vp.TopLeftX * inv + texel;
    e.tile[1] = vp.TopLeftY * inv + texel;
    e.tile[2] = (vp.TopLeftX + vp.Width) * inv - texel;
    e.tile[3] = (vp.TopLeftY + vp.Height) * inv - texel;
    if (e.tile[2] <= e.tile[0] || e.tile[3] <= e.tile[1]) return;
    // KH_LIVE_CAM_PAIR (mode 334 = the historic injection-camera pairing).
    float khlp_cam[3] = { g_ls.cam[0], g_ls.cam[1], g_ls.cam[2] };
    int   khlp_src = 0;   // 0 injection (fallback / 334), 1 frame view, 2 cycle latch
    if (g_dbg_mode.load(std::memory_order_relaxed) != 334) {
        const float khlp_now = effect_time_seconds();
        float khlp_c[3];
        if (g_ls.frame_view_valid && g_ls.frame_view_time >= 0.0f &&
            khlp_now - g_ls.frame_view_time < 0.05f &&
            kh_view_camera_exact(reinterpret_cast<const float(*)[4]>(g_ls.frame_view), khlp_c)) {
            khlp_cam[0] = khlp_c[0]; khlp_cam[1] = khlp_c[1]; khlp_cam[2] = khlp_c[2];
            khlp_src = 1;
        } else if (g_ro.cycle_pv_valid &&
                   kh_view_camera_exact(g_ro.cycle_pv.view, khlp_c)) {
            khlp_cam[0] = khlp_c[0]; khlp_cam[1] = khlp_c[1]; khlp_cam[2] = khlp_c[2];
            khlp_src = 2;
        }
    }
    if (khlp_src == 1) g_live_cam_pair_fv++;
    else if (khlp_src == 2) g_live_cam_pair_pv++;
    else g_live_cam_pair_stale++;
    {
        const float khlp_dx = khlp_cam[0] - g_ls.cam[0];
        const float khlp_dy = khlp_cam[1] - g_ls.cam[1];
        const float khlp_dz = khlp_cam[2] - g_ls.cam[2];
        const float khlp_d = sqrtf(khlp_dx * khlp_dx + khlp_dy * khlp_dy + khlp_dz * khlp_dz);
        if (khlp_d == khlp_d && khlp_d < 1.0e6f) {
            g_live_cam_pair_dx = khlp_d;
            if (khlp_d > g_live_cam_pair_dx_max) g_live_cam_pair_dx_max = khlp_d;
        }
    }
    e.cam[0] = khlp_cam[0];
    e.cam[1] = khlp_cam[1];
    e.cam[2] = khlp_cam[2];
    e.stamp = ++g_ls.stamp_counter;
    e.time = effect_time_seconds();
    g_ls.newest = slot;
    g_ls.cycle_latched = true;
    g_stats.shadow_live_latches++;
    if (g_first_livelatch_t < 0.0f) g_first_livelatch_t = e.time;   // cold timeline

}

// CASCADE BINDING HARVEST (upload-dark disease, third victim, third
// application of the cure): a session arrived with shadowLiveLatches 0,
// liveAccepts 0 AND every rejection counter 0 - shadow_live_upload never
// received a single cascade-family upload while the general hooks ran
// millions of light-probe confirmations.
struct CascBindProbe {
    ID3D11Buffer* staging[4] = {};
    uint32_t      bytes[4] = {};
    uint8_t       pending = 0;
};
static CascBindProbe g_cascbind;
static uint64_t g_cascbind_scans = 0;   // harvested windows fed to live_upload
static uint32_t g_cascbind_span_last = 0;   // bound span seen at the last arm
static uint32_t g_cascbind_span_max = 0;
static uint32_t g_cascharv_ctr = 0;   // atlas-draw sampling counter

inline void cascbind_release() {
    for (int i = 0; i < 4; ++i) {
        KH_SAFE_RELEASE(g_cascbind.staging[i]);
        g_cascbind.bytes[i] = 0;
    }
    g_cascbind.pending = 0;
}

inline void cascbind_step(ID3D11DeviceContext* ctx) {
    for (int i = 0; i < 4; ++i) {
        if (!(g_cascbind.pending & (1u << i)) || !g_cascbind.staging[i]) continue;
        D3D11_MAPPED_SUBRESOURCE ms = {};
        const HRESULT hr = ctx->Map(g_cascbind.staging[i], 0, D3D11_MAP_READ,
                                    D3D11_MAP_FLAG_DO_NOT_WAIT, &ms);
        if (hr == DXGI_ERROR_WAS_STILL_DRAWING) continue;
        g_cascbind.pending &= static_cast<uint8_t>(~(1u << i));
        if (FAILED(hr) || !ms.pData) continue;
        g_cascbind_scans++;
        g_cascbind_feed_t = effect_time_seconds();   // stamp
        g_tw_harvest = true; g_hv_windows++;   // near-miss scope
        shadow_live_upload(ms.pData, g_cascbind.bytes[i]);
        g_tw_harvest = false;
        ctx->Unmap(g_cascbind.staging[i], 0);
    }

    // Idle while the table is being fed by anyone (uploads included).
    const float now_c = effect_time_seconds();

    for (uint32_t i = 0; i < g_ls.count && i < KH_LIVE_MAX_CASCADES; ++i) {
        const auto& e = g_ls.entries[i];
        if (e.tile[2] > 0.0f && e.stamp != 0 && now_c - e.time < 3.0f) return;
    }

    ID3D11Buffer* bufs[4] = {};
    UINT first16[4] = {};
    UINT num16[4] = {};
    ID3D11DeviceContext1* ctx1 = kh_ctx1(ctx);   // cached Q(no release)

    if (ctx1) {
        ctx1->VSGetConstantBuffers1(0, 4, bufs, first16, num16);
    } else {
        ctx->VSGetConstantBuffers(0, 4, bufs);
    }

    ID3D11Device* dev = nullptr;
    ctx->GetDevice(&dev);

    for (int i = 0; i < 4; ++i) {
        if (!bufs[i]) continue;

        if (dev && !(g_cascbind.pending & (1u << i))) {
            D3D11_BUFFER_DESC bd = {};
            bufs[i]->GetDesc(&bd);
            const uint32_t off_b = first16[i] * 16u;
            const uint32_t span_b = num16[i] > 0 ? num16[i] * 16u
                                                 : (bd.ByteWidth > off_b ? bd.ByteWidth - off_b : 0u);

            if (span_b >= 64 && off_b + 64 <= bd.ByteWidth) {
                // A switched camera's whole-range binds can place the cascade
                // matrix beyond 2 KB into the bound window, unreachable under
                // the old clamp while perfectly scannable under the
                // consumer's own cap. The harvest now stages the full bound
                // span.
                uint32_t win = span_b < 65536u ? span_b : 65536u;
                g_cascbind_span_last = span_b;
                if (span_b > g_cascbind_span_max) g_cascbind_span_max = span_b;
                if (off_b + win > bd.ByteWidth) win = bd.ByteWidth - off_b;

                if (g_cascbind.staging[i] && g_cascbind.bytes[i] != win) {
                    KH_SAFE_RELEASE(g_cascbind.staging[i]);
                    g_cascbind.bytes[i] = 0;
                }

                if (!g_cascbind.staging[i]) {
                    D3D11_BUFFER_DESC sd = {};
                    sd.ByteWidth = win;
                    sd.Usage = D3D11_USAGE_STAGING;
                    sd.CPUAccessFlags = D3D11_CPU_ACCESS_READ;

                    if (SUCCEEDED(dev->CreateBuffer(&sd, nullptr, &g_cascbind.staging[i]))) {
                        g_cascbind.bytes[i] = win;
                    }
                }

                if (g_cascbind.staging[i] && g_cascbind.bytes[i] == win) {
                    if (win == bd.ByteWidth && off_b == 0) {
                        ctx->CopyResource(g_cascbind.staging[i], bufs[i]);
                    } else {
                        D3D11_BOX box = {};
                        box.left = off_b;
                        box.right = off_b + win;
                        box.bottom = 1;
                        box.back = 1;
                        ctx->CopySubresourceRegion(g_cascbind.staging[i], 0, 0, 0, 0,
                                                   bufs[i], 0, &box);
                    }

                    g_cascbind.pending |= static_cast<uint8_t>(1u << i);
                }
            }
        }

        bufs[i]->Release();
    }

    if (dev) dev->Release();
}

inline bool shadow_probe_target(ID3D11DepthStencilView* dsv) {
    if (!dsv) return false;
    ID3D11Resource* res = nullptr;
    dsv->GetResource(&res);
    if (!res) return false;

    ID3D11Texture2D* tex = nullptr;
    res->QueryInterface(__uuidof(ID3D11Texture2D), reinterpret_cast<void**>(&tex));
    res->Release();
    if (!tex) return false;

    D3D11_TEXTURE2D_DESC td = {};
    tex->GetDesc(&td);
    shadow_live_consider_atlas(tex, td);
    const bool is_atlas = static_cast<void*>(tex) == g_ls.atlas_identity;

    D3D11_DEPTH_STENCIL_VIEW_DESC vd = {};
    dsv->GetDesc(&vd);
    uint32_t slice = 0;

    if (vd.ViewDimension == D3D11_DSV_DIMENSION_TEXTURE2DARRAY) {
        slice = vd.Texture2DArray.FirstArraySlice;
    } else if (vd.ViewDimension == D3D11_DSV_DIMENSION_TEXTURE2DMSARRAY) {
        slice = vd.Texture2DMSArray.FirstArraySlice;
    }

    void* id = static_cast<void*>(tex);
    tex->Release();   // identity only; the desc is already copied out

    return is_atlas;   // (recon-era target census removed)
}

// Frame boundary (main depth clear): publish the size, start a new table.
inline void shadow_live_frame_reset() {
    // The table PERSISTS - entries stay valid until their cascade re-renders
    // and replaces them - WITH ONE EXCEPTION, learned from the time-change
    // field test: a cascade-LAYOUT change (sun elevation swings alter the
    // count; 8 -> 5 observed) orphans slots that will never re-render, and
    // they keep testing fragments against the OLD sun's transforms - shadows
    // visibly drift and never heal.
    const float now_fr = effect_time_seconds();

    // An orphaned slot is only diagnosable RELATIVE to activity: if some
    // entry refreshed within the last second, slots silent for 3 s are dead
    // (layout change); if NOTHING refreshed, the scene is static - keep
    // everything (a sun JUMP is still handled instantly by the boundary
    // wipe).
    float freshest = -1e9f;

    for (uint32_t i = 0; i < g_ls.count; ++i) {
        if (g_ls.entries[i].time > freshest) freshest = g_ls.entries[i].time;
    }

    const bool table_active = g_ls.count > 0 && now_fr - freshest < 1.0f;
    uint32_t keep = 0;
    int newest = -1;
    uint64_t newest_stamp = 0;

    for (uint32_t i = 0; i < g_ls.count; ++i) {
        if (table_active && g_ls.entries[i].time > 0.0f && now_fr - g_ls.entries[i].time > 3.0f) continue;

        if (keep != i) g_ls.entries[keep] = g_ls.entries[i];

        if (g_ls.entries[keep].stamp >= newest_stamp) {
            newest_stamp = g_ls.entries[keep].stamp;
            newest = static_cast<int>(keep);
        }

        ++keep;
    }

    g_ls.count = keep;
    g_ls.newest = newest;

    // Mode 350 = the 1.0 s bound.
    const float khak_bound =
        g_dbg_mode.load(std::memory_order_relaxed) == 350 ? 1.0f : 4.0f;
    for (int b = 0; b < 8; ++b) {
        if (g_ls.band[b].valid && now_fr - g_ls.band[b].last_time > khak_bound) {
            g_ls.band[b].valid = false;
            g_ls.band[b].pending_view = false;
            g_band_age_kills++;
        }
    }

    g_stats.shadow_live_cascades = g_ls.count;
    if (g_ls.pending_valid) g_live_pend_wipes_maint++;   // census: destructive only
    g_ls.pending_valid = false;
    g_ls.pending_bytes = 0;
    g_atlas_srv_count = 0;   // per-frame SRV relearn (see the cache note)
}

struct ShadowMaskState {
    bool atlas_bound = false;   // atlas seen in PS SRVs since last target change
    bool  rt_is_resolve = false;   // current RT0 is the screen-sized single-channel resolve target
    bool  rt_fmt_ok = false;   // current RT0 has a mask-family format (any size)
    uint32_t rt_w = 0;   // current RT0 width
    ID3D11RenderTargetView* engine_mask_rtv = nullptr;   // captured at the gated resolve sweep
    uint64_t mask_rtv_swaps = 0;   // capture-time target CHANGES (>: partitions use separate masks)
    uint64_t cast_batches = 0;   // resolve-batch re-arms
    uint64_t cast_arms_lost = 0;   // re-arms that died unfired at a frame boundary
    uint64_t arms_lost_miss = 0;   // the cast_misses guard code active at the LAST
                                    // lost arm - names the starving gate if
                                    // the castArmsLost census ever grows into
                                    // a chase
    float    last_fire_fov[2] = {};   // reconstruction inputs at the LAST fire
    float    last_fire_dims[2] = {};   // an overcast-moment dump shows directly
    float    last_fire_rot_err = 0;   // whether the fire was fed garbage
                                    // (high resolve cadence: the mask's last
                                    // batch that frame rendered without our
                                    // shadow) cold chain, reborn lean: seconds
                                    // from the first mesh-carrying flush to
                                    // each milestone (-1 until reached), plus
                                    // the leading rejection streak - the
                                    // spawn-delay question answered in one
                                    // log.
    double cold_t0 = -1.0;
    float  cold_first_inject = -1.0f;   // first SUCCESSFUL injection
    float  cold_first_cast = -1.0f;   // first analytic mask write
    uint32_t cold_lead_ambiguous = 0;   // ambiguous rejections before the first injection
    float  cold_first_stage = -1.0f;   // first flush that staged >= 1 mesh for injection
    float  cold_first_trigger = -1.0f;   // first entry into the trigger body (past silent guards)
    uint32_t cold_g_nodsv = 0;   // cold exits: no main DSV this cycle
    uint32_t cold_g_floor = 0;   // cold exits: opaque floor
    uint32_t cold_g_tid = 0;   // cold exits: render thread not yet identified
                                        // (needs the flush to adopt the main depth
                                        // first - a cold-start ordering
                                        // dependency)
    uint32_t cold_cast_miss = 0;   // sticky: last castMisses code seen while the first cast was pending
    float last_inject_near = -1.0f;   // the near plane of the LAST injection (slice forensics)
                                        // x = band near, y = band far, z = fade
                                        // (the doc's f198, named at last), w =
                                        // captured overlay trisection gauges (per
                                        // latest flush, not cumulative)
    uint32_t ov_listed = 0;   // mode-2 solids in the flush's mesh list
    uint32_t ov_skipped = 0;   // skipped by the comp_healthy gate (must stay 0 for mode-2)
    uint32_t ov_drawn = 0;   // Draw actually issued
    ID3D11BlendState*       min_blend = nullptr;   // out = min(dst, src)
    // PRIMING STATES. min_blend CANNOT be reused: it is out = min(dst, src),
    // so min(x, 1.0) = x and a priming write would be a silent no-op.
    // cast_dss cannot be reused either - it is depth-OFF and fullscreen,
    // while priming must land exactly on our own footprint.
    ID3D11BlendState*       prime_blend = nullptr;   // overwrite, R only
    ID3D11DepthStencilState* prime_dss = nullptr;   // depth LESS_EQUAL, no write
    bool                    prime_states_failed = false;
    // PRIME OCCLUSION RING. svPrimeDraws proves the priming pass was ISSUED;
    // it says nothing about whether a single pixel survived the LESS_EQUAL
    // test against our injected depth.
    ID3D11Query*            prime_occl[3] = {};
    bool                    prime_occl_inflight[3] = {};
    int                     prime_occl_cursor = 0;
    bool                    prime_occl_failed = false;
    bool engine_mask_failed = false;
    ID3D11ShaderResourceView* cast_depth = nullptr;   // scene linear depth (AddRef)
    float cast_dims[2] = {};
    float cast_fov[4] = {};
    bool  cast_fov_valid = false;
    // Shadow-distance re-engages, time skips and sun<->moon swaps interleave
    // transitional passes whose captures misregister the reconstruction - the
    // boundary overcast flash, the offset shadow on return, the two-direction
    // duplicates.
    float    sweep_last_time = -1.0f;   // last gated capture
    uint32_t sweep_settle = 0;   // coherent sweeps since a discontinuity
    uint32_t sweep_need = 3;   // sweeps required before firing: 3 after
                                        // an fov blip, 10 after a capture GAP (a
                                        // boundary re-engage runs transitional
                                        // passes for several sweeps - the
                                        // 'overcast only when crossing the
                                        // boundary facing away' signature)
    ID3D11DepthStencilState* cast_dss = nullptr;   // depth off
    bool  cast_states_failed = false;
    uint64_t analytic_casts = 0;
};

static ShadowMaskState g_mask;

inline void ffr_fold_late_deltas() {
    if (!ffr_armed()) return;   // diagnostics arming: see g_diag_armed
    static uint64_t khr_late_snap[KH_FFR_NDELTA - KH_FFR_NDELTA_EARLY] = {};
    const uint64_t khr_now_c[KH_FFR_NDELTA - KH_FFR_NDELTA_EARLY] = {
        g_mask.cast_batches,
        g_cast_frozen_fires,
    };
    FfrRecord& r = ffr_head();

    for (uint32_t i = 0; i < KH_FFR_NDELTA - KH_FFR_NDELTA_EARLY; ++i) {
        // Reset-tolerant (session destroy zeroes the counters, not this
        // snapshot): a smaller "now" reseeds with a zero delta.
        const uint64_t dd = khr_now_c[i] >= khr_late_snap[i]
                          ? khr_now_c[i] - khr_late_snap[i] : 0;
        khr_late_snap[i] = khr_now_c[i];
        const uint32_t khr_sum =
            static_cast<uint32_t>(r.d[KH_FFR_NDELTA_EARLY + i]) +
            static_cast<uint32_t>(dd > 0xFFFFu ? 0xFFFFu : dd);
        r.d[KH_FFR_NDELTA_EARLY + i] =
            static_cast<uint16_t>(khr_sum > 0xFFFFu ? 0xFFFFu : khr_sum);
    }
}

inline void kh_svs_mask_release(bool khm_scrub_vmir);   // default on the 11.6k decl
inline void kh_vmir_release();   // KH_VOL_MIRROR (defined with its statics)
// same arrangement for the content-probe stagings.
inline void kh_prb_release();
inline void kh_vpx_release();
inline void kh_vpx_capture(ID3D11DeviceContext*);   // defined with the probes
inline void kh_vpx_capture_draw(ID3D11DeviceContext*);   // the counting-draw channel

inline void release_shadow_device_state() {
    // mask SRV, the latched mask candidate, the pre-resolve snapshot texture
    // + SRV, the pending-copy arm and every weak seam identity die with the
    // device. See kh_svs_mask_release - the SWAP half of that function is
    // what mask adoption calls, and it deliberately does none of this.
    kh_svs_mask_release();
    kh_prb_release();   // probe stagings die with the device
    kh_vpx_release();   // so does the volume-pass pair staging
    kh_ctx1_release();   // cached context1 interface the device
    g_rt0_desc_n = 0;   // RT0 desc cache = weak identities; wholesale evict
    g_rt0_desc_next = 0;
    memset(g_rt0_desc, 0, sizeof(g_rt0_desc));

    // dynamic-lights mirror machinery (device objects + weak identities; the
    // POD censuses survive until the session reset)
    for (int khd_s = 0; khd_s < 2; ++khd_s) {
        if (g_dl.staging[khd_s]) { g_dl.staging[khd_s]->Release(); g_dl.staging[khd_s] = nullptr; }
        g_dl.inflight[khd_s] = 0;
    }

    for (int khd_s = 0; khd_s < 2; ++khd_s) {
        if (g_dl.arena[khd_s]) { g_dl.arena[khd_s]->Release(); g_dl.arena[khd_s] = nullptr; }
        g_dl.arena_inflight[khd_s] = 0;
        g_dl.win_count[khd_s] = 0;
    }

    memset(g_dl.win_meta, 0, sizeof(g_dl.win_meta));   // weak identities
    g_dl.pool_n = 0;   // pool positions are POD but the stamp must not lie
    g_dl.pool_stamp = 0;
    g_dl.slot10_buf = nullptr;
    g_dl.slot11_buf = nullptr;
    g_dl.valid = false;   // consumers gate on valid; a fresh harvest re-arms

    // screen-mask machinery (cast write)
    if (g_mask.engine_mask_rtv) { g_mask.engine_mask_rtv->Release(); g_mask.engine_mask_rtv = nullptr; }
    g_mask_res_id = nullptr;   // census key the RTV
    if (g_mask.cast_depth) { g_mask.cast_depth->Release(); g_mask.cast_depth = nullptr; }
    if (g_mask.min_blend) { g_mask.min_blend->Release(); g_mask.min_blend = nullptr; }
    if (g_mask.prime_blend) { g_mask.prime_blend->Release(); g_mask.prime_blend = nullptr; }
    if (g_mask.prime_dss) { g_mask.prime_dss->Release(); g_mask.prime_dss = nullptr; }
    g_mask.prime_states_failed = false;
    for (int khpq_i = 0; khpq_i < 3; ++khpq_i) {   // prime occlusion ring
        if (g_mask.prime_occl[khpq_i]) {
            g_mask.prime_occl[khpq_i]->Release();
            g_mask.prime_occl[khpq_i] = nullptr;
        }
        g_mask.prime_occl_inflight[khpq_i] = false;
    }
    g_mask.prime_occl_cursor = 0;
    g_mask.prime_occl_failed = false;
    if (g_mask.cast_dss) { g_mask.cast_dss->Release(); g_mask.cast_dss = nullptr; }
    g_mask.rt_is_resolve = false;
    g_topo_scene_rt_id = nullptr;   // weak identity: recycled allocations must not false-match
    g_topo_rt0_scene = false;
    g_topo_rt0_valid = false;
    g_topo_rt0_id = nullptr;
    g_topo_scene_tex_id = nullptr;
    g_topo_color_seen_n = 0;
    memset(g_topo_color_seen, 0, sizeof(g_topo_color_seen));
    g_mask.atlas_bound = false;
    g_mask.engine_mask_failed = false;
    g_mask.cast_states_failed = false;
    g_mask.cast_fov_valid = false;
    g_mask.cast_dims[0] = g_mask.cast_dims[1] = 0.0f;
    g_mask.sweep_settle = 0;
    g_mask.sweep_need = 10;   // a reset IS a capture gap
    g_mask.sweep_last_time = -1.0f;

    // live capture state
    if (g_ls.atlas_srv) { g_ls.atlas_srv->Release(); g_ls.atlas_srv = nullptr; }
    if (g_ls.atlas_tex) { g_ls.atlas_tex->Release(); g_ls.atlas_tex = nullptr; }
    g_ls.atlas_identity = nullptr;
    g_ls.atlas_size = 0;
    g_ls.atlas_fmt = 0;
    g_ls.atlas_last_seen = 0.0f;
    g_ls.first_capture_time = -1.0f;
    g_band_wipe_events++;   // the vanish trigger, counted
    // msaaToggleWipes does NOT gate that repair: kh_msaa_toggle_wipe never
    // releases g_res. It is zeroed by reset_session_state, so a mission
    // restart erases the event it just produced - only an in-session device
    // reset can leave it readable in a dump.
    g_ls.srv_failed = false;
    g_ls.phase_on_atlas = false;
    g_ls.pending_valid = false;
    g_ls.pending_bytes = 0;
    g_ls.pending_vp_valid = false;
    g_ls.cycle_latched = false;
    g_ls.cache_valid = false;
    g_ls.count = 0;
    g_ls.newest = -1;
    g_ls.resolve_window = 0;
    g_ls.resolve_seen_since_cast = false;

    for (int b = 0; b < 8; ++b) {
        auto& bb = g_ls.band[b];
        if (bb.srv) { bb.srv->Release(); bb.srv = nullptr; }
        if (bb.tex) { bb.tex->Release(); bb.tex = nullptr; }
        bb.valid = false;
        bb.pending_view = false;
        memset(bb.sm, 0, sizeof(bb.sm));
        memset(bb.border, 0, sizeof(bb.border));
        bb.last_time = 0.0f;
    }

    kh_band_pool_release();   // staging back buffers die with the device

    for (uint32_t i = 0; i < 16; ++i) {
        g_ls.cb_reg[i].buf = nullptr;   // weak keys into a dead device's allocations
        g_ls.cb_reg[i].floats = 0;
    }

    memset(g_ls.vc_ring, 0, sizeof(g_ls.vc_ring));
    g_ls.vc_n = 0;
    g_ls.view_src_res = nullptr;
    g_ls.view_src_valid = false;
    g_ls.view_src_miss = 0;
    g_ls.frame_view_valid = false;
    g_ls.frame_view_time = -1.0f;
    g_ls.prev_view_valid = false;
    g_ls.alt_view_valid = false;   // the alt latch the session
    g_ls.receive_warmed = false;   // next session warms up again
    g_band_pool_miss_t = -1000.0f;   // pressure clock the session
    g_band_fall_flush = ~0ull;   // cap latch the session
    g_ls.alt_view_time = -1.0f;
    g_ls.view_published_this_frame = false;

    // frozen fire + private sun map
    if (g_fire_lock) { g_fire_lock->Release(); g_fire_lock = nullptr; }
    if (g_fire_snap_srv) { g_fire_snap_srv->Release(); g_fire_snap_srv = nullptr; }   // snapshot
    if (g_fire_snap_tex) { g_fire_snap_tex->Release(); g_fire_snap_tex = nullptr; }
    g_fire_snap_w = 0;
    g_fire_snap_h = 0;
    g_fire_snap_fmt = DXGI_FORMAT_UNKNOWN;
    g_fire_snap_live = false;
    g_fire_lock_valid = false;
    g_fire_refreeze_pending = false;
    g_fire_dims_div_px = -1.0f;   // grid-coherence census rolls with the lock
    g_fire_dims_incoh = 0;

    g_mask_cast_arm = false;
    g_mask_cast_fired = false;
    g_sun_map_valid = false;
    g_sun2_map_valid = false;
    g_sun3_map_valid = false;
    g_sun4_map_valid = false;
    g_sun5_map_valid = false;
    g_sun_pf_valid[0] = false;   // pyramids' freshness
    g_sun_pf_valid[1] = false;   // the device alongside the
    g_sun_pf_valid[2] = false;   // band validity flags above.
    g_sun_map_rendered_frame = false;
    g_sun_map_no_local = false;
    g_sun_map_hash = 0;
    g_sun_map_render_time = -1.0f;
    g_sun_mat_chash = 0;
    g_sun_mat_sun[0] = g_sun_mat_sun[1] = g_sun_mat_sun[2] = 0.0f;
    g_sun_local_count = 0;
    g_sun_locals.clear();
    g_sun_locals.shrink_to_fit();

    // weak identities the render hooks compare against
    g_main_depth_identity = nullptr;
    g_atlas_srv_count = 0;
    g_proj_locator = ProjLocator{};
    kh_engcam_device_reset();   // same weak-identity rule
    for (int p = 0; p < 8; ++p) g_proj_pending[p] = ProjPendingMap{};
    g_light_probe = CbColorProbe{};
    g_sky_probe = CbColorProbe{};
    // DSV census: raw pointers, the weak-identity rule
    for (int khdr_i = 0; khdr_i < 6; ++khdr_i) g_dsvcen_tex[khdr_i] = nullptr;
    for (int khdr_i = 0; khdr_i < 16; ++khdr_i) {
        g_dsvcen_memo_dsv[khdr_i] = nullptr;
        g_dsvcen_memo_slot[khdr_i] = -1;
    }
    g_dsvcen_n = 0;
    skybind_release();
    cascbind_release();
}

// View-paired band capture: at this band's resolve, freeze SM + border (from
// the resolve CB, at fixed offsets relative to the found matrix) + this
// frame's view matrix + the atlas content, together. KH_SEAL_LAND_CENSUS body
// (declared with its globals; needs g_topo_cycles and g_ro, which are
// declared after the stage-commit site).
inline void kh_seal_land_note(int khsl_slot, float khsl_now, float khsl_esc_t,
                              uint64_t khsl_esc_cycle, const float* khsl_old,
                              const float* khsl_vc) {
    auto khsl_cam_of = [](const float* khsl_v, float* khsl_c) -> bool {
        khsl_c[0] = khsl_c[1] = khsl_c[2] = 0.0f;
        for (int khsl_j = 0; khsl_j < 3; ++khsl_j) {
            const float* khsl_a = &khsl_v[khsl_j * 4];
            const float khsl_n = sqrtf(khsl_a[0] * khsl_a[0] + khsl_a[1] * khsl_a[1] +
                                       khsl_a[2] * khsl_a[2]);
            if (!(khsl_n > 0.9f && khsl_n < 1.1f)) return false;
            khsl_c[0] -= khsl_a[3] * khsl_a[0];
            khsl_c[1] -= khsl_a[3] * khsl_a[1];
            khsl_c[2] -= khsl_a[3] * khsl_a[2];
        }
        return true;
    };
    float khsl_cn[3], khsl_co[3];
    const bool khsl_okn = khsl_cam_of(khsl_vc, khsl_cn);
    const bool khsl_oko = khsl_cam_of(khsl_old, khsl_co);
    const int khsl_tier = khsl_slot < 3 ? 0 : (khsl_slot < 6 ? 1 : 2);
    // (i) reseal step: how far the baked camera jumped at this landing
    if (khsl_okn && khsl_oko) {
        const float khsl_dx = khsl_cn[0] - khsl_co[0];
        const float khsl_dy = khsl_cn[1] - khsl_co[1];
        const float khsl_dz = khsl_cn[2] - khsl_co[2];
        const float khsl_st = sqrtf(khsl_dx * khsl_dx + khsl_dy * khsl_dy + khsl_dz * khsl_dz);
        if (khsl_st == khsl_st && khsl_st < 1.0e6f) {
            g_band_reseal_step = khsl_st;
            if (khsl_st > g_band_reseal_step_max[khsl_tier]) g_band_reseal_step_max[khsl_tier] = khsl_st;
            g_band_reseal_n[khsl_tier]++;
            g_band_reseal_sum[khsl_tier] += khsl_st;
            if (ffr_armed()) {
                FfrRecord& khsl_r = ffr_head();
                if (khsl_st > khsl_r.band_reseal_step_m) khsl_r.band_reseal_step_m = khsl_st;
            }
        }
    }
    // Read against the standing basis offset. (ii) seal-side split proxy:
    // committed vcol camera/forward against THIS cycle's injection basis.
    if (khsl_okn && g_ro.cycle_pv_valid) {
        float khsl_ci[3];
        extract_camera_pos(g_ro.cycle_pv.view, khsl_ci);
        const float khsl_dx = khsl_cn[0] - khsl_ci[0];
        const float khsl_dy = khsl_cn[1] - khsl_ci[1];
        const float khsl_dz = khsl_cn[2] - khsl_ci[2];
        const float khsl_d = sqrtf(khsl_dx * khsl_dx + khsl_dy * khsl_dy + khsl_dz * khsl_dz);
        if (khsl_d == khsl_d && khsl_d < 1.0e6f) {
            g_band_seal_inj_dx = khsl_d;
            if (khsl_d > g_band_seal_inj_dx_max) g_band_seal_inj_dx_max = khsl_d;
        }
        // forward axes: vcol column 2 = (vc[8], vc[9], vc[10]); cycle_pv.view
        // row-vector col 2
        float khsl_f = khsl_vc[8] * g_ro.cycle_pv.view[0][2] + khsl_vc[9] * g_ro.cycle_pv.view[1][2] +
                       khsl_vc[10] * g_ro.cycle_pv.view[2][2];
        khsl_f = khsl_f > 1.0f ? 1.0f : (khsl_f < -1.0f ? -1.0f : khsl_f);
        const float khsl_deg = acosf(khsl_f) * 57.29578f;
        if (khsl_deg == khsl_deg) {
            g_band_seal_inj_rot = khsl_deg;
            if (khsl_deg > g_band_seal_inj_rot_max) g_band_seal_inj_rot_max = khsl_deg;
        }
    }
    // (iii) escape -> land latency and camDx AT LAND (candidate (a)) (a stamp
    // older than 5 s spans a wipe or a mission seam and is discarded)
    if (khsl_esc_t >= 0.0f && khsl_now - khsl_esc_t < 5.0f) {
        const float khsl_ms = (khsl_now - khsl_esc_t) * 1000.0f;
        const uint32_t khsl_fr = g_topo_cycles >= khsl_esc_cycle
            ? static_cast<uint32_t>(g_topo_cycles - khsl_esc_cycle) : 0u;
        g_band_esc_lands++;
        g_band_esc_land_ms = khsl_ms;
        g_band_esc_land_ms_sum += khsl_ms;
        if (khsl_ms > g_band_esc_land_ms_max) g_band_esc_land_ms_max = khsl_ms;
        g_band_esc_land_fr = khsl_fr;
        if (khsl_fr > g_band_esc_land_fr_max) g_band_esc_land_fr_max = khsl_fr;
        float khsl_cdx = -1.0f;
        if (khsl_okn) {
            const float khsl_dx = khsl_cn[0] - g_ls.cam[0];
            const float khsl_dy = khsl_cn[1] - g_ls.cam[1];
            const float khsl_dz = khsl_cn[2] - g_ls.cam[2];
            const float khsl_d = sqrtf(khsl_dx * khsl_dx + khsl_dy * khsl_dy + khsl_dz * khsl_dz);
            if (khsl_d == khsl_d && khsl_d < 1.0e6f) khsl_cdx = khsl_d;
        }
        g_band_esc_land_cdx = khsl_cdx;
        if (khsl_cdx > g_band_esc_land_cdx_max) g_band_esc_land_cdx_max = khsl_cdx;
        if (ffr_armed()) {
            FfrRecord& khsl_r = ffr_head();
            khsl_r.band_esc_land_fr = static_cast<int16_t>(khsl_fr > 0x7FFEu ? 0x7FFE : static_cast<int>(khsl_fr));
            khsl_r.band_esc_land_cdx_m = khsl_cdx;
        }
    }
}

inline void band_capture(ID3D11DeviceContext* ctx, const float* cb, uint32_t off, uint32_t nf) {
    if (!g_ro.cycle_pv_valid || !g_ls.atlas_tex) { g_ls.band_bail_pv++; return; }
    if (off + 20 > nf) { g_ls.band_bail_off++; return; }   // need matrix + border
    const float* sm = cb + off;
    const float* border = cb + off + 16;

    if (!(border[1] > border[0]) || border[0] < 0.0f || border[1] > 4000.0f) {
        g_ls.band_bail_border++;
        memcpy(g_ls.band_last_reject, border, sizeof(g_ls.band_last_reject));
        return;
    }
    // slot: match an existing band by near edge, else take invalid/oldest,
    // preferring to keep the two NEAREST bands
    int slot = -1;

    for (int i = 0; i < 8; ++i) {
        if (g_ls.band[i].valid && fabsf(g_ls.band[i].border[0] - border[0]) < 0.5f) { slot = i; break; }
    }

    if (slot < 0) {
        for (int i = 0; i < 8; ++i) {
            if (!g_ls.band[i].valid) { slot = i; break; }
        }
    }

    if (slot < 0) {   // all valid, different bands: replace the farthest if nearer
        int far_i = 0;

        for (int i = 1; i < 8; ++i) {
            if (g_ls.band[i].border[0] > g_ls.band[far_i].border[0]) far_i = i;
        }

        if (border[0] < g_ls.band[far_i].border[0]) slot = far_i;
        else { g_ls.band_bail_slot++; return; }
    }

    BandSlotRef:
    {
        auto& b = g_ls.band[slot];
        const float now = effect_time_seconds();
        // The upload-matching latch (three designs, three pathologies:
        // promiscuity, lockout, wrong-family tracking) remains available as
        // an opt-in experiment (elem 13) and is used only when actually fresh
        // - NEVER by skipping work: the skips were the cast flicker and the
        // reseal starvation. View source: the BRIDGE PV.
        if (!g_ro.cycle_pv_valid && !g_ls.frame_view_valid) { g_ls.band_bail_view++; return; }
        // Big-jump bypass: a large window move (look-away/look-back) must
        // reseal IMMEDIATELY - the sub-second "shadow appears late" was the
        // throttle serving 0.25 s stale windows after a view swing.
        const bool big_jump = b.valid &&
            (fabsf(sm[3] - b.sm[3]) > 0.08f || fabsf(sm[7] - b.sm[7]) > 0.08f);
        // ROTATION-DELTA reseal: the cascade grid ROTATES with the view; a
        // frozen copy requantizes shadow edges by up to a texel at each
        // reseal - at 4 Hz that is a visible discrete hop proportional to
        // turn rate (the received-side "step-dance"; the engine never
        // freezes, so it spreads the same shimmer into per-frame dust).
        bool grid_turned = false;
        bool grid_flung = false;   // mode 209, the rotation bypass

        if (b.valid) {
            float n_new = sqrtf(sm[0] * sm[0] + sm[1] * sm[1] + sm[2] * sm[2]);
            float n_old = sqrtf(b.sm[0] * b.sm[0] + b.sm[1] * b.sm[1] + b.sm[2] * b.sm[2]);

            if (n_new > 1e-12f && n_old > 1e-12f) {
                const float d = (sm[0] * b.sm[0] + sm[1] * b.sm[1] + sm[2] * b.sm[2]) / (n_new * n_old);
                grid_turned = d < 0.9999995f;   // ~0.06 deg of grid rotation
                // grid_turned only SHORTENS the interval, 0.25 s -> 0.10 s;
                // it never bypasses it.
                if (b.valid && g_dbg_mode.load(std::memory_order_relaxed) == 209 &&
                    d < 1.0f) {
                    const float khbr_s = sqrtf(1.0f - d * d);   // sin(grid angle)
                    if (khbr_s == khbr_s && khbr_s > 0.25f) {
                        grid_flung = true;
                        g_ls.band_rot_escapes++;
                    }
                }
            }
        }
        // The dancing foliage taught us the frozen- copy truth: received
        // content can never be fresher than the reseal rate, and RV
        // vegetation both animates (wind) and RE-ORIENTS WITH THE CAMERA
        // (leaf planes are partially camera- facing) - so its shadows
        // genuinely evolve per frame, and copies serve that evolution in
        // steps.
        float khbd_d = -1.0f;
        {
            float khbd_c[3] = { 0.0f, 0.0f, 0.0f };
            bool  khbd_ok = true;
            for (int khbd_j = 0; khbd_j < 3; ++khbd_j) {
                const float* khbd_v = &b.vcol[khbd_j * 4];
                const float khbd_n = sqrtf(khbd_v[0] * khbd_v[0] +
                                           khbd_v[1] * khbd_v[1] +
                                           khbd_v[2] * khbd_v[2]);
                if (!(khbd_n > 0.9f && khbd_n < 1.1f)) { khbd_ok = false; break; }
                khbd_c[0] -= khbd_v[3] * khbd_v[0];
                khbd_c[1] -= khbd_v[3] * khbd_v[1];
                khbd_c[2] -= khbd_v[3] * khbd_v[2];
            }
            if (khbd_ok) {
                const float khbd_dx = khbd_c[0] - g_ls.cam[0];
                const float khbd_dy = khbd_c[1] - g_ls.cam[1];
                const float khbd_dz = khbd_c[2] - g_ls.cam[2];
                const float khbd_m = sqrtf(khbd_dx * khbd_dx +
                                           khbd_dy * khbd_dy + khbd_dz * khbd_dz);
                if (khbd_m == khbd_m && khbd_m < 1.0e6f) khbd_d = khbd_m;
            }
        }
        const bool khbd_rev = g_dbg_mode.load(std::memory_order_relaxed) == 88;
        const float khbd_k = khbd_rev ? 0.15f : 0.045f;
        const bool khbd_over = !khbd_rev && b.valid && khbd_d >= 0.0f &&
                               border[1] > border[0] &&
                               khbd_d > khbd_k * (border[1] - border[0]);
        if (khbd_over) g_ls.band_budget_escapes++;
        if (khbd_over && b.esc_t < 0.0f) {   // stamp the request
            b.esc_t = now;
            b.esc_cycle = g_topo_cycles;
        }
        // THE ESCAPE IS THE SHAPE EXACTLY: a slot whose incoming borders
        // disagree with its sealed borders by more than 2% of the incoming
        // width is promoted to the NEAR tier (0.05 s) and no further - same
        // rate cap, same one-sided construction (it can only make a
        // stale-layout slot reseal SOONER; agreeing slots are byte-identical
        // to).
        bool khly_over = false;
        if (b.valid && border[1] > border[0] &&
            g_dbg_mode.load(std::memory_order_relaxed) != 251) {
            const float khly_w = border[1] - border[0];
            if (fabsf(border[0] - b.border[0]) > 0.02f * khly_w ||
                fabsf(border[1] - b.border[1]) > 0.02f * khly_w) {
                khly_over = true;
                g_ls.band_layout_escapes++;
                if (b.esc_t < 0.0f) { b.esc_t = now; b.esc_cycle = g_topo_cycles; }
            }
        }
        const bool near_band = border[0] < 10.0f || khbd_over || khly_over;
        // A staleness offset shrinks ~5x under this arm; a registration
        // offset does not move. Engagement lane below; mode 0 identical.
        const bool khfc_all = g_dbg_mode.load(std::memory_order_relaxed) == 338;
        if (khfc_all && !near_band) g_band_cadence_forced++;
        const float min_interval = (near_band || khfc_all)
                                 ? 0.05f : (grid_turned ? 0.10f : 0.25f);

        // MODE 195 = THE TRANSLATION ESCAPE, ARMED ONLY. Ledger at The band
        // is not stale in TIME - it is stale in DISTANCE, and the far bands'
        // 0.25 s throttle is 15 frames at this frame rate.
        bool khbt_moved = false;
        if (b.valid && g_dbg_mode.load(std::memory_order_relaxed) == 195 &&
            border[1] > border[0]) {
            float khbt_c[3] = { 0.0f, 0.0f, 0.0f };
            bool  khbt_ok = true;

            for (int khbt_j = 0; khbt_j < 3; ++khbt_j) {
                const float* khbt_v = &b.vcol[khbt_j * 4];
                const float khbt_n = sqrtf(khbt_v[0] * khbt_v[0] +
                                           khbt_v[1] * khbt_v[1] +
                                           khbt_v[2] * khbt_v[2]);
                if (!(khbt_n > 0.9f && khbt_n < 1.1f)) { khbt_ok = false; break; }
                khbt_c[0] -= khbt_v[3] * khbt_v[0];
                khbt_c[1] -= khbt_v[3] * khbt_v[1];
                khbt_c[2] -= khbt_v[3] * khbt_v[2];
            }

            if (khbt_ok) {
                const float khbt_dx = khbt_c[0] - g_ls.cam[0];
                const float khbt_dy = khbt_c[1] - g_ls.cam[1];
                const float khbt_dz = khbt_c[2] - g_ls.cam[2];
                const float khbt_d = sqrtf(khbt_dx * khbt_dx + khbt_dy * khbt_dy +
                                           khbt_dz * khbt_dz);
                if (khbt_d == khbt_d && khbt_d > 0.25f * border[1]) {
                    khbt_moved = true;
                    g_ls.band_trn_escapes++;
                }
            }
        }

        // Keep 209 opt-in; do not spend another round on the throttle.
        // bandRotEscapes 0 means the arm never fired and the test is void,
        // exactly as bandTrnEscapes is read for 195. FIELD ON 209: NULL, AND
        // IT IS A CLEAN ONE. So the reseal throttle is NOT what holds the
        // cascade off our box after a flick.
        if (b.valid && !big_jump && !khbt_moved && !grid_flung &&
            now - b.last_time < min_interval) { g_ls.band_bail_time++; return; }

        bool khbx_foreign = false;

        {
            const float* khbx_r2 = sm + 8;
            const bool khbx_fv = g_ls.frame_view_valid && g_ls.frame_view_time >= 0.0f &&
                                 now - g_ls.frame_view_time < 0.05f;

            if (!(khbx_fv || g_ro.cycle_pv_valid)) {
                g_band_rej_no_view++;
                if (g_dbg_mode.load(std::memory_order_relaxed) != 37) khbx_foreign = true;   // 37 = pristine
            } else if (!khbx_fv && !g_ls.view_src_valid && b.last_time > 0.0f &&
                       g_dbg_mode.load(std::memory_order_relaxed) != 37) {
                g_band_rej_stale_view++;
                khbx_foreign = true;
            } else {
                float khbx_w[3];

                for (int c = 0; c < 3; ++c) {
                    khbx_w[c] = khbx_fv
                        ? g_ls.frame_view[c * 4 + 0] * khbx_r2[0] +
                          g_ls.frame_view[c * 4 + 1] * khbx_r2[1] +
                          g_ls.frame_view[c * 4 + 2] * khbx_r2[2]
                        : g_ro.cycle_pv.view[c][0] * khbx_r2[0] +
                          g_ro.cycle_pv.view[c][1] * khbx_r2[1] +
                          g_ro.cycle_pv.view[c][2] * khbx_r2[2];
                }

                float khbx_deg = -1.0f;

                if (kh_sun_axis_foreign(khbx_w[0], khbx_w[1], khbx_w[2], &khbx_deg)) {
                    g_band_rej_sun_axis++;
                    g_band_rej_sun_axis_deg = khbx_deg;
                    khbx_foreign = true;
                }
            }
        }

        // Seal section, gated on the axis verdict (wrapped, not re-indented:
        // the foreign path falls through to the derivation below unchanged).
        if (!khbx_foreign) {

        if (!b.tex) {
            // Batch: create ALL six slots' textures now - staggering six 67
            // MB allocations across the first seals was the seconds of
            // shadow-less mesh at spawn.
            D3D11_TEXTURE2D_DESC td = {};
            g_ls.atlas_tex->GetDesc(&td);
            td.BindFlags = D3D11_BIND_SHADER_RESOURCE;
            td.Usage = D3D11_USAGE_DEFAULT;
            td.CPUAccessFlags = 0;
            td.MiscFlags = 0;
            ID3D11Device* dev = nullptr;
            g_ls.atlas_tex->GetDevice(&dev);
            if (!dev) return;

            for (int bi = 0; bi < 8; ++bi) {
                auto& bb = g_ls.band[bi];
                if (bb.tex) continue;

                if (SUCCEEDED(dev->CreateTexture2D(&td, nullptr, &bb.tex)) && bb.tex) {
                    D3D11_SHADER_RESOURCE_VIEW_DESC sd = {};
                    sd.Format = DXGI_FORMAT_R32_FLOAT;
                    sd.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
                    sd.Texture2D.MipLevels = 1;

                    if (FAILED(dev->CreateShaderResourceView(bb.tex, &sd, &bb.srv))) {
                        bb.srv = nullptr;
                        bb.tex->Release();
                        bb.tex = nullptr;
                    }
                }
            }

            // the staging back buffers share the band desc exactly -
            // CopyResource demands it, and the commit SWAPS them into band
            // slots, so they must remain interchangeable for the session.
            const int khbp_n = kh_band_pool_n();   // only create what is used
            for (int khbp_k = 0; khbp_k < khbp_n; ++khbp_k) {
                if (g_band_pool[khbp_k].tex) continue;

                if (SUCCEEDED(dev->CreateTexture2D(&td, nullptr, &g_band_pool[khbp_k].tex)) &&
                    g_band_pool[khbp_k].tex) {
                    D3D11_SHADER_RESOURCE_VIEW_DESC sd = {};
                    sd.Format = DXGI_FORMAT_R32_FLOAT;
                    sd.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
                    sd.Texture2D.MipLevels = 1;

                    if (FAILED(dev->CreateShaderResourceView(g_band_pool[khbp_k].tex,
                                                             &sd, &g_band_pool[khbp_k].srv))) {
                        g_band_pool[khbp_k].srv = nullptr;
                        g_band_pool[khbp_k].tex->Release();
                        g_band_pool[khbp_k].tex = nullptr;
                    }
                }

                g_band_pool[khbp_k].busy = false;
            }

            dev->Release();
            if (!b.tex || !b.srv) { g_stats.shadow_srv_failed++; return; }
        }

        bool khdf_staged = false;
        {
            const int khdf_m = g_dbg_mode.load(std::memory_order_relaxed);

            if (b.valid && khdf_m != 50 && khdf_m != 48) {
                // The immediate path must not run either way: on a pool miss
                // the slot's existing COMPLETE seal stands and the next sweep
                // retries (last_time is left alone so the throttle allows
                // it).
                khdf_staged = true;
                int khdf_p = b.stage_pool;   // re-sweep of a slot already staged

                if (khdf_p < 0) {
                    const int khdf_n = kh_band_pool_n();
                    kh_band_pool_ensure_n(khdf_n);   // creation follows the count
                    for (int k = 0; k < khdf_n; ++k) {
                        if (!g_band_pool[k].busy && g_band_pool[k].tex && g_band_pool[k].srv) {
                            khdf_p = k;
                            break;
                        }
                    }
                }

                if (khdf_p < 0 || !g_band_pool[khdf_p].tex) {
                    g_band_stage_pool_miss++;
                    g_band_pool_miss_t = now;   // pool pressure clock
                    if (g_dbg_mode.load(std::memory_order_relaxed) != 214) {
                        // one fall-through per flush (347 = uncapped).
                        const bool khfc_un =
                            g_dbg_mode.load(std::memory_order_relaxed) == 347;
                        if (khfc_un || g_band_fall_flush != g_stats.flushes) {
                            g_band_fall_flush = g_stats.flushes;
                            khdf_staged = false;   // > the immediate path below
                            g_band_stage_pool_fall++;
                        } else {
                            g_band_stage_pool_cap++;   // drop: old seal serves
                        }   // next sweep retries
                    }
                } else {
                    g_band_pool[khdf_p].busy = true;
                    b.stage_pool = khdf_p;
                    memcpy(b.stage_sm, sm, sizeof(b.stage_sm));
                    memcpy(b.stage_border, border, sizeof(b.stage_border));
                    // hold the CAPTURE-time view for the mode-335 pairing.
                    b.stage_view_ok = false;
                    b.stage_pair_ok = false;   // fresh stage, fresh pair
                    b.stage_first_ok = false;   // fresh stage
                    {
                        // staged seals are born from the other source too
                        // (the commit welds stage_view into vcol, so birth is
                        // the whole pairing). staged seals born on the proven
                        // camera too.
                        const bool khip_s = g_dbg_mode.load(std::memory_order_relaxed) == 345 &&
                            g_inj_view_ms != 0 &&
                            steady_now_ms() - g_inj_view_ms < 50;
                        const bool khav_s = g_dbg_mode.load(std::memory_order_relaxed) == 343 &&
                            g_ls.alt_view_valid && g_ls.alt_view_time >= 0.0f &&
                            now - g_ls.alt_view_time < 0.05f;
                        const bool khsv_fvf = g_ls.frame_view_valid &&
                            g_ls.frame_view_time >= 0.0f &&
                            now - g_ls.frame_view_time < 0.05f;
                        if (khip_s) {
                            for (int khsv_c = 0; khsv_c < 3; ++khsv_c)
                                for (int khsv_r = 0; khsv_r < 4; ++khsv_r)
                                    b.stage_view[khsv_c * 4 + khsv_r] =
                                        g_inj_view[khsv_r * 4 + khsv_c];
                            b.stage_view_ok = true;
                            g_band_inj_pair++;
                        } else if (khav_s) {
                            for (int khsv_c = 0; khsv_c < 3; ++khsv_c)
                                for (int khsv_r = 0; khsv_r < 4; ++khsv_r)
                                    b.stage_view[khsv_c * 4 + khsv_r] =
                                        g_ls.alt_view[khsv_r * 4 + khsv_c];
                            b.stage_view_ok = true;
                            g_band_prov_alt++;
                        } else if (khsv_fvf) {
                            for (int khsv_c = 0; khsv_c < 3; ++khsv_c)
                                for (int khsv_r = 0; khsv_r < 4; ++khsv_r)
                                    b.stage_view[khsv_c * 4 + khsv_r] =
                                        g_ls.frame_view[khsv_r * 4 + khsv_c];
                            b.stage_view_ok = true;
                        } else if (g_ro.cycle_pv_valid) {
                            for (int khsv_c = 0; khsv_c < 3; ++khsv_c)
                                for (int khsv_r = 0; khsv_r < 4; ++khsv_r)
                                    b.stage_view[khsv_c * 4 + khsv_r] =
                                        g_ro.cycle_pv.view[khsv_r][khsv_c];
                            b.stage_view_ok = true;
                        }
                    }
                    b.stage_since = now;
                    b.stage_valid = true;
                    b.last_time = now;   // throttle as before; a drop resets it
                    g_ls.stage_any = true;
                    g_band_stage_takes++;
                    // THE COPY HAPPENS HERE, at the resolve that paired this
                    // sm with this atlas content. That pairing is the
                    // engine's own statement at its own consumption site and
                    // it is only true at this instant - moved this line a
                    // cycle later and mispaired 90% of seals.
                    ctx->CopyResource(g_band_pool[khdf_p].tex, g_ls.atlas_tex);
                    if (!g_ls.view_src_valid) g_band_seal_unlocked++;
                }
            }
        }

        // Wrapped, not re-indented (same convention as the khbx_foreign block
        // above): a staged capture must still fall through to the SUN
        // DERIVATION below, which is measurement, not consumption, and has
        // always sampled every window this function sees.
        if (!khdf_staged) {

        memcpy(b.sm, sm, sizeof(b.sm));
        memcpy(b.border, border, sizeof(b.border));

        const int  khsv_m = g_dbg_mode.load(std::memory_order_relaxed);
        const bool khsv_177 = (khsv_m == 44);   // form (; opt-in)
        const bool khsv_179 = (khsv_m == 45);   // form (opt-in)
        const bool khsv_old = !khsv_177 && !khsv_179;   // default
        const bool khsv_anch = (g_boundary_t < 0.0f ||
                                g_ls.frame_view_time >= g_boundary_t);
        const bool fv = g_ls.frame_view_valid && g_ls.frame_view_time >= 0.0f &&
                        (khsv_old || khsv_anch) &&
                        now - g_ls.frame_view_time < 0.05f;
        // ORDER CENSUS: the frame view's age at THIS capture. Ledger at
        if (fv) {
            const float khoc_ms = (now - g_ls.frame_view_time) * 1000.0f;
            g_band_cap_fv_age_ms = khoc_ms;
            g_band_cap_fv_age_sum += khoc_ms;
            g_band_cap_fv_age_n++;
            if (khoc_ms > g_band_cap_fv_age_max_ms) g_band_cap_fv_age_max_ms = khoc_ms;
        }
        const bool khsv_brg = !fv && khsv_177 &&
                              g_ro.cycle_pv_valid && !g_ro.cycle_pv_stale;

        const bool khsv_nat = !fv || kh_band_view_native(g_ls.frame_view, true);
        // Seals born on it are COMPLETE AT CAPTURE; the completion machinery
        // never runs.
        const bool khip_on = g_dbg_mode.load(std::memory_order_relaxed) == 345 &&
                             g_inj_view_ms != 0 &&
                             steady_now_ms() - g_inj_view_ms < 50;
        if (khip_on) g_band_inj_pair++; else g_band_inj_pair_miss++;
        // alt-birth DEMOTED to opt-in (mode 343) - the global latch paired
        // bands with random other cascades (field, 48.8 m class).
        const bool khav_on = g_dbg_mode.load(std::memory_order_relaxed) == 343 &&
                             g_ls.alt_view_valid && g_ls.alt_view_time >= 0.0f &&
                             now - g_ls.alt_view_time < 0.05f;
        if (khav_on) g_band_prov_alt++;
        else if (fv) g_band_prov_alt_miss++;
        float khsl_old[12];   // the vcol being replaced
        memcpy(khsl_old, b.vcol, sizeof(khsl_old));
        for (int c = 0; c < 3; ++c) {
            for (int r = 0; r < 4; ++r) {
                b.vcol[c * 4 + r] = khip_on ? g_inj_view[r * 4 + c]
                                  : khav_on ? g_ls.alt_view[r * 4 + c]
                                  : (fv && khsv_nat) ? g_ls.frame_view[r * 4 + c]
                                       : g_ro.cycle_pv.view[r][c];
            }
        }
        kh_seal_land_note(slot, now, b.esc_t, b.esc_cycle, khsl_old, b.vcol);
        b.esc_t = -1.0f;

        b.pending_view = khip_on ? false   // complete at capture
                       : (g_dbg_mode.load(std::memory_order_relaxed) == 335 && fv)
                       ? false
                       : (khsv_old ? true : !(fv || khsv_brg));
        b.vcol_bridge  = (khip_on || khav_on) ? false
                       : (khsv_old ? !fv : (!fv && !khsv_brg));
        if (!b.pending_view) kh_weld_note(b.vcol, 7.0f);   // kept at birth

        if (fv) g_band_seal_same++;
        else if (khsv_brg) g_band_seal_bridge++;
        else g_band_seal_pending++;

        if (!g_ls.view_src_valid) g_band_seal_unlocked++;   // cold forensics

        b.pending_since = now;
        if (g_ls.first_capture_time < 0.0f) g_ls.first_capture_time = now;
        ctx->CopyResource(b.tex, g_ls.atlas_tex);
        b.last_time = now;
        b.valid = true;
        b.copies++;
        g_ls.band_captures++;
        if (g_first_bandcap_t < 0.0f) g_first_bandcap_t = now;   // cold timeline

        }   // end !khdf_staged (immediate path)

        }   // end !khbx_foreign (seal section)

        const bool khdg_ok = g_ls.frame_view_valid && g_ls.frame_view_time >= 0.0f &&
                             now - g_ls.frame_view_time < 0.05f &&
                             g_ls.pub_fresh_ms != 0 &&
                             steady_now_ms() - g_ls.pub_fresh_ms <= 1000;
        if (g_ls.frame_view_valid && !khdg_ok) g_sun_derived_view_skips++;
        // A starved warm-up becomes a normal one (prediction: coldDerived120S
        // ~4-5 s against the measured 16.9 s, pulling coldFirstCast from 18.2
        // s toward the healthy ~7 s) while a poisoned frozen view still
        // cannot steer the latch - the poison era was frame_view freezing,
        // and the bridge never freezes.
        const bool khdg_bridge = !khdg_ok && g_ro.cycle_pv_valid;
        if (khdg_bridge) g_sun_derived_bridge++;

        if (khdg_ok || khdg_bridge) {
            const float* r2 = sm + 8;   // view-space light axis
            const float* V = g_ls.frame_view;   // world->view (row-major rows = world axes in view space)
            float wdir[3];

            for (int c = 0; c < 3; ++c) {   // R^T * r2 (bridge twin = the khbx block's proven indexing)
                wdir[c] = khdg_ok
                    ? V[c * 4 + 0] * r2[0] + V[c * 4 + 1] * r2[1] + V[c * 4 + 2] * r2[2]
                    : g_ro.cycle_pv.view[c][0] * r2[0] +
                      g_ro.cycle_pv.view[c][1] * r2[1] +
                      g_ro.cycle_pv.view[c][2] * r2[2];
            }

            const float n2 = sqrtf(wdir[0] * wdir[0] + wdir[1] * wdir[1] + wdir[2] * wdir[2]);

            if (n2 > 1e-6f) {
                for (int c = 0; c < 3; ++c) wdir[c] /= n2;
                if (wdir[1] < 0.0f) { wdir[0] = -wdir[0]; wdir[1] = -wdir[1]; wdir[2] = -wdir[2]; }   // skyward
                const float dd = fabsf(wdir[0] - g_sun_dir_derived[0]) +
                                 fabsf(wdir[1] - g_sun_dir_derived[1]) +
                                 fabsf(wdir[2] - g_sun_dir_derived[2]);

                if (g_sun_derived_samples < 1000000) g_sun_derived_samples++;
                if (g_first_derived120_t < 0.0f && g_sun_derived_samples >= 120) {
                    g_first_derived120_t = effect_time_seconds();   // cold timeline
                }

                if (!g_sun_dir_derived_valid) {
                    // MEASUREMENT SEED (the engine-sun seed retired with
                    // getLighting): the latch starts at the first measured
                    // direction, and the 120-sample validity gate holds every
                    // consumer off until the glide has converged - nobody
                    // sees the early junk, so nothing can slew.
                    g_sun_dir_derived[0] = wdir[0];
                    g_sun_dir_derived[1] = wdir[1];
                    g_sun_dir_derived[2] = wdir[2];
                } else if (dd > 0.05f && g_sun_derived_samples > 120) {
                    // A real skipTime repeats the same new direction on every
                    // subsequent cascade finalize, so five consecutive
                    // agreeing samples adopt within a fraction of a second; a
                    // one-off poison sample never repeats and is refused (any
                    // small-dd sample in between proves the latch fine and
                    // clears the hold).
                    const float khsn_dc = fabsf(wdir[0] - g_sun_snap_cand[0]) +
                                          fabsf(wdir[1] - g_sun_snap_cand[1]) +
                                          fabsf(wdir[2] - g_sun_snap_cand[2]);

                    if (g_sun_snap_hold > 0 && khsn_dc < 0.05f) {
                        g_sun_snap_hold++;
                    } else {
                        g_sun_snap_cand[0] = wdir[0];
                        g_sun_snap_cand[1] = wdir[1];
                        g_sun_snap_cand[2] = wdir[2];
                        g_sun_snap_hold = 1;
                    }

                    if (g_sun_snap_hold >= 5) {
                        float khsn_dp = wdir[0] * g_sun_dir_derived[0] +
                                        wdir[1] * g_sun_dir_derived[1] +
                                        wdir[2] * g_sun_dir_derived[2];
                        khsn_dp = khsn_dp > 1.0f ? 1.0f : (khsn_dp < -1.0f ? -1.0f : khsn_dp);
                        g_sun_snap_last_deg = acosf(khsn_dp) * 57.29578f;
                        // PUBLISH-NEUTRAL SNAP CLASSIFICATION (lognew3, the
                        // look-away/look-back blink): 44 confirmed snaps at
                        // ~9.4 deg in one session while the PUBLISHED sun
                        // never moved (sunSettleHolds 0, sunChurnMaxDeg 0.17)
                        // - camera turns re-lay the engine cascades, the
                        // derived latch wanders on the degraded stream, and
                        // the snap merely RELOCKS it to the direction the
                        // publish already points at.
                        bool khsn_neutral = false;

                        if (g_pub_valid) {
                            float khsn_pp = wdir[0] * g_pub_dir[0] +
                                            wdir[1] * g_pub_dir[1] +
                                            wdir[2] * g_pub_dir[2];
                            khsn_pp = khsn_pp > 1.0f ? 1.0f : (khsn_pp < -1.0f ? -1.0f : khsn_pp);
                            khsn_neutral = acosf(khsn_pp) * 57.29578f < KH_CAST_READY_SNAP_PUB_DEG;
                        }

                        if (khsn_neutral) {
                            g_sun_snap_neutral++;
                        } else {
                            g_sun_snap_ms = steady_now_ms();
                        }

                        g_sun_snap_adopts++;
                        g_sun_snap_hold = 0;
                        g_sun_dir_derived[0] = wdir[0];
                        g_sun_dir_derived[1] = wdir[1];
                        g_sun_dir_derived[2] = wdir[2];
                    } else {
                        g_sun_snap_refusals++;
                    }
                } else if (dd > 0.004f) {
                    g_sun_snap_hold = 0;   // a small-dd sample: the latch is fine
                    // Real-but-small motion: GLIDE 25% per sample instead of
                    // hopping the full 0.25-deg step - the discrete adoptions
                    // were a visible per-hop shadow jump under refit churn
                    // (the 'jitters even initially' report).
                    g_sun_dir_derived[0] += (wdir[0] - g_sun_dir_derived[0]) * 0.25f;
                    g_sun_dir_derived[1] += (wdir[1] - g_sun_dir_derived[1]) * 0.25f;
                    g_sun_dir_derived[2] += (wdir[2] - g_sun_dir_derived[2]) * 0.25f;
                    const float gl = sqrtf(g_sun_dir_derived[0] * g_sun_dir_derived[0] +
                                           g_sun_dir_derived[1] * g_sun_dir_derived[1] +
                                           g_sun_dir_derived[2] * g_sun_dir_derived[2]);

                    if (gl > 1e-6f) {
                        g_sun_dir_derived[0] /= gl;
                        g_sun_dir_derived[1] /= gl;
                        g_sun_dir_derived[2] /= gl;
                    }
                } else {
                    g_sun_snap_hold = 0;   // noise-still sample: the latch is fine
                }

                g_sun_dir_derived_valid = true;
            }
        }

    }
}

// At a resolve draw: the bound PS CBs are looked up in the registry; a
// sampling-family matrix found there IS the transform for the atlas content
// this very draw samples. If it's the finest scale, seal the pair right here:
// copy the atlas and store the matrix together.
inline void resolve_pair_capture(ID3D11DeviceContext* ctx) {
    if (!shadow_live_wanted() || !g_ls.atlas_tex) return;
    g_ls.resolve_draws++;
    // The original 0..7 query never saw it: every 'resolve hit' this code has
    // ever processed came from the small VS-side block instead. RV binds
    // constants at varying slots: scan PS b0..b7 AND VS b0..b3.
    ID3D11Buffer* bufs[18] = {};
    ctx->PSGetConstantBuffers(0, 14, bufs);
    ctx->VSGetConstantBuffers(0, 4, bufs + 14);
    {   // resolve-window gate + per-band capture (the pair-mode selector is retired: bands ARE the design)
        if (g_ls.resolve_window == 0) {
            g_ls.resolve_gated++;

            for (int b = 0; b < 18; ++b) { if (bufs[b]) bufs[b]->Release(); }

            return;
        }

        g_ls.resolve_window--;
        // The mode-2 sweep must NOT sit behind the legacy first-hit gate:
        // that gate fails on most resolves (its window test rejects many sun
        // geometries), which starved the cast table to 0-1 entries a frame
        // while 4-8 cascade passes consumed indices - sparse, misaligned cast
        // matrices (jitter, angle-dependent vanishing).
        bool any_capture = false;

        for (int b = 0; b < 18; ++b) {
            if (!bufs[b]) continue;

            for (uint32_t i = 0; i < 16; ++i) {
                if (g_ls.cb_reg[i].buf != static_cast<ID3D11Resource*>(bufs[b])) continue;
                g_ls.resolve_cb_found++;
                const float* f = g_ls.cb_reg[i].data;
                const uint32_t nf = g_ls.cb_reg[i].floats;

                if (nf >= 200 && nf <= 512) {
                    // [180] path byte-identical to pre
                    const float* m180 = f + 180;
                    const float n0 = m180[0] * m180[0] + m180[1] * m180[1] + m180[2] * m180[2];
                    const float n1 = m180[4] * m180[4] + m180[5] * m180[5] + m180[6] * m180[6];

                    if (n0 > 1e-10f && n0 < 1.0f && n1 > 1e-10f && n1 < 1.0f) {
                        g_ls.resolve_seen_since_cast = true;   // partition's resolves ran: re-arm the mask write

                        if (!g_mask_cast_fired && g_ls.frame_view_valid &&
                            g_ls.view_published_this_frame) {
                            g_mask_cast_arm = true;
                        }
                        const bool rt_resolve_ok = g_mask.rt_is_resolve ||
                            (g_mask.rt_fmt_ok && g_mask.rt_w >= 620);

                        if (rt_resolve_ok) g_rt_resolve_true++;
                        else { g_rt_resolve_false++; g_rt_last_rej_w = g_mask.rt_w; }
                        // Frame-topology census: stamp the gated sweep.
                        if (rt_resolve_ok) {
                            if (g_topo.sweeps == 0) g_topo.d_first_sweep = g_topo.draws;
                            g_topo.d_last_sweep = g_topo.draws;
                            ++g_topo.sweeps;
                        }
                        if (rt_resolve_ok && !g_mask.rt_is_resolve) g_rt_half_accepts++;

                        if (rt_resolve_ok) {
                        if (nf >= 180) {
                            const float swp_now = effect_time_seconds();
                            const bool swp_gap = g_mask.sweep_last_time < 0.0f ||
                                                 swp_now - g_mask.sweep_last_time > 0.25f;
                            bool swp_reset = swp_gap;

                            if (!swp_reset && g_mask.cast_fov_valid) {
                                swp_reset =
                                    fabsf(f[176] - g_mask.cast_fov[0]) > 0.1f * fabsf(g_mask.cast_fov[0]) + 1e-4f ||
                                    fabsf(f[177] - g_mask.cast_fov[1]) > 0.1f * fabsf(g_mask.cast_fov[1]) + 1e-4f;
                            }

                            if (swp_reset) {
                                g_mask.sweep_settle = 0;
                                // gap penalty 10 -> 5: under fog at cold the
                                // stream is naturally sparse and stacked gaps
                                // deferred the first cast 13-19 s; five
                                // consecutive clean batches remain a solid
                                // settle
                                g_mask.sweep_need = swp_gap ? 5 : 3;
                                if (swp_gap) g_sweep_gap_resets++;
                            }
                            if (g_mask.sweep_settle < 1000) g_mask.sweep_settle++;

                            g_mask.sweep_last_time = swp_now;

                            memcpy(g_mask.cast_fov, f + 176, sizeof(g_mask.cast_fov));
                            g_mask.cast_fov_valid = true;

                        }

                        {
                            // dims from the RTV desc (READ only; no latch;
                            // ADOPTION-GATED below - see DIMS PROVENANCE)
                            ID3D11RenderTargetView* rtv0 = nullptr;
                            ctx->OMGetRenderTargets(1, &rtv0, nullptr);
                            float khpc_w = 0.0f, khpc_h = 0.0f;
                            bool  khpc_have = false;

                            if (rtv0) {
                                ID3D11Resource* rr = nullptr;
                                rtv0->GetResource(&rr);

                                if (rr) {
                                    ID3D11Texture2D* rt = nullptr;
                                    rr->QueryInterface(__uuidof(ID3D11Texture2D), reinterpret_cast<void**>(&rt));

                                    if (rt) {
                                        D3D11_TEXTURE2D_DESC rd = {};
                                        rt->GetDesc(&rd);
                                        khpc_w = static_cast<float>(rd.Width);
                                        khpc_h = static_cast<float>(rd.Height);
                                        khpc_have = true;
                                        rt->Release();
                                    }

                                    rr->Release();
                                }

                                bool rtv_mask_like = false;

                                {
                                    ID3D11Resource* mres = nullptr;
                                    rtv0->GetResource(&mres);
                                    ID3D11Texture2D* mtex = nullptr;

                                    if (mres && SUCCEEDED(mres->QueryInterface(__uuidof(ID3D11Texture2D), reinterpret_cast<void**>(&mtex)))) {
                                        D3D11_TEXTURE2D_DESC md = {};
                                        mtex->GetDesc(&md);
                                        const DXGI_FORMAT mf = md.Format;
                                        const bool single =
                                            mf == DXGI_FORMAT_R8_UNORM || mf == DXGI_FORMAT_R8_TYPELESS ||
                                            mf == DXGI_FORMAT_R16_UNORM || mf == DXGI_FORMAT_R16_TYPELESS ||
                                            mf == DXGI_FORMAT_R16_FLOAT || mf == DXGI_FORMAT_R8_UINT;
                                        rtv_mask_like = single && md.Width >= 1280;
                                        mtex->Release();
                                    }

                                    if (mres) mres->Release();
                                }

                                // cast_dims now follows the ADOPTABLE mask
                                // target only; foreign sightings are counted,
                                // never adopted. The depth gate below keys on
                                // cast_dims, so the frozen depth SRV stays
                                // paired with the mask grid by construction.
                                if (rtv_mask_like) {
                                    if (khpc_have) {
                                        g_mask.cast_dims[0] = khpc_w;
                                        g_mask.cast_dims[1] = khpc_h;
                                    }
                                } else if (khpc_have &&
                                           (khpc_w != g_mask.cast_dims[0] ||
                                            khpc_h != g_mask.cast_dims[1])) {
                                    g_cast_dims_foreign++;
                                }

                                if (rtv_mask_like && g_mask.engine_mask_rtv != rtv0) {
                                    if (g_mask.engine_mask_rtv) {
                                        g_mask.engine_mask_rtv->Release();
                                        g_mask.mask_rtv_swaps++;   // target CHANGED mid-session
                                    }
                                    g_mask.engine_mask_rtv = rtv0;   // keep the ref

                                    {   // mask-bind census key: RESOURCE identity (weak, never dereferenced)
                                        ID3D11Resource* khmr = nullptr;
                                        rtv0->GetResource(&khmr);
                                        g_mask_res_id = static_cast<void*>(khmr);
                                        if (khmr) khmr->Release();
                                    }
                                } else {
                                    rtv0->Release();   // duplicate OR failed identity
                                }
                            }

                            ID3D11ShaderResourceView* d0 = nullptr;
                            ctx->PSGetShaderResources(0, 1, &d0);

                            if (d0) {
                                // must be a screen-sized single-channel float
                                // texture (the linear depth)
                                bool depth_ok = false;
                                ID3D11Resource* dr = nullptr;
                                d0->GetResource(&dr);

                                if (dr) {
                                    ID3D11Texture2D* dt = nullptr;
                                    dr->QueryInterface(__uuidof(ID3D11Texture2D), reinterpret_cast<void**>(&dt));

                                    if (dt) {
                                        D3D11_TEXTURE2D_DESC dd2 = {};
                                        dt->GetDesc(&dd2);
                                        const int df = static_cast<int>(dd2.Format);
                                        depth_ok = dd2.Width == static_cast<UINT>(g_mask.cast_dims[0]) &&
                                                   (df == 39 || df == 40 || df == 41 || df == 46 || df == 54);
                                        dt->Release();
                                    }

                                    dr->Release();
                                }

                                if (depth_ok && g_mask.cast_depth != d0) {
                                    if (g_mask.cast_depth) g_mask.cast_depth->Release();
                                    g_mask.cast_depth = d0;   // keep the ref
                                } else {
                                    d0->Release();
                                }
                            }
                        }
                        }   // rt_is_resolve gate

                        const uint64_t before = g_ls.band_captures + g_ls.band_bail_time + g_ls.band_bail_slot;
                        band_capture(ctx, f, 180, nf);
                        if (g_ls.band_captures + g_ls.band_bail_time + g_ls.band_bail_slot != before) any_capture = true;
                    }
                }
            }
        }

        if (any_capture) g_ls.resolve_hits++;

        for (int b = 0; b < 18; ++b) { if (bufs[b]) bufs[b]->Release(); }

        return;
    }

}

// Per-RT-change classification: runs at OMSet rate (dozens/frame), NOT per
// draw: the per-draw OMGet/QueryInterface/GetDesc chain ran for every
// atlas-sampling forward draw (tens of thousands/frame) and cost a measured
// ~170 ms/frame - the entire framerate collapse.
inline void mask_classify_rt(UINT n, ID3D11RenderTargetView* const* rtvs) {
    g_mask.rt_is_resolve = false;
    g_topo_rt0_valid = false;
    g_topo_rt0_scene = false;
    if (!n || !rtvs || !rtvs[0]) return;
    ID3D11Resource* res = nullptr;
    rtvs[0]->GetResource(&res);
    if (!res) return;
    g_topo_rt0_scene = (static_cast<void*>(res) == g_topo_scene_rt_id);
    g_topo_rt0_id = static_cast<void*>(res);   // census v2: identity churn

    if (g_topo_rt0_scene) g_topo_srv_scans = 0;

    if (g_stats_armed.load(std::memory_order_relaxed) &&
        g_mask_res_id && static_cast<void*>(res) == g_mask_res_id) {
        g_mask_rt_binds_f++;
        if (g_mask_first_bind_d < 0.0f) g_mask_first_bind_d = static_cast<float>(g_topo.draws);
        g_mask_last_bind_d = static_cast<float>(g_topo.draws);
    }

    uint32_t khcr_fmt = 0;
    UINT khcr_w = 0;
    bool khcr_known = false;

    for (uint32_t khcr_i = 0; khcr_i < g_rt0_desc_n; ++khcr_i) {
        if (g_rt0_desc[khcr_i].res == static_cast<void*>(res)) {
            khcr_fmt = g_rt0_desc[khcr_i].fmt;
            khcr_w = g_rt0_desc[khcr_i].w;
            khcr_known = true;
            break;
        }
    }

    if (!khcr_known) {
        ID3D11Texture2D* tex = nullptr;
        res->QueryInterface(__uuidof(ID3D11Texture2D), reinterpret_cast<void**>(&tex));

        if (tex) {
            D3D11_TEXTURE2D_DESC td = {};
            tex->GetDesc(&td);
            khcr_fmt = static_cast<uint32_t>(td.Format);
            khcr_w = td.Width;
            tex->Release();
        }

        const uint32_t khcr_slot = g_rt0_desc_n < 32
            ? g_rt0_desc_n : (g_rt0_desc_next & 31u);
        g_rt0_desc[khcr_slot].res = static_cast<void*>(res);
        g_rt0_desc[khcr_slot].fmt = khcr_fmt;
        g_rt0_desc[khcr_slot].w = khcr_w;

        if (g_rt0_desc_n < 32) g_rt0_desc_n++;
        else g_rt0_desc_next++;
    }

    res->Release();
    if (khcr_fmt == 0) return;   // non-Texture2D verdict (the historical early return)
    g_mask.rt_fmt_ok =
        (khcr_fmt == static_cast<uint32_t>(DXGI_FORMAT_R8_UNORM) ||
         khcr_fmt == static_cast<uint32_t>(DXGI_FORMAT_R8_TYPELESS) ||
         khcr_fmt == static_cast<uint32_t>(DXGI_FORMAT_R16_UNORM) ||
         khcr_fmt == static_cast<uint32_t>(DXGI_FORMAT_R16_TYPELESS) ||
         khcr_fmt == static_cast<uint32_t>(DXGI_FORMAT_R16_FLOAT));
    g_mask.rt_w = khcr_w;
    g_mask.rt_is_resolve = khcr_w >= 1280 && g_mask.rt_fmt_ok;
    g_topo_rt0_fmt = khcr_fmt;
    g_topo_rt0_valid = true;
}

// Entirely our pipeline - own target, own matrix, no engine forensics - which
// is what makes MESH-SHAPED cast shadows and concave SELF-shadowing possible
// at all: our geometry never enters the engine's atlas, and the analytic slab
// could only ever cast an AABB.

inline bool render_sun_depth(ID3D11DeviceContext* ctx) {
    if (g_sun_map_rendered_frame) return g_sun_map_valid;
    g_sun_map_rendered_frame = true;

    // SUN-SETTLE GATE: no self/cast map from a moving sun - absent beats
    // swinging (see the gate's state block). Validity drops so frozen
    // consumers stand down too; the map re-renders the frame after the
    // direction settles.
    if (!kh_sun_settled()) {
        g_sun_map_valid = false;
        g_sun2_map_valid = false;
        g_sun3_map_valid = false;
        g_sun4_map_valid = false;
        g_sun5_map_valid = false;
        return false;
    }
    // NOTE: validity is NOT cleared here - the previous frame's map stays
    // consumable (the fire runs before this frame's injection renders a new
    // one); a failed render simply leaves the old map to age out of its 0.25
    // s window.
    g_sun_map_no_local = false;
    if (!ctx) return false;

    // SHADOW GEOMETRY uses the DERIVED sun - the direction measured from the
    // engine's own cascade uploads, i.e. the sun the world's shadows actually
    // follow.
    const float* sun = kh_shadow_sun();

    if (!sun) return false;

    // This closes the ring's crevice-wall crossings AND attenuates the seam
    // fight (the disagreeing straddle taps carry weight w ~ 0.31 at the
    // measured fit) without touching the validated regime, the cast path, or
    // any CB layout.
    float cam_e[3] = { 0.0f, 0.0f, 0.0f };
    bool cam_valid = false;

    {
        RVExtBridge::ProjectionViewTransform cpv = {};

        if (RVExtBridge::get_projection_view_transform(cpv)) {
            extract_camera_pos(cpv.view, cam_e);
            cam_valid = true;
        } else if (g_ls.cam[0] != 0.0f || g_ls.cam[1] != 0.0f || g_ls.cam[2] != 0.0f) {
            cam_e[0] = g_ls.cam[0];
            cam_e[1] = g_ls.cam[1];
            cam_e[2] = g_ls.cam[2];
            cam_valid = true;
        }
    }

    // Camera-less flushes anchor at the origin - which is the world-absolute
    // behaviour, correct by construction. Mode 249 forces the world-absolute
    // form everywhere (the bit-exact revert).
    if (cam_valid && g_dbg_mode.load(std::memory_order_relaxed) != 249) {
        g_sun_anchor_now[0] = cam_e[0];
        g_sun_anchor_now[1] = cam_e[1];
        g_sun_anchor_now[2] = cam_e[2];
    } else {
        g_sun_anchor_now[0] = 0.0f; g_sun_anchor_now[1] = 0.0f; g_sun_anchor_now[2] = 0.0f;
    }

    struct SunCaster { float pos[3]; float size[3]; float rot[9]; bool rotated; int mesh; };
    static std::vector<SunCaster> casters;   // render-thread scratch
    casters.clear();

    // Same clamp as every other g_sun_range consumer; hoisted once, read by
    // every caster test.
    const float khsr_rad = g_dbg_mode.load(std::memory_order_relaxed) != 241
        ? fminf(fmaxf(g_sun_range.load(std::memory_order_relaxed), 8.0f), 1000.0f)
        : KH_SUN_FIT_RADIUS;

    {
        std::lock_guard<std::mutex> lk(g_draw_list_mutex);

        for (const auto& kv : g_draw_list) {
            const auto& o = kv.second;
            if (o.fullscreen || o.mode == DepthMode::Off) continue;
            if (!o.visible && !o.caster_only) continue;
            if (o.caster_only) g_sun_proxy_casters++;

            if (cam_valid) {
                const float ce0[3] = { o.pos[0], o.pos[2], o.pos[1] };
                const float he0[3] = { o.size[0] * 0.5f, o.size[2] * 0.5f, o.size[1] * 0.5f };
                const float dx = ce0[0] - cam_e[0];
                const float dy = ce0[1] - cam_e[1];
                const float dz = ce0[2] - cam_e[2];
                const float hd = sqrtf(he0[0] * he0[0] + he0[1] * he0[1] + he0[2] * he0[2]);
                const float lim = khsr_rad + hd;   // range-following

                if (dx * dx + dy * dy + dz * dz > lim * lim) {
                    // The sole guard is the sy > 1e-4 horizon test below,
                    // which is a validity floor, not a length cap - at sy
                    // 1e-4 the reach is ~2e4 x height, well inside fp32, and
                    // the reach feeds ONLY this eligibility test, never the
                    // map fit) - tested at the same lim with the vertical
                    // extent as slack.
                    bool khsr_in = false;

                    if (g_sun_valid) {
                        const float khsr_sx = g_sun_dir_engine[0];
                        const float khsr_sy = g_sun_dir_engine[1];
                        const float khsr_sz = g_sun_dir_engine[2];
                        const float khsr_hl = sqrtf(khsr_sx * khsr_sx + khsr_sz * khsr_sz);

                        if (khsr_hl > 1.0e-4f && khsr_sy > 1.0e-4f) {
                            const float khsr_tan = khsr_sy / khsr_hl;
                            const float khsr_len = (2.0f * he0[1]) / khsr_tan + hd;
                            const float khsr_ux = -khsr_sx / khsr_hl;   // shadow runs OPPOSITE
                            const float khsr_uz = -khsr_sz / khsr_hl;   // the horizontal sun
                            float khsr_t = (-dx) * khsr_ux + (-dz) * khsr_uz;
                            khsr_t = khsr_t < 0.0f ? 0.0f : (khsr_t > khsr_len ? khsr_len : khsr_t);
                            const float khsr_rx = -dx - khsr_t * khsr_ux;
                            const float khsr_rz = -dz - khsr_t * khsr_uz;
                            float khsr_ry = fabsf(dy) - he0[1];   // vertical slack: the shadow
                            if (khsr_ry < 0.0f) khsr_ry = 0.0f;   // lies at the caster's base
                            khsr_in = khsr_rx * khsr_rx + khsr_ry * khsr_ry + khsr_rz * khsr_rz
                                      <= lim * lim;
                        }
                    }

                    if (!khsr_in) {
                        g_sun_map_no_local = true;   // provisional: cleared below if any caster lands in radius
                        continue;
                    }
                }
            }
            SunCaster c;
            memcpy(c.pos, o.pos, sizeof(c.pos));
            memcpy(c.size, o.size, sizeof(c.size));
            memcpy(c.rot, o.rot_m, sizeof(c.rot));
            c.rotated = o.rotated;
            c.mesh = mesh_id_clamp(o.mesh);
            casters.push_back(c);
        }
    }

    if (!casters.empty()) g_sun_map_no_local = false;   // at least one local caster
    if (casters.empty()) return false;

    // The hash commits ONLY at render success below, so a failed render can
    // never let a stale map vouch for new inputs. (Failure-exonerated
    // re-application: this block sits after the derived-sun guard and
    // provably never executed in the corrupted sessions.)
    uint64_t input_hash = CryptoGenerator::FNV1A64_OFFSET;
    auto khsh_render_cams = [&](bool khsh_standalone) -> void {
        const int khsh_dm = g_dbg_mode.load(std::memory_order_relaxed);
        if (!cam_valid || casters.empty()) {
            g_sun2_map_valid = false;
            g_sun3_map_valid = false;
            g_sun4_map_valid = false;
            g_sun5_map_valid = false;
            return;
        }

        ID3D11Device* khsh_dev = nullptr;
        ctx->GetDevice(&khsh_dev);
        if (!khsh_dev) {
            g_sun2_map_valid = false;
            g_sun3_map_valid = false;
            g_sun4_map_valid = false;
            g_sun5_map_valid = false;
            return;
        }
        // per-band enable: a mode stands ONE band down (239 hero / 242 mid /
        // 244 outer) and only that band - its resources are not even ensured,
        // its meta stays zeroed, and both consumers fall through to the next
        // tier. Resource failure degrades the same way, per band,
        // non-fatally.
        const bool khsh_core = g_res.vs_sundepth && g_res.layout_sundepth &&
                               g_res.sun_instance_vb;
        const bool khsh_ok0 = khsh_core && khsh_dm != 239 && khsh_dm != 366 && ensure_sun_depth2(khsh_dev);   // era arm
        const bool khsh_ok1 = khsh_core && khsh_dm != 242 && khsh_dm != 366 && ensure_sun_depth3(khsh_dev);   // era arm
        const bool khsh_ok2 = khsh_core && khsh_dm != 244 && khsh_dm != 366 && ensure_sun_depth4(khsh_dev);   // era arm
        const bool khsh_ok3 = khsh_core && khsh_dm != 389 && khsh_dm != 366 && ensure_sun_depth5(khsh_dev);   // FAR band (389 stands it down)
        // the moment pyramids + convert pair. Non-fatal: a failed ensure
        // leaves every band classic (sun_pf flags stay false).
        const bool khsh_pf_ok = ensure_sun_pf(khsh_dev);
        khsh_dev->Release();
        if (!khsh_ok0) g_sun2_map_valid = false;
        if (!khsh_ok1) g_sun3_map_valid = false;
        if (!khsh_ok2) g_sun4_map_valid = false;
        if (!khsh_ok3) g_sun5_map_valid = false;
        if (!khsh_ok0 && !khsh_ok1 && !khsh_ok2 && !khsh_ok3) return;

        // Sun basis - same construction as the union fit, ONCE for all bands
        // (they share the sun; only the footprint differs).
        const float khsh_f[3] = { -sun[0], -sun[1], -sun[2] };
        float khsh_up[3] = { 0.0f, 1.0f, 0.0f };
        if (fabsf(khsh_f[1]) > 0.99f) { khsh_up[0] = 1.0f; khsh_up[1] = 0.0f; }
        float khsh_r3[3] = {
            khsh_up[1] * khsh_f[2] - khsh_up[2] * khsh_f[1],
            khsh_up[2] * khsh_f[0] - khsh_up[0] * khsh_f[2],
            khsh_up[0] * khsh_f[1] - khsh_up[1] * khsh_f[0],
        };
        const float khsh_rl = sqrtf(khsh_r3[0] * khsh_r3[0] +
                                    khsh_r3[1] * khsh_r3[1] +
                                    khsh_r3[2] * khsh_r3[2]);
        if (khsh_rl < 1e-6f) {
            g_sun2_map_valid = false;
            g_sun3_map_valid = false;
            g_sun4_map_valid = false;
            g_sun5_map_valid = false;
            return;
        }
        khsh_r3[0] /= khsh_rl; khsh_r3[1] /= khsh_rl; khsh_r3[2] /= khsh_rl;
        const float khsh_u3[3] = {
            khsh_f[1] * khsh_r3[2] - khsh_f[2] * khsh_r3[1],
            khsh_f[2] * khsh_r3[0] - khsh_f[0] * khsh_r3[2],
            khsh_f[0] * khsh_r3[1] - khsh_f[1] * khsh_r3[0],
        };

        // Bias mode arms, one load for the whole pass (khsh_dm above): the
        // two branches cannot disagree about the mode.
        const bool khsh_rev = khsh_dm == 224;
        const bool khsh_qf  = khsh_dm == 235;

        // State envelope: own on union-skip frames, the union's otherwise -
        // ONE envelope for all bands (one capture/restore, up to three clears
        // + draw sets inside it).
        StateBackup khsh_bk;
        ID3D11RenderTargetView* khsh_rt[4] = {};
        ID3D11DepthStencilView* khsh_od = nullptr;
        UINT khsh_nvp = D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE;
        D3D11_VIEWPORT khsh_ovp[D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE] = {};
        const bool khsh_pinj = g_ro.in_injection;

        ID3D11Buffer* khsh_ovb1 = nullptr;
        UINT khsh_ovb1_stride = 0, khsh_ovb1_offset = 0;

        if (khsh_standalone) {
            g_ro.in_injection = true;
            khsh_bk.capture(ctx);
            // b: VB slot 1 is OUTSIDE StateBackup's coverage - the union pass
            // saves it explicitly for exactly this reason, and the standalone
            // pass must too. Missing this leaked OUR mesh + instance buffers
            // into the engine's next draws every skip frame: the sky-splat /
            // black-flicker field report on
            ctx->IAGetVertexBuffers(1, 1, &khsh_ovb1, &khsh_ovb1_stride, &khsh_ovb1_offset);
            // OMSetRenderTargets(4, ...) NULLS every slot it does not name: an engine
            // RTV bound at slots 4..7 here would be silently dropped.
            ctx->OMGetRenderTargets(4, khsh_rt, &khsh_od);
            ctx->RSGetViewports(&khsh_nvp, khsh_ovp);
            ctx->IASetInputLayout(g_res.layout_sundepth);
            ctx->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
            ctx->VSSetShader(g_res.vs_sundepth, nullptr, 0);
            ctx->PSSetShader(nullptr, nullptr, 0);
            ctx->GSSetShader(nullptr, nullptr, 0);
            ctx->HSSetShader(nullptr, nullptr, 0);
            ctx->DSSetShader(nullptr, nullptr, 0);
            ID3D11Buffer* khsh_cbs[2] = { g_res.composite_cb, g_res.composite_frame_cb };
            ctx->VSSetConstantBuffers(0, 2, khsh_cbs);
            ctx->OMSetDepthStencilState(g_res.dss_test_write, 0);
            // FRONT faces stay the default (227 = the back-face arm, historic
            // meaning intact). Twin of the union site through kh_sun_rs_pick.
            // KH_SUN_PANCAKE: the tiers bind the CLAMP twin of the picked
            // state (451 = clip again, the A/B); the gauge reads whether a
            // clamp twin was actually bound (a null twin falls through).
            {
                ID3D11RasterizerState* khsh_rs = kh_sun_rs_pick(khsh_dm, khsh_dm != 451);
                g_sun_pancake_on.store(khsh_rs != kh_sun_rs_pick(khsh_dm, false) ? 1 : 0,
                                       std::memory_order_relaxed);
                ctx->RSSetState(khsh_rs);
            }
        }

        // the hero body, parameterized - one band per call. Outputs land in
        // the band's own statics through the reference parameters.
        auto khsh_one = [&](float khsh_half, float khsh_dep, UINT khsh_size,
                            ID3D11DepthStencilView* khsh_dsv,
                            float (&khsh_out_vp)[4][4], float& khsh_out_bias,
                            float& khsh_out_hd, bool& khsh_out_valid,
                            uint64_t& khsh_out_renders, uint64_t& khsh_out_casters,
                            float& khsh_out_reach,   // KH_BAND_SUN_REACH
                            ID3D11ShaderResourceView* khsh_dep_srv,
                            ID3D11RenderTargetView* khsh_pf_rtv,
                            ID3D11ShaderResourceView* khsh_pf_srv,
                            UINT khsh_pf_size, int khsh_pf_idx,
                            bool& khsh_out_pf) -> void {
            khsh_out_valid = false;   // proven true only by a completed render
            khsh_out_pf = false;   // proven true only by a completed convert
            g_sun_fit_why[khsh_pf_idx] = 5;   // overwritten by every exit below
            g_sun_fit_n[khsh_pf_idx] = 0;
            g_sun_fit_er_max[khsh_pf_idx] = 0.0f;   // per-call, never stale
            g_sun_fit_fwd[khsh_pf_idx] = 0.0f;
            g_sun_fit_tex[khsh_pf_idx] = 0.0f;   // same discipline
            g_sun_fit_bfl[khsh_pf_idx] = 0.0f;
            g_sun_fit_bias[khsh_pf_idx] = 0.0f;
            g_sun_fit_d2v[khsh_pf_idx] = 0.0f;
            g_sun_fit_admit[khsh_pf_idx] = 0u;   // census
            for (int khsh_zi = 0; khsh_zi < 4; ++khsh_zi) {
                g_sun_fit_lat[khsh_pf_idx][khsh_zi] = 0.0f;
                g_sun_fit_ds[khsh_pf_idx][khsh_zi] = 0.0f;
            }
            double khsh_dctr[3] = { 0.0, 0.0, 0.0 };   // double-snap carry
            bool   khsh_dsnap = false;

            // Fixed footprint, texel-snapped in the sun plane (engine-
            // cascade discipline: the window moves in whole texels, so a
            // moving camera never makes stored depth crawl under the
            // compare).
            const float khsh_r2 = khsh_half * 1.02f;
            const float khsh_tex = (2.0f * khsh_r2) / static_cast<float>(khsh_size);
            float khsh_ctr[3] = { cam_e[0], cam_e[1], cam_e[2] };
            if (g_dbg_mode.load(std::memory_order_relaxed) == 256) {
                const float khsh_pr = khsh_ctr[0] * khsh_r3[0] + khsh_ctr[1] * khsh_r3[1] + khsh_ctr[2] * khsh_r3[2];
                const float khsh_pu = khsh_ctr[0] * khsh_u3[0] + khsh_ctr[1] * khsh_u3[1] + khsh_ctr[2] * khsh_u3[2];
                const float khsh_sr = floorf(khsh_pr / khsh_tex) * khsh_tex - khsh_pr;
                const float khsh_su = floorf(khsh_pu / khsh_tex) * khsh_tex - khsh_pu;
                khsh_ctr[0] += khsh_sr * khsh_r3[0] + khsh_su * khsh_u3[0];
                khsh_ctr[1] += khsh_sr * khsh_r3[1] + khsh_su * khsh_u3[1];
                khsh_ctr[2] += khsh_sr * khsh_r3[2] + khsh_su * khsh_u3[2];
            } else {
                const double khsh_dr3[3] = { khsh_r3[0], khsh_r3[1], khsh_r3[2] };
                const double khsh_du3[3] = { khsh_u3[0], khsh_u3[1], khsh_u3[2] };
                const double khsh_dc[3] = { khsh_ctr[0], khsh_ctr[1], khsh_ctr[2] };
                const double khsh_dtex = static_cast<double>(khsh_tex);
                const double khsh_dpr = khsh_dc[0] * khsh_dr3[0] + khsh_dc[1] * khsh_dr3[1] + khsh_dc[2] * khsh_dr3[2];
                const double khsh_dpu = khsh_dc[0] * khsh_du3[0] + khsh_dc[1] * khsh_du3[1] + khsh_dc[2] * khsh_du3[2];
                const double khsh_dsr = floor(khsh_dpr / khsh_dtex) * khsh_dtex - khsh_dpr;
                const double khsh_dsu = floor(khsh_dpu / khsh_dtex) * khsh_dtex - khsh_dpu;
                // The snapped centre STAYS DOUBLE into the eye and the
                // translation row below - collapsing to float here would
                // re-quantise at the very ulp this block exists to beat.
                khsh_dctr[0] = khsh_dc[0] + khsh_dsr * khsh_dr3[0] + khsh_dsu * khsh_du3[0];
                khsh_dctr[1] = khsh_dc[1] + khsh_dsr * khsh_dr3[1] + khsh_dsu * khsh_du3[1];
                khsh_dctr[2] = khsh_dc[2] + khsh_dsr * khsh_dr3[2] + khsh_dsu * khsh_du3[2];
                khsh_dsnap = true;
                khsh_ctr[0] = static_cast<float>(khsh_dctr[0]);
                khsh_ctr[1] = static_cast<float>(khsh_dctr[1]);
                khsh_ctr[2] = static_cast<float>(khsh_dctr[2]);
            }
            // KH_BAND_SUN_REACH - (mode 326 reverts to isotropic sphere +
            // symmetric window, bit-exactly).
            const int khsh_rm = g_dbg_mode.load(std::memory_order_relaxed);
            const bool khsh_reach_off = (khsh_rm == 326);
            static std::vector<SunCaster> khsh_set;   // render-thread scratch
            khsh_set.clear();
            float khsh_fwd = khsh_dep;   // floored at the historic window
            uint32_t khsh_ci = 0;   // census: union-caster index

            for (const auto& c : casters) {
                const uint32_t khsh_i = khsh_ci++;
                const float khsh_dx[3] = { c.pos[0] - khsh_ctr[0],
                                           c.pos[2] - khsh_ctr[1],
                                           c.pos[1] - khsh_ctr[2] };
                const float khsh_hl[3] = { c.size[0] * 0.5f, c.size[2] * 0.5f, c.size[1] * 0.5f };
                float khsh_he[3];
                kh_rot_half_extents(khsh_hl, c.rot, c.rotated, khsh_he);
                const float khsh_er = sqrtf(khsh_he[0] * khsh_he[0] +
                                            khsh_he[1] * khsh_he[1] +
                                            khsh_he[2] * khsh_he[2]);
                const float khsh_dd2 = khsh_dx[0] * khsh_dx[0] +
                                       khsh_dx[1] * khsh_dx[1] +
                                       khsh_dx[2] * khsh_dx[2];

                if (khsh_reach_off) {   // 326: sphere
                    if (sqrtf(khsh_dd2) <= khsh_dep + khsh_er) khsh_set.push_back(c);
                    continue;
                }
                // Sun-axis split: khsh_ds is how far UP-SUN the caster sits
                // (sun[] points toward the sun - the eye below rides it),
                // khsh_lat is the offset the ortho clips on (the per-axis max
                // - the radial form under 447; see below).
                const float khsh_ds = khsh_dx[0] * sun[0] + khsh_dx[1] * sun[1] +
                                      khsh_dx[2] * sun[2];
                // The clip below is the ortho's own per-axis norm - exact,
                // two dots, and the basis depends only on the sun, so camera
                // rotation cannot move the verdict. er over-bounds the
                // per-axis extent the same way it over-bounded the radial
                // one.
                // BAND ADMISSION NORM: the band footprint is a SQUARE in the
                // sun plane, +-r2 along r3 and u3, so the lateral clip must
                // use the same per-axis max norm - a radial (disc) test
                // misses casters in the corners (radial up to r2*sqrt(2))
                // whose silhouettes land inside the window. er (enclosing
                // radius) over-bounds the per-axis extent conservatively.
                // Mode 447 restores the radial form; 326 the old sphere.
                const float khsh_lu = fabsf(khsh_dx[0] * khsh_r3[0] +
                                            khsh_dx[1] * khsh_r3[1] +
                                            khsh_dx[2] * khsh_r3[2]);
                const float khsh_lv = fabsf(khsh_dx[0] * khsh_u3[0] +
                                            khsh_dx[1] * khsh_u3[1] +
                                            khsh_dx[2] * khsh_u3[2]);
                const float khsh_l2 = khsh_dd2 - khsh_ds * khsh_ds;   // 447 arm
                const float khsh_lat = (khsh_dm == 447)
                                     ? (khsh_l2 > 0.0f ? sqrtf(khsh_l2) : 0.0f)
                                     : fmaxf(khsh_lu, khsh_lv);
                // It refused a caster whose enclosing radius exceeded this
                // tier's half-diagonal by more than eight times. AND THE
                // SHAPE CANNOT BE RESCUED BY A TIGHTER CONSTANT: a 5 m crate
                // sits at 2.1x its hero half-diagonal and works, a 983 m
                // caster sits at 2.4x its far half-diagonal and does not, so
                // no multiplier separates them.
                if (khsh_i < 4u) {   // census, stamped before any refusal
                    g_sun_fit_lat[khsh_pf_idx][khsh_i] = khsh_lat - (khsh_r2 + khsh_er);
                    g_sun_fit_ds[khsh_pf_idx][khsh_i] = khsh_ds;
                }
                if (khsh_lat > khsh_r2 + khsh_er) continue;   // ortho clips it laterally
                if (khsh_ds > khsr_rad + khsh_er) {
                    // THE BANDS NEVER GOT THE RESCUE THE UNION HAS HAD SINCE
                    // The two admission paths therefore disagreed, and built
                    // certification on the premise that they agree: a band
                    // certifies "no occluder in my guard" from a map that
                    // never contained one it had refused.
                    float khsh_slim = khsr_rad + khsh_er;
                    if (g_sun_valid &&
                        g_dbg_mode.load(std::memory_order_relaxed) != 399) {
                        const float khsh_ssx = g_sun_dir_engine[0];
                        const float khsh_ssy = g_sun_dir_engine[1];
                        const float khsh_ssz = g_sun_dir_engine[2];
                        const float khsh_shl = sqrtf(khsh_ssx * khsh_ssx +
                                                     khsh_ssz * khsh_ssz);
                        if (khsh_shl > 1.0e-4f && khsh_ssy > 1.0e-4f) {
                            // The tighten remains BANKED exactly as left it,
                            // in the same safe form - the height is the max
                            // of khsh_he[1] and khsh_hl[1], because this site
                            // rotates its half-extents and the union does not
                            // - and it still owes its own arm and its own
                            // build.
                            const float khsh_slen = (2.0f * khsh_er)
                                                  * (khsh_shl / khsh_ssy) + khsh_er;
                            if (khsh_slen > khsh_slim) khsh_slim = khsh_slen;
                        }
                    }
                    if (khsh_ds > khsh_slim) continue;   // shadow cannot reach
                }
                if (khsh_ds < -(khsh_dep) - khsh_er) continue;   // anti-sun side unchanged
                khsh_set.push_back(c);
                if (khsh_i < 32u) g_sun_fit_admit[khsh_pf_idx] |= (1u << khsh_i);   // census
                if (khsh_er > g_sun_fit_er_max[khsh_pf_idx])
                    g_sun_fit_er_max[khsh_pf_idx] = khsh_er;
                const float khsh_need = khsh_ds + khsh_er;
                if (khsh_need > khsh_fwd) khsh_fwd = khsh_need;
            }

            // Entered ONLY above the floor, so a band whose window was never
            // stretched is bit-exact. khsh_fwd is a MAXIMUM over every
            // admitted caster and it sizes khsh_d2v, so this number is how
            // much one member of the set costs all the others in depth
            // precision.
            if (g_dbg_mode.load(std::memory_order_relaxed) != 428 &&
                khsh_fwd > khsh_dep) {
                float& khsh_hold = g_sun_fwd_held[khsh_pf_idx];

                if (khsh_hold >= khsh_fwd && khsh_hold <= khsh_fwd * KH_BAND_FWD_DROP) {
                    khsh_fwd = khsh_hold;
                    g_sun_fwd_holds++;
                } else {
                    khsh_hold = khsh_fwd * KH_BAND_FWD_SLACK;
                    khsh_fwd = khsh_hold;
                    g_sun_fwd_relatches++;
                }
            } else {
                g_sun_fwd_held[khsh_pf_idx] = -1.0f;   // never leave a stale latch
            }
            g_sun_fit_fwd[khsh_pf_idx] = khsh_fwd - khsh_dep;

            // The eye rides khsh_rdep exactly as it always has; only the
            // number it carries can now be larger than khsh_dep, and the
            // view-axis range is the two sides plus the historic 1 m guard at
            // each end. khsh_fwd == khsh_dep reproduces 2*dep+2 exactly.
            const float khsh_rdep = khsh_fwd;
            const float khsh_d2v = khsh_fwd + khsh_dep + 2.0f;
            const float khsh_eye[3] = {
                khsh_ctr[0] + sun[0] * (khsh_rdep + 1.0f),
                khsh_ctr[1] + sun[1] * (khsh_rdep + 1.0f),
                khsh_ctr[2] + sun[2] * (khsh_rdep + 1.0f),
            };
            const double khsh_deye[3] = {
                (khsh_dsnap ? khsh_dctr[0] : static_cast<double>(khsh_ctr[0]))
                    + static_cast<double>(sun[0]) * (static_cast<double>(khsh_rdep) + 1.0),
                (khsh_dsnap ? khsh_dctr[1] : static_cast<double>(khsh_ctr[1]))
                    + static_cast<double>(sun[1]) * (static_cast<double>(khsh_rdep) + 1.0),
                (khsh_dsnap ? khsh_dctr[2] : static_cast<double>(khsh_ctr[2]))
                    + static_cast<double>(sun[2]) * (static_cast<double>(khsh_rdep) + 1.0),
            };
            float khsh_view[4][4] = {};
            khsh_view[0][0] = khsh_r3[0]; khsh_view[0][1] = khsh_u3[0]; khsh_view[0][2] = khsh_f[0];
            khsh_view[1][0] = khsh_r3[1]; khsh_view[1][1] = khsh_u3[1]; khsh_view[1][2] = khsh_f[1];
            khsh_view[2][0] = khsh_r3[2]; khsh_view[2][1] = khsh_u3[2]; khsh_view[2][2] = khsh_f[2];
            // Mode 256 falls back through the float eye.
            const double khsh_da[3] = {
                (khsh_dsnap ? khsh_deye[0] : static_cast<double>(khsh_eye[0]))
                    - static_cast<double>(g_sun_anchor_now[0]),
                (khsh_dsnap ? khsh_deye[1] : static_cast<double>(khsh_eye[1]))
                    - static_cast<double>(g_sun_anchor_now[1]),
                (khsh_dsnap ? khsh_deye[2] : static_cast<double>(khsh_eye[2]))
                    - static_cast<double>(g_sun_anchor_now[2]),
            };
            khsh_view[3][0] = static_cast<float>(-(khsh_da[0] * khsh_r3[0] + khsh_da[1] * khsh_r3[1] + khsh_da[2] * khsh_r3[2]));
            khsh_view[3][1] = static_cast<float>(-(khsh_da[0] * khsh_u3[0] + khsh_da[1] * khsh_u3[1] + khsh_da[2] * khsh_u3[2]));
            khsh_view[3][2] = static_cast<float>(-(khsh_da[0] * khsh_f[0] + khsh_da[1] * khsh_f[1] + khsh_da[2] * khsh_f[2]));
            khsh_view[3][3] = 1.0f;
            float khsh_proj[4][4] = {};
            khsh_proj[0][0] = 1.0f / khsh_r2;
            khsh_proj[1][1] = 1.0f / khsh_r2;
            khsh_proj[2][2] = 1.0f / khsh_d2v;
            khsh_proj[3][3] = 1.0f;
            float khsh_lvp[4][4];
            mul_4x4(khsh_view, khsh_proj, khsh_lvp);

            const float khsh_bcx = fabsf(khsh_ctr[0]) > fabsf(khsh_ctr[1]) ? fabsf(khsh_ctr[0]) : fabsf(khsh_ctr[1]);
            const float khsh_bcm = khsh_bcx > fabsf(khsh_ctr[2]) ? khsh_bcx : fabsf(khsh_ctr[2]);
            const float khsh_bulp = nextafterf(khsh_bcm, 3.0e38f) - khsh_bcm;
            const float khsh_bq = khsh_d2v * 4.0f * 5.9604645e-8f;
            const float khsh_bfl = khsh_rev ? 0.01f : (khsh_qf ? khsh_bq : 4.0f * khsh_bulp);
            // KH_BAND_BIAS_TEXELS: the texel term is a MULTIPLE of the tier's
            // own texel and the ulp term is a FLOOR under it, which is what
            // it should always have been. Mode 426 restores 0.5f and is
            // bit-exact - the ternary shape, the max order and the floor are
            // all unchanged. Ledger at KH_BAND_BIAS_TEXELS.
            const float khsh_bk = g_dbg_mode.load(std::memory_order_relaxed) == 426
                                ? 0.5f : KH_BAND_BIAS_TEXELS;
            const float khsh_bbw = khsh_tex * khsh_bk > khsh_bfl ? khsh_tex * khsh_bk : khsh_bfl;
            // KH_BAND_BIAS_CENSUS, stamped HERE and not lower: this is above
            // the empty-set and cap exits, so a tier that fitted anything
            // reports it. Ledger at the lane declarations.
            g_sun_fit_tex[khsh_pf_idx]  = khsh_tex;
            g_sun_fit_bfl[khsh_pf_idx]  = khsh_bfl;
            g_sun_fit_bias[khsh_pf_idx] = khsh_bbw;
            g_sun_fit_d2v[khsh_pf_idx]  = khsh_d2v;

            // The v2 requirement is unchanged and better served - membership
            // is the ortho's own lateral clip, never a positional subset of
            // it. KH_BAND_SUN_REACH: the caster set and the sun-ward reach
            // are built ABOVE, before the eye/d2v that now depend on them.
            // Mode 326 restores the isotropic sphere in place.
            g_sun_fit_n[khsh_pf_idx] = static_cast<uint64_t>(khsh_set.size());
            if (khsh_set.empty() ||
                khsh_set.size() > static_cast<size_t>(g_res.sun_instance_cap)) {
                g_sun_fit_why[khsh_pf_idx] = khsh_set.empty() ? 1 : 2;
                return;   // capacity grows on union render frames; valid stays false
            }

            ConstantData khsh_obj = {};
            ConstantData khsh_cbf = {};
            memcpy(khsh_cbf.view_proj, khsh_lvp, sizeof(khsh_cbf.view_proj));
            // KH_SUN_ANCHOR: the matrix above is anchor-relative; VSSunDepth
            // subtracts the same anchor from every vertex.
            khsh_cbf.sun_origin[0] = g_sun_anchor_now[0];
            khsh_cbf.sun_origin[1] = g_sun_anchor_now[1];
            khsh_cbf.sun_origin[2] = g_sun_anchor_now[2];

            g_sun_fit_why[khsh_pf_idx] = 3;   // deepest stage reached
            if (kh_upload_frame_cb(ctx, g_res.composite_frame_cb, khsh_cbf) &&
                kh_upload_obj_cb(ctx, g_res.composite_cb, khsh_obj)) {
                ctx->ClearDepthStencilView(khsh_dsv, D3D11_CLEAR_DEPTH, 1.0f, 0);
                ctx->OMSetRenderTargets(0, nullptr, khsh_dsv);
                {
                    D3D11_VIEWPORT khsh_vp = {};
                    khsh_vp.Width = static_cast<FLOAT>(khsh_size);
                    khsh_vp.Height = static_cast<FLOAT>(khsh_size);
                    khsh_vp.MaxDepth = 1.0f;
                    ctx->RSSetViewports(1, &khsh_vp);
                }

                std::sort(khsh_set.begin(), khsh_set.end(),
                          [](const SunCaster& a, const SunCaster& b) { return a.mesh < b.mesh; });
                D3D11_MAPPED_SUBRESOURCE khsh_im = {};

                if (SUCCEEDED(ctx->Map(g_res.sun_instance_vb, 0, D3D11_MAP_WRITE_DISCARD, 0, &khsh_im))) {
                    g_sun_fit_why[khsh_pf_idx] = 4;   // deepest stage reached
                    float* khsh_outp = static_cast<float*>(khsh_im.pData);

                    for (const auto& c : khsh_set) {
                        khsh_outp[0] = c.pos[0];
                        khsh_outp[1] = c.pos[2];
                        khsh_outp[2] = c.pos[1];
                        khsh_outp[3] = 0.0f;
                        khsh_outp[4] = c.size[0];
                        khsh_outp[5] = c.size[2];
                        khsh_outp[6] = c.size[1];
                        khsh_outp[7] = 0.0f;

                        for (int khsh_rr = 0; khsh_rr < 3; ++khsh_rr) {
                            khsh_outp[8 + khsh_rr * 4 + 0] = c.rot[khsh_rr * 3 + 0];
                            khsh_outp[8 + khsh_rr * 4 + 1] = c.rot[khsh_rr * 3 + 1];
                            khsh_outp[8 + khsh_rr * 4 + 2] = c.rot[khsh_rr * 3 + 2];
                            khsh_outp[8 + khsh_rr * 4 + 3] = 0.0f;
                        }

                        khsh_outp += 20;
                    }

                    ctx->Unmap(g_res.sun_instance_vb, 0);

                    ID3D11Buffer* khsh_vbs[2] = { nullptr, g_res.sun_instance_vb };
                    UINT khsh_strides[2] = { sizeof(MeshVertex), sizeof(float) * 20 };
                    UINT khsh_offsets[2] = { 0, 0 };
                    size_t khsh_first = 0;

                    while (khsh_first < khsh_set.size()) {
                        const int khsh_mid = khsh_set[khsh_first].mesh;
                        size_t khsh_last = khsh_first + 1;
                        while (khsh_last < khsh_set.size() && khsh_set[khsh_last].mesh == khsh_mid) ++khsh_last;
                        khsh_vbs[0] = g_res.mesh_vb[khsh_mid];
                        ctx->IASetVertexBuffers(0, 2, khsh_vbs, khsh_strides, khsh_offsets);
                        // KH_SHADOW_LOD: a coarse level, the grouping
                        // untouched. Mode 422 restores level 0.
                        UINT khsh_ls = 0, khsh_lc = 0;
                        mesh_shadow_range(khsh_mid, khsh_ls, khsh_lc);
                        ctx->DrawInstanced(khsh_lc,
                                           static_cast<UINT>(khsh_last - khsh_first), khsh_ls,
                                           static_cast<UINT>(khsh_first));
                        khsh_first = khsh_last;
                    }

                    memcpy(khsh_out_vp, khsh_lvp, sizeof(khsh_out_vp));
                    khsh_out_bias = khsh_bbw / khsh_d2v;
                    khsh_out_hd = khsh_half;
                    khsh_out_valid = true;
                    g_sun_fit_why[khsh_pf_idx] = 0;   // completed
                    khsh_out_renders++;
                    khsh_out_casters = static_cast<uint64_t>(khsh_set.size());
                    // ARMING LANE: the reach this fit actually took. Equal to
                    // the band's KH_SUN_*_DEPTH floor = no caster sat farther
                    // up-sun than the historic window and this fit is
                    // bit-identical to Above it = the arm fired.
                    khsh_out_reach = khsh_fwd;
                    if (khsh_fwd > khsh_dep) g_sun_band_reach_takes++;
                    // At THIS site the t0 SRV bind silently delivered a
                    // foreign kilometre-scale texture (CPU-proven: pyramid mu
                    // 2630-2752) while the RTV and shader sets took. The band
                    // renders here; freshness is all this site marks.
                    (void)khsh_pf_ok; (void)khsh_dep_srv; (void)khsh_pf_rtv;
                    (void)khsh_pf_srv; (void)khsh_pf_size; (void)khsh_pf_idx;
                    khsh_out_pf = khsh_out_valid;   // fresh map => convert due
                }
            }
        };

        // KH_SUN_LADDER_SCALE - (mode 382 reverts to the fixed 8/32 m
        // footprints; at shadowVisibility 200 the scaled defaults are ALREADY
        // bit-exact, which is the whole validated corpus).
        float khls_cr = 0.0f;

        for (const auto& khls_c : casters) {
            const float khls_hl[3] = { khls_c.size[0] * 0.5f, khls_c.size[2] * 0.5f,
                                       khls_c.size[1] * 0.5f };
            float khls_he[3];
            kh_rot_half_extents(khls_hl, khls_c.rot, khls_c.rotated, khls_he);
            const float khls_r = sqrtf(khls_he[0] * khls_he[0] + khls_he[1] * khls_he[1] +
                                       khls_he[2] * khls_he[2]);
            if (khls_r > khls_cr) khls_cr = khls_r;
        }

        g_sun_ladder_caster_r = khls_cr;   // gauge only, feeds nothing
        float khls_s = 1.0f;
        if (khsh_dm != 241 && khsh_dm != 382) {
            khls_s = khsr_rad / 200.0f;
            if (khls_s < 1.0f) khls_s = 1.0f;
            if (khls_s > 5.0f) khls_s = 5.0f;
        }
        g_sun_ladder_scale = khls_s;
        for (int khsh_wi = 0; khsh_wi < 4; ++khsh_wi) g_sun_fit_why[khsh_wi] = 6;
        // KH_SUN_LADDER: the ensures above guarantee each texture IS the
        // wanted size; record it as the rendered size for the CB fills.
        if (khsh_ok0) g_sun2_map_size = kh_sun_hero_size();
        if (khsh_ok1) g_sun3_map_size = kh_sun_mid_size();
        if (khsh_ok2) g_sun4_map_size = kh_sun_out_size();
        if (khsh_ok3) g_sun5_map_size = kh_sun_far_size();
        if (khsh_ok0) khsh_one(KH_SUN_HERO_HALF, KH_SUN_HERO_DEPTH, kh_sun_hero_size(),
                               g_res.sun2_dsv, g_sun2_map_vp, g_sun2_map_bias,
                               g_sun2_half_diag, g_sun2_map_valid,
                               g_sun2_renders, g_sun2_casters, g_sun_band_reach[0],
                               g_res.sun2_srv, g_res.sun_pf_rtv[0],
                               g_res.sun_pf_srv[0], kh_sun_hero_size() / 2u, 0,
                               g_sun_pf_valid[0]);
        if (khsh_ok1) khsh_one(KH_SUN_MID_HALF * khls_s, KH_SUN_MID_DEPTH * khls_s,
                               kh_sun_mid_size(),
                               g_res.sun3_dsv, g_sun3_map_vp, g_sun3_map_bias,
                               g_sun3_half_diag, g_sun3_map_valid,
                               g_sun3_renders, g_sun3_casters, g_sun_band_reach[1],
                               g_res.sun3_srv, g_res.sun_pf_rtv[1],
                               g_res.sun_pf_srv[1], kh_sun_mid_size() / 2u, 1,
                               g_sun_pf_valid[1]);
        if (khsh_ok2) khsh_one(KH_SUN_OUT_HALF * khls_s, KH_SUN_OUT_DEPTH * khls_s,
                               kh_sun_out_size(),
                               g_res.sun4_dsv, g_sun4_map_vp, g_sun4_map_bias,
                               g_sun4_half_diag, g_sun4_map_valid,
                               g_sun4_renders, g_sun4_casters, g_sun_band_reach[2],
                               g_res.sun4_srv, g_res.sun_pf_rtv[2],
                               g_res.sun_pf_srv[2], kh_sun_out_size() / 2u, 2,
                               g_sun_pf_valid[2]);
        // No moment pyramid (the far texel is already the minified scale the
        // pyramids exist to reach; nulls keep the convert inert - pf index 3
        // is never read by kh_sun_pf_convert, which walks 0..2).
        // KH_SUN_FAR_BAND: half = the range ITSELF (khsr_rad, no ladder scale
        // - the window IS the range), depth = 6x half.
        bool khsh_far_pf = false;
        if (khsh_ok3) khsh_one(khsr_rad, khsr_rad * 6.0f, kh_sun_far_size(),
                               g_res.sun5_dsv, g_sun5_map_vp, g_sun5_map_bias,
                               g_sun5_half_diag, g_sun5_map_valid,
                               g_sun5_renders, g_sun5_casters, g_sun_band_reach[3],
                               g_res.sun5_srv, nullptr,
                               nullptr, kh_sun_far_size() / 2u, 3,
                               khsh_far_pf);
        // KH_SUN_ANCHOR: all three band matrices above were built about this
        // flush's anchor - pair them with it for the fills.
        memcpy(g_sun_cam_anchor, g_sun_anchor_now, sizeof(g_sun_cam_anchor));

        if (khsh_standalone) {
            ctx->OMSetRenderTargets(4, khsh_rt, khsh_od);
            if (khsh_nvp > 0) ctx->RSSetViewports(khsh_nvp, khsh_ovp);
            ctx->IASetVertexBuffers(1, 1, &khsh_ovb1, &khsh_ovb1_stride, &khsh_ovb1_offset);
            KH_SAFE_RELEASE(khsh_ovb1);
            khsh_bk.restore(ctx);
            for (int khsh_r4 = 0; khsh_r4 < 4; ++khsh_r4) KH_SAFE_RELEASE(khsh_rt[khsh_r4]);
            KH_SAFE_RELEASE(khsh_od);
            g_ro.in_injection = khsh_pinj;
        }
    };

    uint64_t khsm_caster_hash = 0;

    {
        auto fnv = [&input_hash](const void* p, size_t n) {
            input_hash = CryptoGenerator::fnv1a64_update(input_hash, p, n);
        };

        for (const auto& c : casters) {
            fnv(c.pos, sizeof(c.pos));
            fnv(c.size, sizeof(c.size));
            fnv(c.rot, sizeof(c.rot));   // rotating a caster re-renders
            fnv(&c.mesh, sizeof(c.mesh));
        }

        khsm_caster_hash = input_hash;   // caster-only component (maturity)
        fnv(sun, 12);
        // the union window is camera-anchored, so its 2 m cell is fit input -
        // crossings re-render, everything else skips. camera-anchored is the
        // DEFAULT now (the cascade ladder exists - KH_SUN_CASCADE); 241
        // reverts to the caster-anchored fit, whose hash correctly carries no
        // camera term.
        if (cam_valid && g_dbg_mode.load(std::memory_order_relaxed) != 241) {
            const int32_t khsm_cell[3] = {
                static_cast<int32_t>(floorf(cam_e[0] * 0.5f)),
                static_cast<int32_t>(floorf(cam_e[1] * 0.5f)),
                static_cast<int32_t>(floorf(cam_e[2] * 0.5f)),
            };
            fnv(khsm_cell, sizeof(khsm_cell));
            const int32_t khsm_rng = static_cast<int32_t>(
                g_sun_range.load(std::memory_order_relaxed));
            fnv(&khsm_rng, sizeof(khsm_rng));
        }

        if (g_sun_map_valid && input_hash == g_sun_map_hash) {
            g_sun_map_time = effect_time_seconds();
            g_sun_map_skips++;
            khsh_render_cams(true);   // camera bands render every call
            return true;
        }
    }

    ID3D11Device* dev = nullptr;
    ctx->GetDevice(&dev);
    if (!dev) return false;
    const bool res_ok = kh_ensure_ok("sun-depth resources", ensure_resources(dev)) && ensure_sun_depth(dev);
    bool instanced = res_ok && g_res.vs_sundepth && g_res.layout_sundepth;

    if (instanced) {
        // Grow-only dynamic instance buffer: 20 floats per caster
        // (engine-space center, engine-space extents, three engine-axes
        // rotation rows - float4-strided to match the input layout).
        const UINT need = static_cast<UINT>(casters.size());

        if (need > g_res.sun_instance_cap) {
            KH_SAFE_RELEASE(g_res.sun_instance_vb);
            UINT cap = g_res.sun_instance_cap > 64 ? g_res.sun_instance_cap : 64;
            while (cap < need) cap *= 2;
            D3D11_BUFFER_DESC bd = {};
            bd.ByteWidth = cap * sizeof(float) * 20;
            bd.Usage = D3D11_USAGE_DYNAMIC;
            bd.BindFlags = D3D11_BIND_VERTEX_BUFFER;
            bd.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;

            if (SUCCEEDED(dev->CreateBuffer(&bd, nullptr, &g_res.sun_instance_vb))) {
                g_res.sun_instance_cap = cap;
            } else {
                g_res.sun_instance_cap = 0;
                instanced = false;
            }
        }
    }

    dev->Release();
    if (!res_ok) return false;

    // Combined caster AABB, engine axes (SQF [x, y, zASL] -> [x, zASL, y]).
    float mn[3] = { 1e18f, 1e18f, 1e18f };
    float mx[3] = { -1e18f, -1e18f, -1e18f };

    for (const auto& c : casters) {
        const float ce[3] = { c.pos[0], c.pos[2], c.pos[1] };
        const float hl[3] = { c.size[0] * 0.5f, c.size[2] * 0.5f, c.size[1] * 0.5f };
        float he[3];
        kh_rot_half_extents(hl, c.rot, c.rotated, he);   // enclosing (rotation-safe)

        for (int k = 0; k < 3; ++k) {
            if (ce[k] - he[k] < mn[k]) mn[k] = ce[k] - he[k];
            if (ce[k] + he[k] > mx[k]) mx[k] = ce[k] + he[k];
        }
    }

    float ctr[3] = { (mn[0] + mx[0]) * 0.5f, (mn[1] + mx[1]) * 0.5f, (mn[2] + mx[2]) * 0.5f };
    float hf[3] = { (mx[0] - mn[0]) * 0.5f, (mx[1] - mn[1]) * 0.5f, (mx[2] - mn[2]) * 0.5f };

    g_sun_map_cam_anchor = false;   // re-derived on every re-fit
                                    // skip frames keep the committed value
    if (cam_valid && g_dbg_mode.load(std::memory_order_relaxed) != 241) {
        g_sun_map_cam_anchor = true;
        ctr[0] = floorf(cam_e[0] * 0.5f) * 2.0f + 1.0f;
        ctr[1] = floorf(cam_e[1] * 0.5f) * 2.0f + 1.0f;
        ctr[2] = floorf(cam_e[2] * 0.5f) * 2.0f + 1.0f;
        const float khsu_rng = fminf(fmaxf(
            g_sun_range.load(std::memory_order_relaxed), 8.0f), 1000.0f);
        hf[0] = hf[1] = hf[2] = khsu_rng / 1.7320508f;
        // KH_SUN_CASTER_UNION - (catalog ledger; mode 294 reverts to the pure
        // camera window).
        if (g_dbg_mode.load(std::memory_order_relaxed) != 294) {
            constexpr float KH_SUN_GROW_CAP = 3500.0f;   // enclosing-radius ceiling (~7 km span)
            const float khsg_h = KH_SUN_GROW_CAP / 1.7320508f;
            bool khsg_grew = false;

            for (int khsg_k = 0; khsg_k < 3; ++khsg_k) {
                const float khsg_cl = fmaxf(mn[khsg_k], ctr[khsg_k] - khsg_h);
                const float khsg_ch = fminf(mx[khsg_k], ctr[khsg_k] + khsg_h);
                if (khsg_cl > khsg_ch) continue;   // capped caster box empty on this axis
                float khsg_lo = ctr[khsg_k] - hf[khsg_k];
                float khsg_hi = ctr[khsg_k] + hf[khsg_k];
                if (khsg_cl < khsg_lo) { khsg_lo = khsg_cl; khsg_grew = true; }
                if (khsg_ch > khsg_hi) { khsg_hi = khsg_ch; khsg_grew = true; }
                ctr[khsg_k] = (khsg_lo + khsg_hi) * 0.5f;
                hf[khsg_k] = (khsg_hi - khsg_lo) * 0.5f;
            }

            if (khsg_grew) g_kh_sunvp_fit_grows++;
        }
    }
    // KH_UNION_R_LATCH - (mode 329 reverts, bit-exactly). KH_SUN_FIT_SPLIT -
    // THE LATERAL EXTENT AND THE DEPTH GUARD BAND ARE TWO DIFFERENT
    // QUANTITIES AND WERE ONE NUMBER.
    const float khsf_rad_raw = sqrtf(hf[0] * hf[0] + hf[1] * hf[1] + hf[2] * hf[2]);
    float khsf_rad_use = khsf_rad_raw;
    if (g_sun_map_cam_anchor &&
        g_dbg_mode.load(std::memory_order_relaxed) != 329) {
        constexpr float KH_SUN_UNION_R_SLACK = 1.10f;   // headroom taken on acquisition
        constexpr float KH_SUN_UNION_R_DROP  = 1.25f;   // re-latch tighter past this
        if (g_sun_union_rad_held >= khsf_rad_raw &&
            g_sun_union_rad_held <= khsf_rad_raw * KH_SUN_UNION_R_DROP) {
            khsf_rad_use = g_sun_union_rad_held;
            g_sun_union_rad_holds++;
        } else {
            g_sun_union_rad_held = khsf_rad_raw * KH_SUN_UNION_R_SLACK;
            khsf_rad_use = g_sun_union_rad_held;
            g_sun_union_rad_relatches++;
        }
    }
    const float khsf_rad = khsf_rad_use;
    const bool  khsf_rev = g_dbg_mode.load(std::memory_order_relaxed) == 224;
    const float R_dep = khsf_rad + 1.0f;   // depth guard: unchanged
    // KH_SUN_UNION_LAT_FIT: R is refined (only ever downward) after the sun
    // basis exists below - it needs the sun plane to measure in.
    float R = khsf_rev ? R_dep   // 224 = the old single number
                       : (khsf_rad > 1.0e-4f ? khsf_rad * 1.02f : R_dep);

    // Ortho sun basis (row-vector convention, like every matrix here). The
    // light LOOKS opposite the "toward the light" direction.
    const float f[3] = { -sun[0], -sun[1], -sun[2] };
    float up_hint[3] = { 0.0f, 1.0f, 0.0f };
    if (fabsf(f[1]) > 0.99f) { up_hint[0] = 1.0f; up_hint[1] = 0.0f; }

    float r3[3] = {
        up_hint[1] * f[2] - up_hint[2] * f[1],
        up_hint[2] * f[0] - up_hint[0] * f[2],
        up_hint[0] * f[1] - up_hint[1] * f[0],
    };

    const float rl = sqrtf(r3[0] * r3[0] + r3[1] * r3[1] + r3[2] * r3[2]);
    if (rl < 1e-6f) return false;
    r3[0] /= rl; r3[1] /= rl; r3[2] /= rl;

    const float u3[3] = {
        f[1] * r3[2] - f[2] * r3[1],
        f[2] * r3[0] - f[0] * r3[2],
        f[0] * r3[1] - f[1] * r3[0],
    };

    // KH_SUN_UNION_LAT_FIT - (mode 383 reverts to the enclosing-sphere price,
    // bit-exactly). Capped at the sphere radius so it can never price coarser
    // than did.
    if (g_sun_map_cam_anchor && !khsf_rev &&
        g_dbg_mode.load(std::memory_order_relaxed) != 383) {
        const float khsl_rng = fminf(fmaxf(
            g_sun_range.load(std::memory_order_relaxed), 8.0f), 1000.0f);
        // Camera window term: its cell centre's lateral offset from the
        // committed (possibly growth-moved) centre, plus the range - the
        // enclosing-sphere bound of the camera box about its own centre.
        const float khsl_cc[3] = {
            floorf(cam_e[0] * 0.5f) * 2.0f + 1.0f,
            floorf(cam_e[1] * 0.5f) * 2.0f + 1.0f,
            floorf(cam_e[2] * 0.5f) * 2.0f + 1.0f,
        };
        const float khsl_cd[3] = { khsl_cc[0] - ctr[0], khsl_cc[1] - ctr[1],
                                   khsl_cc[2] - ctr[2] };
        const float khsl_cs = khsl_cd[0] * sun[0] + khsl_cd[1] * sun[1] +
                              khsl_cd[2] * sun[2];
        const float khsl_cl2 = khsl_cd[0] * khsl_cd[0] + khsl_cd[1] * khsl_cd[1] +
                               khsl_cd[2] * khsl_cd[2] - khsl_cs * khsl_cs;
        float khsl_need = (khsl_cl2 > 0.0f ? sqrtf(khsl_cl2) : 0.0f) + khsl_rng;

        for (const auto& khsl_c : casters) {
            const float khsl_ce[3] = { khsl_c.pos[0], khsl_c.pos[2], khsl_c.pos[1] };
            const float khsl_hl[3] = { khsl_c.size[0] * 0.5f, khsl_c.size[2] * 0.5f,
                                       khsl_c.size[1] * 0.5f };
            float khsl_he[3];
            kh_rot_half_extents(khsl_hl, khsl_c.rot, khsl_c.rotated, khsl_he);
            const float khsl_er = sqrtf(khsl_he[0] * khsl_he[0] +
                                        khsl_he[1] * khsl_he[1] +
                                        khsl_he[2] * khsl_he[2]);
            const float khsl_d[3] = { khsl_ce[0] - ctr[0], khsl_ce[1] - ctr[1],
                                      khsl_ce[2] - ctr[2] };
            const float khsl_ds = khsl_d[0] * sun[0] + khsl_d[1] * sun[1] +
                                  khsl_d[2] * sun[2];
            const float khsl_l2 = khsl_d[0] * khsl_d[0] + khsl_d[1] * khsl_d[1] +
                                  khsl_d[2] * khsl_d[2] - khsl_ds * khsl_ds;
            const float khsl_lat = (khsl_l2 > 0.0f ? sqrtf(khsl_l2) : 0.0f) + khsl_er;
            if (khsl_lat > khsl_need) khsl_need = khsl_lat;
        }

        if (khsl_need > khsf_rad) khsl_need = khsf_rad;   // never coarser than the sphere
        float khsl_use = khsl_need;
        if (g_dbg_mode.load(std::memory_order_relaxed) != 329) {
            constexpr float KH_SUN_UNION_L_SLACK = 1.10f;   // policy
            constexpr float KH_SUN_UNION_L_DROP  = 1.25f;
            if (g_sun_union_lat_held >= khsl_need &&
                g_sun_union_lat_held <= khsl_need * KH_SUN_UNION_L_DROP) {
                khsl_use = g_sun_union_lat_held;
                g_sun_union_lat_holds++;
            } else {
                g_sun_union_lat_held = khsl_need * KH_SUN_UNION_L_SLACK;
                khsl_use = g_sun_union_lat_held;
                g_sun_union_lat_relatches++;
            }
        }
        // Apply only when it genuinely refines - the latch slack can push the
        // held value past the sphere in dense-lateral scenes, where the
        // sphere price is already the honest one.
        if (khsl_use > 1.0e-4f && khsl_use * 1.02f < R) R = khsl_use * 1.02f;
    }

    // KH_UNION_TEXEL_SNAP - (mode 327 reverts, bit-exactly). This fit never
    // has.
    if (g_dbg_mode.load(std::memory_order_relaxed) != 327) {
        const double khut_tex = (2.0 * static_cast<double>(R)) /
                                static_cast<double>(kh_sun_depth_size());
        if (khut_tex > 1.0e-9) {
            const double khut_c[3] = { ctr[0], ctr[1], ctr[2] };
            const double khut_r[3] = { r3[0], r3[1], r3[2] };
            const double khut_u[3] = { u3[0], u3[1], u3[2] };
            const double khut_pr = khut_c[0] * khut_r[0] + khut_c[1] * khut_r[1] +
                                   khut_c[2] * khut_r[2];
            const double khut_pu = khut_c[0] * khut_u[0] + khut_c[1] * khut_u[1] +
                                   khut_c[2] * khut_u[2];
            const double khut_sr = floor(khut_pr / khut_tex) * khut_tex - khut_pr;
            const double khut_su = floor(khut_pu / khut_tex) * khut_tex - khut_pu;
            const double khut_n[3] = {
                khut_c[0] + khut_sr * khut_r[0] + khut_su * khut_u[0],
                khut_c[1] + khut_sr * khut_r[1] + khut_su * khut_u[1],
                khut_c[2] + khut_sr * khut_r[2] + khut_su * khut_u[2],
            };
            g_sun_union_snap_m = static_cast<float>(
                sqrt(khut_sr * khut_sr + khut_su * khut_su));
            g_sun_union_texel_m = static_cast<float>(khut_tex);
            g_sun_union_snaps++;
            ctr[0] = static_cast<float>(khut_n[0]);
            ctr[1] = static_cast<float>(khut_n[1]);
            ctr[2] = static_cast<float>(khut_n[2]);
        }
    }
    // Depth-domain behaviour is byte- identical to whatever the lateral
    // extent does.
    const float eye[3] = {
        ctr[0] + sun[0] * (R_dep + 1.0f),
        ctr[1] + sun[1] * (R_dep + 1.0f),
        ctr[2] + sun[2] * (R_dep + 1.0f),
    };

    const float D = 2.0f * R_dep + 2.0f;   // view-axis range: casters sit in [1, 2R_dep+1]

    float view[4][4] = {};
    view[0][0] = r3[0]; view[0][1] = u3[0]; view[0][2] = f[0];
    view[1][0] = r3[1]; view[1][1] = u3[1]; view[1][2] = f[1];
    view[2][0] = r3[2]; view[2][1] = u3[2]; view[2][2] = f[2];
    // KH_SUN_ANCHOR: the translation row measures from the anchor, not the
    // world origin - the shader subtracts the same anchor from wpos, so the
    // mapping is identical while the fp products shrink from world magnitude
    // to fit magnitude.
    const float khse_a[3] = { eye[0] - g_sun_anchor_now[0],
                              eye[1] - g_sun_anchor_now[1],
                              eye[2] - g_sun_anchor_now[2] };
    view[3][0] = -(khse_a[0] * r3[0] + khse_a[1] * r3[1] + khse_a[2] * r3[2]);
    view[3][1] = -(khse_a[0] * u3[0] + khse_a[1] * u3[1] + khse_a[2] * u3[2]);
    view[3][2] = -(khse_a[0] * f[0] + khse_a[1] * f[1] + khse_a[2] * f[2]);
    view[3][3] = 1.0f;

    float proj[4][4] = {};
    proj[0][0] = 1.0f / R;   // LATERAL extent (no depth guard in it)
    proj[1][1] = 1.0f / R;
    proj[2][2] = 1.0f / D;   // z in [0, D] -> [0, 1]
    proj[3][3] = 1.0f;

    float lvp[4][4];
    mul_4x4(view, proj, lvp);

    // Compare bias, deliberately SMALL: the world CAST cannot acne (the
    // ground is never in our map, so it never compares against itself), and
    // the SELF term's acne is handled geometrically by the receiver- normal
    // offset + grazing fade.
    const float texel_world = (2.0f * R) / static_cast<float>(kh_sun_depth_size());
    // THE FLOOR IS fp32 WORLD PRECISION, NOT DEPTH-BUFFER PRECISION. 235
    // restores the D32 quantisation.
    const float khsb_cx = fabsf(ctr[0]) > fabsf(ctr[1]) ? fabsf(ctr[0]) : fabsf(ctr[1]);
    const float khsb_cm = khsb_cx > fabsf(ctr[2]) ? khsb_cx : fabsf(ctr[2]);
    const float khsb_ulp = nextafterf(khsb_cm, 3.0e38f) - khsb_cm;
    const float khsb_quant = D * 4.0f * 5.9604645e-8f;   // 4 ulp of the D32 encode
    const float khsb_floor = khsf_rev ? 0.01f
                           : (g_dbg_mode.load(std::memory_order_relaxed) == 235
                              ? khsb_quant : 4.0f * khsb_ulp);
    const float bias_world = texel_world * 0.5f > khsb_floor ? texel_world * 0.5f : khsb_floor;

    // depth-only pass: full save/restore, own clear, recursion off
    const bool prev_inj = g_ro.in_injection;
    g_ro.in_injection = true;
    StateBackup backup;
    backup.capture(ctx);
    // Slot-1 IA save/restore is LOCAL to this pass (the only code that binds
    // it): keeping StateBackup itself byte-identical to its pre-refactor
    // single-slot behavior removes a global behavioral diff from every other
    // save/restore user (fire, flush, injection).
    ID3D11Buffer* old_vb1 = nullptr;
    UINT old_vb1_stride = 0, old_vb1_offset = 0;
    ctx->IAGetVertexBuffers(1, 1, &old_vb1, &old_vb1_stride, &old_vb1_offset);
    ID3D11RenderTargetView* old_rtvs[4] = {};
    ID3D11DepthStencilView* old_dsv = nullptr;
    // OMSetRenderTargets(4, ...) NULLS every slot it does not name: an engine
    // RTV bound at slots 4..7 here would be silently dropped.
    ctx->OMGetRenderTargets(4, old_rtvs, &old_dsv);
    UINT old_nvp = D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE;
    D3D11_VIEWPORT old_vps[D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE] = {};
    ctx->RSGetViewports(&old_nvp, old_vps);

    g_sun_map_size = kh_sun_depth_size();   // KH_SUN_LADDER: the union's rendered size
    ctx->ClearDepthStencilView(g_res.sun_dsv, D3D11_CLEAR_DEPTH, 1.0f, 0);
    ctx->OMSetRenderTargets(0, nullptr, g_res.sun_dsv);

    {
        D3D11_VIEWPORT vp = {};
        vp.Width = static_cast<FLOAT>(kh_sun_depth_size());
        vp.Height = static_cast<FLOAT>(kh_sun_depth_size());
        vp.MaxDepth = 1.0f;
        ctx->RSSetViewports(1, &vp);
    }

    ctx->IASetInputLayout(instanced ? g_res.layout_sundepth : g_res.input_layout);
    ctx->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
    ctx->VSSetShader(instanced ? g_res.vs_sundepth : g_res.vs, nullptr, 0);
    ctx->PSSetShader(nullptr, nullptr, 0);   // depth only
    ctx->GSSetShader(nullptr, nullptr, 0);
    ctx->HSSetShader(nullptr, nullptr, 0);
    ctx->DSSetShader(nullptr, nullptr, 0);
    ID3D11Buffer* khsd_cbs[2] = { g_res.composite_cb, g_res.composite_frame_cb };
    ctx->VSSetConstantBuffers(0, 2, khsd_cbs);
    ConstantData khsd_cbf = {};
    memcpy(khsd_cbf.view_proj, lvp, sizeof(khsd_cbf.view_proj));
    khsd_cbf.sun_origin[0] = g_sun_anchor_now[0];
    khsd_cbf.sun_origin[1] = g_sun_anchor_now[1];
    khsd_cbf.sun_origin[2] = g_sun_anchor_now[2];
    const bool khsd_frame_ok = kh_upload_frame_cb(ctx, g_res.composite_frame_cb, khsd_cbf);
    ctx->OMSetDepthStencilState(g_res.dss_test_write, 0);
    // One load feeds both tests: the two arms cannot disagree about the mode.
    {
        const int khsd_dm = g_dbg_mode.load(std::memory_order_relaxed);
        // A thin wall puts the back face millimetres behind the front, the
        // 16/3.0 bias exceeds the thickness and light leaks straight through;
        // OPEN or single-sided meshes store NO back face at all and
        // everything behind them reads lit. TWIN of the band pass
        // (khsh_one) through kh_sun_rs_pick. The union stays on the CLIP
        // form (khrs_clamp false): its ortho volume is fitted around the
        // caster set, so the fitting argument holds here and only here
        // (KH_SUN_PANCAKE).
        ctx->RSSetState(kh_sun_rs_pick(khsd_dm, false));
    }
    if (instanced) {
        // ONE constant upload, ONE instance-buffer fill, ONE DrawInstanced
        // per mesh type: object count no longer multiplies map/draw calls,
        // which is what makes the uncapped caster set plausible.
        std::sort(casters.begin(), casters.end(),
                  [](const SunCaster& a, const SunCaster& b) { return a.mesh < b.mesh; });

        bool filled = false;
        D3D11_MAPPED_SUBRESOURCE im = {};

        if (SUCCEEDED(ctx->Map(g_res.sun_instance_vb, 0, D3D11_MAP_WRITE_DISCARD, 0, &im))) {
            float* outp = static_cast<float*>(im.pData);

            for (const auto& c : casters) {
                outp[0] = c.pos[0];   // SQF [x,y,zASL] -> engine [x,zASL,y]
                outp[1] = c.pos[2];
                outp[2] = c.pos[1];
                outp[3] = 0.0f;
                outp[4] = c.size[0];   // SQF [x,y,z] sizes -> engine [x,z,y]
                outp[5] = c.size[2];
                outp[6] = c.size[1];
                outp[7] = 0.0f;

                for (int rr = 0; rr < 3; ++rr) {   // engine-axes rotation rows
                    outp[8 + rr * 4 + 0] = c.rot[rr * 3 + 0];
                    outp[8 + rr * 4 + 1] = c.rot[rr * 3 + 1];
                    outp[8 + rr * 4 + 2] = c.rot[rr * 3 + 2];
                    outp[8 + rr * 4 + 3] = 0.0f;
                }

                outp += 20;
            }

            ctx->Unmap(g_res.sun_instance_vb, 0);
            filled = true;
        }

        ConstantData khsd_obj = {};   // zeroed object slice (unread by VSSunDepth)

        if (filled && khsd_frame_ok && kh_upload_obj_cb(ctx, g_res.composite_cb, khsd_obj)) {

            ID3D11Buffer* vbs[2] = { nullptr, g_res.sun_instance_vb };
            UINT strides[2] = { sizeof(MeshVertex), sizeof(float) * 20 };
            UINT offsets[2] = { 0, 0 };
            size_t first = 0;

            while (first < casters.size()) {
                const int mid = casters[first].mesh;
                size_t last = first + 1;
                while (last < casters.size() && casters[last].mesh == mid) ++last;
                vbs[0] = g_res.mesh_vb[mid];
                ctx->IASetVertexBuffers(0, 2, vbs, strides, offsets);
                // KH_SHADOW_LOD twin - the mask cast is a casting pass
                // exactly as the sun depth is. Mode 422 restores level 0.
                UINT khmc_ls = 0, khmc_lc = 0;
                mesh_shadow_range(mid, khmc_ls, khmc_lc);
                ctx->DrawInstanced(khmc_lc,
                                   static_cast<UINT>(last - first), khmc_ls,
                                   static_cast<UINT>(first));
                g_stats.sun_depth_casters += last - first;
                first = last;
            }
        }
    } else {
        // Per-caster fallback (instancing unavailable): one constant upload +
        // draw each - correct at any count, just not cheap.
        UINT stride = sizeof(MeshVertex), offset = 0;
        int bound_mesh = -1;

        for (const auto& c : casters) {
            if (c.mesh != bound_mesh) {
                ctx->IASetVertexBuffers(0, 1, &g_res.mesh_vb[c.mesh], &stride, &offset);
                bound_mesh = c.mesh;
            }

            if (!khsd_frame_ok) break;
            ConstantData cbd = {};
            cbd.center_size[0] = c.pos[0];
            cbd.center_size[1] = c.pos[2];   // SQF [x,y,zASL] -> engine [x,zASL,y]
            cbd.center_size[2] = c.pos[1];
            cbd.size_axes[0] = c.size[0];   // SQF [x,y,z] sizes -> engine [x,z,y]
            cbd.size_axes[1] = c.size[2];
            cbd.size_axes[2] = c.size[1];

            kh_fill_obj_rot(cbd, c.rot);   // object rotation (VSMain path)
            if (!kh_upload_obj_cb(ctx, g_res.composite_cb, cbd)) break;   // CB SPLIT: object slice
            // KH_SHADOW_LOD: the per-caster fallback takes the same level as
            // the instanced path, or the two disagree on silhouette.
            UINT khsf_ls = 0, khsf_lc = 0;
            mesh_shadow_range(c.mesh, khsf_ls, khsf_lc);
            ctx->Draw(khsf_lc, khsf_ls);
            g_stats.sun_depth_casters++;
        }
    }

    // Nested backup inside the union envelope is harmless and removes the
    // whole state-assumption class.
    khsh_render_cams(true);

    ctx->OMSetRenderTargets(4, old_rtvs, old_dsv);
    if (old_nvp > 0) ctx->RSSetViewports(old_nvp, old_vps);
    ctx->IASetVertexBuffers(1, 1, &old_vb1, &old_vb1_stride, &old_vb1_offset);
    KH_SAFE_RELEASE(old_vb1);
    backup.restore(ctx);

    for (int r4 = 0; r4 < 4; ++r4) KH_SAFE_RELEASE(old_rtvs[r4]);

    KH_SAFE_RELEASE(old_dsv);
    g_ro.in_injection = prev_inj;

    // Locality export: EVERY in-map caster for the fire's per-pixel reach
    // test (engine axes; no count cap - <=16 rides the CB list, more ride the
    // t2 structured-buffer twin at the fire).
    g_sun_locals.clear();

    for (const auto& c : casters) {
        const size_t khsl_b = g_sun_locals.size();
        g_sun_locals.resize(khsl_b + 6);
        float* lb = g_sun_locals.data() + khsl_b;
        lb[0] = c.pos[0];
        lb[1] = c.pos[2];   // SQF -> engine axes
        lb[2] = c.pos[1];
        const float hl[3] = { c.size[0] * 0.5f, c.size[2] * 0.5f, c.size[1] * 0.5f };
        kh_rot_half_extents(hl, c.rot, c.rotated, lb + 3);   // enclosing (rotation-safe)
    }

    g_sun_local_count = static_cast<int>(casters.size());

    memcpy(g_sun_map_vp, lvp, sizeof(g_sun_map_vp));
    {   // extent lanes, ED (catalog): lvp is
        // The column NORMS of the upper 3x3 are basis-free: |col0| = |col1| =
        // 1/R, |col2| = 1/D, because the view basis is orthonormal.
        const float khsn0 = sqrtf(lvp[0][0]*lvp[0][0] + lvp[1][0]*lvp[1][0] + lvp[2][0]*lvp[2][0]);
        const float khsn1 = sqrtf(lvp[0][1]*lvp[0][1] + lvp[1][1]*lvp[1][1] + lvp[2][1]*lvp[2][1]);
        const float khsn2 = sqrtf(lvp[0][2]*lvp[0][2] + lvp[1][2]*lvp[1][2] + lvp[2][2]*lvp[2][2]);
        g_kh_sunvp_span[0] = khsn0 > 1e-12f ? 2.0f / khsn0 : -1.0f;
        g_kh_sunvp_span[1] = khsn1 > 1e-12f ? 2.0f / khsn1 : -1.0f;
        g_kh_sunvp_span[2] = khsn2 > 1e-12f ? 1.0f / khsn2 : -1.0f;
        g_kh_sunvp_latches++;
    }
    memcpy(g_sun_map_anchor, g_sun_anchor_now, sizeof(g_sun_map_anchor));
    g_sun_map_hash = input_hash;   // commit-on-success only (see the skip above)
    g_sun_map_bias = bias_world / D;
    g_sun_map_bounds[0] = ctr[0];
    g_sun_map_bounds[1] = ctr[1];
    g_sun_map_bounds[2] = ctr[2];
    g_sun_map_bounds[3] = hf[0];
    g_sun_map_bounds[4] = hf[1];
    g_sun_map_bounds[5] = hf[2];
    g_sun_map_valid = true;
    g_sun_map_time = effect_time_seconds();

    // A sub-settle sun wobble re-renders the map (float-exact hash) but must
    // not de-mature it. MATURITY COMMIT: reset the presence-test clock only
    // when the render was driven by a SIGNIFICANT input change - the caster
    // set moved/changed, or the sun swung > 0.5 deg since the reference.
    {
        const float khsm_dot = sun[0] * g_sun_mat_sun[0] +
                               sun[1] * g_sun_mat_sun[1] +
                               sun[2] * g_sun_mat_sun[2];

        {
            const bool khsm_new = g_sun_map_render_time < 0.0f;
            const bool khsm_cchg = khsm_caster_hash != g_sun_mat_chash;
            const bool khsm_big = khsm_dot < 0.99862953f;   // cos(3 deg)
            const bool khsm_drift = khsm_dot < 0.99996192f;   // cos(0.5 deg)
            const bool khsm_calm = khsm_drift && !khsm_big && kh_sky_static();

            // The roll already covers a sub-3-degree sun drift that arrives
            // while the sky witness is static: the map re-rendered correctly
            // at every step, so it is proven wobble and must not disarm the
            // far-plane presence test.
            const bool khsm_ccalm = khsm_cchg && !khsm_new && !khsm_big &&
                                    !khsm_drift && kh_sky_static() &&
                                    g_dbg_mode.load(std::memory_order_relaxed) != 46;

            if (khsm_new || (khsm_cchg && !khsm_ccalm) || khsm_big ||
                (khsm_drift && !khsm_calm)) {
                if (khsm_new) g_sun_mat_dem_new++;
                else if (khsm_cchg) g_sun_mat_dem_cchg++;
                else if (khsm_big) g_sun_mat_dem_big++;
                else g_sun_mat_dem_drift++;

                g_sun_map_render_time = g_sun_map_time;
                g_sun_mat_chash = khsm_caster_hash;
                g_sun_mat_sun[0] = sun[0];
                g_sun_mat_sun[1] = sun[1];
                g_sun_mat_sun[2] = sun[2];
            } else if (khsm_calm || khsm_ccalm) {
                g_sun_mat_chash = khsm_caster_hash;   // roll the caster
                g_sun_mat_sun[0] = sun[0];   // set too (a no-op when)
                g_sun_mat_sun[1] = sun[1];   // only the sun moved)
                g_sun_mat_sun[2] = sun[2];
                if (khsm_ccalm) g_sun_mat_caster_rolls++;
                else g_sun_mat_calm_rolls++;
            }
        }
    }

    g_stats.sun_depth_passes++;
    return true;
}

// (2) The engine's ~10 view uploads per frame carry EVOLVING rotations (the
// sim advances mid-frame; compositeAmbiguous ~70% is this phenomenon) - same
// frame is not same rotation; any pairing must key on recent-exact windows,
// never instant equality.
// KH_CAST_OCC (26742): the caster-occupancy grid.
//
// PSMaskCast's reach test answers one question - "is this reconstructed world
// point within reach of ANY caster" - and answered it by looping every caster
// per pixel. That is O(casters x pixels), and it was the whole performance
// problem: 301 props cost ~75 ms/frame while the actual shadow lookup
// (SunShadowOcclusion) was already O(1) tier samples. Vanilla shadows
// thousands of objects cheaply for exactly this reason - only this GATE
// scaled with caster count.
//
// The grid is KH_OCC_N x KH_OCC_N over the casters' world XZ bounds. Each
// texel holds (minY, maxY) across every caster whose reach volume covers that
// column; empty texels hold (+big, -big) so the compare fails. The shader
// does one Load and one Y-range compare - constant time in the caster count.
//
// CONSERVATIVE BY CONSTRUCTION: each caster is splatted over the full XZ and
// Y extent of its reach volume, using the shader's own reach formula, so the
// grid is a strict SUPERSET of the rounded-box test it replaces. It can never
// refuse a point the loop admitted, so no shadow can be lost. It admits ~9%
// extra points (the corners the rounded test trimmed); there
// SunShadowOcclusion returns the authoritative verdict, as it does anywhere
// else. The garbage-depth defence the gate was built for is khcNearOk, which
// is untouched. Verified against the original test over 800k samples at 301
// and 1200 casters: zero dropped. Mode 474 = KH_CAST_OCC_OFF (the per-pixel
// scan, for A/B).
static constexpr int KH_OCC_N = 256;
// KH_CAST_OCC_SYQ (26760): buckets per unit of sin-elevation for the reuse
// key - 1/64 is ~0.9 deg at the horizon, coarser overhead where reach barely
// moves. See the quantisation note in kh_cast_occ_build.
static constexpr float KH_OCC_SY_Q = 64.0f;
static uint64_t g_castocc_builds = 0;
static uint64_t g_castocc_falls = 0;
static uint64_t g_castocc_cells = 0;   // occupied texels, summed over builds
// KH_CAST_OCC_ONCE (26759): the grid depends only on the caster set, the sun
// elevation and the two arms, none of which move between the ~9 fires of one
// frame - and the caster set moves only when render_sun_depth commits. The
// build (a 128 KB splat + a 512 KB dynamic upload) therefore runs once per
// change, and a fire whose inputs match the last build re-arms the CB lanes
// from the retained origin / cell and reuses the bound texture. The texture
// itself is the validity witness: a device reset nulls it and forces a
// rebuild, so no reset hook is needed. castOccReuses counts the reuses;
// castOccBuilds keeps counting real builds, so a healthy dump reads
// castOccBuilds << castOccReuses.
static uint64_t g_castocc_reuses = 0;
static uint64_t g_castocc_key = 0;   // FNV-1a over the last built inputs (0 = none)
static float    g_castocc_lo[2] = {};   // retained grid origin XZ (engine axes)
static float    g_castocc_inv = 0.0f;   // retained 1 / cell
inline bool kh_cast_occ_build(ID3D11DeviceContext* khco_ctx, ConstantData& khco_cb) {
    if (g_dbg_mode.load(std::memory_order_relaxed) == 474) return false;
    const int khco_n = static_cast<int>(khco_cb.locality_meta[0]);
    if (khco_n <= 0 || static_cast<size_t>(khco_n) * 6u > g_sun_locals.size()) return false;
    const float khco_sy = fabsf(khco_cb.cast_view[2][1]);
    // KH_CAST_OCC_SYQ (26760): 26759 keyed the grid on sy EXACT, so a sun
    // that advances every frame (time acceleration, any skipTime-driven day)
    // rebuilt once per frame - castOccBuilds ~ flushes, the 26759 handoff's
    // own open item. The superset argument only needs the build's stretch >=
    // the shader's, and stretch = 2 + 3 / max(sy, 0.15) is DECREASING in sy:
    // a sy quantised DOWNWARD (floor to a 1/KH_OCC_SY_Q bucket) therefore
    // yields a reach >= the exact one for every fire inside the bucket. Every
    // reach and extent below is computed from khco_syq; the shader's
    // castView[2].y stays exact. One rebuild per bucket crossing.
    const float khco_syq = floorf(khco_sy * KH_OCC_SY_Q) / KH_OCC_SY_Q;
    {   // KH_CAST_OCC_ONCE: same inputs as the last build -> reuse it.
        const int32_t khco_mode = g_dbg_mode.load(std::memory_order_relaxed);
        uint64_t khco_k = CryptoGenerator::fnv1a64_raw(g_sun_locals.data(),
                                                       static_cast<size_t>(khco_n) * 6u * sizeof(float));
        khco_k = CryptoGenerator::fnv1a64_update(khco_k, &khco_syq, sizeof(khco_syq));
        khco_k = CryptoGenerator::fnv1a64_update(khco_k, &khco_mode, sizeof(khco_mode));
        if (khco_k == 0) khco_k = 1;   // 0 is the empty sentinel
        if (g_res.castocc_tex && g_res.castocc_srv && khco_k == g_castocc_key) {
            khco_cb.cast_mat[0][3] = g_castocc_inv;   // armed (> 0) - lane note at the build tail
            khco_cb.cast_mat[1][3] = g_castocc_lo[0];
            khco_cb.cast_mat[2][3] = g_castocc_lo[1];
            g_castocc_reuses++;
            return true;
        }
        g_castocc_key = khco_k;   // provisional; cleared below on any failure
    }
    // KH_CAST_REACH_X4 (mode 479): the gate admits a pixel only within
    // reach = min(|he| * stretch, max(600, |he| * 24)) of a caster, so a
    // shadow longer than that is refused at a hard radius - which on screen
    // reads as a straight, arbitrary slice through one mesh's shadow with no
    // relation to geometry. That matches the remaining VR symptom, and it is
    // NOT something 474 could test: the O(N) loop it restores uses this same
    // formula. This multiplies the reach so the boundary moves; if the slice
    // moves out or disappears, the reach is the cause and the fix is to
    // derive it from the sun tier's actual coverage instead of a per-caster
    // heuristic. Diagnostic only - it widens the gate, costing fill.
    const float khco_reach_x =
        (g_dbg_mode.load(std::memory_order_relaxed) == 479) ? 4.0f : 1.0f;
    const float khco_stretch = 2.0f + 3.0f / (khco_syq > 0.15f ? khco_syq : 0.15f);

    float khco_lo[2] = { 1.0e30f, 1.0e30f };
    float khco_hi[2] = { -1.0e30f, -1.0e30f };
    static std::vector<float> khco_r;   // per caster reach (render-thread scratch)
    khco_r.assign(static_cast<size_t>(khco_n), 0.0f);
    for (int i = 0; i < khco_n; ++i) {
        const float* e = g_sun_locals.data() + static_cast<size_t>(i) * 6u;
        const float khco_he = sqrtf(e[3] * e[3] + e[4] * e[4] + e[5] * e[5]);
        const float khco_cap = 600.0f > khco_he * 24.0f ? 600.0f : khco_he * 24.0f;
        khco_r[i] = (khco_he * khco_stretch < khco_cap ? khco_he * khco_stretch : khco_cap) * khco_reach_x;
        const float khco_ex = e[3] + khco_r[i];
        const float khco_ez = e[5] + khco_r[i];
        if (e[0] - khco_ex < khco_lo[0]) khco_lo[0] = e[0] - khco_ex;
        if (e[2] - khco_ez < khco_lo[1]) khco_lo[1] = e[2] - khco_ez;
        if (e[0] + khco_ex > khco_hi[0]) khco_hi[0] = e[0] + khco_ex;
        if (e[2] + khco_ez > khco_hi[1]) khco_hi[1] = e[2] + khco_ez;
    }
    const float khco_sp0 = khco_hi[0] - khco_lo[0];
    const float khco_sp1 = khco_hi[1] - khco_lo[1];
    if (!(khco_sp0 > 0.0f) || !(khco_sp1 > 0.0f)) { g_castocc_key = 0; return false; }
    float khco_cell = (khco_sp0 > khco_sp1 ? khco_sp0 : khco_sp1) / KH_OCC_N;
    if (!(khco_cell > 1.0e-4f)) khco_cell = 1.0e-4f;
    const float khco_inv = 1.0f / khco_cell;

    static std::vector<float> khco_grid;   // (minY, maxY) per texel
    khco_grid.resize(static_cast<size_t>(KH_OCC_N) * KH_OCC_N * 2u);
    for (size_t g = 0; g < khco_grid.size(); g += 2) { khco_grid[g] = 1.0e30f; khco_grid[g + 1] = -1.0e30f; }
    for (int i = 0; i < khco_n; ++i) {
        const float* e = g_sun_locals.data() + static_cast<size_t>(i) * 6u;
        const float khco_rr = khco_r[i];
        int khco_x0 = static_cast<int>(floorf((e[0] - e[3] - khco_rr - khco_lo[0]) * khco_inv));
        int khco_x1 = static_cast<int>(floorf((e[0] + e[3] + khco_rr - khco_lo[0]) * khco_inv));
        int khco_z0 = static_cast<int>(floorf((e[2] - e[5] - khco_rr - khco_lo[1]) * khco_inv));
        int khco_z1 = static_cast<int>(floorf((e[2] + e[5] + khco_rr - khco_lo[1]) * khco_inv));
        if (khco_x0 < 0) khco_x0 = 0;
        if (khco_z0 < 0) khco_z0 = 0;
        if (khco_x1 > KH_OCC_N - 1) khco_x1 = KH_OCC_N - 1;
        if (khco_z1 > KH_OCC_N - 1) khco_z1 = KH_OCC_N - 1;
        const float khco_y0 = e[1] - e[4] - khco_rr;
        const float khco_y1 = e[1] + e[4] + khco_rr;
        for (int z = khco_z0; z <= khco_z1; ++z) {
            float* khco_row = khco_grid.data() + (static_cast<size_t>(z) * KH_OCC_N) * 2u;
            for (int x = khco_x0; x <= khco_x1; ++x) {
                if (khco_y0 < khco_row[x * 2]) khco_row[x * 2] = khco_y0;
                if (khco_y1 > khco_row[x * 2 + 1]) khco_row[x * 2 + 1] = khco_y1;
            }
        }
    }

    if (!g_res.castocc_tex) {
        ID3D11Device* khco_dev = nullptr;
        khco_ctx->GetDevice(&khco_dev);
        if (!khco_dev) { g_castocc_key = 0; return false; }
        D3D11_TEXTURE2D_DESC khco_td = {};
        khco_td.Width = KH_OCC_N;
        khco_td.Height = KH_OCC_N;
        khco_td.MipLevels = 1;
        khco_td.ArraySize = 1;
        khco_td.Format = DXGI_FORMAT_R32G32_FLOAT;
        khco_td.SampleDesc.Count = 1;
        khco_td.Usage = D3D11_USAGE_DYNAMIC;
        khco_td.BindFlags = D3D11_BIND_SHADER_RESOURCE;
        khco_td.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
        const bool khco_ok =
            SUCCEEDED(khco_dev->CreateTexture2D(&khco_td, nullptr, &g_res.castocc_tex)) &&
            SUCCEEDED(khco_dev->CreateShaderResourceView(g_res.castocc_tex, nullptr, &g_res.castocc_srv));
        if (!khco_ok) { KH_SAFE_RELEASE(g_res.castocc_srv); KH_SAFE_RELEASE(g_res.castocc_tex); }
        khco_dev->Release();
        if (!g_res.castocc_srv) { g_castocc_key = 0; return false; }
    }
    D3D11_MAPPED_SUBRESOURCE khco_m = {};
    if (FAILED(khco_ctx->Map(g_res.castocc_tex, 0, D3D11_MAP_WRITE_DISCARD, 0, &khco_m))) { g_castocc_key = 0; return false; }
    for (int z = 0; z < KH_OCC_N; ++z) {
        memcpy(static_cast<uint8_t*>(khco_m.pData) + static_cast<size_t>(z) * khco_m.RowPitch,
               khco_grid.data() + static_cast<size_t>(z) * KH_OCC_N * 2u,
               static_cast<size_t>(KH_OCC_N) * 2u * sizeof(float));
    }
    khco_ctx->Unmap(g_res.castocc_tex, 0);

    uint64_t khco_used = 0;
    for (size_t g = 0; g < khco_grid.size(); g += 2) if (khco_grid[g + 1] >= khco_grid[g]) khco_used++;
    g_castocc_cells += khco_used;
    g_castocc_builds++;
    // LANES (26759 correction): castMat[0].w = 1/cell, and armed IS > 0;
    // castMat[1].w / castMat[2].w = grid origin XZ. Three lanes that were
    // never written, so the CB layout and its mirror tripwire are untouched.
    // 26758 carried 1/cell in castView[2].w - but that lane is the CAST
    // STRENGTH (mask_cast_engine writes g_shadow_map_strength there and the
    // fire-clamp ladder zeroes it to suppress a fire; PSMaskCast's shade is
    // 1 - hit * saturate(castView[2].w)). Writing it here after those fills
    // replaced the strength with saturate(1/cell) and un-suppressed every
    // clamped fire whenever the grid armed. castView[2].w is no longer
    // touched by this function.
    khco_cb.cast_mat[0][3] = khco_inv;
    khco_cb.cast_mat[1][3] = khco_lo[0];
    khco_cb.cast_mat[2][3] = khco_lo[1];
    g_castocc_lo[0] = khco_lo[0];
    g_castocc_lo[1] = khco_lo[1];
    g_castocc_inv = khco_inv;
    return true;
}

inline bool kh_upload_locality_ext(ID3D11DeviceContext* ctx) {
    const UINT khle_n = static_cast<UINT>(g_sun_locals.size() / 6);
    if (khle_n == 0) return false;

    if (khle_n > g_res.locality_cap || !g_res.locality_buf) {
        ID3D11Device* khle_dev = nullptr;
        ctx->GetDevice(&khle_dev);
        if (!khle_dev) return false;
        KH_SAFE_RELEASE(g_res.locality_srv);
        KH_SAFE_RELEASE(g_res.locality_buf);
        g_res.locality_cap = 0;
        UINT khle_cap = 64;
        while (khle_cap < khle_n) khle_cap *= 2;
        D3D11_BUFFER_DESC bd = {};
        bd.ByteWidth = khle_cap * 2 * sizeof(float) * 4;
        bd.Usage = D3D11_USAGE_DYNAMIC;
        bd.BindFlags = D3D11_BIND_SHADER_RESOURCE;
        bd.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
        bd.MiscFlags = D3D11_RESOURCE_MISC_BUFFER_STRUCTURED;
        bd.StructureByteStride = sizeof(float) * 4;
        const bool khle_ok =
            SUCCEEDED(khle_dev->CreateBuffer(&bd, nullptr, &g_res.locality_buf));
        D3D11_SHADER_RESOURCE_VIEW_DESC sd = {};
        sd.Format = DXGI_FORMAT_UNKNOWN;
        sd.ViewDimension = D3D11_SRV_DIMENSION_BUFFER;
        sd.Buffer.NumElements = khle_cap * 2;
        if (khle_ok &&
            SUCCEEDED(khle_dev->CreateShaderResourceView(g_res.locality_buf, &sd,
                                                         &g_res.locality_srv))) {
            g_res.locality_cap = khle_cap;
        } else {
            KH_SAFE_RELEASE(g_res.locality_srv);
            KH_SAFE_RELEASE(g_res.locality_buf);
        }
        khle_dev->Release();
        if (g_res.locality_cap == 0) return false;
    }

    D3D11_MAPPED_SUBRESOURCE khle_m = {};
    if (FAILED(ctx->Map(g_res.locality_buf, 0, D3D11_MAP_WRITE_DISCARD, 0, &khle_m))) return false;
    float* khle_d = static_cast<float*>(khle_m.pData);

    for (UINT i = 0; i < khle_n; ++i) {
        const float* lb = g_sun_locals.data() + static_cast<size_t>(i) * 6;
        khle_d[i * 8 + 0] = lb[0]; khle_d[i * 8 + 1] = lb[1];
        khle_d[i * 8 + 2] = lb[2]; khle_d[i * 8 + 3] = 0.0f;
        khle_d[i * 8 + 4] = lb[3]; khle_d[i * 8 + 5] = lb[4];
        khle_d[i * 8 + 6] = lb[5]; khle_d[i * 8 + 7] = 0.0f;
    }

    ctx->Unmap(g_res.locality_buf, 0);
    return true;
}

// Near-vertical looks fall back to the UP vector's heading, which yaw still
// swings; a fully degenerate pair reports no yaw evidence (dot 1) and leaves
// the translation term in charge. Both matrices are the world-space camera
// basis rows the freeze already relies on ([4..6] up, [8..10] forward).
inline float kh_epoch_yaw_dot(const float* khyd_a, const float* khyd_b) {
    float khyd_ax = khyd_a[8];
    float khyd_az = khyd_a[10];
    float khyd_bx = khyd_b[8];
    float khyd_bz = khyd_b[10];

    if (khyd_ax * khyd_ax + khyd_az * khyd_az < 0.04f) {   // near-vertical look
        khyd_ax = khyd_a[4]; khyd_az = khyd_a[6];
        khyd_bx = khyd_b[4]; khyd_bz = khyd_b[6];
    }

    const float khyd_na = sqrtf(khyd_ax * khyd_ax + khyd_az * khyd_az);
    const float khyd_nb = sqrtf(khyd_bx * khyd_bx + khyd_bz * khyd_bz);
    if (khyd_na < 1e-5f || khyd_nb < 1e-5f) return 1.0f;   // degenerate: no yaw evidence
    float khyd_d = (khyd_ax * khyd_bx + khyd_az * khyd_bz) / (khyd_na * khyd_nb);
    return khyd_d > 1.0f ? 1.0f : (khyd_d < -1.0f ? -1.0f : khyd_d);
}

// We do not have that camera, but we have this frame's and the last one's,
// and a one-frame linear advance is what every reprojection scheme in the
// industry uses for the same reason. ONE-FRAME CAMERA EXTRAPOLATION
// (setRenderDebug 28). at the sweeps, which for this frame run at draws
// 2504-3439 and have not happened yet.
inline bool kh_extrapolate_view(const float* khx_base, float* khx_out) {
    if (!g_ls.frame_view_valid || !g_ls.prev_view_valid || !khx_base) return false;
    const float* khx_c = g_ls.frame_view;
    const float* khx_p = g_ls.prev_view;
    float khx_d[9];

    for (int r = 0; r < 3; ++r) {
        for (int c = 0; c < 3; ++c) {
            float khx_s = 0.0f;

            for (int k = 0; k < 3; ++k) khx_s += khx_c[r * 4 + k] * khx_p[c * 4 + k];

            khx_d[r * 3 + c] = khx_s;
        }
    }

    // advance the BASE the freeze actually adopted (the bridge view), not
    // frame_view - the two agree to millimetres but only one of them is what
    // the paint is placed with.
    memcpy(khx_out, khx_base, sizeof(float) * 16);

    for (int r = 0; r < 3; ++r) {
        for (int c = 0; c < 3; ++c) {
            float khx_s = 0.0f;

            for (int k = 0; k < 3; ++k) khx_s += khx_d[r * 3 + k] * khx_base[k * 4 + c];

            khx_out[r * 4 + c] = khx_s;
        }
    }

    float khx_cc[3];
    float khx_pc[3];
    float khx_bc[3];
    extract_camera_pos(reinterpret_cast<const float(*)[4]>(khx_c), khx_cc);
    extract_camera_pos(reinterpret_cast<const float(*)[4]>(khx_p), khx_pc);
    extract_camera_pos(reinterpret_cast<const float(*)[4]>(khx_base), khx_bc);
    const double khx_n[3] = {
        static_cast<double>(khx_bc[0]) + static_cast<double>(khx_cc[0] - khx_pc[0]),
        static_cast<double>(khx_bc[1]) + static_cast<double>(khx_cc[1] - khx_pc[1]),
        static_cast<double>(khx_bc[2]) + static_cast<double>(khx_cc[2] - khx_pc[2]),
    };

    for (int c = 0; c < 3; ++c) {
        khx_out[12 + c] = static_cast<float>(
            -(khx_n[0] * static_cast<double>(khx_out[0 * 4 + c]) +
              khx_n[1] * static_cast<double>(khx_out[1 * 4 + c]) +
              khx_n[2] * static_cast<double>(khx_out[2 * 4 + c])));
    }

    khx_out[15] = 1.0f;
    return true;
}

inline void mask_cast_engine(ID3D11DeviceContext* ctx) {
    // OWNERSHIP TEST (setRenderDebug 20): the analytic cast stands down
    // entirely. If the camera-tracking ghost SURVIVES this, it is not our
    // cast - it is engine screen-space content reprojecting our
    // motion-vector-less depth writes, and the fix moves to the injection
    // side, not the cast.
    if (g_dbg_mode.load(std::memory_order_relaxed) == 20) return;

    // Baseline resolve-keyed re-fires are restored VERBATIM; do not gate this
    // cadence again without new capture-level evidence. starved the fire on
    // look-down frames. Baseline semantics restored.").

    if (!ctx) return;

    // Placed here, at the top of the per-draw fire, so it cannot run at the
    // frame boundary - the partitioned-frame overcast is the one real
    // objection and that is where it lived. Every guard below is untouched;
    // this only removes the wait for a publish whose data the freeze discards
    // anyway.
    if (!g_mask_cast_fired && !g_mask_cast_arm &&
        g_dbg_mode.load(std::memory_order_relaxed) != 43 &&
        g_ro.cycle_pv_valid && !g_ro.cycle_pv_stale && !g_ls.phase_on_atlas) {
        g_mask_cast_arm = true;
        g_cast_bridge_arms++;
        if (!g_ls.view_published_this_frame) g_cast_bridge_first++;
    }

    if (g_mask_cast_arm && !g_mask_cast_fired) {
        g_ls.cast_misses = 1;
    } else if (!g_mask_cast_arm && !g_mask_cast_fired) {
        g_ls.cast_misses = 2;   // never armed this cycle
    }

    if (g_mask.cold_t0 >= 0.0 && g_mask.cold_first_cast < 0.0f && g_ls.cast_misses != 0) {
        g_mask.cold_cast_miss = g_ls.cast_misses;   // sticky while cold
    }
    if (g_mask_cast_fired && g_ls.resolve_seen_since_cast && g_ls.frame_view_valid) {
        // Evidence predating a cascade phase is cleared at atlas entry; a
        // mid-frame atlas re-entry re-earns its evidence at its own resolves,
        // so legitimate per-batch re-firing is untouched.
        if (g_ls.phase_on_atlas) {
            g_cast_rearm_atlas_blocks++;
        } else {
            // (stood the per-batch re-fire down under dbg 23, for the
            // SRV-keyed arm.
            g_mask_cast_arm = true;
            g_mask_cast_fired = false;
            g_mask.cast_batches++;
        }
    }

    if (!g_mask_cast_arm || g_mask_cast_fired) return;
    g_ls.resolve_seen_since_cast = false;
    if (!g_res.initialized || !g_res.ps_maskcast || !g_res.vs_fullscreen || !g_res.composite_cb) { g_ls.cast_misses = 3; return; }
    if (!g_mask.cast_depth) { g_ls.cast_misses = 41; return; }
    if (!g_mask.cast_fov_valid) { g_ls.cast_misses = 42; return; }
    if (g_mask.engine_mask_failed) { g_ls.cast_misses = 43; return; }
    if (!g_ls.frame_view_valid) { g_ls.cast_misses = 5; return; }

    // (A miss-56 timestamp epoch gate lived here for one build and is
    // REMOVED: the view CB re-uploads ~164x/frame, so a timestamp can never
    // carry epoch identity, and the hold starved cold arms.

    // On a session that never reaches exact quality, the cast simply never
    // fires - by directive.
    if (g_ls.pub_exact_ms == 0 ||
        steady_now_ms() - g_ls.pub_exact_ms > 250) { g_ls.cast_misses = 51; return; }
    // Transition hold: fire only into a SETTLED capture stream (see the
    // sweep_settle note). Steady state saturates this within one frame.
    if (g_mask.sweep_settle < g_mask.sweep_need) { g_ls.cast_misses = 52; return; }
    // Absent beats swinging: hold until the publish arbiter reports the
    // direction stable.
    if (!kh_sun_settled()) {
        g_ls.cast_misses = 53;
        if (g_cast_ready) g_cast_ready_drops++;
        g_cast_ready = false;
        g_cast_ready_since_ms = 0;   // readiness dwell restarts after the sun re-settles
        return;
    }
    // The fire now waits for the debounced published direction; the fallback
    // line in the freeze is retained inert (fsun can no longer be null
    // there).
    if (!kh_shadow_sun()) {
        g_ls.cast_misses = 54;
        if (g_cast_ready) g_cast_ready_drops++;
        g_cast_ready = false;
        g_cast_ready_since_ms = 0;
        return;
    }
    // Absent beats swinging (the sun-settle gate's own doctrine); at a
    // healthy cold this adds at most 1 s to a first cast already 8-10 s out
    // (the churn clock and the cold pipeline run concurrently), and a settled
    // steady state never stamps.
    if (g_dbg_mode.load(std::memory_order_relaxed) != 26 &&
        g_lock_churn_ms_v != 0 &&
        steady_now_ms() - g_lock_churn_ms_v < 1000) {
        g_ls.cast_misses = 55;
        g_cast_lock_settle_holds++;
        return;
    }

    // Two cold/mid-session artifact classes survived the per-condition ladder
    // above because each gate releases the instant its own condition clears,
    // while the SYSTEM is still converging: (1) the depth-structured
    // wrong-sun cast - buildings appearing in the darkening, sliding with the
    // camera - fires through the glide that follows a derived-sun SNAP (43
    // confirmed snaps in the last field session, 6.8 deg, 13 s in: nothing
    // above holds for those); (2) the RECTANGLE (the 'cut-off shadow') - the
    // AABB slab fallback firing whenever the private sun map is stale,
    // indistinguishable from a warm-up state by design.
    if (g_dbg_mode.load(std::memory_order_relaxed) != 21) {
        const uint64_t khcr_now = steady_now_ms();
        // castReadyHolds counts both branches below and therefore cannot say
        // which one is standing, let alone which term.
        const bool khcr_q_churn =
            (g_lock_churn_ms_v == 0 || khcr_now - g_lock_churn_ms_v >= KH_CAST_READY_QUIET_MS);
        const bool khcr_q_travel =
            (g_sun_pub_travel_ms == 0 || khcr_now - g_sun_pub_travel_ms >= KH_CAST_READY_QUIET_MS);
        const bool khcr_q_jump =
            (g_sun_last_jump_ms == 0 || khcr_now - g_sun_last_jump_ms >= KH_CAST_READY_QUIET_MS);
        const bool khcr_stable = khcr_q_churn && khcr_q_travel && khcr_q_jump;

        if (!khcr_stable) {
            if (!khcr_q_churn) g_cast_dwell_churn++;
            if (!khcr_q_travel) g_cast_dwell_travel++;
            if (!khcr_q_jump) g_cast_dwell_jump++;
            if (g_cast_ready_since_ms != 0) g_cast_dwell_resets++;
            if (g_cast_ready) g_cast_ready_drops++;
            g_cast_ready = false;
            g_cast_ready_since_ms = 0;
            g_cast_ready_holds++;
            g_ls.cast_misses = 57;
            return;
        }

        if (!g_cast_ready) {
            if (g_cast_ready_since_ms == 0) g_cast_ready_since_ms = khcr_now;

            if (khcr_now - g_cast_ready_since_ms < KH_CAST_READY_DWELL_MS) {
                g_cast_dwell_ticks++;
                g_cast_ready_holds++;
                g_ls.cast_misses = 57;
                return;
            }

            g_cast_ready = true;
            g_cast_ready_ms = khcr_now;
            g_cast_ready_t = static_cast<float>(effect_time_seconds());
        }

        // SLAB RETIREMENT: fire only through a fresh private sun map (same
        // freshness bar the fire body uses). Absent beats a rectangle; the
        // arm survives and the next fresh map fires.
        const bool khcr_map_fresh = g_sun_map_valid &&
                                    g_sun_map_time >= 0.0f &&
                                    effect_time_seconds() - g_sun_map_time < 0.25f;

        if (!khcr_map_fresh) {
            if (g_sun_map_no_local) { g_ls.cast_misses = 81; return; }   // distance rule, not a failure
            g_cast_map_holds++;
            g_ls.cast_misses = 58;
            return;
        }
    }
    g_mask.last_fire_fov[0] = g_mask.cast_fov[0];
    g_mask.last_fire_fov[1] = g_mask.cast_fov[1];
    g_mask.last_fire_dims[0] = g_mask.cast_dims[0];
    g_mask.last_fire_dims[1] = g_mask.cast_dims[1];
    g_mask.last_fire_rot_err = g_ls.last_publish_rot_err;
    if (!g_mask.engine_mask_rtv) { g_ls.cast_misses = 61; return; }   // captured at the gated resolve sweep
    g_fire_epoch_mute = false;   // per-fire; the check below re-raises it

    if (g_fire_lock_valid && g_ls.frame_view_valid &&
        g_dbg_mode.load(std::memory_order_relaxed) != 34) {
        float khep_a[3];
        float khep_b[3];
        extract_camera_pos(reinterpret_cast<const float(*)[4]>(g_ls.frame_view), khep_a);
        extract_camera_pos(reinterpret_cast<const float(*)[4]>(g_fire_view2), khep_b);
        const float khep_dx = khep_a[0] - khep_b[0];
        const float khep_dy = khep_a[1] - khep_b[1];
        const float khep_dz = khep_a[2] - khep_b[2];
        float khep_d = sqrtf(khep_dx * khep_dx + khep_dy * khep_dy + khep_dz * khep_dz);
        const float khep_ybar = 0.9999905f;   // 0.25 deg
        float khep_p9a = g_ls.frame_view[9];
        float khep_p9b = g_fire_view2[9];
        khep_p9a = khep_p9a > 1.0f ? 1.0f : (khep_p9a < -1.0f ? -1.0f : khep_p9a);
        khep_p9b = khep_p9b > 1.0f ? 1.0f : (khep_p9b < -1.0f ? -1.0f : khep_p9b);
        const float khep_pt = fabsf(asinf(khep_p9a) - asinf(khep_p9b));   // pitch delta, rad
        float khep_yd = kh_epoch_yaw_dot(g_ls.frame_view, g_fire_view2);
        bool khep_moved = (khep_yd < khep_ybar ||
                           khep_pt > 0.004363f ||
                           khep_d > 0.012f) &&
                          khep_d < KH_LATCH_JUMP_M;
        bool khep_via_bridge = false;

        // At rest the bridge equals the frozen epoch to sway scale, which the
        // thresholds now clear; under motion it is ahead of every stale
        // replay by construction.
        if (!khep_moved) {
            RVExtBridge::ProjectionViewTransform khep_pv = {};

            if (RVExtBridge::get_projection_view_transform(khep_pv)) {
                float khep_c[3];
                extract_camera_pos(khep_pv.view, khep_c);
                const float khep_bx = khep_c[0] - khep_b[0];
                const float khep_by = khep_c[1] - khep_b[1];
                const float khep_bz = khep_c[2] - khep_b[2];
                const float khep_bd = sqrtf(khep_bx * khep_bx + khep_by * khep_by + khep_bz * khep_bz);
                const float khep_byd = kh_epoch_yaw_dot(&khep_pv.view[0][0], g_fire_view2);
                float khep_q9 = khep_pv.view[2][1];
                khep_q9 = khep_q9 > 1.0f ? 1.0f : (khep_q9 < -1.0f ? -1.0f : khep_q9);
                const float khep_bpt = fabsf(asinf(khep_q9) - asinf(khep_p9b));

                if ((khep_byd < khep_ybar ||
                     khep_bpt > 0.004363f ||
                     khep_bd > 0.012f) && khep_bd < KH_LATCH_JUMP_M) {
                    khep_moved = true;
                    khep_via_bridge = true;
                    khep_d = khep_bd;
                    khep_yd = khep_byd;
                }
            }
        }

        // A moved-epoch re-fire therefore PAINTS at 0.35 strength (fill_frame
        // consumes the flag): full shadow at rest and for same-epoch
        // re-fires, dim-only-while-moving everywhere else, at every distance.
        // Miss 82 is retired with the withhold; fireEpochSkips now counts
        // mutes.
        if (khep_moved) {
            g_fire_epoch_skips++;
            if (khep_via_bridge) g_fire_epoch_skips_bridge++;
            g_fire_epoch_last_m = khep_d;
            g_fire_epoch_last_rot = acosf(khep_yd) * 57.29578f;   // yaw delta, degrees
            // But both fires replay ONE frozen epoch - g_fire_view2 is
            // written only under !g_fire_lock_valid, and re-fires are
            // byte-identical replays by construction - so moving that freeze
            // translates BOTH copies together and can never change the offset
            // BETWEEN them.
            const int khep_m = g_dbg_mode.load(std::memory_order_relaxed);
            // mode 19 consumes the late fire too (last-fire clamp), and is
            // the ONLY mode that lets the re-freeze keep its own epoch.
            const bool khep_late_used = (khep_m == 22 || khep_m == 40 ||
                                         khep_m == 19 || khep_m == 28);
            bool khep_refroze = false;

            if (khep_late_used) {
                // This whole block sits inside if (khep_moved), an
                // INTRA-frame delta test with a 12 mm / 0.25 deg bar, and
                // fireCamDeltaMaxM measures 0.001 m - it essentially never
                // trips. The fresh -epoch variant ghosted in every round that
                // tried it.
                if (khep_m != 19) {
                    memcpy(g_fire_refreeze_view, g_fire_view2, sizeof(g_fire_refreeze_view));
                    g_fire_refreeze_pending = true;
                }

                g_fire_depth_refreshes++;
                // Drop the lock so the freeze block below re-runs at THIS
                // fire's stream position: same continuity and era guards,
                // same ortho inverse, fresh depth.
                if (g_fire_lock) { g_fire_lock->Release(); g_fire_lock = nullptr; }
                g_fire_lock_valid = false;
                g_fire_refreezes++;
                khep_refroze = true;
            }

            g_fire_epoch_mute = !khep_refroze;
        }
    }

    g_ls.cast_misses = 0;
    g_mask_cast_arm = false;
    g_mask_cast_fired = true;

    if (g_mask.cold_t0 >= 0.0 && g_mask.cold_first_cast < 0.0f) {
        g_mask.cold_first_cast = static_cast<float>(effect_time_seconds() - g_mask.cold_t0);
    }

    // On INFRASTRUCTURE failure the legacy AABB slab below carries the frame
    // - never a lost fire. Render (or reuse) this frame's private sun-depth
    // map FIRST: the fire consumes it for mesh-shaped casts.
    const bool map_fresh = g_sun_map_valid &&
                           g_sun_map_time >= 0.0f &&
                           effect_time_seconds() - g_sun_map_time < 0.25f;
    if (!map_fresh && g_sun_map_no_local) { g_ls.cast_misses = 81; return; }
    const bool sun_map = map_fresh;

    if (!g_mask.cast_dss && !g_mask.cast_states_failed) {
        ID3D11Device* dv2 = nullptr;
        ctx->GetDevice(&dv2);

        if (dv2) {
            D3D11_DEPTH_STENCIL_DESC dd2 = {};
            dd2.DepthEnable = FALSE;
            if (FAILED(dv2->CreateDepthStencilState(&dd2, &g_mask.cast_dss))) g_mask.cast_states_failed = true;
            dv2->Release();
        }
    }

    if (!g_mask.min_blend) {
        ID3D11Device* dev = nullptr;
        ctx->GetDevice(&dev);
        if (!dev) { g_mask.engine_mask_failed = true; g_ls.cast_misses = 7; return; }

        if (!g_mask.min_blend) {
            D3D11_BLEND_DESC bd = {};
            bd.RenderTarget[0].BlendEnable = TRUE;
            bd.RenderTarget[0].SrcBlend = D3D11_BLEND_ONE;
            bd.RenderTarget[0].DestBlend = D3D11_BLEND_ONE;
            bd.RenderTarget[0].BlendOp = D3D11_BLEND_OP_MIN;   // darken-only
            bd.RenderTarget[0].SrcBlendAlpha = D3D11_BLEND_ONE;
            bd.RenderTarget[0].DestBlendAlpha = D3D11_BLEND_ONE;
            bd.RenderTarget[0].BlendOpAlpha = D3D11_BLEND_OP_MIN;
            bd.RenderTarget[0].RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_ALL;

            if (FAILED(dev->CreateBlendState(&bd, &g_mask.min_blend))) {
                g_mask.engine_mask_failed = true;
                dev->Release();
                return;
            }
        }

        dev->Release();
    }

    struct CastEntry { float pos[3]; float size[3]; };
    CastEntry centries[64];   // FALLBACK-ONLY cap: the sun-map path is one
                              // fullscreen draw for ANY caster count; only
                              // the per-caster AABB-slab fallback (cold /
                              // map-unavailable frames) pays per object, and
                              // 64 nearest-in-map-order bounds that.
    uint32_t ncb = 0;

    if (!sun_map) {
        std::lock_guard<std::mutex> lk(g_draw_list_mutex);

        for (const auto& kv2 : g_draw_list) {
            if (ncb >= 64) break;
            const auto& o = kv2.second;
            // Casters are world-space meshes only: fullscreen passes carry
            // default pos/size (a phantom 1 m shadow at the map origin),
            // hidden objects must not shadow the world they are hidden from,
            // and overlays (mode 2) never participate in world depth. Effect
            // meshes remain casters - they are real volumes.
            if (o.fullscreen || !o.visible || o.mode == DepthMode::Off) continue;
            memcpy(centries[ncb].pos, o.pos, 12);
            // Slab entries stay SQF-ordered (the fill below swaps); a rotated
            // mesh contributes its ENCLOSING extents so the analytic AABB
            // slab remains conservative.
            float khc_he[3];
            kh_world_half_extents(o, khc_he);   // engine axes
            centries[ncb].size[0] = khc_he[0] * 2.0f;   // > SQF order
            centries[ncb].size[1] = khc_he[2] * 2.0f;
            centries[ncb].size[2] = khc_he[1] * 2.0f;
            ncb++;
        }
    }

    // Map path: a valid sun map implies casters existed this frame (the pass
    // refuses to render without any) - no snapshot needed.
    if (!sun_map && ncb == 0) { g_ls.cast_misses = 8; return; }
    g_ro.in_injection = true;
    ID3D11RenderTargetView* old_rtvs[8] = {};
    ID3D11DepthStencilView* old_dsv = nullptr;
    ID3D11UnorderedAccessView* old_uavs[8] = {};
    ctx->OMGetRenderTargets(8, old_rtvs, &old_dsv);
    ctx->OMGetRenderTargetsAndUnorderedAccessViews(0, nullptr, nullptr, 0, 8, old_uavs);
    int khf_uav_n = 0, khf_uav_lo = 8;

    for (int ui = 0; ui < 8; ++ui) {
        if (old_uavs[ui]) {
            khf_uav_n++;
            if (ui < khf_uav_lo) khf_uav_lo = ui;
        }
    }

    UINT old_nvp = D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE;
    D3D11_VIEWPORT old_vps[D3D11_VIEWPORT_AND_SCISSORRECT_OBJECT_COUNT_PER_PIPELINE] = {};
    ctx->RSGetViewports(&old_nvp, old_vps);
    ID3D11VertexShader* old_vs = nullptr;
    ID3D11PixelShader* old_ps = nullptr;
    ID3D11InputLayout* old_il = nullptr;
    D3D11_PRIMITIVE_TOPOLOGY old_topo = D3D11_PRIMITIVE_TOPOLOGY_UNDEFINED;
    ID3D11Buffer* old_cb = nullptr;
    ID3D11BlendState* old_blend = nullptr;
    FLOAT old_bf[4] = {};
    UINT old_bmask = 0xFFFFFFFF;
    ID3D11DepthStencilState* old_dss = nullptr;
    UINT old_sref = 0;
    ctx->VSGetShader(&old_vs, nullptr, nullptr);
    ctx->PSGetShader(&old_ps, nullptr, nullptr);
    ctx->IAGetInputLayout(&old_il);
    ctx->IAGetPrimitiveTopology(&old_topo);
    // OFFSET-AWARE b0 SAVE - the round-7 root fix: capture the pool offsets
    // the plain getters cannot see. num == 0 marks a non-offset bind
    // (restored with the plain setter, identical to the historical path);
    // ctx1 unavailable degrades to historical.
    UINT old_cb_first = 0, old_cb_num = 0;
    UINT old_vs_cb_first = 0, old_vs_cb_num = 0;
    // CB SPLIT: we bind b1 too now, so the fire's manual save set covers BOTH
    // slots (same offset-aware discipline as b0).
    ID3D11Buffer* old_cb1 = nullptr;
    ID3D11Buffer* old_vs_cb1 = nullptr;
    UINT old_cb1_first = 0, old_cb1_num = 0;
    UINT old_vs_cb1_first = 0, old_vs_cb1_num = 0;
    ID3D11DeviceContext1* khf_ctx1 = nullptr;
    ctx->QueryInterface(__uuidof(ID3D11DeviceContext1), reinterpret_cast<void**>(&khf_ctx1));
    ID3D11Buffer* old_vs_cb = nullptr;

    if (khf_ctx1) {
        khf_ctx1->PSGetConstantBuffers1(0, 1, &old_cb, &old_cb_first, &old_cb_num);
        khf_ctx1->VSGetConstantBuffers1(0, 1, &old_vs_cb, &old_vs_cb_first, &old_vs_cb_num);
        khf_ctx1->PSGetConstantBuffers1(1, 1, &old_cb1, &old_cb1_first, &old_cb1_num);
        khf_ctx1->VSGetConstantBuffers1(1, 1, &old_vs_cb1, &old_vs_cb1_first, &old_vs_cb1_num);

    } else {
        ctx->PSGetConstantBuffers(0, 1, &old_cb);
        ctx->VSGetConstantBuffers(0, 1, &old_vs_cb);   // the fire sets VS b0
        ctx->PSGetConstantBuffers(1, 1, &old_cb1);
        ctx->VSGetConstantBuffers(1, 1, &old_vs_cb1);
    }
    // and never restored it: every engine VERTEX shader after the fire read
    // our mesh cbd as its constants - the last-fired mesh's COLOR tinted all
    // particles (blue, from the fog array). The dual-gated arm exposed it by
    // moving the fire later in the frame, past the engine's last natural
    // VS-b0 rebind before the particle pass.
    ctx->OMGetBlendState(&old_blend, old_bf, &old_bmask);
    ctx->OMGetDepthStencilState(&old_dss, &old_sref);
    // widened 16 -> 28 with the cascade build. Array size IS the save range
    // here too: capture, restore, scan and release all follow.
    ID3D11ShaderResourceView* old_ps_srvs[33] = {};   // +t28; +t32 (far band; t29-31 unbound on this path but saved for width parity)
    ID3D11ShaderResourceView* old_vs_srvs[33] = {};   // widened with the PS table
    ctx->PSGetShaderResources(0, _countof(old_ps_srvs), old_ps_srvs);   // width, not a literal
    ctx->VSGetShaderResources(0, _countof(old_vs_srvs), old_vs_srvs);

    g_fire_mask_srv_now = false;   // per-fire (at the statics)

    if (g_mask.engine_mask_rtv) {
        ID3D11Resource* khf_mask_res = nullptr;
        g_mask.engine_mask_rtv->GetResource(&khf_mask_res);

        if (khf_mask_res) {
            for (int si = 0; si < 66; ++si) {   // 33 slots per stage
                ID3D11ShaderResourceView* sv = si < static_cast<int>(_countof(old_ps_srvs)) ? old_ps_srvs[si]
                                                       : old_vs_srvs[si - 33];
                if (!sv) continue;
                ID3D11Resource* sr = nullptr;
                sv->GetResource(&sr);

                if (sr == khf_mask_res) {
                    g_fire_mask_srv_fires++;
                    g_fire_mask_srv_now = true;
                    g_fire_mask_srv_seen_frame = true;
                    // remember WHERE in the frame the window was.
                    // g_fire_count_frame has not been bumped for this fire
                    // yet, so the index of this fire is +1.
                    {
                        const uint32_t khsi_ix = g_fire_count_frame + 1u;
                        if (g_fire_srv_index != khsi_ix) {
                            g_fire_srv_index = khsi_ix;
                            g_fire_srv_index_moves++;
                        }
                    }
                    g_fire_mask_srv_last = static_cast<uint32_t>(
                        (si < 28 ? 0 : 100) + (si < 28 ? si : si - 28));   // 28-wide
                    if (sr) sr->Release();
                    break;
                }

                if (sr) sr->Release();
            }

            khf_mask_res->Release();
        }
    }
    // The fire draws a fullscreen triangle: a bound GS would route our
    // vertices through a foreign expansion, and an engine rasterizer state
    // with ScissorEnable would clip the MIN write to whatever rect the
    // resolve left behind - both silent partial-cast modes. Saved here,
    // nulled below, restored with the rest.
    ID3D11GeometryShader* old_gs = nullptr;
    ID3D11HullShader* old_hs = nullptr;
    ID3D11DomainShader* old_ds2 = nullptr;
    ID3D11RasterizerState* old_rs = nullptr;
    ID3D11ShaderResourceView* khco_old_t35 = nullptr;   // KH_CAST_OCC: t35 sits past old_ps_srvs[33]
    ctx->PSGetShaderResources(35, 1, &khco_old_t35);
    ctx->GSGetShader(&old_gs, nullptr, nullptr);
    ctx->HSGetShader(&old_hs, nullptr, nullptr);
    ctx->DSGetShader(&old_ds2, nullptr, nullptr);
    ctx->RSGetState(&old_rs);
    ctx->OMSetRenderTargets(1, &g_mask.engine_mask_rtv, nullptr);
    D3D11_VIEWPORT vpn = {};
    vpn.Width = g_mask.cast_dims[0];
    vpn.Height = g_mask.cast_dims[1];
    vpn.MaxDepth = 1.0f;
    ctx->RSSetViewports(1, &vpn);
    ctx->IASetInputLayout(nullptr);
    ctx->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
    ctx->VSSetShader(g_res.vs_fullscreen, nullptr, 0);
    ctx->PSSetShader(g_res.ps_maskcast, nullptr, 0);   // engine linear depth: single-sample
    ctx->GSSetShader(nullptr, nullptr, 0);
    ctx->HSSetShader(nullptr, nullptr, 0);
    ctx->DSSetShader(nullptr, nullptr, 0);
    // The standard SV_VertexID fullscreen triangle is clockwise in
    // render-target space - the default front face - so CullBack never
    // rejects it; DepthClip is moot at z = 0. Default rasterizer: solid fill,
    // scissor OFF.
    ctx->RSSetState(nullptr);
    // CB SPLIT: b0 = per-object, b1 = per-frame; both slices upload per fire
    // below (the ad-hoc backup saves/restores BOTH slots).
    ID3D11Buffer* khmc_cbs[2] = { g_res.composite_cb, g_res.composite_frame_cb };
    ctx->VSSetConstantBuffers(0, 2, khmc_cbs);
    ctx->PSSetConstantBuffers(0, 2, khmc_cbs);
    const FLOAT bfm[4] = { 1.0f, 1.0f, 1.0f, 1.0f };
    ctx->OMSetBlendState(g_mask.min_blend, bfm, 0xFFFFFFFF);
    ctx->OMSetDepthStencilState(g_mask.cast_dss, 0);
    if (!g_fire_lock_valid) {   // frame's first fire: freeze the inputs
        g_fire_snap_live = false;
        if (g_dbg_mode.load(std::memory_order_relaxed) == 33) {
            ID3D11Resource* khsn_res = nullptr;
            ID3D11Texture2D* khsn_src = nullptr;
            g_mask.cast_depth->GetResource(&khsn_res);
            if (khsn_res) khsn_res->QueryInterface(__uuidof(ID3D11Texture2D), reinterpret_cast<void**>(&khsn_src));
            if (khsn_src) {
                D3D11_TEXTURE2D_DESC khsn_sd = {};
                khsn_src->GetDesc(&khsn_sd);

                if (khsn_sd.MipLevels == 1 && khsn_sd.ArraySize == 1 && khsn_sd.SampleDesc.Count == 1) {
                    if (!g_fire_snap_tex || g_fire_snap_w != khsn_sd.Width ||
                        g_fire_snap_h != khsn_sd.Height || g_fire_snap_fmt != khsn_sd.Format) {
                        if (g_fire_snap_srv) { g_fire_snap_srv->Release(); g_fire_snap_srv = nullptr; }
                        if (g_fire_snap_tex) { g_fire_snap_tex->Release(); g_fire_snap_tex = nullptr; }
                        g_fire_snap_w = 0;
                        g_fire_snap_h = 0;
                        g_fire_snap_fmt = DXGI_FORMAT_UNKNOWN;
                        ID3D11Device* khsn_dev = nullptr;
                        ctx->GetDevice(&khsn_dev);

                        if (khsn_dev) {
                            D3D11_TEXTURE2D_DESC khsn_dd = khsn_sd;
                            khsn_dd.Usage = D3D11_USAGE_DEFAULT;
                            khsn_dd.BindFlags = D3D11_BIND_SHADER_RESOURCE;
                            khsn_dd.CPUAccessFlags = 0;
                            khsn_dd.MiscFlags = 0;

                            if (SUCCEEDED(khsn_dev->CreateTexture2D(&khsn_dd, nullptr, &g_fire_snap_tex))) {
                                // Mirror the ENGINE SRV's own view format:
                                // typeless sources need the exact
                                // interpretation the fire already samples.
                                D3D11_SHADER_RESOURCE_VIEW_DESC khsn_vd = {};
                                g_mask.cast_depth->GetDesc(&khsn_vd);
                                D3D11_SHADER_RESOURCE_VIEW_DESC khsn_nd = {};
                                khsn_nd.Format = khsn_vd.Format;
                                khsn_nd.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
                                khsn_nd.Texture2D.MostDetailedMip = 0;
                                khsn_nd.Texture2D.MipLevels = 1;

                                if (SUCCEEDED(khsn_dev->CreateShaderResourceView(g_fire_snap_tex, &khsn_nd, &g_fire_snap_srv))) {
                                    g_fire_snap_w = khsn_sd.Width;
                                    g_fire_snap_h = khsn_sd.Height;
                                    g_fire_snap_fmt = khsn_sd.Format;
                                } else {
                                    g_fire_snap_tex->Release();
                                    g_fire_snap_tex = nullptr;
                                }
                            }

                            khsn_dev->Release();
                        }
                    }

                    if (g_fire_snap_tex && g_fire_snap_srv) {
                        ctx->CopyResource(g_fire_snap_tex, khsn_src);
                        g_fire_snap_live = true;
                    }
                }

                khsn_src->Release();
            }
            if (khsn_res) khsn_res->Release();
        }

        if (g_fire_snap_live) {
            g_fire_lock = g_fire_snap_srv;
            g_fire_lock->AddRef();
            g_fire_snap_copies++;
        } else {
            if (g_dbg_mode.load(std::memory_order_relaxed) == 33) g_fire_snap_fails++;
            g_fire_lock = g_mask.cast_depth;
            g_fire_lock->AddRef();
        }
        g_fire_fov2[0] = g_mask.cast_fov[0];
        g_fire_fov2[1] = g_mask.cast_fov[1];
        g_fire_dims2[0] = g_mask.cast_dims[0];
        g_fire_dims2[1] = g_mask.cast_dims[1];
        memcpy(g_fire_view2, g_ls.frame_view, sizeof(g_fire_view2));
        // Taken HERE, while g_fire_view2 still holds the engine's own render
        // view and before the bridge adoption below replaces it: this is the
        // only point where both members of the pair exist at once.
        g_fire_eng_dy_m = -1.0f;
        g_fire_eng_pitch_deg = -1.0f;
        g_fire_eng_yaw_deg = -1.0f;
        g_fire_eng_pos_m = -1.0f;

        if (g_ro.cycle_pv_valid) {
            float khev_a[3];
            float khev_b[3];
            extract_camera_pos(reinterpret_cast<const float(*)[4]>(g_fire_view2), khev_a);
            extract_camera_pos(g_ro.cycle_pv.view, khev_b);
            const float khev_dx = khev_a[0] - khev_b[0];
            const float khev_dy = khev_a[1] - khev_b[1];
            const float khev_dz = khev_a[2] - khev_b[2];
            g_fire_eng_pos_m = sqrtf(khev_dx * khev_dx + khev_dy * khev_dy + khev_dz * khev_dz);
            if (g_fire_eng_pos_m > g_fire_eng_pos_max_m) g_fire_eng_pos_max_m = g_fire_eng_pos_m;
            g_fire_eng_dy_m = fabsf(khev_dy);
            if (g_fire_eng_dy_m > g_fire_eng_dy_max_m) g_fire_eng_dy_max_m = g_fire_eng_dy_m;
            float khev_q1 = g_fire_view2[9];   // view[2][1]
            float khev_q2 = g_ro.cycle_pv.view[2][1];
            khev_q1 = khev_q1 > 1.0f ? 1.0f : (khev_q1 < -1.0f ? -1.0f : khev_q1);
            khev_q2 = khev_q2 > 1.0f ? 1.0f : (khev_q2 < -1.0f ? -1.0f : khev_q2);
            g_fire_eng_pitch_deg = fabsf(asinf(khev_q1) - asinf(khev_q2)) * 57.29578f;

            if (g_fire_eng_pitch_deg > g_fire_eng_pitch_max_deg) {
                g_fire_eng_pitch_max_deg = g_fire_eng_pitch_deg;
            }

            float khev_yd = kh_epoch_yaw_dot(g_fire_view2, &g_ro.cycle_pv.view[0][0]);
            khev_yd = khev_yd > 1.0f ? 1.0f : (khev_yd < -1.0f ? -1.0f : khev_yd);
            g_fire_eng_yaw_deg = acosf(khev_yd) * 57.29578f;

            if (g_fire_eng_yaw_deg > g_fire_eng_yaw_max_deg) {
                g_fire_eng_yaw_max_deg = g_fire_eng_yaw_deg;
            }

            g_fire_eng_samples++;
        }

        // It is kept because it makes the fire independent of the publish
        // stream (Zeus-class publish stalls never touch the fire) at zero
        // measured cost. BRIDGE-EPOCH FREEZE (kept as shipped behavior).
        if (g_ro.cycle_pv_stale) {
            RVExtBridge::ProjectionViewTransform khfe_pv = {};
            if (RVExtBridge::get_projection_view_transform(khfe_pv) &&
                latch_view_continuous(khfe_pv.view)) {
                if (g_ro.cycle_pv_valid) {
                    memcpy(&khfe_pv.projection[0][0], &g_ro.cycle_pv.projection[0][0],
                           sizeof(khfe_pv.projection));
                }

                g_ro.cycle_pv = khfe_pv;
                g_ro.cycle_pv_valid = true;
                g_ro.cycle_pv_stale = false;
                g_pv_latch_serial++;   // stamp every latch write
                g_fire_view_repairs++;
            }
        }

        if (g_dbg_mode.load(std::memory_order_relaxed) == 39) {
            g_fire_eng_freezes++;
        } else if (g_ro.cycle_pv_valid && !g_ro.cycle_pv_stale) {
            float khfe_bc[3];
            float khfe_pc[3];
            extract_camera_pos(g_ro.cycle_pv.view, khfe_bc);
            // frame_view[r*4+c] == cycle_pv.view[r][c] elementwise (the seal
            // vcol dual-source fill is the standing proof).
            extract_camera_pos(reinterpret_cast<const float(*)[4]>(g_fire_view2), khfe_pc);
            const float khfe_dx = khfe_pc[0] - khfe_bc[0];
            const float khfe_dy = khfe_pc[1] - khfe_bc[1];
            const float khfe_dz = khfe_pc[2] - khfe_bc[2];
            const float khfe_d = sqrtf(khfe_dx * khfe_dx + khfe_dy * khfe_dy + khfe_dz * khfe_dz);

            if (khfe_d <= KH_LATCH_JUMP_M) {   // era guard: a foreign bridge never steers the fire
                for (int khfe_r = 0; khfe_r < 4; ++khfe_r) {
                    for (int khfe_c = 0; khfe_c < 4; ++khfe_c) {
                        g_fire_view2[khfe_r * 4 + khfe_c] = g_ro.cycle_pv.view[khfe_r][khfe_c];
                    }
                }

                g_fire_view_bridge_fires++;
            } else {
                g_fire_view_era_rejects++;
                g_fire_view_pub_fires++;
            }
        } else {
            g_fire_view_pub_fires++;
        }

        // Era-guarded against the publish camera exactly like the bridge
        // adoption it replaces - a foreign sample never steers the fire - and
        // a refusal falls back to the epoch just adopted. Applied AFTER the
        // standard adoption so the shipped path is untouched byte-for-byte
        // when no re-freeze is pending.
        if (g_dbg_mode.load(std::memory_order_relaxed) == 28) {
            float khx_v[16];

            if (kh_extrapolate_view(g_fire_view2, khx_v)) {
                memcpy(g_fire_view2, khx_v, sizeof(g_fire_view2));
                g_fire_extrap_used++;
            } else {
                g_fire_extrap_fails++;
            }
        }

        if (g_fire_refreeze_pending) {
            g_fire_refreeze_pending = false;
            float khrv_a[3];
            float khrv_b[3];
            extract_camera_pos(reinterpret_cast<const float(*)[4]>(g_fire_refreeze_view), khrv_a);
            extract_camera_pos(reinterpret_cast<const float(*)[4]>(g_fire_view2), khrv_b);
            const float khrv_dx = khrv_a[0] - khrv_b[0];
            const float khrv_dy = khrv_a[1] - khrv_b[1];
            const float khrv_dz = khrv_a[2] - khrv_b[2];
            const float khrv_d = sqrtf(khrv_dx * khrv_dx + khrv_dy * khrv_dy + khrv_dz * khrv_dz);

            if (khrv_d <= KH_LATCH_JUMP_M) {
                memcpy(g_fire_view2, g_fire_refreeze_view, sizeof(g_fire_view2));
            } else {
                g_fire_view_era_rejects++;
                g_fire_refreeze_fails++;
            }
        }

        const float* fsun = kh_shadow_sun();
        if (!fsun) fsun = g_sun_dir_engine;
        g_fire_sun2[0] = fsun[0];
        g_fire_sun2[1] = fsun[1];
        g_fire_sun2[2] = fsun[2];

        {
            const uint64_t khs_now = steady_now_ms();

            if (g_sun_churn_prev_ms == 0) {
                g_sun_churn_prev[0] = fsun[0];
                g_sun_churn_prev[1] = fsun[1];
                g_sun_churn_prev[2] = fsun[2];
                g_sun_churn_prev_ms = khs_now;
            } else if (khs_now - g_sun_churn_prev_ms >= 1000) {
                float d = fsun[0] * g_sun_churn_prev[0] +
                          fsun[1] * g_sun_churn_prev[1] +
                          fsun[2] * g_sun_churn_prev[2];
                d = d > 1.0f ? 1.0f : (d < -1.0f ? -1.0f : d);
                const float khs_deg = acosf(d) * 57.29578f;
                if (khs_deg > g_sun_churn_max_deg) g_sun_churn_max_deg = khs_deg;
                g_sun_churn_prev[0] = fsun[0];
                g_sun_churn_prev[1] = fsun[1];
                g_sun_churn_prev[2] = fsun[2];
                g_sun_churn_prev_ms = khs_now;
            }
        }
        g_fire_cam_delta_m = -1.0f;
        g_fire_freeze_dy_m = -1.0f;
        g_fire_freeze_pitch_deg = -1.0f;
        g_fire_freeze_yaw_deg = -1.0f;

        if (g_ro.cycle_pv_valid) {
            RVExtBridge::ProjectionViewTransform khfc_pv = {};

            if (RVExtBridge::get_projection_view_transform(khfc_pv)) {
                float khfc_a[3], khfc_b[3];
                extract_camera_pos(khfc_pv.view, khfc_a);
                extract_camera_pos(g_ro.cycle_pv.view, khfc_b);
                const float khfc_dx = khfc_a[0] - khfc_b[0];
                const float khfc_dy = khfc_a[1] - khfc_b[1];
                const float khfc_dz = khfc_a[2] - khfc_b[2];
                g_fire_cam_delta_m = sqrtf(khfc_dx * khfc_dx + khfc_dy * khfc_dy + khfc_dz * khfc_dz);
                if (g_fire_cam_delta_m > g_fire_cam_delta_max) g_fire_cam_delta_max = g_fire_cam_delta_m;
                // Height (engine y is altitude - the camEngAltY lane).
                g_fire_freeze_dy_m = fabsf(khfc_dy);
                if (g_fire_freeze_dy_m > g_fire_freeze_dy_max_m) g_fire_freeze_dy_max_m = g_fire_freeze_dy_m;
                // Pitch: view[2][1], the same element the epoch detector
                // reads, through the same asin clamp.
                float khfc_p1 = khfc_pv.view[2][1];
                float khfc_p2 = g_ro.cycle_pv.view[2][1];
                khfc_p1 = khfc_p1 > 1.0f ? 1.0f : (khfc_p1 < -1.0f ? -1.0f : khfc_p1);
                khfc_p2 = khfc_p2 > 1.0f ? 1.0f : (khfc_p2 < -1.0f ? -1.0f : khfc_p2);
                g_fire_freeze_pitch_deg = fabsf(asinf(khfc_p1) - asinf(khfc_p2)) * 57.29578f;

                if (g_fire_freeze_pitch_deg > g_fire_freeze_pitch_max_deg) {
                    g_fire_freeze_pitch_max_deg = g_fire_freeze_pitch_deg;
                }

                float khfc_yd = kh_epoch_yaw_dot(&khfc_pv.view[0][0], &g_ro.cycle_pv.view[0][0]);
                khfc_yd = khfc_yd > 1.0f ? 1.0f : (khfc_yd < -1.0f ? -1.0f : khfc_yd);
                g_fire_freeze_yaw_deg = acosf(khfc_yd) * 57.29578f;

                if (g_fire_freeze_yaw_deg > g_fire_freeze_yaw_max_deg) {
                    g_fire_freeze_yaw_max_deg = g_fire_freeze_yaw_deg;
                }

                g_fire_freeze_samples++;
            }
        }

        // Verdict: the engine erases the mask EVERY frame; the ghost was
        // never stale paint. (A mask persistence probe lived here for two
        // builds - armed- only marker texels written into the mask and read
        // back a frame later. Once per freeze; re-fires replay it.
        {
            const double khoi_r[3][3] = {
                { g_fire_view2[0], g_fire_view2[1], g_fire_view2[2] },
                { g_fire_view2[4], g_fire_view2[5], g_fire_view2[6] },
                { g_fire_view2[8], g_fire_view2[9], g_fire_view2[10] }
            };
            double khoi_def = 0.0;

            for (int khoi_i = 0; khoi_i < 3; ++khoi_i) {
                const double khoi_n = sqrt(khoi_r[khoi_i][0] * khoi_r[khoi_i][0] +
                                           khoi_r[khoi_i][1] * khoi_r[khoi_i][1] +
                                           khoi_r[khoi_i][2] * khoi_r[khoi_i][2]);
                if (fabs(khoi_n - 1.0) > khoi_def) khoi_def = fabs(khoi_n - 1.0);

                for (int khoi_j = khoi_i + 1; khoi_j < 3; ++khoi_j) {
                    const double khoi_d = fabs(khoi_r[khoi_i][0] * khoi_r[khoi_j][0] +
                                               khoi_r[khoi_i][1] * khoi_r[khoi_j][1] +
                                               khoi_r[khoi_i][2] * khoi_r[khoi_j][2]);
                    if (khoi_d > khoi_def) khoi_def = khoi_d;
                }
            }

            // Cofactors: inv[c][j] = khoi_c[j][c] / det; the fill's row-dot
            // wants castMat[j][c] = inv[c][j], i.e. khoi_c[j][c] / det.
            const double khoi_c[3][3] = {
                { khoi_r[1][1] * khoi_r[2][2] - khoi_r[1][2] * khoi_r[2][1],
                  khoi_r[1][2] * khoi_r[2][0] - khoi_r[1][0] * khoi_r[2][2],
                  khoi_r[1][0] * khoi_r[2][1] - khoi_r[1][1] * khoi_r[2][0] },
                { khoi_r[0][2] * khoi_r[2][1] - khoi_r[0][1] * khoi_r[2][2],
                  khoi_r[0][0] * khoi_r[2][2] - khoi_r[0][2] * khoi_r[2][0],
                  khoi_r[0][1] * khoi_r[2][0] - khoi_r[0][0] * khoi_r[2][1] },
                { khoi_r[0][1] * khoi_r[1][2] - khoi_r[0][2] * khoi_r[1][1],
                  khoi_r[0][2] * khoi_r[1][0] - khoi_r[0][0] * khoi_r[1][2],
                  khoi_r[0][0] * khoi_r[1][1] - khoi_r[0][1] * khoi_r[1][0] } };
            const double khoi_det = khoi_r[0][0] * khoi_c[0][0] +
                                    khoi_r[0][1] * khoi_c[0][1] +
                                    khoi_r[0][2] * khoi_c[0][2];
            g_fire_cast_inv_valid = false;
            g_fire_ortho_defect = static_cast<float>(khoi_def);
            if (g_fire_ortho_defect > g_fire_ortho_defect_max) g_fire_ortho_defect_max = g_fire_ortho_defect;
            g_fire_cam_skew_m = -1.0f;

            if (fabs(khoi_det - 1.0) < 0.1) {
                for (int khoi_j = 0; khoi_j < 3; ++khoi_j) {
                    for (int khoi_k = 0; khoi_k < 3; ++khoi_k) {
                        g_fire_cast_inv[khoi_j * 3 + khoi_k] =
                            static_cast<float>(khoi_c[khoi_j][khoi_k] / khoi_det);
                    }
                }

                g_fire_cast_inv_valid = true;
                // Double throughout.
                const double khoi_t[3] = { g_fire_view2[12], g_fire_view2[13], g_fire_view2[14] };
                double khoi_sk2 = 0.0;

                for (int khoi_j = 0; khoi_j < 3; ++khoi_j) {
                    const double khoi_ct = -(khoi_t[0] * (khoi_c[khoi_j][0] / khoi_det) +
                                             khoi_t[1] * (khoi_c[khoi_j][1] / khoi_det) +
                                             khoi_t[2] * (khoi_c[khoi_j][2] / khoi_det));
                    const double khoi_cT = -(khoi_t[0] * khoi_r[khoi_j][0] +
                                             khoi_t[1] * khoi_r[khoi_j][1] +
                                             khoi_t[2] * khoi_r[khoi_j][2]);
                    khoi_sk2 += (khoi_ct - khoi_cT) * (khoi_ct - khoi_cT);
                }

                g_fire_cam_skew_m = static_cast<float>(sqrt(khoi_sk2));
                if (g_fire_cam_skew_m > g_fire_cam_skew_max) g_fire_cam_skew_max = g_fire_cam_skew_m;
            }
        }
        g_fire_lock_valid = true;

    }

    // Pristine set the fire's viewport from LIVE g_mask.cast_dims per paint
    // while PSMaskCast addresses pixels through the FROZEN dims (dimsM =
    // castView[1].zw) against the frozen depth SRV: whenever the live pair
    // diverged mid-frame, later repaints rasterized on one grid and
    // reconstructed on another - scaled/offset darkening, last-paint- wins
    // ghost/drift under motion, and the engine's TAA blending the coherent
    // early paint in as the simultaneous anchored copy.
    {
        const float khvp_dx = fabsf(g_mask.cast_dims[0] - g_fire_dims2[0]);
        const float khvp_dy = fabsf(g_mask.cast_dims[1] - g_fire_dims2[1]);
        const float khvp_d = khvp_dx > khvp_dy ? khvp_dx : khvp_dy;
        if (khvp_d > g_fire_dims_div_px) g_fire_dims_div_px = khvp_d;
        if (khvp_d > g_fire_dims_div_max) g_fire_dims_div_max = khvp_d;

        if (khvp_d > 0.5f) {
            g_fire_dims_incoh++;
            g_fire_dims_incoh_total++;
        }

        if (g_dbg_mode.load(std::memory_order_relaxed) == 25) {
            g_fire_vp_mode = 2;   // revert: pristine live viewport stands
        } else if (g_fire_dims2[0] <= 0.0f || g_fire_dims2[1] <= 0.0f) {
            g_fire_vp_mode = 1;   // belt: no frozen pair, live viewport stands
        } else {
            D3D11_VIEWPORT vpf = {};
            vpf.Width = g_fire_dims2[0];
            vpf.Height = g_fire_dims2[1];
            vpf.MaxDepth = 1.0f;
            ctx->RSSetViewports(1, &vpf);
            g_fire_vp_mode = 0;   // frozen grid: raster == reconstruction
        }
    }

    // The band-era keeps its two proven, input-mode-independent wins
    // upstream: the half-res resolve acceptance (the 74,941-batch classifier
    // starvation - the fog-overcast root) and resolution-agnostic depth
    // addressing (the quadrant bug).
    if (g_ls.frame_view_valid) {
        float khlv_a[3];
        float khlv_b[3];
        extract_camera_pos(reinterpret_cast<const float(*)[4]>(g_ls.frame_view), khlv_a);
        extract_camera_pos(reinterpret_cast<const float(*)[4]>(g_fire_view2), khlv_b);
        const float khlv_dx = khlv_a[0] - khlv_b[0];
        const float khlv_dy = khlv_a[1] - khlv_b[1];
        const float khlv_dz = khlv_a[2] - khlv_b[2];
        g_fire_live_view_delta_m = sqrtf(khlv_dx * khlv_dx + khlv_dy * khlv_dy + khlv_dz * khlv_dz);
        if (g_fire_live_view_delta_m > g_fire_live_view_delta_max) g_fire_live_view_delta_max = g_fire_live_view_delta_m;
        if (g_fire_live_view_delta_m > 0.05f) g_fire_live_view_moved++;
    }

    g_fire_count_frame++;
    g_cast_frozen_fires++;
    if (g_fire_first_d < 0.0f) {   // ordering census
        g_fire_first_d = static_cast<float>(g_topo.draws);
        // how far fire 1 is from the engine's most recent mask read. This is
        // the margin the whole flicker turns on.
        if (g_mask_srv_last_d >= 0.0f) {
            g_fire_srv_gap_d = g_fire_first_d - g_mask_srv_last_d;
            if (g_fire_srv_gap_d > g_fire_srv_gap_max) {
                g_fire_srv_gap_max = g_fire_srv_gap_d;
            }
        }
    }
    g_fire_last_d = static_cast<float>(g_topo.draws);
    ctx->PSSetShaderResources(0, 1, &g_fire_lock);   // frozen: identical replay per batch
    if (sun_map && g_res.sun_srv) ctx->PSSetShaderResources(11, 1, &g_res.sun_srv);
    if (sun_map && g_sun2_map_valid && g_res.sun2_srv) ctx->PSSetShaderResources(25, 1, &g_res.sun2_srv);
    if (sun_map && g_sun3_map_valid && g_res.sun3_srv) ctx->PSSetShaderResources(26, 1, &g_res.sun3_srv);
    if (sun_map && g_sun4_map_valid && g_res.sun4_srv) ctx->PSSetShaderResources(27, 1, &g_res.sun4_srv);
    if (sun_map && g_sun5_map_valid && g_res.sun5_srv) ctx->PSSetShaderResources(32, 1, &g_res.sun5_srv);
    if (g_res.thm_srv) ctx->PSSetShaderResources(10, 1, &g_res.thm_srv);   // terrain snap
                                                                           // (full-table restore covers it)

    auto fill_frame = [&](ConstantData& cbd) {
        for (int r = 0; r < 3; ++r) {
            memcpy(cbd.cast_mat[r], g_fire_view2 + r * 4, 16);   // frozen view
        }

        // setRenderDebug 30 = pristine raw rows for a live A/B (moved off 27,
        // which the UI coverage debug view already owned - a mode collision).
        if (g_fire_cast_inv_valid &&
            g_dbg_mode.load(std::memory_order_relaxed) != 30) {
            for (int r = 0; r < 3; ++r) {
                cbd.cast_mat[r][0] = g_fire_cast_inv[r * 3 + 0];
                cbd.cast_mat[r][1] = g_fire_cast_inv[r * 3 + 1];
                cbd.cast_mat[r][2] = g_fire_cast_inv[r * 3 + 2];
            }
        }

        memcpy(cbd.cast_view[0], g_fire_view2 + 12, 16);
        cbd.cast_view[0][3] = (g_mask.sweep_settle >= g_mask.sweep_need) ? 1.0f : 0.0f;
        cbd.cast_view[1][0] = g_fire_fov2[0];
        cbd.cast_view[1][1] = g_fire_fov2[1];
        cbd.cast_view[1][2] = g_fire_dims2[0];
        cbd.cast_view[1][3] = g_fire_dims2[1];
        cbd.cast_view[2][0] = g_fire_sun2[0];   // frozen sun (see the latch)
        cbd.cast_view[2][1] = g_fire_sun2[1];
        cbd.cast_view[2][2] = g_fire_sun2[2];
        cbd.cast_view[2][3] = g_shadow_map_strength;   // 1 = full: engine handles ambient
                                                       // 31 = per-CYCLE parity tint (odd cycles
                                                       // paint lighter) - a ghost whose darkness
                                                       // differs from the good shadow under
                                                       // motion is a CROSS-FRAME copy, and which
                                                       // of the two is lighter names the stale
                                                       // side.
        {
            const int khgt_m = g_dbg_mode.load(std::memory_order_relaxed);
            if (khgt_m == 31 && (g_topo_cycles & 1ull) != 0) cbd.cast_view[2][3] *= 0.45f;
            if (khgt_m == 32 && g_fire_count_frame > 1) cbd.cast_view[2][3] *= 0.45f;
            // setRenderDebug 40 = clamp to the LAST fire (behaviour); 22 =
            // clamp off entirely (anchor + ghost). setRenderDebug 36 =
            // first-fire clamp; 40 = last fire; 22 = no clamp at all.
            if (khgt_m == 36) {
                if (g_fire_count_frame > 1) {
                    cbd.cast_view[2][3] = 0.0f;
                    g_fire_single_suppressed++;
                } else {
                    g_fire_clamp_painted++;
                    g_fire_clamp_paints++;
                    // Path 3 = first-fire clamp, 4 = last-fire clamp. Census
                    // only.
                    g_fire_paint_ix = g_fire_count_frame;
                    g_fire_paint_path = 3;
                    g_fire_paint_was_srv = g_fire_mask_srv_now;
                    if (!(g_mask.sweep_settle >= g_mask.sweep_need)) g_fire_clamp_unverified++;
                }
            } else if (khgt_m != 22 && khgt_m != 40 && khgt_m != 19 && khgt_m != 28) {
                const bool khsc_last = (g_fire_count_frame >= g_fire_clamp_target);

                if (g_fire_clamp_painted > 0 && g_fire_paint_path == 1 &&
                    khsc_last && g_cam_step_m >= 0.0f &&
                    khgt_m == 42 && g_fire_cast_inv_valid) {
                    // Project the one-frame camera step to screen pixels at
                    // the shadow, using the frozen grid and fov this very
                    // fire is painting with - not a live value that could
                    // disagree.
                    float khcy_c[3];
                    extract_camera_pos(
                        reinterpret_cast<const float(*)[4]>(g_fire_view2), khcy_c);
                    const float khcy_dx = khcy_c[0] - g_sun_map_bounds[0];
                    const float khcy_dy = khcy_c[1] - g_sun_map_bounds[1];
                    const float khcy_dz = khcy_c[2] - g_sun_map_bounds[2];
                    float khcy_d = sqrtf(khcy_dx * khcy_dx + khcy_dy * khcy_dy +
                                         khcy_dz * khcy_dz);
                    if (khcy_d < KH_CARRY_MIN_DIST_M) khcy_d = KH_CARRY_MIN_DIST_M;

                    if (g_sun_map_valid && g_fire_dims2[0] > 1.0f &&
                        g_fire_fov2[0] > 1.0e-4f) {
                        const float khcy_px = g_cam_step_m * g_fire_dims2[0] /
                                              (2.0f * khcy_d * g_fire_fov2[0]);

                        if (khcy_px <= KH_CARRY_MAX_PX) {
                            g_fire_carry_paints++;
                            g_fire_carry_px = khcy_px;
                            if (khcy_px > g_fire_carry_px_max) {
                                g_fire_carry_px_max = khcy_px;
                            }
                            // Deliberately does NOT touch
                            // g_fire_clamp_painted or the paint lanes: this
                            // frame's VERDICT is still path 1 at fire 1, and
                            // firePaintIx / firePaintPath must keep pointing
                            // at it or the one instrument that can name a
                            // flicker frame goes blind.
                        } else {
                            cbd.cast_view[2][3] = 0.0f;
                            g_fire_carry_skips_motion++;
                            g_fire_carry_px_skip = khcy_px;
                            g_fire_single_suppressed++;
                        }
                    } else {
                        cbd.cast_view[2][3] = 0.0f;
                        g_fire_carry_skips_gauge++;
                        g_fire_single_suppressed++;
                    }
                } else if (g_fire_clamp_painted == 0 && (g_fire_mask_srv_now || khsc_last)) {
                    g_fire_clamp_painted++;
                    g_fire_clamp_paints++;
                    g_fire_paint_was_srv = g_fire_mask_srv_now;
                    // Recorded HERE, at the one place that knows both the
                    // index and the path, so a flicker frame in the trace can
                    // be read off directly instead of inferred.
                    g_fire_paint_ix = g_fire_count_frame;

                    if (g_fire_mask_srv_now) {
                        g_fire_srv_clamp_paints++;
                        g_fire_paint_path = 1;
                        if (g_fire_count_frame > 1) g_fire_catchup_paints++;
                    } else {
                        g_fire_srv_clamp_fallbacks++;
                        g_fire_srv_backstop_at_last++;
                        g_fire_paint_path = 2;
                    }
                } else {
                    cbd.cast_view[2][3] = 0.0f;
                    g_fire_single_suppressed++;
                }
            } else if (khgt_m == 40 || khgt_m == 19 || khgt_m == 28) {   // 19 = 40 + fresh epoch, 28 = 40 + extrapolated epoch
                if (g_fire_count_frame < g_fire_clamp_target) {
                    cbd.cast_view[2][3] = 0.0f;
                    g_fire_single_suppressed++;
                } else {
                    g_fire_clamp_painted++;
                    g_fire_clamp_paints++;
                    g_fire_paint_ix = g_fire_count_frame;   // (see the 36 branch)
                    g_fire_paint_path = 4;
                    g_fire_paint_was_srv = g_fire_mask_srv_now;
                }
            }
        }
        // One field session decides.
        if (g_fire_epoch_mute && g_dbg_mode.load(std::memory_order_relaxed) == 35) {
            cbd.cast_view[2][3] *= 0.35f;
        }
        if (g_dbg_mode.load(std::memory_order_relaxed) != 24) {
            kh_fill_occ(cbd);   // terrain-snap lanes (24 = snap off; zeroed = shader no-op)
        }
        // KH_SUN_ANCHOR: one origin for every sun matrix this fill carries
        // (the cast tier chain consumes sunVP2/3/4 here); the matrices are
        // rebased to it at their own fills below. Ledger at g_sun_anchor_now.
        cbd.sun_origin[0] = g_sun_anchor_now[0];
        cbd.sun_origin[1] = g_sun_anchor_now[1];
        cbd.sun_origin[2] = g_sun_anchor_now[2];
        // The cast chain is this fill's consumer - the side never faded.
        if (g_dbg_mode.load(std::memory_order_relaxed) != 255 &&
            (g_sun_anchor_now[0] != 0.0f || g_sun_anchor_now[1] != 0.0f ||
             g_sun_anchor_now[2] != 0.0f)) {
            cbd.mir_meta[3] = fminf(fmaxf(
                g_sun_range.load(std::memory_order_relaxed), 8.0f), 1000.0f);
        }
    };

    if (sun_map) {
        // MESH-SHAPED cast: ONE fullscreen test against the sun-depth map
        // covers EVERY caster at once - the map already holds them all.
        // centerSize/sizeAxes carry the COMBINED caster bounds (already
        // engine axes) for the shader's locality clamp.
        {
            ConstantData cbd = {};
            fill_frame(cbd);
            cbd.center_size[0] = g_sun_map_bounds[0];
            cbd.center_size[1] = g_sun_map_bounds[1];
            cbd.center_size[2] = g_sun_map_bounds[2];
            cbd.size_axes[0] = g_sun_map_bounds[3] * 2.0f;
            cbd.size_axes[1] = g_sun_map_bounds[4] * 2.0f;
            cbd.size_axes[2] = g_sun_map_bounds[5] * 2.0f;
            kh_sun_rebase_vp(&cbd.sun_vp[0][0], g_sun_map_vp,
                             g_sun_map_anchor, g_sun_anchor_now);
            cbd.sun_meta[0] = g_sun_map_cam_anchor ? 2.0f : 1.0f;
            cbd.sun_meta[1] = static_cast<float>(g_sun_map_size);   // rendered size (KH_SUN_LADDER)
            cbd.sun_meta[2] = g_sun_map_bias;
            cbd.sun_meta[3] = g_shadow_map_strength;
            // lighting0.y 21 (mode 243) reverts the whole chain to the
            // union-only compare - set HERE and only here, because the cast
            // is this CB's consumer; the mesh fill's map deliberately does
            // not carry 243 (its default 1.0 keeps every mesh-side term at
            // mode-0 behaviour).
            kh_fill_sun_tier_cb(cbd.sun_vp2, cbd.sun_meta2, g_sun2_map_valid,
                                g_sun2_map_vp, g_sun2_map_bias, g_sun2_half_diag, g_sun2_map_size);
            kh_fill_sun_tier_cb(cbd.sun_vp3, cbd.sun_meta3, g_sun3_map_valid,
                                g_sun3_map_vp, g_sun3_map_bias, g_sun3_half_diag, g_sun3_map_size);
            kh_fill_sun_tier_cb(cbd.sun_vp4, cbd.sun_meta4, g_sun4_map_valid,
                                g_sun4_map_vp, g_sun4_map_bias, g_sun4_half_diag, g_sun4_map_size);
            kh_fill_sun_tier_cb(cbd.sun_vp5, cbd.sun_meta5, g_sun5_map_valid,
                                g_sun5_map_vp, g_sun5_map_bias, g_sun5_half_diag, g_sun5_map_size);   // FAR band
            {
                const int khcc_m = g_dbg_mode.load(std::memory_order_relaxed);
                cbd.lighting0[1] = khcc_m == 243 ? 21.0f   // cast chain revert
                                 : khcc_m == 257 ? 26.0f   // tier blend OFF (twin)
                                 : khcc_m == 245 ? 22.0f   // filtering revert
                                 : khcc_m == 442 ? 72.0f   // KH_TIER_FADE_DIR OFF (twin)
                                 : khcc_m == 443 ? 73.0f   // partner paint (twin)
                                 // 446 / 450 / 452 (codes 76 / 77 / 78, the absence witness) - 446 an alias since 26711, 450 / 452 RETIRED at 26719 with the witness body (twin of the mesh ladder); codes burned. 454 / 456 / 457 (the self-kernel gradient clamp and slope-bias arms) are mesh-fill only: the cast chain has no receiver-plane kernel, so they map to the default here deliberately - the 264 precedent. 453 / 455 are retired (26714). 463 (code 89, the far-self gate restore) is mesh-fill only for the same reason: the cast chain has no far gate (the 264 precedent); 401 retired (26719).
                                 : khcc_m == 445 ? 75.0f   // hold 0.28, opt-in (twin)
                                 : khcc_m == 458 ? 84.0f   // hold off - alias of the default (twin)
                                 : khcc_m == 459 ? 85.0f   // hold 0.10, opt-in (twin)
                                 : khcc_m == 460 ? 86.0f   // alias of 445 (twin)
                                 : khcc_m == 461 ? 87.0f   // alias of the default (twin)
                                 : khcc_m == 462 ? 88.0f   // fade to the guard, opt-in (twin)
                                 // 328 arms it deliberately; 326 arms it
                                 // because it reverts KH_BAND_SUN_REACH, and
                                 // the fallthrough is the cover for exactly
                                 // the camera-local windows 326 restores - a
                                 // revert that leaves its dependant behind is
                                 // not a revert. Code 40 (295) now resolves
                                 // to the DEFAULT and is an accepted alias.
                                 : (khcc_m == 328 || khcc_m == 326) ? 42.0f
                                 : khcc_m == 295 ? 40.0f   // accepted alias of the default
                                 : 0.0f;
                // ARMING LANE: the code the cast chain actually received.
                g_cast_chain_code = cbd.lighting0[1];
            }
            cbd.locality_meta[0] = static_cast<float>(g_sun_local_count);
            {
                const int khlw_m = g_dbg_mode.load(std::memory_order_relaxed);
                cbd.locality_meta[3] = (khlw_m == 34) ? 2.0f : ((khlw_m == 29) ? 1.0f : 0.0f);
            }
            // Presence-test maturity: unchanged-input for 0.5 s (no
            // re-render) = the cold churn is over. See the shader gate.
            cbd.locality_meta[2] = (g_sun_map_render_time >= 0.0f &&
                                    effect_time_seconds() - g_sun_map_render_time > 0.5f)
                                 ? 1.0f : 0.0f;
            g_sun_map_mature_pub = cbd.locality_meta[2];   // as the SHADER got it

            if (g_sun_local_count > 0 && g_sun_local_count <= 16) {
                for (int li = 0; li < g_sun_local_count; ++li) {
                    const float* lb = g_sun_locals.data() + static_cast<size_t>(li) * 6;
                    cbd.locality[li * 2][0] = lb[0];
                    cbd.locality[li * 2][1] = lb[1];
                    cbd.locality[li * 2][2] = lb[2];
                    cbd.locality[li * 2 + 1][0] = lb[3];
                    cbd.locality[li * 2 + 1][1] = lb[4];
                    cbd.locality[li * 2 + 1][2] = lb[5];
                }
            } else if (g_sun_local_count > 16 && kh_upload_locality_ext(ctx)) {
                // UNCAPPED t2 twin; failure leaves meta.y = 0 and the shader
                // takes the combined-bounds fallback (the pre-extension >16
                // behavior).
                cbd.locality_meta[1] = 1.0f;
                ctx->PSSetShaderResources(2, 1, &g_res.locality_srv);
                // KH_CAST_OCC: build and bind the occupancy grid; the shader
                // then gates in O(1). Any failure leaves the per-pixel scan.
                if (kh_cast_occ_build(ctx, cbd)) {
                    ctx->PSSetShaderResources(35, 1, &g_res.castocc_srv);
                } else {
                    cbd.cast_mat[0][3] = 0.0f;
                    g_castocc_falls++;
                }
            }

            // CB SPLIT: both slices (centerSize/sizeAxes ride b0; the cast
            // matrices, sun map + locality list ride b1)
            if (!kh_upload_obj_cb(ctx, g_res.composite_cb, cbd) ||
                !kh_upload_frame_cb(ctx, g_res.composite_frame_cb, cbd)) {
                g_ls.cast_misses = 9;
            } else {
                ctx->Draw(3, 0);
                g_mask.analytic_casts++;
            }
        }
    } else {
        // AABB slab fallback: one fullscreen test per caster, exactly the
        // pre-map behavior (zeroed sunMeta selects the shader's slab path).
        for (uint32_t bi = 0; bi < ncb; ++bi) {
            ConstantData cbd = {};
            fill_frame(cbd);
            cbd.center_size[0] = centries[bi].pos[0];
            cbd.center_size[1] = centries[bi].pos[2];
            cbd.center_size[2] = centries[bi].pos[1];
            cbd.size_axes[0] = centries[bi].size[0];
            cbd.size_axes[1] = centries[bi].size[2];
            cbd.size_axes[2] = centries[bi].size[1];
            // CB SPLIT: both slices per caster (slab path - rare)
            if (!kh_upload_obj_cb(ctx, g_res.composite_cb, cbd) ||
                !kh_upload_frame_cb(ctx, g_res.composite_frame_cb, cbd)) { g_ls.cast_misses = 9; break; }
            ctx->Draw(3, 0);
            g_mask.analytic_casts++;
        }
    }

    // UAV-complete restore (the root fix): rebind the engine's exact
    // RTV+DSV+UAV layout. The engine's own layout satisfies the API's slot
    // rule (UAV start >= RTV count); a driver-rejected call would degrade to
    // the historical behavior, never worse.
    if (khf_uav_n > 0) {
        int khf_uav_hi = 0;

        for (int ui = 7; ui >= 0; --ui) {
            if (old_uavs[ui]) { khf_uav_hi = ui; break; }
        }

        UINT khf_rt_n = 0;

        for (int ri = 7; ri >= 0; --ri) {
            if (old_rtvs[ri]) { khf_rt_n = static_cast<UINT>(ri) + 1; break; }
        }

        static const UINT khf_keep[8] = {
            0xFFFFFFFFu, 0xFFFFFFFFu, 0xFFFFFFFFu, 0xFFFFFFFFu,
            0xFFFFFFFFu, 0xFFFFFFFFu, 0xFFFFFFFFu, 0xFFFFFFFFu,
        };
        ctx->OMSetRenderTargetsAndUnorderedAccessViews(
            khf_rt_n, old_rtvs, old_dsv,
            static_cast<UINT>(khf_uav_lo),
            static_cast<UINT>(khf_uav_hi - khf_uav_lo + 1),
            old_uavs + khf_uav_lo, khf_keep);
    } else {
        ctx->OMSetRenderTargets(8, old_rtvs, old_dsv);
    }

    if (old_nvp > 0) ctx->RSSetViewports(old_nvp, old_vps);
    ctx->VSSetShader(old_vs, nullptr, 0);
    ctx->PSSetShader(old_ps, nullptr, 0);
    ctx->IASetInputLayout(old_il);
    ctx->IASetPrimitiveTopology(old_topo);
    // Our composite_cb is bound here, so the buffer always CHANGES at this
    // call - the same-buffer offset-only SetConstantBuffers1 runtime bug
    // cannot drop it. Offset-aware b0 restore (round-7 root fix): rebind the
    // engine's pool windows exactly.
    if (khf_ctx1) {
        if (old_cb && old_cb_num > 0) {
            khf_ctx1->PSSetConstantBuffers1(0, 1, &old_cb, &old_cb_first, &old_cb_num);
        } else {
            ctx->PSSetConstantBuffers(0, 1, &old_cb);
        }

        if (old_vs_cb && old_vs_cb_num > 0) {
            khf_ctx1->VSSetConstantBuffers1(0, 1, &old_vs_cb, &old_vs_cb_first, &old_vs_cb_num);
        } else {
            ctx->VSSetConstantBuffers(0, 1, &old_vs_cb);
        }

        // Slot 1 (CB split): same offset-aware restore discipline
        if (old_cb1 && old_cb1_num > 0) {
            khf_ctx1->PSSetConstantBuffers1(1, 1, &old_cb1, &old_cb1_first, &old_cb1_num);
        } else {
            ctx->PSSetConstantBuffers(1, 1, &old_cb1);
        }

        if (old_vs_cb1 && old_vs_cb1_num > 0) {
            khf_ctx1->VSSetConstantBuffers1(1, 1, &old_vs_cb1, &old_vs_cb1_first, &old_vs_cb1_num);
        } else {
            ctx->VSSetConstantBuffers(1, 1, &old_vs_cb1);
        }

        khf_ctx1->Release();
    } else {
        ctx->PSSetConstantBuffers(0, 1, &old_cb);
        ctx->VSSetConstantBuffers(0, 1, &old_vs_cb);
        ctx->PSSetConstantBuffers(1, 1, &old_cb1);
        ctx->VSSetConstantBuffers(1, 1, &old_vs_cb1);
    }

    ctx->OMSetBlendState(old_blend, old_bf, old_bmask);
    ctx->OMSetDepthStencilState(old_dss, old_sref);
    // Full-table restore (round-8 root fix): rebind BOTH stages' exact SRV
    // tables - this runs after the OM restore, so any mask SRV in the
    // captured table is legal to rebind again (the RTV set that nulled it has
    // been reverted). Covers t0/t11 by construction.
    ctx->PSSetShaderResources(0, _countof(old_ps_srvs), old_ps_srvs);   // covers t25-t28; +t32; width
    ctx->VSSetShaderResources(0, _countof(old_vs_srvs), old_vs_srvs);
    ctx->GSSetShader(old_gs, nullptr, 0);
    ctx->HSSetShader(old_hs, nullptr, 0);
    ctx->DSSetShader(old_ds2, nullptr, 0);
    ctx->RSSetState(old_rs);
    ctx->PSSetShaderResources(35, 1, &khco_old_t35);   // KH_CAST_OCC
    KH_SAFE_RELEASE(khco_old_t35);
    g_ro.in_injection = false;
    KH_SAFE_RELEASE(old_vs_cb);
    KH_SAFE_RELEASE(old_vs_cb1);

    for (int r = 0; r < 8; ++r) KH_SAFE_RELEASE(old_rtvs[r]);

    for (int u = 0; u < 8; ++u) KH_SAFE_RELEASE(old_uavs[u]);

    KH_SAFE_RELEASE(old_dsv);
    KH_SAFE_RELEASE(old_vs);
    KH_SAFE_RELEASE(old_ps);
    KH_SAFE_RELEASE(old_il);
    KH_SAFE_RELEASE(old_cb);
    KH_SAFE_RELEASE(old_cb1);
    KH_SAFE_RELEASE(old_blend);
    KH_SAFE_RELEASE(old_dss);

    for (int s16 = 0; s16 < static_cast<int>(_countof(old_ps_srvs)); ++s16) {
        KH_SAFE_RELEASE(old_ps_srvs[s16]);
        KH_SAFE_RELEASE(old_vs_srvs[s16]);
    }
    KH_SAFE_RELEASE(old_gs);
    KH_SAFE_RELEASE(old_hs);
    KH_SAFE_RELEASE(old_ds2);
    KH_SAFE_RELEASE(old_rs);
}

inline void mask_note_draw(ID3D11DeviceContext* ctx) {
    if (!g_mask.atlas_bound || !ctx) return;
    g_mask.atlas_bound = false;   // one record per pass segment is plenty
    g_ls.atlas_last_seen = effect_time_seconds();   // the engine just consumed the held atlas: it is alive
    if (g_mask.rt_is_resolve) {
        resolve_pair_capture(ctx);
    }
}

// Lazy SRV over the atlas; typeless depth formats map to their color-read
// equivalents. Render thread (injection) only.
inline bool shadow_live_ensure_srv() {
    if (g_ls.atlas_srv) return true;
    if (!g_ls.atlas_tex || g_ls.srv_failed) return false;

    DXGI_FORMAT fmt = DXGI_FORMAT_UNKNOWN;

    switch (static_cast<DXGI_FORMAT>(g_ls.atlas_fmt)) {
        case DXGI_FORMAT_R32_TYPELESS:    fmt = DXGI_FORMAT_R32_FLOAT; break;
        case DXGI_FORMAT_R24G8_TYPELESS:  fmt = DXGI_FORMAT_R24_UNORM_X8_TYPELESS; break;
        case DXGI_FORMAT_R16_TYPELESS:    fmt = DXGI_FORMAT_R16_UNORM; break;
        case DXGI_FORMAT_R32G8X24_TYPELESS: fmt = DXGI_FORMAT_R32_FLOAT_X8X24_TYPELESS; break;
        default: break;
    }

    if (fmt == DXGI_FORMAT_UNKNOWN) { g_ls.srv_failed = true; g_stats.shadow_srv_failed++; return false; }

    ID3D11Device* dev = nullptr;
    g_ls.atlas_tex->GetDevice(&dev);
    if (!dev) { g_ls.srv_failed = true; g_stats.shadow_srv_failed++; return false; }

    D3D11_SHADER_RESOURCE_VIEW_DESC sd = {};
    sd.Format = fmt;
    sd.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
    sd.Texture2D.MipLevels = 1;
    const HRESULT hr = dev->CreateShaderResourceView(g_ls.atlas_tex, &sd, &g_ls.atlas_srv);
    dev->Release();

    if (FAILED(hr) || !g_ls.atlas_srv) {
        g_ls.atlas_srv = nullptr;
        g_ls.srv_failed = true;
        g_stats.shadow_srv_failed++;
        return false;
    }

    return true;
}

// BLAST RADIUS, measured before writing a line: that depth buffer is NEVER
// read as a shader resource anywhere in the frame, and after the volume pass
// its only remaining consumer is the resolve quad. OM-binding tracking for
// the recon: keeps phase_active / target_identity current.
static void*    g_svs_prev_dsv = nullptr;   // identity of the previous OM depth bind
static bool     g_svs_prev_had_rtv = false;
static uint64_t g_svs_seams = 0;   // depth-only continuations seen
static uint64_t g_svs_seam_main = 0;   // ... that were OUR main-depth id (refused)
static uint64_t g_svs_seam_square = 0;   // ... square target, i.e. a cascade (refused)
static uint32_t g_svs_seam_w = 0, g_svs_seam_h = 0, g_svs_seam_fmt = 0;
static uint64_t g_svs_arm_skips = 0;   // seam hit, injection not armed
static uint64_t g_svs_injects = 0;   // depth renders performed
static uint64_t g_svs_inject_draws = 0;   // meshes drawn across them
static uint64_t g_svs_frame_dupes = 0;   // seam fired again in the same frame
static uint64_t g_svs_skip_proj = 0;   // no usable projection
static uint64_t g_svs_skip_empty = 0;   // nothing eligible to draw
static uint64_t g_svs_skip_res = 0;   // resources cold
// the shape of the seam refused as OUR main depth, published separately from
// svSeamW/H/Fmt so one dump names BOTH buffers.
static uint32_t g_svs_main_w = 0, g_svs_main_h = 0, g_svs_main_fmt = 0;

static const void* g_svs_colour_dsv_id = nullptr;   // resource behind the colour injection's DSV
static uint64_t g_svs_vol_is_colour = 0;   // frames where it IS the volume source
static uint64_t g_svs_vol_not_colour = 0;   // frames where it is not
static uint64_t g_svs_colour_dsv_none = 0;   // no DSV bound at the injection

// Nothing measured this; the dimensions were published but never differenced.
// SEAM-TARGET STABILITY. If the detector sometimes latches a half-res target
// the injection is going into the wrong buffer entirely on those runs, which
// would explain results that refuse to reproduce across sessions.
static uint32_t g_svs_seam_w_prev = 0, g_svs_seam_h_prev = 0;
static uint64_t g_svs_seam_dim_changes = 0;
static uint32_t g_svs_seam_w_min = 0, g_svs_seam_h_min = 0;
static uint64_t g_svs_skip_dims = 0;   // seam target not at scene resolution
static uint32_t g_svs_seam_ord = 0;   // which seam of the frame was injected
static uint32_t g_svs_seams_frame = 0;   // seams so far this frame
static uint32_t g_svs_seams_frame_max = 0;
static uint32_t g_svs_inj_w = 0, g_svs_inj_h = 0, g_svs_inj_fmt = 0;
static uint32_t g_svs_inj_bind = 0;   // bind flags of the written target
static uint32_t g_svs_sel_w = 0, g_svs_sel_h = 0, g_svs_sel_fmt = 0, g_svs_sel_bind = 0;
static uint64_t g_svs_enters = 0;   // injector entered
static uint64_t g_svs_fail_framecb = 0;   // frame CB upload refused
static uint64_t g_svs_fail_objcb = 0;   // object CB upload refused mid-loop
// The set is tiny (8), cleared at the frame boundary, and holds identity
// tokens that are compared and never dereferenced - the same discipline as
// the SRV memo. THE ADJACENCY RULE IS RETIRED.
static void*    g_svs_rtv_seen[8] = {};
static uint32_t g_svs_rtv_seen_n = 0;
static uint64_t g_svs_seam_adj = 0;   // seams that ALSO passed adjacency
// A rule cannot fire on a bind it never sees, so the question is no longer
// "which rule" but "what does the hook actually see". This engine records on
// deferred contexts; if the prepass binds land somewhere we do not watch,
// that buffer is never marked and no rule can help. DEPTH-BIND CENSUS. Pure
// read, no behaviour.
static void*    g_svs_cls_id[8] = {};
static uint8_t  g_svs_cls_srv[8] = {};
static uint32_t g_svs_cls_n = 0;
static uint64_t g_svs_bind_vol_rtv = 0;   // non-SRV depth target, RTV attached
static uint64_t g_svs_bind_vol_only = 0;   // non-SRV depth target, depth-only
static uint64_t g_svs_bind_srv_rtv = 0;   // SRV-capable depth target, RTV attached
static uint64_t g_svs_bind_srv_only = 0;   // SRV-capable depth target, depth-only
static uint32_t g_svs_rtv_set_max = 0;   // peak size of the per-frame with-RTV set
// This is a hypothesis with a named mechanism and a cheap test, not a
// rewrite: if captures start containing the draw, it was re-entrancy; if they
// still do not while svInjects keeps climbing, it is not, and the next move
// is to stop trying to verify this step through RenderDoc at all. THE
// INJECTION IS DEFERRED OUT OF THE OM HOOK BODY.
static bool     g_svs_pending = false;
static uint32_t g_svs_pend_w = 0, g_svs_pend_h = 0;
static uint64_t g_svs_pend_arms = 0;   // deferred injections armed
static uint64_t g_svs_pend_fires = 0;   // ... performed at a later draw
static uint64_t g_svs_pend_dropped = 0;   // ... still armed at frame end
static void*    g_svs_mask_id = nullptr;
static ID3D11ShaderResourceView* g_svs_mask_srv = nullptr;
static uint32_t g_svs_mask_w = 0, g_svs_mask_h = 0, g_svs_mask_fmt = 0;
static uint64_t g_svs_mask_hits = 0;   // resolve binds recognised
static uint64_t g_svs_mask_adopts = 0;   // SRV created over a new identity
static uint64_t g_svs_mask_fails = 0;   // SRV creation refused
static uint64_t g_svs_mask_binds = 0;   // bound to our mesh shaders
static bool     g_svs_seam_hit_frame = false;
// MASK CAPTURE DECOUPLED. Locating the mask has nothing to do with whether we
// inject.
static ID3D11Texture2D* g_svs_mask_cand = nullptr;
static uint64_t g_svs_ord_rtv_first = 0;
static uint64_t g_svs_ord_only_first = 0;
static uint8_t  g_svs_ord_frame = 0;   // 0 none yet, 1 rtv first, 2 depth-only first
// The mask has two writers - eight cascade resolves and one stencil-volume
// resolve - and only the second one knows about our box, because our
// injection writes DEPTH ONLY and the cascade half is resolved against the
// linear-depth target we deliberately do not touch. THE PRE-RESOLVE SNAPSHOT.
static ID3D11Texture2D*          g_svs_pre_tex = nullptr;
static ID3D11ShaderResourceView* g_svs_pre_srv = nullptr;
static uint32_t g_svs_pre_w = 0, g_svs_pre_h = 0, g_svs_pre_fmt = 0;
static uint64_t g_svs_copy_made = 0;   // CopyResource issued
static uint64_t g_svs_copy_fails = 0;   // destination texture or SRV refused
static uint64_t g_svs_copy_skips = 0;   // trigger hit, no usable destination
static uint64_t g_svs_copy_arms = 0;   // deferred copies armed at the bind
static uint64_t g_svs_copy_drops = 0;   // ... bracket incomplete at frame end
static ID3D11Texture2D*          g_svs_post_tex = nullptr;
static ID3D11ShaderResourceView* g_svs_post_srv = nullptr;
static uint64_t g_svs_post_made = 0;   // post snapshots taken
static uint64_t g_svs_post_skips = 0;   // post snapshot had no destination
static uint64_t g_svs_post_binds = 0;   // post snapshot bound to our shaders
// KH_SVS_SKIP: the seam inject fires many times a frame (svSeams), and every
// one redraws EVERY visible caster into a volume depth target. Most of those
// passes write bit-identical depth: same target, same view, same casters, no
// clear in between - so the target already holds exactly what the pass would
// write and the pass is pure waste. This signature covers every input the
// injected depth depends on; when it matches the last COMPLETED inject the
// pass is skipped. A skip happens only when the output would be identical, so
// unlike drawing coarser proxies it has no silhouette to get wrong and cannot
// flicker. Field: 49 skips vs 2.1 misses per flush, svInjectDraws 14,820 ->
// 550. Mode 476 disables.
static uint64_t g_depth_clear_serial = 0;   // bumped by hooked_clear_depthstencil
static uint64_t g_svs_skip_sig = 0;         // signature of the last completed inject
static bool     g_svs_skip_valid = false;
static uint64_t g_svs_skips_redundant = 0;  // passes skipped
static uint64_t g_svs_skip_misses = 0;      // passes that ran
static uint64_t g_svs_frame_seq = 0;   // bumped once per seam frame boundary
static uint64_t g_svs_prime_stamp = ~0ull;   // seq at the seam's publish
static uint64_t g_comp_share_takes = 0;   // colour took the seam's camera
static uint64_t g_comp_share_stale = 0;   // ... refused, publication not adjacent
static uint64_t g_svs_post_seq = 0;   // frame_seq when post was last written
static uint64_t g_svs_post_age_last = 0;
static uint64_t g_svs_post_age_max = 0;
static bool     g_svs_prime_vp_seen = false;
static float    g_svs_vp_hist[4][4][4] = {};
static float    g_svs_vp_lo_hist[4] = {};
static float    g_svs_vp_hi_hist[4] = {};
static float    g_svs_cam_hist[4][3] = {};
static bool     g_svs_rebase_hist[4] = {};
static uint64_t g_svs_seq_hist[4] = {};
static float    g_svs_cyc_hist[4][4][4] = {};
static bool     g_svs_cyc_hist_ok[4] = {};
static uint64_t g_sten_cyc_pubs = 0;   // fills that armed the cycle tap
static uint64_t g_sten_cyc_miss = 0;   // ... that stood it down (epoch miss / cycle invalid / 431)
